window.PACK={"book":{"id":"shatibiyya","title":"الشاطبية (حرز الأماني ووجه التهاني) — القراءات السبع","type":"matn","author":"القاسم بن فيره الشاطبي (ت ٥٩٠هـ)","source":"المكتبة الشاملة (رقم 0007754) عبر مشروع OpenITI","edition":"مكتبة دار الهدى ودار الغوثاني للدراسات القرآنية","optional":false,"packVersion":"ae0c772de583"},"items":[{"id":"shatibiyya:1","bookId":"shatibiyya","type":"bayt","num":1,"seq":1,"chapter":"مقدمة","title":"البيت 1","page":"ص0","text":"بدأت ببسم الله في النظم أولا ... تبارك رحمانا رحيما وموئلا","a":"بدأت ببسم الله في النظم أولا","b":"تبارك رحمانا رحيما وموئلا","ref":["ibraz:4","siraj:1"]},{"id":"shatibiyya:2","bookId":"shatibiyya","type":"bayt","num":2,"seq":2,"chapter":"مقدمة","title":"البيت 2","page":"ص0","text":"وثنيت صلى الله ربي على الرضا ... محمد المهدى إلى الناس مرسلا","a":"وثنيت صلى الله ربي على الرضا","b":"محمد المهدى إلى الناس مرسلا","ref":["ibraz:5"]},{"id":"shatibiyya:3","bookId":"shatibiyya","type":"bayt","num":3,"seq":3,"chapter":"مقدمة","title":"البيت 3","page":"ص0","text":"وعترته ثم الصحابة ثم من ... تلاهم على الإحسان بالخير وبلا","a":"وعترته ثم الصحابة ثم من","b":"تلاهم على الإحسان بالخير وبلا","ref":["ibraz:6","siraj:1"]},{"id":"shatibiyya:4","bookId":"shatibiyya","type":"bayt","num":4,"seq":4,"chapter":"مقدمة","title":"البيت 4","page":"ص0","text":"وثلثت أن الحمد لله دائما ... وما ليس مبدوءا به أجذم العلا","a":"وثلثت أن الحمد لله دائما","b":"وما ليس مبدوءا به أجذم العلا","ref":["ibraz:7","siraj:1"]},{"id":"shatibiyya:5","bookId":"shatibiyya","type":"bayt","num":5,"seq":5,"chapter":"مقدمة","title":"البيت 5","page":"ص0","text":"وبعد فحبل الله فينا كتابه ... فجاهد به حبل العدا متحبلا","a":"وبعد فحبل الله فينا كتابه","b":"فجاهد به حبل العدا متحبلا","ref":["ibraz:9","siraj:1"]},{"id":"shatibiyya:6","bookId":"shatibiyya","type":"bayt","num":6,"seq":6,"chapter":"مقدمة","title":"البيت 6","page":"ص0","text":"وأخلق به إذ ليس يخلق جدة ... جديدا مواليه على الجد مقبلا","a":"وأخلق به إذ ليس يخلق جدة","b":"جديدا مواليه على الجد مقبلا","ref":["ibraz:10","siraj:1"]},{"id":"shatibiyya:7","bookId":"shatibiyya","type":"bayt","num":7,"seq":7,"chapter":"مقدمة","title":"البيت 7","page":"ص0","text":"وقارئه المرضي قر مثاله ... كالاترج حاليه مريحا وموكلا","a":"وقارئه المرضي قر مثاله","b":"كالاترج حاليه مريحا وموكلا","ref":["ibraz:11","siraj:1"]},{"id":"shatibiyya:8","bookId":"shatibiyya","type":"bayt","num":8,"seq":8,"chapter":"مقدمة","title":"البيت 8","page":"ص0","text":"هو المرتضى أما إذا كان أمه ... ويممه ظل الرزانة قنقلا","a":"هو المرتضى أما إذا كان أمه","b":"ويممه ظل الرزانة قنقلا","ref":["ibraz:12","siraj:1"]},{"id":"shatibiyya:9","bookId":"shatibiyya","type":"bayt","num":9,"seq":9,"chapter":"مقدمة","title":"البيت 9","page":"ص0","text":"هو الحر إن كان الحري حواريا ... له بتحريه إلى أن تنبلا","a":"هو الحر إن كان الحري حواريا","b":"له بتحريه إلى أن تنبلا","ref":["ibraz:13","siraj:1"]},{"id":"shatibiyya:10","bookId":"shatibiyya","type":"bayt","num":10,"seq":10,"chapter":"مقدمة","title":"البيت 10","page":"ج1 ص1","text":"وإن كتاب الله أوثق شافع ... وأغنى غناء واهبا متفضلا","a":"وإن كتاب الله أوثق شافع","b":"وأغنى غناء واهبا متفضلا","ref":["ibraz:14","siraj:1"]},{"id":"shatibiyya:11","bookId":"shatibiyya","type":"bayt","num":11,"seq":11,"chapter":"مقدمة","title":"البيت 11","page":"ج1 ص1","text":"وخير جليس لا يمل حديثه ... وترداده يزداد فيه تجملا","a":"وخير جليس لا يمل حديثه","b":"وترداده يزداد فيه تجملا","ref":["ibraz:15","siraj:1"]},{"id":"shatibiyya:12","bookId":"shatibiyya","type":"bayt","num":12,"seq":12,"chapter":"مقدمة","title":"البيت 12","page":"ج1 ص1","text":"وحيث الفتى يرتاع في ظلماته ... من القبر يلقاه سنا متهللا","a":"وحيث الفتى يرتاع في ظلماته","b":"من القبر يلقاه سنا متهللا","ref":["ibraz:16","siraj:1"]},{"id":"shatibiyya:13","bookId":"shatibiyya","type":"bayt","num":13,"seq":13,"chapter":"مقدمة","title":"البيت 13","page":"ج1 ص1","text":"هنالك يهنيه مقيلا وروضة ... ومن أجله في ذروة العز يجتلى","a":"هنالك يهنيه مقيلا وروضة","b":"ومن أجله في ذروة العز يجتلى","ref":["ibraz:17","siraj:1"]},{"id":"shatibiyya:14","bookId":"shatibiyya","type":"bayt","num":14,"seq":14,"chapter":"مقدمة","title":"البيت 14","page":"ج1 ص1","text":"يناشد في إرضائه لحبيبه ... وأجدر به سؤلا إليه موصلا","a":"يناشد في إرضائه لحبيبه","b":"وأجدر به سؤلا إليه موصلا","ref":["siraj:1"]},{"id":"shatibiyya:15","bookId":"shatibiyya","type":"bayt","num":15,"seq":15,"chapter":"مقدمة","title":"البيت 15","page":"ج1 ص1","text":"فيا أيها القاري به متمسكا ... مجلا له في كل حال مبجلا","a":"فيا أيها القاري به متمسكا","b":"مجلا له في كل حال مبجلا","ref":["ibraz:19","siraj:1"]},{"id":"shatibiyya:16","bookId":"shatibiyya","type":"bayt","num":16,"seq":16,"chapter":"مقدمة","title":"البيت 16","page":"ج1 ص1","text":"هنيئا مريئا والداك عليهما ... ملابس أنوار من التاج والحلا","a":"هنيئا مريئا والداك عليهما","b":"ملابس أنوار من التاج والحلا","ref":["ibraz:20","siraj:1"]},{"id":"shatibiyya:17","bookId":"shatibiyya","type":"bayt","num":17,"seq":17,"chapter":"مقدمة","title":"البيت 17","page":"ج1 ص1","text":"فما ظنكم بالنجل عند جزائه ... أولئك أهل الله والصفوة الملا","a":"فما ظنكم بالنجل عند جزائه","b":"أولئك أهل الله والصفوة الملا","ref":["ibraz:21","siraj:2"]},{"id":"shatibiyya:18","bookId":"shatibiyya","type":"bayt","num":18,"seq":18,"chapter":"مقدمة","title":"البيت 18","page":"ج1 ص1","text":"أولو البر والإحسان والصبر والتقى ... حلاهم بها جاء القران مفصلا","a":"أولو البر والإحسان والصبر والتقى","b":"حلاهم بها جاء القران مفصلا","ref":["ibraz:22","siraj:2"]},{"id":"shatibiyya:19","bookId":"shatibiyya","type":"bayt","num":19,"seq":19,"chapter":"مقدمة","title":"البيت 19","page":"ج1 ص1","text":"عليك بها ما عشت فيها منافسا ... وبع نفسك الدنيا بأنفاسها العلا","a":"عليك بها ما عشت فيها منافسا","b":"وبع نفسك الدنيا بأنفاسها العلا","ref":["ibraz:23","siraj:2"]},{"id":"shatibiyya:20","bookId":"shatibiyya","type":"bayt","num":20,"seq":20,"chapter":"مقدمة","title":"البيت 20","page":"ج1 ص1","text":"جزى الله بالخيرات عنا أئمة ... لنا نقلوا القرآن عذبا وسلسلا","a":"جزى الله بالخيرات عنا أئمة","b":"لنا نقلوا القرآن عذبا وسلسلا","ref":["ibraz:25","siraj:2"]},{"id":"shatibiyya:21","bookId":"shatibiyya","type":"bayt","num":21,"seq":21,"chapter":"مقدمة","title":"البيت 21","page":"ج1 ص1","text":"فمنهم بدور سبعة قد توسطت ... سماء العلى والعدل زهرا وكملا","a":"فمنهم بدور سبعة قد توسطت","b":"سماء العلى والعدل زهرا وكملا","ref":["ibraz:26","siraj:2"]},{"id":"shatibiyya:22","bookId":"shatibiyya","type":"bayt","num":22,"seq":22,"chapter":"مقدمة","title":"البيت 22","page":"ج1 ص1","text":"لها شهب عنها استنارت فنورت ... سواد الدجى حتى تفرق وانجلا","a":"لها شهب عنها استنارت فنورت","b":"سواد الدجى حتى تفرق وانجلا","ref":["ibraz:27","siraj:2"]},{"id":"shatibiyya:23","bookId":"shatibiyya","type":"bayt","num":23,"seq":23,"chapter":"مقدمة","title":"البيت 23","page":"ج1 ص1","text":"وسوف تراهم واحدا بعد واحد ... مع اثنين من أصحابه متمثلا","a":"وسوف تراهم واحدا بعد واحد","b":"مع اثنين من أصحابه متمثلا","ref":["ibraz:28","siraj:2"]},{"id":"shatibiyya:24","bookId":"shatibiyya","type":"bayt","num":24,"seq":24,"chapter":"مقدمة","title":"البيت 24","page":"ج1 ص2","text":"تخيرهم نقادهم كل بارع ... وليس على قرآنه متأكلا","a":"تخيرهم نقادهم كل بارع","b":"وليس على قرآنه متأكلا","ref":["ibraz:29","siraj:2"]},{"id":"shatibiyya:25","bookId":"shatibiyya","type":"bayt","num":25,"seq":25,"chapter":"مقدمة","title":"البيت 25","page":"ج1 ص2","text":"فأما الكريم السر في الطيب نافع ... فذاك الذي اختار المدينة منزلا","a":"فأما الكريم السر في الطيب نافع","b":"فذاك الذي اختار المدينة منزلا","ref":["ibraz:30","siraj:2"]},{"id":"shatibiyya:26","bookId":"shatibiyya","type":"bayt","num":26,"seq":26,"chapter":"مقدمة","title":"البيت 26","page":"ج1 ص2","text":"وقالون عيسى ثم عثمان ورشهم ... بصحبته المجد الرفيع تأثلا","a":"وقالون عيسى ثم عثمان ورشهم","b":"بصحبته المجد الرفيع تأثلا","ref":["ibraz:31","siraj:2"]},{"id":"shatibiyya:27","bookId":"shatibiyya","type":"bayt","num":27,"seq":27,"chapter":"مقدمة","title":"البيت 27","page":"ج1 ص2","text":"ومكة عبد الله فيها مقامه ... هو ابن كثير كاثر القوم معتلا","a":"ومكة عبد الله فيها مقامه","b":"هو ابن كثير كاثر القوم معتلا","ref":["ibraz:32","siraj:2"]},{"id":"shatibiyya:28","bookId":"shatibiyya","type":"bayt","num":28,"seq":28,"chapter":"مقدمة","title":"البيت 28","page":"ج1 ص2","text":"روى أحمد البزي له ومحمد ... على سند وهو الملقب قنبلا","a":"روى أحمد البزي له ومحمد","b":"على سند وهو الملقب قنبلا","ref":["ibraz:33","siraj:2"]},{"id":"shatibiyya:29","bookId":"shatibiyya","type":"bayt","num":29,"seq":29,"chapter":"مقدمة","title":"البيت 29","page":"ج1 ص2","text":"وأما الإمام المازني صريحهم ... أبو عمرو البصري فوالده العلا","a":"وأما الإمام المازني صريحهم","b":"أبو عمرو البصري فوالده العلا","ref":["ibraz:34","siraj:2"]},{"id":"shatibiyya:30","bookId":"shatibiyya","type":"bayt","num":30,"seq":30,"chapter":"مقدمة","title":"البيت 30","page":"ج1 ص2","text":"أفاض على يحيى اليزيدي سيبه ... فأصبح بالعذب الفرات معللا","a":"أفاض على يحيى اليزيدي سيبه","b":"فأصبح بالعذب الفرات معللا","ref":["ibraz:35","siraj:2"]},{"id":"shatibiyya:31","bookId":"shatibiyya","type":"bayt","num":31,"seq":31,"chapter":"مقدمة","title":"البيت 31","page":"ج1 ص2","text":"أبو عمر الدوري وصالحهم أبو ... شعيب هو السوسي عنه تقبلا","a":"أبو عمر الدوري وصالحهم أبو","b":"شعيب هو السوسي عنه تقبلا","ref":["ibraz:36","siraj:2"]},{"id":"shatibiyya:32","bookId":"shatibiyya","type":"bayt","num":32,"seq":32,"chapter":"مقدمة","title":"البيت 32","page":"ج1 ص2","text":"وأما دمشق الشام دار ابن عامر ... فتلك بعبد الله طابت محللا","a":"وأما دمشق الشام دار ابن عامر","b":"فتلك بعبد الله طابت محللا","ref":["ibraz:37","siraj:2"]},{"id":"shatibiyya:33","bookId":"shatibiyya","type":"bayt","num":33,"seq":33,"chapter":"مقدمة","title":"البيت 33","page":"ج1 ص2","text":"هشام وعبد الله وهو انتسابه ... لذكوان بالإسناد عنه تنقلا","a":"هشام وعبد الله وهو انتسابه","b":"لذكوان بالإسناد عنه تنقلا","ref":["ibraz:38","siraj:2"]},{"id":"shatibiyya:34","bookId":"shatibiyya","type":"bayt","num":34,"seq":34,"chapter":"مقدمة","title":"البيت 34","page":"ج1 ص2","text":"وبالكوفة الغراء منهم ثلاتة ... أذاعوا فقد ضاعت شذا وقرنفلا","a":"وبالكوفة الغراء منهم ثلاتة","b":"أذاعوا فقد ضاعت شذا وقرنفلا","ref":["ibraz:39"]},{"id":"shatibiyya:35","bookId":"shatibiyya","type":"bayt","num":35,"seq":35,"chapter":"مقدمة","title":"البيت 35","page":"ج1 ص2","text":"فأما أبو بكر وعاصم اسمه ... فشعبة راويه المبرز أفضلا","a":"فأما أبو بكر وعاصم اسمه","b":"فشعبة راويه المبرز أفضلا","ref":["ibraz:40","siraj:2"]},{"id":"shatibiyya:36","bookId":"shatibiyya","type":"bayt","num":36,"seq":36,"chapter":"مقدمة","title":"البيت 36","page":"ج1 ص2","text":"وذاك ابن عياش أبو بكر الرضا ... وحفص وبالإتقان كان مفضلا","a":"وذاك ابن عياش أبو بكر الرضا","b":"وحفص وبالإتقان كان مفضلا","ref":["ibraz:41","siraj:2"]},{"id":"shatibiyya:37","bookId":"shatibiyya","type":"bayt","num":37,"seq":37,"chapter":"مقدمة","title":"البيت 37","page":"ج1 ص2","text":"وحمزة ما أزكاه من متورع ... إماما صبورا للقران مرتلا","a":"وحمزة ما أزكاه من متورع","b":"إماما صبورا للقران مرتلا","ref":["ibraz:42","siraj:2"]},{"id":"shatibiyya:38","bookId":"shatibiyya","type":"bayt","num":38,"seq":38,"chapter":"مقدمة","title":"البيت 38","page":"ج1 ص3","text":"روى خلف عنه وخلاد الذي ... رواه سليم متقنا ومحصلا","a":"روى خلف عنه وخلاد الذي","b":"رواه سليم متقنا ومحصلا","ref":["ibraz:43","siraj:2"]},{"id":"shatibiyya:39","bookId":"shatibiyya","type":"bayt","num":39,"seq":39,"chapter":"مقدمة","title":"البيت 39","page":"ج1 ص3","text":"وأما علي فالكسائي نعته ... لما كان في الإحرام فيه تسربلا","a":"وأما علي فالكسائي نعته","b":"لما كان في الإحرام فيه تسربلا","ref":["ibraz:44","siraj:2"]},{"id":"shatibiyya:40","bookId":"shatibiyya","type":"bayt","num":40,"seq":40,"chapter":"مقدمة","title":"البيت 40","page":"ج1 ص3","text":"روى ليثهم عنه أبو الحارث الرضا ... وحفص هو الدوري وفي الذكر قد خلا","a":"روى ليثهم عنه أبو الحارث الرضا","b":"وحفص هو الدوري وفي الذكر قد خلا","ref":["ibraz:45","siraj:2"]},{"id":"shatibiyya:41","bookId":"shatibiyya","type":"bayt","num":41,"seq":41,"chapter":"مقدمة","title":"البيت 41","page":"ج1 ص3","text":"أبو عمرهم واليحصبي ابن عامر ... صريح وباقيهم أحاط به الولا","a":"أبو عمرهم واليحصبي ابن عامر","b":"صريح وباقيهم أحاط به الولا","ref":["ibraz:46","siraj:2"]},{"id":"shatibiyya:42","bookId":"shatibiyya","type":"bayt","num":42,"seq":42,"chapter":"مقدمة","title":"البيت 42","page":"ج1 ص3","text":"لهم طرق يهدى بها كل طارق ... ولا طارق يخشى بها متمحلا","a":"لهم طرق يهدى بها كل طارق","b":"ولا طارق يخشى بها متمحلا","ref":["ibraz:47","siraj:3"]},{"id":"shatibiyya:43","bookId":"shatibiyya","type":"bayt","num":43,"seq":43,"chapter":"مقدمة","title":"البيت 43","page":"ج1 ص3","text":"وهن اللواتي للمواتي نصبتها ... مناصب فانصب في نصابك مفضلا","a":"وهن اللواتي للمواتي نصبتها","b":"مناصب فانصب في نصابك مفضلا","ref":["ibraz:48","siraj:3"]},{"id":"shatibiyya:44","bookId":"shatibiyya","type":"bayt","num":44,"seq":44,"chapter":"مقدمة","title":"البيت 44","page":"ج1 ص3","text":"وها أنا ذا أسعى لعل حروفهم ... يطوع بها نظم القوافي مسهلا","a":"وها أنا ذا أسعى لعل حروفهم","b":"يطوع بها نظم القوافي مسهلا","ref":["siraj:3"]},{"id":"shatibiyya:45","bookId":"shatibiyya","type":"bayt","num":45,"seq":45,"chapter":"مقدمة","title":"البيت 45","page":"ج1 ص3","text":"جعلت أبا جاد على كل قارئ ... دليلا على المنظوم أول أولا","a":"جعلت أبا جاد على كل قارئ","b":"دليلا على المنظوم أول أولا","ref":["ibraz:50","siraj:3"]},{"id":"shatibiyya:46","bookId":"shatibiyya","type":"bayt","num":46,"seq":46,"chapter":"مقدمة","title":"البيت 46","page":"ج1 ص3","text":"ومن بعد ذكري الحرف أسمي رجاله ... متى تنقضي آتيك بالواو فيصلا","a":"ومن بعد ذكري الحرف أسمي رجاله","b":"متى تنقضي آتيك بالواو فيصلا","ref":["ibraz:51","siraj:3"]},{"id":"shatibiyya:47","bookId":"shatibiyya","type":"bayt","num":47,"seq":47,"chapter":"مقدمة","title":"البيت 47","page":"ج1 ص3","text":"سوى أحرف لا ريبة في اتصالها ... وباللفظ أستغني عن القيد إن جلا","a":"سوى أحرف لا ريبة في اتصالها","b":"وباللفظ أستغني عن القيد إن جلا","ref":["ibraz:52","siraj:3"]},{"id":"shatibiyya:48","bookId":"shatibiyya","type":"bayt","num":48,"seq":48,"chapter":"مقدمة","title":"البيت 48","page":"ج1 ص3","text":"ورب مكان كرر الحرف قبلها ... لما عارض والأمر ليس مهولا","a":"ورب مكان كرر الحرف قبلها","b":"لما عارض والأمر ليس مهولا","ref":["ibraz:53","siraj:3"]},{"id":"shatibiyya:49","bookId":"shatibiyya","type":"bayt","num":49,"seq":49,"chapter":"مقدمة","title":"البيت 49","page":"ج1 ص4","text":"ومنهن للكوفي ثاء مثلت ... وستتهم بالخاء ليس بأغفلا","a":"ومنهن للكوفي ثاء مثلت","b":"وستتهم بالخاء ليس بأغفلا","ref":["ibraz:54"]},{"id":"shatibiyya:50","bookId":"shatibiyya","type":"bayt","num":50,"seq":50,"chapter":"مقدمة","title":"البيت 50","page":"ج1 ص4","text":"عنيت الألى أثبتهم بعد نافع ... وكوف وشام ذالهم ليس مغفلا","a":"عنيت الألى أثبتهم بعد نافع","b":"وكوف وشام ذالهم ليس مغفلا","ref":["ibraz:55"]},{"id":"shatibiyya:51","bookId":"shatibiyya","type":"bayt","num":51,"seq":51,"chapter":"مقدمة","title":"البيت 51","page":"ج1 ص4","text":"وكوف مع المكي بالظاء معجما ... وكوف وبصر غينهم ليس مهملا","a":"وكوف مع المكي بالظاء معجما","b":"وكوف وبصر غينهم ليس مهملا","ref":["ibraz:56","siraj:3"]},{"id":"shatibiyya:52","bookId":"shatibiyya","type":"bayt","num":52,"seq":52,"chapter":"مقدمة","title":"البيت 52","page":"ج1 ص4","text":"وذو النقط شين للكسائي وحمزة ... وقل فيهما مع شعبة صحبة تلا","a":"وذو النقط شين للكسائي وحمزة","b":"وقل فيهما مع شعبة صحبة تلا","ref":["ibraz:57","siraj:3"]},{"id":"shatibiyya:53","bookId":"shatibiyya","type":"bayt","num":53,"seq":53,"chapter":"مقدمة","title":"البيت 53","page":"ج1 ص4","text":"صحاب هما مع حفصهم عم نافع ... وشام سما في نافع وفتى العلا","a":"صحاب هما مع حفصهم عم نافع","b":"وشام سما في نافع وفتى العلا","ref":["ibraz:58","siraj:3"]},{"id":"shatibiyya:54","bookId":"shatibiyya","type":"bayt","num":54,"seq":54,"chapter":"مقدمة","title":"البيت 54","page":"ج1 ص4","text":"ومك وحق فيه وابن العلاء قل ... وقل فيهما واليحصبي نفر حلا","a":"ومك وحق فيه وابن العلاء قل","b":"وقل فيهما واليحصبي نفر حلا","ref":["ibraz:59","siraj:3"]},{"id":"shatibiyya:55","bookId":"shatibiyya","type":"bayt","num":55,"seq":55,"chapter":"مقدمة","title":"البيت 55","page":"ج1 ص4","text":"وحرمي المكي فيه ونافع ... وحصن عن الكوفي ونافعهم علا","a":"وحرمي المكي فيه ونافع","b":"وحصن عن الكوفي ونافعهم علا","ref":["ibraz:60","siraj:3"]},{"id":"shatibiyya:56","bookId":"shatibiyya","type":"bayt","num":56,"seq":56,"chapter":"مقدمة","title":"البيت 56","page":"ج1 ص4","text":"ومهما أتت من قبل أو بعد كلمة ... فكن عند شرطي واقض بالواو فيصلا","a":"ومهما أتت من قبل أو بعد كلمة","b":"فكن عند شرطي واقض بالواو فيصلا","ref":["ibraz:61","siraj:3"]},{"id":"shatibiyya:57","bookId":"shatibiyya","type":"bayt","num":57,"seq":57,"chapter":"مقدمة","title":"البيت 57","page":"ج1 ص4","text":"وما كان ذا ضد فإني بضده ... غني فزاحم بالذكاء لتفضلا","a":"وما كان ذا ضد فإني بضده","b":"غني فزاحم بالذكاء لتفضلا","ref":["ibraz:62","siraj:3"]},{"id":"shatibiyya:58","bookId":"shatibiyya","type":"bayt","num":58,"seq":58,"chapter":"مقدمة","title":"البيت 58","page":"ج1 ص4","text":"كمد وإثبات وفتح ومدغم ... وهمز ونقل واختلاس تحصلا","a":"كمد وإثبات وفتح ومدغم","b":"وهمز ونقل واختلاس تحصلا","ref":["ibraz:63","siraj:3"]},{"id":"shatibiyya:59","bookId":"shatibiyya","type":"bayt","num":59,"seq":59,"chapter":"مقدمة","title":"البيت 59","page":"ج1 ص4","text":"وجزم وتذكير وغيب وخفة ... وجمع وتنوين وتحريك اعملا","a":"وجزم وتذكير وغيب وخفة","b":"وجمع وتنوين وتحريك اعملا","ref":["ibraz:64","siraj:4"]},{"id":"shatibiyya:60","bookId":"shatibiyya","type":"bayt","num":60,"seq":60,"chapter":"مقدمة","title":"البيت 60","page":"ج1 ص4","text":"وحيث جرى التحريك غير مقيد ... هو الفتح والإسكان آخاه منزلا","a":"وحيث جرى التحريك غير مقيد","b":"هو الفتح والإسكان آخاه منزلا","ref":["ibraz:65","siraj:4"]},{"id":"shatibiyya:61","bookId":"shatibiyya","type":"bayt","num":61,"seq":61,"chapter":"مقدمة","title":"البيت 61","page":"ج1 ص4","text":"وآخيت بين النون واليا وفتحهم ... وكسر وبين النصب والخفض منزلا","a":"وآخيت بين النون واليا وفتحهم","b":"وكسر وبين النصب والخفض منزلا","ref":["ibraz:66","siraj:4"]},{"id":"shatibiyya:62","bookId":"shatibiyya","type":"bayt","num":62,"seq":62,"chapter":"مقدمة","title":"البيت 62","page":"ج1 ص5","text":"وحيث أقول الضم والرفع ساكتا ... فغيرهم بالفتح والنصب أقبلا","a":"وحيث أقول الضم والرفع ساكتا","b":"فغيرهم بالفتح والنصب أقبلا","ref":["ibraz:67","siraj:4"]},{"id":"shatibiyya:63","bookId":"shatibiyya","type":"bayt","num":63,"seq":63,"chapter":"مقدمة","title":"البيت 63","page":"ج1 ص5","text":"وفي الرفع والتذكير والغيب جملة ... على لفظها أطلقت من قيد العلا","a":"وفي الرفع والتذكير والغيب جملة","b":"على لفظها أطلقت من قيد العلا","ref":["ibraz:68","siraj:4"]},{"id":"shatibiyya:64","bookId":"shatibiyya","type":"bayt","num":64,"seq":64,"chapter":"مقدمة","title":"البيت 64","page":"ج1 ص5","text":"وقبل وبعد الحرف آتي بكل ما ... رمزت به في الجمع إذ ليس مشكلا","a":"وقبل وبعد الحرف آتي بكل ما","b":"رمزت به في الجمع إذ ليس مشكلا","ref":["ibraz:69","siraj:4"]},{"id":"shatibiyya:65","bookId":"shatibiyya","type":"bayt","num":65,"seq":65,"chapter":"مقدمة","title":"البيت 65","page":"ج1 ص5","text":"وسوف أسمي حيث يسمح نظمه ... به موضحا جيدا معما ومخولا","a":"وسوف أسمي حيث يسمح نظمه","b":"به موضحا جيدا معما ومخولا","ref":["ibraz:70","siraj:4"]},{"id":"shatibiyya:66","bookId":"shatibiyya","type":"bayt","num":66,"seq":66,"chapter":"مقدمة","title":"البيت 66","page":"ج1 ص5","text":"ومن كان ذا باب له فيه مذهب ... فلا بد أن يسمى فيدرى ويعقلا","a":"ومن كان ذا باب له فيه مذهب","b":"فلا بد أن يسمى فيدرى ويعقلا","ref":["ibraz:71","siraj:4"]},{"id":"shatibiyya:67","bookId":"shatibiyya","type":"bayt","num":67,"seq":67,"chapter":"مقدمة","title":"البيت 67","page":"ج1 ص5","text":"أهلت فلبتها المعاني لبابها ... وصغت بها ما ساغ عذبا مسلسلا","a":"أهلت فلبتها المعاني لبابها","b":"وصغت بها ما ساغ عذبا مسلسلا","ref":["ibraz:72","siraj:4"]},{"id":"shatibiyya:68","bookId":"shatibiyya","type":"bayt","num":68,"seq":68,"chapter":"مقدمة","title":"البيت 68","page":"ج1 ص5","text":"وفي يسرها التيسير رمت اختصاره ... فأجنت بعون الله منه مؤملا","a":"وفي يسرها التيسير رمت اختصاره","b":"فأجنت بعون الله منه مؤملا","ref":["ibraz:73","siraj:4"]},{"id":"shatibiyya:69","bookId":"shatibiyya","type":"bayt","num":69,"seq":69,"chapter":"مقدمة","title":"البيت 69","page":"ج1 ص5","text":"وألفافها زادت بنشر فوائد ... فلفت حياء وجهها أن تفضلا","a":"وألفافها زادت بنشر فوائد","b":"فلفت حياء وجهها أن تفضلا","ref":["ibraz:74","siraj:4"]},{"id":"shatibiyya:70","bookId":"shatibiyya","type":"bayt","num":70,"seq":70,"chapter":"مقدمة","title":"البيت 70","page":"ج1 ص5","text":"وسميتها \"حرز الأماني\" تيمنا ... ووجه التهاني فاهنه متقبلا","a":"وسميتها \"حرز الأماني\" تيمنا","b":"ووجه التهاني فاهنه متقبلا","ref":["ibraz:75","siraj:4"]},{"id":"shatibiyya:71","bookId":"shatibiyya","type":"bayt","num":71,"seq":71,"chapter":"مقدمة","title":"البيت 71","page":"ج1 ص5","text":"وناديت أللهم يا خير سامع ... أعذني من التسميع قولا ومفعلا","a":"وناديت أللهم يا خير سامع","b":"أعذني من التسميع قولا ومفعلا","ref":["ibraz:76","siraj:4"]},{"id":"shatibiyya:72","bookId":"shatibiyya","type":"bayt","num":72,"seq":72,"chapter":"مقدمة","title":"البيت 72","page":"ج1 ص5","text":"إليك يدي منك الأيادي تمدها ... أجرني فلا أجري بجور قأخطلا","a":"إليك يدي منك الأيادي تمدها","b":"أجرني فلا أجري بجور قأخطلا","ref":["ibraz:77","siraj:4"]},{"id":"shatibiyya:73","bookId":"shatibiyya","type":"bayt","num":73,"seq":73,"chapter":"مقدمة","title":"البيت 73","page":"ج1 ص5","text":"أمين وأمنا للأمين بسرها ... وإن عثرت فهو الأمون تحملا","a":"أمين وأمنا للأمين بسرها","b":"وإن عثرت فهو الأمون تحملا","ref":["ibraz:78","siraj:4"]},{"id":"shatibiyya:74","bookId":"shatibiyya","type":"bayt","num":74,"seq":74,"chapter":"مقدمة","title":"البيت 74","page":"ج1 ص5","text":"أقول لحر والمروءة مرؤها ... لإخوته المرآة ذو النور مكحلا","a":"أقول لحر والمروءة مرؤها","b":"لإخوته المرآة ذو النور مكحلا","ref":["ibraz:79","siraj:4"]},{"id":"shatibiyya:75","bookId":"shatibiyya","type":"bayt","num":75,"seq":75,"chapter":"مقدمة","title":"البيت 75","page":"ج1 ص6","text":"أخي أيها المجتاز نظمي ببابه ... ينادى عليه كاسد السوق أجملا","a":"أخي أيها المجتاز نظمي ببابه","b":"ينادى عليه كاسد السوق أجملا","ref":["ibraz:80","siraj:4"]},{"id":"shatibiyya:76","bookId":"shatibiyya","type":"bayt","num":76,"seq":76,"chapter":"مقدمة","title":"البيت 76","page":"ج1 ص6","text":"وظن به خيرا وسامح نسيجه ... بالاغضاء والحسنى وإن كان هلهلا","a":"وظن به خيرا وسامح نسيجه","b":"بالاغضاء والحسنى وإن كان هلهلا","ref":["ibraz:81","siraj:4"]},{"id":"shatibiyya:77","bookId":"shatibiyya","type":"bayt","num":77,"seq":77,"chapter":"مقدمة","title":"البيت 77","page":"ج1 ص6","text":"وسلم لإحدى الحسنيين إصابة ... والاخرى اجتهاد رام صوبا فأمحلا","a":"وسلم لإحدى الحسنيين إصابة","b":"والاخرى اجتهاد رام صوبا فأمحلا","ref":["ibraz:82","siraj:4"]},{"id":"shatibiyya:78","bookId":"shatibiyya","type":"bayt","num":78,"seq":78,"chapter":"مقدمة","title":"البيت 78","page":"ج1 ص6","text":"وإن كان خرق فادركه بفضلة ... من الحلم وليصلحه من جاد مقولا","a":"وإن كان خرق فادركه بفضلة","b":"من الحلم وليصلحه من جاد مقولا","ref":["ibraz:83","siraj:5"]},{"id":"shatibiyya:79","bookId":"shatibiyya","type":"bayt","num":79,"seq":79,"chapter":"مقدمة","title":"البيت 79","page":"ج1 ص6","text":"وقل صادقا لولا الوئام وروحه ... لطاح الأنام الكل في الخلف والقلا","a":"وقل صادقا لولا الوئام وروحه","b":"لطاح الأنام الكل في الخلف والقلا","ref":["ibraz:84","siraj:5"]},{"id":"shatibiyya:80","bookId":"shatibiyya","type":"bayt","num":80,"seq":80,"chapter":"مقدمة","title":"البيت 80","page":"ج1 ص6","text":"وعش سالما صدرا وعن غيبة فغب ... تحضر حظار القدس أنقى مغسلا","a":"وعش سالما صدرا وعن غيبة فغب","b":"تحضر حظار القدس أنقى مغسلا","ref":["ibraz:85","siraj:5"]},{"id":"shatibiyya:81","bookId":"shatibiyya","type":"bayt","num":81,"seq":81,"chapter":"مقدمة","title":"البيت 81","page":"ج1 ص6","text":"وهذا زمان الصبر من لك بالتي ... كقبض على جمر فتنجو من البلا","a":"وهذا زمان الصبر من لك بالتي","b":"كقبض على جمر فتنجو من البلا","ref":["ibraz:86","siraj:5"]},{"id":"shatibiyya:82","bookId":"shatibiyya","type":"bayt","num":82,"seq":82,"chapter":"مقدمة","title":"البيت 82","page":"ج1 ص6","text":"ولو أن عينا ساعدت لتوكفت ... سحائبها بالدمع ديما وهطلا","a":"ولو أن عينا ساعدت لتوكفت","b":"سحائبها بالدمع ديما وهطلا","ref":["ibraz:87","siraj:5"]},{"id":"shatibiyya:83","bookId":"shatibiyya","type":"bayt","num":83,"seq":83,"chapter":"مقدمة","title":"البيت 83","page":"ج1 ص6","text":"ولكنها عن قسوة القلب قحطها ... فيا ضيعة الأعمار تمشى سبهللا","a":"ولكنها عن قسوة القلب قحطها","b":"فيا ضيعة الأعمار تمشى سبهللا","ref":["ibraz:88","siraj:5"]},{"id":"shatibiyya:84","bookId":"shatibiyya","type":"bayt","num":84,"seq":84,"chapter":"مقدمة","title":"البيت 84","page":"ج1 ص6","text":"بنفسي من استهدى إلى الله وحده ... وكان له القرآن شربا ومغسلا","a":"بنفسي من استهدى إلى الله وحده","b":"وكان له القرآن شربا ومغسلا","ref":["ibraz:89","siraj:5"]},{"id":"shatibiyya:85","bookId":"shatibiyya","type":"bayt","num":85,"seq":85,"chapter":"مقدمة","title":"البيت 85","page":"ج1 ص6","text":"وطابت عليه أرضه فتفتقت ... بكل عبير حين أصبح مخضلا","a":"وطابت عليه أرضه فتفتقت","b":"بكل عبير حين أصبح مخضلا","ref":["ibraz:90","siraj:5"]},{"id":"shatibiyya:86","bookId":"shatibiyya","type":"bayt","num":86,"seq":86,"chapter":"مقدمة","title":"البيت 86","page":"ج1 ص6","text":"فطوبى له والشوق يبعث همه ... وزند الأسى يهتاج في القلب مشعلا","a":"فطوبى له والشوق يبعث همه","b":"وزند الأسى يهتاج في القلب مشعلا","ref":["ibraz:91","siraj:5"]},{"id":"shatibiyya:87","bookId":"shatibiyya","type":"bayt","num":87,"seq":87,"chapter":"مقدمة","title":"البيت 87","page":"ج1 ص6","text":"هو المجتبى يغدو على الناس كلهم ... قريبا غريبا مستمالا مؤملا","a":"هو المجتبى يغدو على الناس كلهم","b":"قريبا غريبا مستمالا مؤملا","ref":["ibraz:92","siraj:5"]},{"id":"shatibiyya:88","bookId":"shatibiyya","type":"bayt","num":88,"seq":88,"chapter":"مقدمة","title":"البيت 88","page":"ج1 ص7","text":"يعد جميع الناس مولى لأنهم ... على ما قضاه الله يجرون أفعلا","a":"يعد جميع الناس مولى لأنهم","b":"على ما قضاه الله يجرون أفعلا","ref":["ibraz:93","siraj:5"]},{"id":"shatibiyya:89","bookId":"shatibiyya","type":"bayt","num":89,"seq":89,"chapter":"مقدمة","title":"البيت 89","page":"ج1 ص7","text":"يرى نفسه بالذم أولى لأنها ... على المجد لم تلعق من الصبر والألا","a":"يرى نفسه بالذم أولى لأنها","b":"على المجد لم تلعق من الصبر والألا","ref":["ibraz:94","siraj:5"]},{"id":"shatibiyya:90","bookId":"shatibiyya","type":"bayt","num":90,"seq":90,"chapter":"مقدمة","title":"البيت 90","page":"ج1 ص7","text":"وقد قيل كن كالكلب يقصيه ... أهله وما يأتلي في نصحهم متبذلا","a":"وقد قيل كن كالكلب يقصيه","b":"أهله وما يأتلي في نصحهم متبذلا","ref":["ibraz:95","siraj:5"]},{"id":"shatibiyya:91","bookId":"shatibiyya","type":"bayt","num":91,"seq":91,"chapter":"مقدمة","title":"البيت 91","page":"ج1 ص7","text":"لعل إله العرش يا إخوتي يقي ... جماعتنا كل المكاره هولا","a":"لعل إله العرش يا إخوتي يقي","b":"جماعتنا كل المكاره هولا","ref":["ibraz:96"]},{"id":"shatibiyya:92","bookId":"shatibiyya","type":"bayt","num":92,"seq":92,"chapter":"مقدمة","title":"البيت 92","page":"ج1 ص7","text":"ويجعلنا ممن يكون كتابه ... شفيعا لهم إذ ما نسوه فيمحلا","a":"ويجعلنا ممن يكون كتابه","b":"شفيعا لهم إذ ما نسوه فيمحلا","ref":["ibraz:97","siraj:5"]},{"id":"shatibiyya:93","bookId":"shatibiyya","type":"bayt","num":93,"seq":93,"chapter":"مقدمة","title":"البيت 93","page":"ج1 ص7","text":"وبالله حولى واعتصامي وقوتى ... ومالي إلا ستره متجللا","a":"وبالله حولى واعتصامي وقوتى","b":"ومالي إلا ستره متجللا","ref":["ibraz:98","siraj:5"]},{"id":"shatibiyya:94","bookId":"shatibiyya","type":"bayt","num":94,"seq":94,"chapter":"مقدمة","title":"البيت 94","page":"ج1 ص7","text":"فيا رب أنت الله حسبي وعدتي ... عليك اعتمادي ضارعا متوكلا","a":"فيا رب أنت الله حسبي وعدتي","b":"عليك اعتمادي ضارعا متوكلا","ref":["ibraz:99","siraj:5"]},{"id":"shatibiyya:95","bookId":"shatibiyya","type":"bayt","num":95,"seq":95,"chapter":"باب الاستعاذة","title":"البيت 95","page":"ج1 ص7","text":"إذا ما أردت الدهر تقرأ فاستعذ ... جهارا من الشيطان بالله مسجلا","a":"إذا ما أردت الدهر تقرأ فاستعذ","b":"جهارا من الشيطان بالله مسجلا","ref":["ibraz:101","siraj:6"]},{"id":"shatibiyya:96","bookId":"shatibiyya","type":"bayt","num":96,"seq":96,"chapter":"باب الاستعاذة","title":"البيت 96","page":"ج1 ص7","text":"على ما أتى في النحل يسرا ... وإن تزد لربك تنزيها فلست مجهلا","a":"على ما أتى في النحل يسرا","b":"وإن تزد لربك تنزيها فلست مجهلا","ref":["ibraz:102","siraj:6"]},{"id":"shatibiyya:97","bookId":"shatibiyya","type":"bayt","num":97,"seq":97,"chapter":"باب الاستعاذة","title":"البيت 97","page":"ج1 ص7","text":"وقد ذكروا لفظ الرسول فلم يزد ... ولو صح هذا النقل لم يبق مجملا","a":"وقد ذكروا لفظ الرسول فلم يزد","b":"ولو صح هذا النقل لم يبق مجملا","ref":["ibraz:103","siraj:6"]},{"id":"shatibiyya:98","bookId":"shatibiyya","type":"bayt","num":98,"seq":98,"chapter":"باب الاستعاذة","title":"البيت 98","page":"ج1 ص7","text":"وفيه مقال في الأصول فروعه ... فلا تعد منها باسقا ومظللا","a":"وفيه مقال في الأصول فروعه","b":"فلا تعد منها باسقا ومظللا","ref":["ibraz:104","siraj:6"]},{"id":"shatibiyya:99","bookId":"shatibiyya","type":"bayt","num":99,"seq":99,"chapter":"باب الاستعاذة","title":"البيت 99","page":"ج1 ص7","text":"وإخفاؤه فصل أباه وعاتنا ... وكم من فتى كالمهدوي فيه أعملا","a":"وإخفاؤه فصل أباه وعاتنا","b":"وكم من فتى كالمهدوي فيه أعملا","ref":["ibraz:105","siraj:6"]},{"id":"shatibiyya:100","bookId":"shatibiyya","type":"bayt","num":100,"seq":100,"chapter":"باب البسملة","title":"البيت 100","page":"ج1 ص8","text":"وبسمل بين السورتين بسنة ... رجال نموها درية وتحملا","a":"وبسمل بين السورتين بسنة","b":"رجال نموها درية وتحملا","ref":["ibraz:50","siraj:7"]},{"id":"shatibiyya:101","bookId":"shatibiyya","type":"bayt","num":101,"seq":101,"chapter":"باب البسملة","title":"البيت 101","page":"ج1 ص8","text":"ووصلك بين السورتين فصاحة ... وصل واسكتن كل جلاياه حصلا","a":"ووصلك بين السورتين فصاحة","b":"وصل واسكتن كل جلاياه حصلا","ref":["ibraz:108","siraj:7"]},{"id":"shatibiyya:102","bookId":"shatibiyya","type":"bayt","num":102,"seq":102,"chapter":"باب البسملة","title":"البيت 102","page":"ج1 ص8","text":"ولا نص كلا حب وجه ذكرته ... وفيها خلاف جيده واضح الطلا","a":"ولا نص كلا حب وجه ذكرته","b":"وفيها خلاف جيده واضح الطلا","ref":["ibraz:109","siraj:7"]},{"id":"shatibiyya:103","bookId":"shatibiyya","type":"bayt","num":103,"seq":103,"chapter":"باب البسملة","title":"البيت 103","page":"ج1 ص8","text":"وسكتهم المختار دون تنفس ... وبعضهم في الأربع الزهر بسملا","a":"وسكتهم المختار دون تنفس","b":"وبعضهم في الأربع الزهر بسملا","ref":["ibraz:110","siraj:7"]},{"id":"shatibiyya:104","bookId":"shatibiyya","type":"bayt","num":104,"seq":104,"chapter":"باب البسملة","title":"البيت 104","page":"ج1 ص8","text":"لهم دون نص وهو فيهن ساكت ... لحمزة فافهمه وليس مخذلا","a":"لهم دون نص وهو فيهن ساكت","b":"لحمزة فافهمه وليس مخذلا","ref":["ibraz:111","siraj:7"]},{"id":"shatibiyya:105","bookId":"shatibiyya","type":"bayt","num":105,"seq":105,"chapter":"باب البسملة","title":"البيت 105","page":"ج1 ص8","text":"ومهما تصلها أو بدأت براءة ... لتنزيلها بالسيف لست مبسملا","a":"ومهما تصلها أو بدأت براءة","b":"لتنزيلها بالسيف لست مبسملا","ref":["ibraz:61","siraj:7"]},{"id":"shatibiyya:106","bookId":"shatibiyya","type":"bayt","num":106,"seq":106,"chapter":"باب البسملة","title":"البيت 106","page":"ج1 ص8","text":"ولا بد منها في ابتدائك سورة ... سواها وفي الأجزاء خير من تلا","a":"ولا بد منها في ابتدائك سورة","b":"سواها وفي الأجزاء خير من تلا","ref":["ibraz:113","siraj:7"]},{"id":"shatibiyya:107","bookId":"shatibiyya","type":"bayt","num":107,"seq":107,"chapter":"سورة أم القرآن","title":"البيت 107","page":"ج1 ص8","text":"ومالك يوم الدين راويه ناصر ... وعند سراط والسراط ل قنبلا","a":"ومالك يوم الدين راويه ناصر","b":"وعند سراط والسراط ل قنبلا","ref":["ibraz:50","siraj:7"]},{"id":"shatibiyya:108","bookId":"shatibiyya","type":"bayt","num":108,"seq":108,"chapter":"سورة أم القرآن","title":"البيت 108","page":"ج1 ص8","text":"بحيث أتى والصاد زايا اشمها ... لدى خلف واشمم لخلاد الاولا","a":"بحيث أتى والصاد زايا اشمها","b":"لدى خلف واشمم لخلاد الاولا","ref":["ibraz:117"]},{"id":"shatibiyya:109","bookId":"shatibiyya","type":"bayt","num":109,"seq":109,"chapter":"سورة أم القرآن","title":"البيت 109","page":"ج1 ص8","text":"عليهم إليهم حمزة ولديهمو ... جميعا بضم الهاء وقفا وموصلا","a":"عليهم إليهم حمزة ولديهمو","b":"جميعا بضم الهاء وقفا وموصلا","ref":["ibraz:118","siraj:7"]},{"id":"shatibiyya:110","bookId":"shatibiyya","type":"bayt","num":110,"seq":110,"chapter":"سورة أم القرآن","title":"البيت 110","page":"ج1 ص8","text":"وصل ضم ميم الجمع قبل محرك ... دراكا وقالون بتخييره جلا","a":"وصل ضم ميم الجمع قبل محرك","b":"دراكا وقالون بتخييره جلا","ref":["ibraz:119","siraj:7"]},{"id":"shatibiyya:111","bookId":"shatibiyya","type":"bayt","num":111,"seq":111,"chapter":"سورة أم القرآن","title":"البيت 111","page":"ج1 ص9","text":"ومن قبل همز القطع صلها لورشهم ... وأسكنها الباقون بعد لتكملا","a":"ومن قبل همز القطع صلها لورشهم","b":"وأسكنها الباقون بعد لتكملا","ref":["ibraz:121","siraj:7"]},{"id":"shatibiyya:112","bookId":"shatibiyya","type":"bayt","num":112,"seq":112,"chapter":"سورة أم القرآن","title":"البيت 112","page":"ج1 ص9","text":"ومن دون وصل ضمها قبل ساكن ... لكل وبعد الهاء كسر فتى العلا","a":"ومن دون وصل ضمها قبل ساكن","b":"لكل وبعد الهاء كسر فتى العلا","ref":["ibraz:532","siraj:7"]},{"id":"shatibiyya:113","bookId":"shatibiyya","type":"bayt","num":113,"seq":113,"chapter":"سورة أم القرآن","title":"البيت 113","page":"ج1 ص9","text":"مع الكسر قبل الها أو الياء ساكنا ... وفي الوصل كسر الهاء بالضم شمللا","a":"مع الكسر قبل الها أو الياء ساكنا","b":"وفي الوصل كسر الهاء بالضم شمللا","ref":["ibraz:123","siraj:7"]},{"id":"shatibiyya:114","bookId":"shatibiyya","type":"bayt","num":114,"seq":114,"chapter":"سورة أم القرآن","title":"البيت 114","page":"ج1 ص9","text":"كما بهم الأسباب ثم عليهم ال ... قتال وقف للكل بالكسر مكملا","a":"كما بهم الأسباب ثم عليهم ال","b":"قتال وقف للكل بالكسر مكملا","ref":["ibraz:124","siraj:7"]},{"id":"shatibiyya:115","bookId":"shatibiyya","type":"bayt","num":115,"seq":115,"chapter":"باب الإدغام الكبير","title":"البيت 115","page":"ج1 ص9","text":"ودونك الادغام الكبير وقطبه ... أبو عمرو البصري فيه تحفلا","a":"ودونك الادغام الكبير وقطبه","b":"أبو عمرو البصري فيه تحفلا","ref":["ibraz:126","siraj:4"]},{"id":"shatibiyya:116","bookId":"shatibiyya","type":"bayt","num":116,"seq":116,"chapter":"باب الإدغام الكبير","title":"البيت 116","page":"ج1 ص9","text":"ففي كلمة عنه مناسككم وما ... سلككم وباقي الباب ليس معولا","a":"ففي كلمة عنه مناسككم وما","b":"سلككم وباقي الباب ليس معولا","ref":["ibraz:127","siraj:8"]},{"id":"shatibiyya:117","bookId":"shatibiyya","type":"bayt","num":117,"seq":117,"chapter":"باب الإدغام الكبير","title":"البيت 117","page":"ج1 ص9","text":"وما كان من مثلين في كلمتيهما ... فلا بد من إدغام ما كان أولا","a":"وما كان من مثلين في كلمتيهما","b":"فلا بد من إدغام ما كان أولا","ref":["ibraz:128","siraj:8"]},{"id":"shatibiyya:118","bookId":"shatibiyya","type":"bayt","num":118,"seq":118,"chapter":"باب الإدغام الكبير","title":"البيت 118","page":"ج1 ص9","text":"كيعلم ما فيه هدى وطبع على ... قلوبهم والعفو وأمر تمثلا","a":"كيعلم ما فيه هدى وطبع على","b":"قلوبهم والعفو وأمر تمثلا","ref":["ibraz:129","siraj:8"]},{"id":"shatibiyya:119","bookId":"shatibiyya","type":"bayt","num":119,"seq":119,"chapter":"باب الإدغام الكبير","title":"البيت 119","page":"ج1 ص9","text":"إذا لم يكن تا مخبر أو مخاطب ... أو المكتسي تنوينه أو مثقلا","a":"إذا لم يكن تا مخبر أو مخاطب","b":"أو المكتسي تنوينه أو مثقلا","ref":["ibraz:130","siraj:8"]},{"id":"shatibiyya:120","bookId":"shatibiyya","type":"bayt","num":120,"seq":120,"chapter":"باب الإدغام الكبير","title":"البيت 120","page":"ج1 ص9","text":"ككنت ترابا أنت تكره واسع ... عليم وأيضا تم ميقات مثلا","a":"ككنت ترابا أنت تكره واسع","b":"عليم وأيضا تم ميقات مثلا","ref":["ibraz:131","siraj:8"]},{"id":"shatibiyya:121","bookId":"shatibiyya","type":"bayt","num":121,"seq":121,"chapter":"باب الإدغام الكبير","title":"البيت 121","page":"ج1 ص9","text":"وقد أظهروا في الكاف يحزنك كفره ... إذ النون تخفى قبلها لتجملا","a":"وقد أظهروا في الكاف يحزنك كفره","b":"إذ النون تخفى قبلها لتجملا","ref":["ibraz:132","siraj:8"]},{"id":"shatibiyya:122","bookId":"shatibiyya","type":"bayt","num":122,"seq":122,"chapter":"باب الإدغام الكبير","title":"البيت 122","page":"ج1 ص9","text":"وعندهم الوجهان في كل موضع ... تسمى لأجل الحذف فيه معللا","a":"وعندهم الوجهان في كل موضع","b":"تسمى لأجل الحذف فيه معللا","ref":["ibraz:133","siraj:8"]},{"id":"shatibiyya:123","bookId":"shatibiyya","type":"bayt","num":123,"seq":123,"chapter":"باب الإدغام الكبير","title":"البيت 123","page":"ج1 ص10","text":"كيبتغ مجزوما وإن يك كاذبا ... ويخل لكم عن عالم طيب الخلا","a":"كيبتغ مجزوما وإن يك كاذبا","b":"ويخل لكم عن عالم طيب الخلا","ref":["ibraz:134","siraj:8"]},{"id":"shatibiyya:124","bookId":"shatibiyya","type":"bayt","num":124,"seq":124,"chapter":"باب الإدغام الكبير","title":"البيت 124","page":"ج1 ص10","text":"ويا قوم مالي ثم يا قوم من بلا ... خلاف على الإدغام لا شك أرسلا","a":"ويا قوم مالي ثم يا قوم من بلا","b":"خلاف على الإدغام لا شك أرسلا","ref":["ibraz:135","siraj:8"]},{"id":"shatibiyya:125","bookId":"shatibiyya","type":"bayt","num":125,"seq":125,"chapter":"باب الإدغام الكبير","title":"البيت 125","page":"ج1 ص10","text":"وإظهار قوم آل لوط لكونه ... قليل حروف رده من تنبلا","a":"وإظهار قوم آل لوط لكونه","b":"قليل حروف رده من تنبلا","ref":["ibraz:136","siraj:8"]},{"id":"shatibiyya:126","bookId":"shatibiyya","type":"bayt","num":126,"seq":126,"chapter":"باب الإدغام الكبير","title":"البيت 126","page":"ج1 ص10","text":"بإدغام لك كيدا ولو حج مظهر ... بإعلال ثانيه إذا صح لاعتلا","a":"بإدغام لك كيدا ولو حج مظهر","b":"بإعلال ثانيه إذا صح لاعتلا","ref":["ibraz:137","siraj:8"]},{"id":"shatibiyya:127","bookId":"shatibiyya","type":"bayt","num":127,"seq":127,"chapter":"باب الإدغام الكبير","title":"البيت 127","page":"ج1 ص10","text":"فإبداله من همزة هاء اصلها ... وقد قال بعض الناس من واو ابدلا","a":"فإبداله من همزة هاء اصلها","b":"وقد قال بعض الناس من واو ابدلا","ref":["ibraz:138","siraj:8"]},{"id":"shatibiyya:128","bookId":"shatibiyya","type":"bayt","num":128,"seq":128,"chapter":"باب الإدغام الكبير","title":"البيت 128","page":"ج1 ص10","text":"وواو هو المضموم هاء كهو ومن ... فأدغم ومن يظهر فبالمد عللا","a":"وواو هو المضموم هاء كهو ومن","b":"فأدغم ومن يظهر فبالمد عللا","ref":["ibraz:139","siraj:8"]},{"id":"shatibiyya:129","bookId":"shatibiyya","type":"bayt","num":129,"seq":129,"chapter":"باب الإدغام الكبير","title":"البيت 129","page":"ج1 ص10","text":"ويأتي يوم أدغموه ونحوه ... ولا فرق ينجي من على المد عولا","a":"ويأتي يوم أدغموه ونحوه","b":"ولا فرق ينجي من على المد عولا","ref":["ibraz:140","siraj:8"]},{"id":"shatibiyya:130","bookId":"shatibiyya","type":"bayt","num":130,"seq":130,"chapter":"باب الإدغام الكبير","title":"البيت 130","page":"ج1 ص10","text":"وقبل يئسن الياء في اللاء عارض ... سكونا أو اصلا فهو يظهر مسهلا","a":"وقبل يئسن الياء في اللاء عارض","b":"سكونا أو اصلا فهو يظهر مسهلا","ref":["ibraz:141","siraj:8"]},{"id":"shatibiyya:131","bookId":"shatibiyya","type":"bayt","num":131,"seq":131,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 131","page":"ج1 ص10","text":"وإن كلمة حرفان فيها تقاربا ... فإدغامه للقاف في الكاف مجتلا","a":"وإن كلمة حرفان فيها تقاربا","b":"فإدغامه للقاف في الكاف مجتلا","ref":["ibraz:143","siraj:9"]},{"id":"shatibiyya:132","bookId":"shatibiyya","type":"bayt","num":132,"seq":132,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 132","page":"ج1 ص10","text":"وهذا إذا ما قبله متحرك ... مبين وبعد الكاف ميم تخللا","a":"وهذا إذا ما قبله متحرك","b":"مبين وبعد الكاف ميم تخللا","ref":["ibraz:144","siraj:9"]},{"id":"shatibiyya:133","bookId":"shatibiyya","type":"bayt","num":133,"seq":133,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 133","page":"ج1 ص10","text":"كيرزقكم واثقكموا وخلقكمو ... وميثاقكم أظهر ونرزقك انجلا","a":"كيرزقكم واثقكموا وخلقكمو","b":"وميثاقكم أظهر ونرزقك انجلا"},{"id":"shatibiyya:134","bookId":"shatibiyya","type":"bayt","num":134,"seq":134,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 134","page":"ج1 ص10","text":"وادغام ذي التحريم طلقكن قل ... أحق وبالتأنيث والجمع أثقلا","a":"وادغام ذي التحريم طلقكن قل","b":"أحق وبالتأنيث والجمع أثقلا","ref":["ibraz:146","siraj:9"]},{"id":"shatibiyya:135","bookId":"shatibiyya","type":"bayt","num":135,"seq":135,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 135","page":"ج1 ص10","text":"ومهما يكونا كلمتين فمدغم ... أوائل كلم البيت بعد على الولا","a":"ومهما يكونا كلمتين فمدغم","b":"أوائل كلم البيت بعد على الولا","ref":["ibraz:147","siraj:9"]},{"id":"shatibiyya:136","bookId":"shatibiyya","type":"bayt","num":136,"seq":136,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 136","page":"ج1 ص11","text":"شفا لم تضق نفسا بها رم دوا ضن ... ثوى كان ذا حسن سأى منه قد جلا","a":"شفا لم تضق نفسا بها رم دوا ضن","b":"ثوى كان ذا حسن سأى منه قد جلا","ref":["ibraz:148"]},{"id":"shatibiyya:137","bookId":"shatibiyya","type":"bayt","num":137,"seq":137,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 137","page":"ج1 ص11","text":"إذا لم ينون أو يكن تا مخاطب ... وما ليس مجزوما ولا متثقلا","a":"إذا لم ينون أو يكن تا مخاطب","b":"وما ليس مجزوما ولا متثقلا","ref":["ibraz:149"]},{"id":"shatibiyya:138","bookId":"shatibiyya","type":"bayt","num":138,"seq":138,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 138","page":"ج1 ص11","text":"فزحزح عن النار الذي حاه مدغم ... وفي الكاف قاف وهو في القاف أدخلا","a":"فزحزح عن النار الذي حاه مدغم","b":"وفي الكاف قاف وهو في القاف أدخلا","ref":["ibraz:150","siraj:9"]},{"id":"shatibiyya:139","bookId":"shatibiyya","type":"bayt","num":139,"seq":139,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 139","page":"ج1 ص11","text":"خلق كل شيء لك قصورا وأظهرا ... إذا سكن الحرف الذي قبل أقبلا","a":"خلق كل شيء لك قصورا وأظهرا","b":"إذا سكن الحرف الذي قبل أقبلا","ref":["ibraz:151","siraj:9"]},{"id":"shatibiyya:140","bookId":"shatibiyya","type":"bayt","num":140,"seq":140,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 140","page":"ج1 ص11","text":"وفي ذي المعارج تعرج الجيم مدغم ... ومن قبل أخرج شطأه قد تثقلا","a":"وفي ذي المعارج تعرج الجيم مدغم","b":"ومن قبل أخرج شطأه قد تثقلا","ref":["ibraz:152","siraj:9"]},{"id":"shatibiyya:141","bookId":"shatibiyya","type":"bayt","num":141,"seq":141,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 141","page":"ج1 ص11","text":"وعند سبيلا شين ذي العرش مدغم ... وضاد لبعض شأنهم مدغما تلا","a":"وعند سبيلا شين ذي العرش مدغم","b":"وضاد لبعض شأنهم مدغما تلا","ref":["ibraz:153","siraj:9"]},{"id":"shatibiyya:142","bookId":"shatibiyya","type":"bayt","num":142,"seq":142,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 142","page":"ج1 ص11","text":"وفي زوجت سين النفوس ومدغم ... له الراس شيبا باختلاف توصلا","a":"وفي زوجت سين النفوس ومدغم","b":"له الراس شيبا باختلاف توصلا","ref":["ibraz:154","siraj:9"]},{"id":"shatibiyya:143","bookId":"shatibiyya","type":"bayt","num":143,"seq":143,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 143","page":"ج1 ص11","text":"وللدال كلم ترب سهل ذكا شذا ... ضفا ثم زهد صدقه ظاهر جلا","a":"وللدال كلم ترب سهل ذكا شذا","b":"ضفا ثم زهد صدقه ظاهر جلا","ref":["ibraz:155","siraj:9"]},{"id":"shatibiyya:144","bookId":"shatibiyya","type":"bayt","num":144,"seq":144,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 144","page":"ج1 ص11","text":"ولم تدغم مفتوحة بعد ساكن ... بحرف بغير التاء فاعلمه واعملا","a":"ولم تدغم مفتوحة بعد ساكن","b":"بحرف بغير التاء فاعلمه واعملا","ref":["ibraz:156","siraj:9"]},{"id":"shatibiyya:145","bookId":"shatibiyya","type":"bayt","num":145,"seq":145,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 145","page":"ج1 ص11","text":"وفي عشرها والطاء تدغم تاؤها ... وفي أحرف وجهان عنه تهللا","a":"وفي عشرها والطاء تدغم تاؤها","b":"وفي أحرف وجهان عنه تهللا","ref":["ibraz:157","siraj:9"]},{"id":"shatibiyya:146","bookId":"shatibiyya","type":"bayt","num":146,"seq":146,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 146","page":"ج1 ص11","text":"فمع حملوا التوراة ثم الزكاة قل ... وقل آت ذا ال ولتأت طائفة علا","a":"فمع حملوا التوراة ثم الزكاة قل","b":"وقل آت ذا ال ولتأت طائفة علا","ref":["ibraz:158","siraj:9"]},{"id":"shatibiyya:147","bookId":"shatibiyya","type":"bayt","num":147,"seq":147,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 147","page":"ج1 ص11","text":"وفي جئت شيئا أظهروا لخطابه ... ونقصانه والكسر الادغام سهلا","a":"وفي جئت شيئا أظهروا لخطابه","b":"ونقصانه والكسر الادغام سهلا","ref":["ibraz:159","siraj:9"]},{"id":"shatibiyya:148","bookId":"shatibiyya","type":"bayt","num":148,"seq":148,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 148","page":"ج1 ص12","text":"وفي خمسة وهي الأوائل ثاؤها ... وفي الصاد ثم السين ذال تدخلا","a":"وفي خمسة وهي الأوائل ثاؤها","b":"وفي الصاد ثم السين ذال تدخلا","ref":["ibraz:160","siraj:9"]},{"id":"shatibiyya:149","bookId":"shatibiyya","type":"bayt","num":149,"seq":149,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 149","page":"ج1 ص12","text":"وفي اللام راء وهي في الرا وأظهرا ... إذا انفتحا بعد المسكن منرلا","a":"وفي اللام راء وهي في الرا وأظهرا","b":"إذا انفتحا بعد المسكن منرلا","ref":["ibraz:161","siraj:9"]},{"id":"shatibiyya:150","bookId":"shatibiyya","type":"bayt","num":150,"seq":150,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 150","page":"ج1 ص12","text":"سوى قال ثم النون تدغم فيهما ... على إثر تحريك سوى نحن مسجلا","a":"سوى قال ثم النون تدغم فيهما","b":"على إثر تحريك سوى نحن مسجلا","ref":["ibraz:162","siraj:10"]},{"id":"shatibiyya:151","bookId":"shatibiyya","type":"bayt","num":151,"seq":151,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 151","page":"ج1 ص12","text":"وتسكن عنه الميم من قبل بائها ... على إثر تحريك فتخفى تنزلا","a":"وتسكن عنه الميم من قبل بائها","b":"على إثر تحريك فتخفى تنزلا","ref":["ibraz:163","siraj:10"]},{"id":"shatibiyya:152","bookId":"shatibiyya","type":"bayt","num":152,"seq":152,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 152","page":"ج1 ص12","text":"وفي من يشاء با يعذب حيثما ... أتى مدغم فادر الأصول لتأصلا","a":"وفي من يشاء با يعذب حيثما","b":"أتى مدغم فادر الأصول لتأصلا","ref":["ibraz:164","siraj:10"]},{"id":"shatibiyya:153","bookId":"shatibiyya","type":"bayt","num":153,"seq":153,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 153","page":"ج1 ص12","text":"ولا يمنع الإدغام إذ هو عارض ... إمالة كالأبرار والنار أثقلا","a":"ولا يمنع الإدغام إذ هو عارض","b":"إمالة كالأبرار والنار أثقلا","ref":["ibraz:165","siraj:10"]},{"id":"shatibiyya:154","bookId":"shatibiyya","type":"bayt","num":154,"seq":154,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 154","page":"ج1 ص12","text":"وأشمم ورم في غير باء وميمها ... مع الباء أو ميم وكن متأملا","a":"وأشمم ورم في غير باء وميمها","b":"مع الباء أو ميم وكن متأملا","ref":["ibraz:166","siraj:10"]},{"id":"shatibiyya:155","bookId":"shatibiyya","type":"bayt","num":155,"seq":155,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 155","page":"ج1 ص12","text":"وإدغام حرف قبله صح ساكن ... عسير وبالإخفاء طبق مفصلا","a":"وإدغام حرف قبله صح ساكن","b":"عسير وبالإخفاء طبق مفصلا","ref":["ibraz:167","siraj:10"]},{"id":"shatibiyya:156","bookId":"shatibiyya","type":"bayt","num":156,"seq":156,"chapter":"باب إدغام الحرفين المتقاربين في كلمة وفي كلمتين","title":"البيت 156","page":"ج1 ص12","text":"خذ العفو وأمر ثم من بعد ظلمه ... وفي المهد ثم الخلد والعلم فاشملا","a":"خذ العفو وأمر ثم من بعد ظلمه","b":"وفي المهد ثم الخلد والعلم فاشملا","ref":["ibraz:168","siraj:10"]},{"id":"shatibiyya:157","bookId":"shatibiyya","type":"bayt","num":157,"seq":157,"chapter":"باب هاء الكناية","title":"البيت 157","page":"ج1 ص12","text":"ولم يصلوا ها مضمر قبل ساكن ... وما قبله التحريك للكل وصلا","a":"ولم يصلوا ها مضمر قبل ساكن","b":"وما قبله التحريك للكل وصلا","ref":["ibraz:171","siraj:11"]},{"id":"shatibiyya:158","bookId":"shatibiyya","type":"bayt","num":158,"seq":158,"chapter":"باب هاء الكناية","title":"البيت 158","page":"ج1 ص12","text":"وما قبله التسكين لابن كثيرهم ... وفيه مهانا معه حفص أخو ولا","a":"وما قبله التسكين لابن كثيرهم","b":"وفيه مهانا معه حفص أخو ولا","ref":["ibraz:70","siraj:11"]},{"id":"shatibiyya:159","bookId":"shatibiyya","type":"bayt","num":159,"seq":159,"chapter":"باب هاء الكناية","title":"البيت 159","page":"ج1 ص12","text":"وسكن يؤده مع نوله ونصله ... ونؤته منها فاعتبر صافيا حلا","a":"وسكن يؤده مع نوله ونصله","b":"ونؤته منها فاعتبر صافيا حلا","ref":["ibraz:51","siraj:11"]},{"id":"shatibiyya:160","bookId":"shatibiyya","type":"bayt","num":160,"seq":160,"chapter":"باب هاء الكناية","title":"البيت 160","page":"ج1 ص12","text":"وعنهم وعن حفص فألقه ويتقه ... حمى صفوه قوم بخلف وأنهلا","a":"وعنهم وعن حفص فألقه ويتقه","b":"حمى صفوه قوم بخلف وأنهلا","ref":["ibraz:174","siraj:11"]},{"id":"shatibiyya:161","bookId":"shatibiyya","type":"bayt","num":161,"seq":161,"chapter":"باب هاء الكناية","title":"البيت 161","page":"ج1 ص13","text":"وقل بسكون القاف والقصر حفصهم ... وياته لدى طه بالاسكان يجتلا","a":"وقل بسكون القاف والقصر حفصهم","b":"وياته لدى طه بالاسكان يجتلا","ref":["ibraz:175","siraj:11"]},{"id":"shatibiyya:162","bookId":"shatibiyya","type":"bayt","num":162,"seq":162,"chapter":"باب هاء الكناية","title":"البيت 162","page":"ج1 ص13","text":"وفي الكل قصر الهاء بان لسانه ... بخلف وفي طه بوجهين بجلا","a":"وفي الكل قصر الهاء بان لسانه","b":"بخلف وفي طه بوجهين بجلا","ref":["siraj:11"]},{"id":"shatibiyya:163","bookId":"shatibiyya","type":"bayt","num":163,"seq":163,"chapter":"باب هاء الكناية","title":"البيت 163","page":"ج1 ص13","text":"وإسكان يرضه يمنه لبس طيب ... بخلفهما والقصر فاذكره نوفلا","a":"وإسكان يرضه يمنه لبس طيب","b":"بخلفهما والقصر فاذكره نوفلا","ref":["ibraz:177","siraj:11"]},{"id":"shatibiyya:164","bookId":"shatibiyya","type":"bayt","num":164,"seq":164,"chapter":"باب هاء الكناية","title":"البيت 164","page":"ج1 ص13","text":"له الرحب والزلزال خيرا يره بها ... وشرا يره حرفيه سكن ليسهلا","a":"له الرحب والزلزال خيرا يره بها","b":"وشرا يره حرفيه سكن ليسهلا","ref":["ibraz:178","siraj:11"]},{"id":"shatibiyya:165","bookId":"shatibiyya","type":"bayt","num":165,"seq":165,"chapter":"باب هاء الكناية","title":"البيت 165","page":"ج1 ص13","text":"وعى نفر أرجئه بالهمز ساكنا ... وفي الهاء ضم لف دعواه حرملا","a":"وعى نفر أرجئه بالهمز ساكنا","b":"وفي الهاء ضم لف دعواه حرملا","ref":["ibraz:179","siraj:11"]},{"id":"shatibiyya:166","bookId":"shatibiyya","type":"bayt","num":166,"seq":166,"chapter":"باب هاء الكناية","title":"البيت 166","page":"ج1 ص13","text":"وأسكن نصيرا فاز واكسر لغيرهم ... وصلها جوادا دون ريب لتوصلا","a":"وأسكن نصيرا فاز واكسر لغيرهم","b":"وصلها جوادا دون ريب لتوصلا","ref":["ibraz:180","siraj:11"]},{"id":"shatibiyya:167","bookId":"shatibiyya","type":"bayt","num":167,"seq":167,"chapter":"باب المد والقصر","title":"البيت 167","page":"ج1 ص13","text":"إذا ألف أو ياؤها بعد كسرة ... أو الواو عن ضم لقي الهمز طولا","a":"إذا ألف أو ياؤها بعد كسرة","b":"أو الواو عن ضم لقي الهمز طولا","ref":["ibraz:182","siraj:12"]},{"id":"shatibiyya:168","bookId":"shatibiyya","type":"bayt","num":168,"seq":168,"chapter":"باب المد والقصر","title":"البيت 168","page":"ج1 ص13","text":"فإن ينفصل فالقصر بادره طالبا ... بخلفهما يرويك درا ومخضلا","a":"فإن ينفصل فالقصر بادره طالبا","b":"بخلفهما يرويك درا ومخضلا","ref":["siraj:12"]},{"id":"shatibiyya:169","bookId":"shatibiyya","type":"bayt","num":169,"seq":169,"chapter":"باب المد والقصر","title":"البيت 169","page":"ج1 ص13","text":"كجئ وعن سوء وشاء اتصاله ... ومفصوله في أمها أمره إلى","a":"كجئ وعن سوء وشاء اتصاله","b":"ومفصوله في أمها أمره إلى"},{"id":"shatibiyya:170","bookId":"shatibiyya","type":"bayt","num":170,"seq":170,"chapter":"باب المد والقصر","title":"البيت 170","page":"ج1 ص13","text":"وما بعد همز ثابت أو مغير ... فقصر وقد يروى لورش مطولا","a":"وما بعد همز ثابت أو مغير","b":"فقصر وقد يروى لورش مطولا","ref":["ibraz:185","siraj:12"]},{"id":"shatibiyya:171","bookId":"shatibiyya","type":"bayt","num":171,"seq":171,"chapter":"باب المد والقصر","title":"البيت 171","page":"ج1 ص13","text":"ووسطه قوم كآمن هؤلا ... ءآلهة آتى للايمان مثلا","a":"ووسطه قوم كآمن هؤلا","b":"ءآلهة آتى للايمان مثلا","ref":["ibraz:186","siraj:12"]},{"id":"shatibiyya:172","bookId":"shatibiyya","type":"bayt","num":172,"seq":172,"chapter":"باب المد والقصر","title":"البيت 172","page":"ج1 ص13","text":"سوى ياء إسراءيل أو بعد ساكن ... صحيح كقرآن ومسئولا اسألا","a":"سوى ياء إسراءيل أو بعد ساكن","b":"صحيح كقرآن ومسئولا اسألا"},{"id":"shatibiyya:173","bookId":"shatibiyya","type":"bayt","num":173,"seq":173,"chapter":"باب المد والقصر","title":"البيت 173","page":"ج1 ص14","text":"وما بعد همز الوصل إيت ... وبعضهم يؤاخذكم آلان مستفهما تلا","a":"وما بعد همز الوصل إيت","b":"وبعضهم يؤاخذكم آلان مستفهما تلا","ref":["siraj:12"]},{"id":"shatibiyya:174","bookId":"shatibiyya","type":"bayt","num":174,"seq":174,"chapter":"باب المد والقصر","title":"البيت 174","page":"ج1 ص14","text":"وعاد الاولى وابن غلبون طاهر ... بقصر جميع الباب قال وقولا","a":"وعاد الاولى وابن غلبون طاهر","b":"بقصر جميع الباب قال وقولا"},{"id":"shatibiyya:175","bookId":"shatibiyya","type":"bayt","num":175,"seq":175,"chapter":"باب المد والقصر","title":"البيت 175","page":"ج1 ص14","text":"وعن كلهم بالمد ما قبل ساكن ... وعند سكون الوقف وجهان أصلا","a":"وعن كلهم بالمد ما قبل ساكن","b":"وعند سكون الوقف وجهان أصلا","ref":["ibraz:190","siraj:3"]},{"id":"shatibiyya:176","bookId":"shatibiyya","type":"bayt","num":176,"seq":176,"chapter":"باب المد والقصر","title":"البيت 176","page":"ج1 ص14","text":"ومد له عند الفواتح مشبعا ... وفي عين الوجهان والطول فضلا","a":"ومد له عند الفواتح مشبعا","b":"وفي عين الوجهان والطول فضلا","ref":["ibraz:191","siraj:12"]},{"id":"shatibiyya:177","bookId":"shatibiyya","type":"bayt","num":177,"seq":177,"chapter":"باب المد والقصر","title":"البيت 177","page":"ج1 ص14","text":"وفي نحو طه القصر إذ ليس ساكن ... وما في ألف من حرف مد فيمطلا","a":"وفي نحو طه القصر إذ ليس ساكن","b":"وما في ألف من حرف مد فيمطلا","ref":["ibraz:192","siraj:12"]},{"id":"shatibiyya:178","bookId":"shatibiyya","type":"bayt","num":178,"seq":178,"chapter":"باب المد والقصر","title":"البيت 178","page":"ج1 ص14","text":"وإن تسكن اليا بين فتح وهمزة ... بكلمة أو واو فوجهان جملا","a":"وإن تسكن اليا بين فتح وهمزة","b":"بكلمة أو واو فوجهان جملا","ref":["ibraz:193","siraj:13"]},{"id":"shatibiyya:179","bookId":"shatibiyya","type":"bayt","num":179,"seq":179,"chapter":"باب المد والقصر","title":"البيت 179","page":"ج1 ص14","text":"بطول وقصر وصل ورش ووقفه ... وعند سكون الوقف للكل أعملا","a":"بطول وقصر وصل ورش ووقفه","b":"وعند سكون الوقف للكل أعملا","ref":["ibraz:194","siraj:13"]},{"id":"shatibiyya:180","bookId":"shatibiyya","type":"bayt","num":180,"seq":180,"chapter":"باب المد والقصر","title":"البيت 180","page":"ج1 ص14","text":"وعنهم سقوط المد فيه وورشهم ... يوافقهم في حيث لا همز مدخلا","a":"وعنهم سقوط المد فيه وورشهم","b":"يوافقهم في حيث لا همز مدخلا","ref":["ibraz:195","siraj:13"]},{"id":"shatibiyya:181","bookId":"shatibiyya","type":"bayt","num":181,"seq":181,"chapter":"باب المد والقصر","title":"البيت 181","page":"ج1 ص14","text":"وفي واو سوآت خلاف لورشهم ... وعن كل الموءودة اقصر وموئلا","a":"وفي واو سوآت خلاف لورشهم","b":"وعن كل الموءودة اقصر وموئلا","ref":["ibraz:196","siraj:13"]},{"id":"shatibiyya:182","bookId":"shatibiyya","type":"bayt","num":182,"seq":182,"chapter":"باب الهمزتين من كلمة","title":"البيت 182","page":"ج1 ص14","text":"وتسهيل أخرى همزتين بكلمة ... سما وبذات الفتح خلف لتجملا","a":"وتسهيل أخرى همزتين بكلمة","b":"سما وبذات الفتح خلف لتجملا","ref":["ibraz:198","siraj:14"]},{"id":"shatibiyya:183","bookId":"shatibiyya","type":"bayt","num":183,"seq":183,"chapter":"باب الهمزتين من كلمة","title":"البيت 183","page":"ج1 ص14","text":"وقل ألفا عن أهل مصر تبدلت ... لورش وفي بغداد يروى مسهلا","a":"وقل ألفا عن أهل مصر تبدلت","b":"لورش وفي بغداد يروى مسهلا","ref":["ibraz:199","siraj:14"]},{"id":"shatibiyya:184","bookId":"shatibiyya","type":"bayt","num":184,"seq":184,"chapter":"باب الهمزتين من كلمة","title":"البيت 184","page":"ج1 ص14","text":"وحققها في فصلت صحبة ءأع ... جمي والاولى أسقطن لتسهلا","a":"وحققها في فصلت صحبة ءأع","b":"جمي والاولى أسقطن لتسهلا","ref":["ibraz:200","siraj:14"]},{"id":"shatibiyya:185","bookId":"shatibiyya","type":"bayt","num":185,"seq":185,"chapter":"باب الهمزتين من كلمة","title":"البيت 185","page":"ج1 ص14","text":"وهمزة أذهبتم في الاحقاف شفعت ... بأخرى كما دامت وصالا موصلا","a":"وهمزة أذهبتم في الاحقاف شفعت","b":"بأخرى كما دامت وصالا موصلا","ref":["ibraz:201","siraj:14"]},{"id":"shatibiyya:186","bookId":"shatibiyya","type":"bayt","num":186,"seq":186,"chapter":"باب الهمزتين من كلمة","title":"البيت 186","page":"ج1 ص15","text":"وفي نون في أن كان شفع حمزة ... وشعبة أيضا والدمشقي مسهلا","a":"وفي نون في أن كان شفع حمزة","b":"وشعبة أيضا والدمشقي مسهلا","ref":["ibraz:202","siraj:14"]},{"id":"shatibiyya:187","bookId":"shatibiyya","type":"bayt","num":187,"seq":187,"chapter":"باب الهمزتين من كلمة","title":"البيت 187","page":"ج1 ص15","text":"وفي آل عمران عن ابن كثيرهم ... يشفع أن يؤتى إلى ما تسهلا","a":"وفي آل عمران عن ابن كثيرهم","b":"يشفع أن يؤتى إلى ما تسهلا","ref":["ibraz:203","siraj:14"]},{"id":"shatibiyya:188","bookId":"shatibiyya","type":"bayt","num":188,"seq":188,"chapter":"باب الهمزتين من كلمة","title":"البيت 188","page":"ج1 ص15","text":"وطه وفي الأعراف والشعرا بها ... ءآمنتم للكل ثالثا ابدلا","a":"وطه وفي الأعراف والشعرا بها","b":"ءآمنتم للكل ثالثا ابدلا","ref":["ibraz:204","siraj:14"]},{"id":"shatibiyya:189","bookId":"shatibiyya","type":"bayt","num":189,"seq":189,"chapter":"باب الهمزتين من كلمة","title":"البيت 189","page":"ج1 ص15","text":"وحقق ثان صحبة ولقنبل ... بإسقاطه الأولى بطه تقبلا","a":"وحقق ثان صحبة ولقنبل","b":"بإسقاطه الأولى بطه تقبلا","ref":["ibraz:205","siraj:14"]},{"id":"shatibiyya:190","bookId":"shatibiyya","type":"bayt","num":190,"seq":190,"chapter":"باب الهمزتين من كلمة","title":"البيت 190","page":"ج1 ص15","text":"وفي كلها حفص وأبدل قنبل ... في الاعراف منها الواو والملك موصلا","a":"وفي كلها حفص وأبدل قنبل","b":"في الاعراف منها الواو والملك موصلا","ref":["ibraz:206","siraj:14"]},{"id":"shatibiyya:191","bookId":"shatibiyya","type":"bayt","num":191,"seq":191,"chapter":"باب الهمزتين من كلمة","title":"البيت 191","page":"ج1 ص15","text":"وإن همز وصل بين لام مسكن ... وهمزة الاستفهام فامدده مبدلا","a":"وإن همز وصل بين لام مسكن","b":"وهمزة الاستفهام فامدده مبدلا","ref":["ibraz:207","siraj:14"]},{"id":"shatibiyya:192","bookId":"shatibiyya","type":"bayt","num":192,"seq":192,"chapter":"باب الهمزتين من كلمة","title":"البيت 192","page":"ج1 ص15","text":"فللكل ذا أولى ويقصره الذي ... يسهل عن كل كآلان مثلا","a":"فللكل ذا أولى ويقصره الذي","b":"يسهل عن كل كآلان مثلا","ref":["ibraz:208","siraj:14"]},{"id":"shatibiyya:193","bookId":"shatibiyya","type":"bayt","num":193,"seq":193,"chapter":"باب الهمزتين من كلمة","title":"البيت 193","page":"ج1 ص15","text":"ولا مد بين الهمزتين هنا ولا ... بحيث ثلاث يتفقن تنزلا","a":"ولا مد بين الهمزتين هنا ولا","b":"بحيث ثلاث يتفقن تنزلا","ref":["ibraz:209","siraj:14"]},{"id":"shatibiyya:194","bookId":"shatibiyya","type":"bayt","num":194,"seq":194,"chapter":"باب الهمزتين من كلمة","title":"البيت 194","page":"ج1 ص15","text":"وأضرب جمع الهمزتين ثلاثة ... ءأنذرتهم أم لم أئنا أءنزلا","a":"وأضرب جمع الهمزتين ثلاثة","b":"ءأنذرتهم أم لم أئنا أءنزلا","ref":["ibraz:210","siraj:14"]},{"id":"shatibiyya:195","bookId":"shatibiyya","type":"bayt","num":195,"seq":195,"chapter":"باب الهمزتين من كلمة","title":"البيت 195","page":"ج1 ص15","text":"ومدك قبل الفتح والكسر حجة ... بها لذ وقبل الكسر خلف له ولا","a":"ومدك قبل الفتح والكسر حجة","b":"بها لذ وقبل الكسر خلف له ولا","ref":["ibraz:211","siraj:14"]},{"id":"shatibiyya:196","bookId":"shatibiyya","type":"bayt","num":196,"seq":196,"chapter":"باب الهمزتين من كلمة","title":"البيت 196","page":"ج1 ص15","text":"وفي سبعة لا خلف عنه بمريم ... وفي حرفي الأعراف والشعرا العلا","a":"وفي سبعة لا خلف عنه بمريم","b":"وفي حرفي الأعراف والشعرا العلا","ref":["ibraz:212","siraj:14"]},{"id":"shatibiyya:197","bookId":"shatibiyya","type":"bayt","num":197,"seq":197,"chapter":"باب الهمزتين من كلمة","title":"البيت 197","page":"ج1 ص15","text":"أئنك آئفكا معا فوق صادها ... وفي فصلت حرف وبالخلف سهلا","a":"أئنك آئفكا معا فوق صادها","b":"وفي فصلت حرف وبالخلف سهلا","ref":["ibraz:213"]},{"id":"shatibiyya:198","bookId":"shatibiyya","type":"bayt","num":198,"seq":198,"chapter":"باب الهمزتين من كلمة","title":"البيت 198","page":"ج1 ص15","text":"وآئمة بالخلف قد مد وحده ... وسهل سما وصفا وفي النحو أبدلا","a":"وآئمة بالخلف قد مد وحده","b":"وسهل سما وصفا وفي النحو أبدلا","ref":["ibraz:214","siraj:14"]},{"id":"shatibiyya:199","bookId":"shatibiyya","type":"bayt","num":199,"seq":199,"chapter":"باب الهمزتين من كلمة","title":"البيت 199","page":"ج1 ص16","text":"ومدك قبل الضم لبى حبيبه ... بخلفهما برا وجاء ليفصلا","a":"ومدك قبل الضم لبى حبيبه","b":"بخلفهما برا وجاء ليفصلا","ref":["ibraz:215","siraj:14"]},{"id":"shatibiyya:200","bookId":"shatibiyya","type":"bayt","num":200,"seq":200,"chapter":"باب الهمزتين من كلمة","title":"البيت 200","page":"ج1 ص16","text":"وفي آل عمران رووا لهشامهم ... كحفص وفي الباقي كقالون واعتلا","a":"وفي آل عمران رووا لهشامهم","b":"كحفص وفي الباقي كقالون واعتلا","ref":["ibraz:216","siraj:14"]},{"id":"shatibiyya:201","bookId":"shatibiyya","type":"bayt","num":201,"seq":201,"chapter":"باب الهمزتين من كلمتين","title":"البيت 201","page":"ج1 ص16","text":"وأسقط الأولى في اتفاقهما معا ... إذا كانتا من كلمتين فتى العلا","a":"وأسقط الأولى في اتفاقهما معا","b":"إذا كانتا من كلمتين فتى العلا","ref":["ibraz:63","siraj:15"]},{"id":"shatibiyya:202","bookId":"shatibiyya","type":"bayt","num":202,"seq":202,"chapter":"باب الهمزتين من كلمتين","title":"البيت 202","page":"ج1 ص16","text":"كجا أمرنا من السما إن أوليا ... أولئك أنواع اتفاق تجملا","a":"كجا أمرنا من السما إن أوليا","b":"أولئك أنواع اتفاق تجملا","ref":["ibraz:219"]},{"id":"shatibiyya:203","bookId":"shatibiyya","type":"bayt","num":203,"seq":203,"chapter":"باب الهمزتين من كلمتين","title":"البيت 203","page":"ج1 ص16","text":"وقالون والبزي في الفتح وافقا ... وفي غيره كاليا وكالواو سهلا","a":"وقالون والبزي في الفتح وافقا","b":"وفي غيره كاليا وكالواو سهلا","ref":["ibraz:220","siraj:15"]},{"id":"shatibiyya:204","bookId":"shatibiyya","type":"bayt","num":204,"seq":204,"chapter":"باب الهمزتين من كلمتين","title":"البيت 204","page":"ج1 ص16","text":"وبالسوء إلا أبدلا ثم أدغما ... وفيه خلاف عنهما ليس مقفلا","a":"وبالسوء إلا أبدلا ثم أدغما","b":"وفيه خلاف عنهما ليس مقفلا","ref":["ibraz:221","siraj:15"]},{"id":"shatibiyya:205","bookId":"shatibiyya","type":"bayt","num":205,"seq":205,"chapter":"باب الهمزتين من كلمتين","title":"البيت 205","page":"ج1 ص16","text":"والاخرى كمد عند ورش وقنبل ... وقد قيل محض المد عنها تبدلا","a":"والاخرى كمد عند ورش وقنبل","b":"وقد قيل محض المد عنها تبدلا","ref":["ibraz:222","siraj:15"]},{"id":"shatibiyya:206","bookId":"shatibiyya","type":"bayt","num":206,"seq":206,"chapter":"باب الهمزتين من كلمتين","title":"البيت 206","page":"ج1 ص16","text":"وفي هؤلا إن والبغا إن لورشهم ... بياء خفيف الكسر بعضهم تلا","a":"وفي هؤلا إن والبغا إن لورشهم","b":"بياء خفيف الكسر بعضهم تلا","ref":["ibraz:223"]},{"id":"shatibiyya:207","bookId":"shatibiyya","type":"bayt","num":207,"seq":207,"chapter":"باب الهمزتين من كلمتين","title":"البيت 207","page":"ج1 ص16","text":"وإن حرف مد قبل همز مغير ... يجز قصره والمد ما زال أعدلا","a":"وإن حرف مد قبل همز مغير","b":"يجز قصره والمد ما زال أعدلا","ref":["ibraz:207","siraj:15"]},{"id":"shatibiyya:208","bookId":"shatibiyya","type":"bayt","num":208,"seq":208,"chapter":"باب الهمزتين من كلمتين","title":"البيت 208","page":"ج1 ص16","text":"وتسهيل الاخرى في اختلافهما سما ... تفيء إلى مع جاء أمة انزلا","a":"وتسهيل الاخرى في اختلافهما سما","b":"تفيء إلى مع جاء أمة انزلا","ref":["ibraz:225","siraj:15"]},{"id":"shatibiyya:209","bookId":"shatibiyya","type":"bayt","num":209,"seq":209,"chapter":"باب الهمزتين من كلمتين","title":"البيت 209","page":"ج1 ص16","text":"نشاء أصبنا والسماء أو ائتنا ... فنوعان قل كاليا وكالواو سهلا","a":"نشاء أصبنا والسماء أو ائتنا","b":"فنوعان قل كاليا وكالواو سهلا","ref":["ibraz:226","siraj:15"]},{"id":"shatibiyya:210","bookId":"shatibiyya","type":"bayt","num":210,"seq":210,"chapter":"باب الهمزتين من كلمتين","title":"البيت 210","page":"ج1 ص16","text":"ونوعان منها أبدلا منهما وقل ... يشاء إلى كالياء أقيس معدلا","a":"ونوعان منها أبدلا منهما وقل","b":"يشاء إلى كالياء أقيس معدلا","ref":["ibraz:227","siraj:15"]},{"id":"shatibiyya:211","bookId":"shatibiyya","type":"bayt","num":211,"seq":211,"chapter":"باب الهمزتين من كلمتين","title":"البيت 211","page":"ج1 ص16","text":"وعن أكثر القراء تبدل واوها ... وكل بهمز الكل يبدا مفصلا","a":"وعن أكثر القراء تبدل واوها","b":"وكل بهمز الكل يبدا مفصلا","ref":["ibraz:228","siraj:15"]},{"id":"shatibiyya:212","bookId":"shatibiyya","type":"bayt","num":212,"seq":212,"chapter":"باب الهمزتين من كلمتين","title":"البيت 212","page":"ج1 ص17","text":"والابدال محض والمسهل بين ما ... هو الهمز والحرف الذي منه أشكلا","a":"والابدال محض والمسهل بين ما","b":"هو الهمز والحرف الذي منه أشكلا","ref":["ibraz:229","siraj:15"]},{"id":"shatibiyya:213","bookId":"shatibiyya","type":"bayt","num":213,"seq":213,"chapter":"باب الهمز المفرد","title":"البيت 213","page":"ج1 ص17","text":"إذا سكنت فاء من الفعل همزة ... فورش يريها حرف مد مبدلا","a":"إذا سكنت فاء من الفعل همزة","b":"فورش يريها حرف مد مبدلا","ref":["ibraz:231","siraj:16"]},{"id":"shatibiyya:214","bookId":"shatibiyya","type":"bayt","num":214,"seq":214,"chapter":"باب الهمز المفرد","title":"البيت 214","page":"ج1 ص17","text":"سوى جملة الإيواء والواو عنه إن ... تفتح إثر الضم نحو مؤجلا","a":"سوى جملة الإيواء والواو عنه إن","b":"تفتح إثر الضم نحو مؤجلا","ref":["ibraz:232","siraj:16"]},{"id":"shatibiyya:215","bookId":"shatibiyya","type":"bayt","num":215,"seq":215,"chapter":"باب الهمز المفرد","title":"البيت 215","page":"ج1 ص17","text":"ويبدل للسوسي كل مسكن ... من الهمز مدا غير مجزوم اهملا","a":"ويبدل للسوسي كل مسكن","b":"من الهمز مدا غير مجزوم اهملا","ref":["ibraz:233","siraj:16"]},{"id":"shatibiyya:216","bookId":"shatibiyya","type":"bayt","num":216,"seq":216,"chapter":"باب الهمز المفرد","title":"البيت 216","page":"ج1 ص17","text":"تسؤ ونشأ ست وعشر يشأ ومع ... يهيئ وننسأها ينبأ تكملا","a":"تسؤ ونشأ ست وعشر يشأ ومع","b":"يهيئ وننسأها ينبأ تكملا","ref":["ibraz:234","siraj:16"]},{"id":"shatibiyya:217","bookId":"shatibiyya","type":"bayt","num":217,"seq":217,"chapter":"باب الهمز المفرد","title":"البيت 217","page":"ج1 ص17","text":"وهيئ وأنبئهم ونبئ بأربع ... وأرجئ معا واقرأ ثلاثا فحصلا","a":"وهيئ وأنبئهم ونبئ بأربع","b":"وأرجئ معا واقرأ ثلاثا فحصلا","ref":["ibraz:235","siraj:16"]},{"id":"shatibiyya:218","bookId":"shatibiyya","type":"bayt","num":218,"seq":218,"chapter":"باب الهمز المفرد","title":"البيت 218","page":"ج1 ص17","text":"وتؤوي وتؤويه أخف بهمزه ... ورئيا بترك الهمز يشبه الامتلا","a":"وتؤوي وتؤويه أخف بهمزه","b":"ورئيا بترك الهمز يشبه الامتلا","ref":["ibraz:236","siraj:16"]},{"id":"shatibiyya:219","bookId":"shatibiyya","type":"bayt","num":219,"seq":219,"chapter":"باب الهمز المفرد","title":"البيت 219","page":"ج1 ص17","text":"ومؤصدة أوصدت يشبه كله ... تخيره أهل الأداء معللا","a":"ومؤصدة أوصدت يشبه كله","b":"تخيره أهل الأداء معللا","ref":["ibraz:237","siraj:16"]},{"id":"shatibiyya:220","bookId":"shatibiyya","type":"bayt","num":220,"seq":220,"chapter":"باب الهمز المفرد","title":"البيت 220","page":"ج1 ص17","text":"وبارئكم بالهمز حال سكونه ... وقال ابن غلبون بياء تبدلا","a":"وبارئكم بالهمز حال سكونه","b":"وقال ابن غلبون بياء تبدلا","ref":["ibraz:238","siraj:16"]},{"id":"shatibiyya:221","bookId":"shatibiyya","type":"bayt","num":221,"seq":221,"chapter":"باب الهمز المفرد","title":"البيت 221","page":"ج1 ص17","text":"ووالاه في بئر وفي بئس ورشهم ... وفي الذئب ورش والكسائي فأبدلا","a":"ووالاه في بئر وفي بئس ورشهم","b":"وفي الذئب ورش والكسائي فأبدلا","ref":["ibraz:116"]},{"id":"shatibiyya:222","bookId":"shatibiyya","type":"bayt","num":222,"seq":222,"chapter":"باب الهمز المفرد","title":"البيت 222","page":"ج1 ص17","text":"وفي لؤلؤ في العرف والنكر شعبة ... ويألتكم الدوري والابدال يجتلا","a":"وفي لؤلؤ في العرف والنكر شعبة","b":"ويألتكم الدوري والابدال يجتلا","ref":["ibraz:240","siraj:16"]},{"id":"shatibiyya:223","bookId":"shatibiyya","type":"bayt","num":223,"seq":223,"chapter":"باب الهمز المفرد","title":"البيت 223","page":"ج1 ص17","text":"وورش لئلا والنسيء بيائه ... وأدغم في ياء النسىء فثقلا","a":"وورش لئلا والنسيء بيائه","b":"وأدغم في ياء النسىء فثقلا","ref":["ibraz:63"]},{"id":"shatibiyya:224","bookId":"shatibiyya","type":"bayt","num":224,"seq":224,"chapter":"باب الهمز المفرد","title":"البيت 224","page":"ج1 ص17","text":"وإبدال أخرى الهمزتين لكلهم ... إذا سكنت عزم كآدم أوهلا","a":"وإبدال أخرى الهمزتين لكلهم","b":"إذا سكنت عزم كآدم أوهلا","ref":["ibraz:242","siraj:16"]},{"id":"shatibiyya:225","bookId":"shatibiyya","type":"bayt","num":225,"seq":225,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 225","page":"ج1 ص18","text":"وحرك لورش كل ساكن آخر ... صحيح بشكل الهمز واحذفه مسهلا","a":"وحرك لورش كل ساكن آخر","b":"صحيح بشكل الهمز واحذفه مسهلا","ref":["ibraz:244","siraj:17"]},{"id":"shatibiyya:226","bookId":"shatibiyya","type":"bayt","num":226,"seq":226,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 226","page":"ج1 ص18","text":"وعن حمزة في الوقف خلف وعنده ... روى خلف في الوصل سكتا مقللا","a":"وعن حمزة في الوقف خلف وعنده","b":"روى خلف في الوصل سكتا مقللا","ref":["ibraz:245","siraj:17"]},{"id":"shatibiyya:227","bookId":"shatibiyya","type":"bayt","num":227,"seq":227,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 227","page":"ج1 ص18","text":"ويسكت في شيء وشيئا وبعضهم ... لدى اللام للتعريف عن حمزة تلا","a":"ويسكت في شيء وشيئا وبعضهم","b":"لدى اللام للتعريف عن حمزة تلا","ref":["ibraz:246","siraj:17"]},{"id":"shatibiyya:228","bookId":"shatibiyya","type":"bayt","num":228,"seq":228,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 228","page":"ج1 ص18","text":"وشيء وشيئا لم يزد ولنافع ... لدى يونس آلان بالنقل نقلا","a":"وشيء وشيئا لم يزد ولنافع","b":"لدى يونس آلان بالنقل نقلا","ref":["ibraz:247","siraj:17"]},{"id":"shatibiyya:229","bookId":"shatibiyya","type":"bayt","num":229,"seq":229,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 229","page":"ج1 ص18","text":"وقل عادا الأولى بإسكان لامه ... وتنوينه بالكسر كاسيه ظللا","a":"وقل عادا الأولى بإسكان لامه","b":"وتنوينه بالكسر كاسيه ظللا","ref":["ibraz:248","siraj:17"]},{"id":"shatibiyya:230","bookId":"shatibiyya","type":"bayt","num":230,"seq":230,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 230","page":"ج1 ص18","text":"وأدغم باقيهم وبالنقل وصلهم ... وبدؤهم والبدء بالأصل فضلا","a":"وأدغم باقيهم وبالنقل وصلهم","b":"وبدؤهم والبدء بالأصل فضلا","ref":["ibraz:249","siraj:17"]},{"id":"shatibiyya:231","bookId":"shatibiyya","type":"bayt","num":231,"seq":231,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 231","page":"ج1 ص18","text":"لقالون والبصري وتهمز واوه ... لقالون حال النقل بدءا وموصلا","a":"لقالون والبصري وتهمز واوه","b":"لقالون حال النقل بدءا وموصلا","ref":["ibraz:250","siraj:17"]},{"id":"shatibiyya:232","bookId":"shatibiyya","type":"bayt","num":232,"seq":232,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 232","page":"ج1 ص18","text":"وتبدا بهمز الوصل في النقل كله ... وإن كنت معتدا بعارضه فلا","a":"وتبدا بهمز الوصل في النقل كله","b":"وإن كنت معتدا بعارضه فلا","ref":["ibraz:251","siraj:17"]},{"id":"shatibiyya:233","bookId":"shatibiyya","type":"bayt","num":233,"seq":233,"chapter":"باب نقل حركة الهمزة إلى الساكن قبلها","title":"البيت 233","page":"ج1 ص18","text":"ونقل ردا عن نافع وكتابيه ... بالاسكان عن ورش أصح تقبلا","a":"ونقل ردا عن نافع وكتابيه","b":"بالاسكان عن ورش أصح تقبلا","ref":["ibraz:252","siraj:17"]},{"id":"shatibiyya:234","bookId":"shatibiyya","type":"bayt","num":234,"seq":234,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 234","page":"ج1 ص18","text":"وحمزة عند الوقف سهل همزه ... إذا كان وسطا أو تطرف منزلا","a":"وحمزة عند الوقف سهل همزه","b":"إذا كان وسطا أو تطرف منزلا","ref":["ibraz:63","siraj:18"]},{"id":"shatibiyya:235","bookId":"shatibiyya","type":"bayt","num":235,"seq":235,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 235","page":"ج1 ص18","text":"فأبدله عنه حرف مد مسكنا ... ومن قبله تحريكه قد تنزلا","a":"فأبدله عنه حرف مد مسكنا","b":"ومن قبله تحريكه قد تنزلا","ref":["ibraz:255","siraj:18"]},{"id":"shatibiyya:236","bookId":"shatibiyya","type":"bayt","num":236,"seq":236,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 236","page":"ج1 ص18","text":"وحرك به ما قبله متسكنا ... وأسقطه حتى يرجع اللفظ أسهلا","a":"وحرك به ما قبله متسكنا","b":"وأسقطه حتى يرجع اللفظ أسهلا","ref":["ibraz:256","siraj:18"]},{"id":"shatibiyya:237","bookId":"shatibiyya","type":"bayt","num":237,"seq":237,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 237","page":"ج1 ص19","text":"سوى أنه من بعد ما ألف جرى ... يسهله مهما توسط مدخلا","a":"سوى أنه من بعد ما ألف جرى","b":"يسهله مهما توسط مدخلا","ref":["ibraz:257","siraj:18"]},{"id":"shatibiyya:238","bookId":"shatibiyya","type":"bayt","num":238,"seq":238,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 238","page":"ج1 ص19","text":"ويبدله مهما تطرف مثله ... ويقصر أو يمضي على المد أطولا","a":"ويبدله مهما تطرف مثله","b":"ويقصر أو يمضي على المد أطولا","ref":["ibraz:245","siraj:18"]},{"id":"shatibiyya:239","bookId":"shatibiyya","type":"bayt","num":239,"seq":239,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 239","page":"ج1 ص19","text":"ويدغم فيه الواو والياء مبدلا ... إذا زيدتا من قبل حتى يفصلا","a":"ويدغم فيه الواو والياء مبدلا","b":"إذا زيدتا من قبل حتى يفصلا","ref":["ibraz:259","siraj:18"]},{"id":"shatibiyya:240","bookId":"shatibiyya","type":"bayt","num":240,"seq":240,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 240","page":"ج1 ص19","text":"ويسمع بعد الكسر والضم همزه ... لدى فتحه ياءا وواوا محولا","a":"ويسمع بعد الكسر والضم همزه","b":"لدى فتحه ياءا وواوا محولا","ref":["ibraz:260","siraj:18"]},{"id":"shatibiyya:241","bookId":"shatibiyya","type":"bayt","num":241,"seq":241,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 241","page":"ج1 ص19","text":"وفي غير هذا بين بين ومثله ... يقول هشام ما تطرف مسهلا","a":"وفي غير هذا بين بين ومثله","b":"يقول هشام ما تطرف مسهلا","ref":["ibraz:261","siraj:18"]},{"id":"shatibiyya:242","bookId":"shatibiyya","type":"bayt","num":242,"seq":242,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 242","page":"ج1 ص19","text":"ورءيا على إظهاره وإدغامه ... وبعض بكسر الها لياء تحولا","a":"ورءيا على إظهاره وإدغامه","b":"وبعض بكسر الها لياء تحولا","ref":["ibraz:262"]},{"id":"shatibiyya:243","bookId":"shatibiyya","type":"bayt","num":243,"seq":243,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 243","page":"ج1 ص19","text":"كقولك أنبئهم ونبئهم وقد ... رووا أنه بالخط كان مسهلا","a":"كقولك أنبئهم ونبئهم وقد","b":"رووا أنه بالخط كان مسهلا","ref":["ibraz:263","siraj:18"]},{"id":"shatibiyya:244","bookId":"shatibiyya","type":"bayt","num":244,"seq":244,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 244","page":"ج1 ص19","text":"ففي اليا يلي والواو والحذف رسمه ... والاخفش بعد الكسر والضم أبدلا","a":"ففي اليا يلي والواو والحذف رسمه","b":"والاخفش بعد الكسر والضم أبدلا","ref":["ibraz:264","siraj:18"]},{"id":"shatibiyya:245","bookId":"shatibiyya","type":"bayt","num":245,"seq":245,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 245","page":"ج1 ص19","text":"بياء وعنه الواو في عكسه ومن ... حكى فيهما كاليا وكالواو أعضلا","a":"بياء وعنه الواو في عكسه ومن","b":"حكى فيهما كاليا وكالواو أعضلا","ref":["ibraz:265","siraj:18"]},{"id":"shatibiyya:246","bookId":"shatibiyya","type":"bayt","num":246,"seq":246,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 246","page":"ج1 ص19","text":"ومستهزءون الحذف فيه ونحوه ... وضم وكسر قبل قيل وأخملا","a":"ومستهزءون الحذف فيه ونحوه","b":"وضم وكسر قبل قيل وأخملا","ref":["siraj:18"]},{"id":"shatibiyya:247","bookId":"shatibiyya","type":"bayt","num":247,"seq":247,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 247","page":"ج1 ص19","text":"وما فيه يلفى واسطا بزوائد ... دخلن عليه فيه وجهان أعملا","a":"وما فيه يلفى واسطا بزوائد","b":"دخلن عليه فيه وجهان أعملا","ref":["ibraz:267"]},{"id":"shatibiyya:248","bookId":"shatibiyya","type":"bayt","num":248,"seq":248,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 248","page":"ج1 ص19","text":"كما ها ويا واللام والبا ونحوها ... ولامات تعريف لمن قد تأملا","a":"كما ها ويا واللام والبا ونحوها","b":"ولامات تعريف لمن قد تأملا","ref":["ibraz:268","siraj:19"]},{"id":"shatibiyya:249","bookId":"shatibiyya","type":"bayt","num":249,"seq":249,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 249","page":"ج1 ص19","text":"وأشمم ورم فيما سوى متبدل ... بها حرف مد واعرف الباب محفلا","a":"وأشمم ورم فيما سوى متبدل","b":"بها حرف مد واعرف الباب محفلا","ref":["ibraz:269","siraj:19"]},{"id":"shatibiyya:250","bookId":"shatibiyya","type":"bayt","num":250,"seq":250,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 250","page":"ج1 ص19","text":"وما واو اصلي تسكن قبله ... أو اليا فعن بعض بالادغام حملا","a":"وما واو اصلي تسكن قبله","b":"أو اليا فعن بعض بالادغام حملا","ref":["ibraz:259","siraj:19"]},{"id":"shatibiyya:251","bookId":"shatibiyya","type":"bayt","num":251,"seq":251,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 251","page":"ج1 ص20","text":"وما قبله التحريك أو ألف محر ... ركا طرفا فالبعض بالروم سهلا","a":"وما قبله التحريك أو ألف محر","b":"ركا طرفا فالبعض بالروم سهلا","ref":["ibraz:271","siraj:19"]},{"id":"shatibiyya:252","bookId":"shatibiyya","type":"bayt","num":252,"seq":252,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 252","page":"ج1 ص20","text":"ومن لم يرم واعتد محضا سكونه ... وألحق مفتوحا فقد شذ موغلا","a":"ومن لم يرم واعتد محضا سكونه","b":"وألحق مفتوحا فقد شذ موغلا","ref":["ibraz:272","siraj:19"]},{"id":"shatibiyya:253","bookId":"shatibiyya","type":"bayt","num":253,"seq":253,"chapter":"باب وقف حمزة وهشام على الهمز","title":"البيت 253","page":"ج1 ص20","text":"وفي الهمز أنحاء وعند نحاته ... يضيء سناه كلما اسود أليلا","a":"وفي الهمز أنحاء وعند نحاته","b":"يضيء سناه كلما اسود أليلا","ref":["ibraz:273","siraj:19"]},{"id":"shatibiyya:254","bookId":"shatibiyya","type":"bayt","num":254,"seq":254,"chapter":"باب الإظهار والإدغام","title":"البيت 254","page":"ج1 ص20","text":"سأذكر ألفاظا تليها حروفها ... بالاظهار والإدغام تروى وتجتلا","a":"سأذكر ألفاظا تليها حروفها","b":"بالاظهار والإدغام تروى وتجتلا","ref":["ibraz:275","siraj:20"]},{"id":"shatibiyya:255","bookId":"shatibiyya","type":"bayt","num":255,"seq":255,"chapter":"باب الإظهار والإدغام","title":"البيت 255","page":"ج1 ص20","text":"فدونك إذ في بيتها وحروفها ... وما بعد بالتقييد قده مذللا","a":"فدونك إذ في بيتها وحروفها","b":"وما بعد بالتقييد قده مذللا","ref":["ibraz:276","siraj:20"]},{"id":"shatibiyya:256","bookId":"shatibiyya","type":"bayt","num":256,"seq":256,"chapter":"باب الإظهار والإدغام","title":"البيت 256","page":"ج1 ص20","text":"سأسمي وبعد الواو تسمو حروف من ... تسمى على سيما تروق مقبلا","a":"سأسمي وبعد الواو تسمو حروف من","b":"تسمى على سيما تروق مقبلا","ref":["ibraz:277","siraj:20"]},{"id":"shatibiyya:257","bookId":"shatibiyya","type":"bayt","num":257,"seq":257,"chapter":"باب الإظهار والإدغام","title":"البيت 257","page":"ج1 ص20","text":"وفي دال قد أيضا وتاء مؤنث ... وفي هل وبل فاحتل بذهنك أحيلا","a":"وفي دال قد أيضا وتاء مؤنث","b":"وفي هل وبل فاحتل بذهنك أحيلا","ref":["ibraz:278","siraj:20"]},{"id":"shatibiyya:258","bookId":"shatibiyya","type":"bayt","num":258,"seq":258,"chapter":"ذكر ذال إذ","title":"البيت 258","page":"ج1 ص20","text":"نعم إذ تمشت زينب صال دلها ... سمي جمال واصلا من توصلا","a":"نعم إذ تمشت زينب صال دلها","b":"سمي جمال واصلا من توصلا","ref":["ibraz:280","siraj:21"]},{"id":"shatibiyya:259","bookId":"shatibiyya","type":"bayt","num":259,"seq":259,"chapter":"ذكر ذال إذ","title":"البيت 259","page":"ج1 ص20","text":"فإظهارها أجرى دوام نسيمها ... وأظهر ريا قوله واصف جلا","a":"فإظهارها أجرى دوام نسيمها","b":"وأظهر ريا قوله واصف جلا","ref":["ibraz:278","siraj:21"]},{"id":"shatibiyya:260","bookId":"shatibiyya","type":"bayt","num":260,"seq":260,"chapter":"ذكر ذال إذ","title":"البيت 260","page":"ج1 ص20","text":"وأدغم ضنكا واصل توم دره ... وأدغم مولى وجده دائم ولا","a":"وأدغم ضنكا واصل توم دره","b":"وأدغم مولى وجده دائم ولا","ref":["ibraz:282","siraj:21"]},{"id":"shatibiyya:261","bookId":"shatibiyya","type":"bayt","num":261,"seq":261,"chapter":"ذكر دال قد","title":"البيت 261","page":"ج1 ص20","text":"وقد سحبت ذيلا ضفا ظل زرنب ... جلته صباه شائقا ومعللا","a":"وقد سحبت ذيلا ضفا ظل زرنب","b":"جلته صباه شائقا ومعللا","ref":["ibraz:284","siraj:22"]},{"id":"shatibiyya:262","bookId":"shatibiyya","type":"bayt","num":262,"seq":262,"chapter":"ذكر دال قد","title":"البيت 262","page":"ج1 ص21","text":"فاظهرها نجم بدا دل واضحا ... وأدغم ورش ضر ظمآن وامتلا","a":"فاظهرها نجم بدا دل واضحا","b":"وأدغم ورش ضر ظمآن وامتلا","ref":["ibraz:285","siraj:22"]},{"id":"shatibiyya:263","bookId":"shatibiyya","type":"bayt","num":263,"seq":263,"chapter":"ذكر دال قد","title":"البيت 263","page":"ج1 ص21","text":"وأدغم مرو واكف ضير ذابل ... زوى ظله وغر تسداه كلكلا","a":"وأدغم مرو واكف ضير ذابل","b":"زوى ظله وغر تسداه كلكلا","ref":["ibraz:286","siraj:22"]},{"id":"shatibiyya:264","bookId":"shatibiyya","type":"bayt","num":264,"seq":264,"chapter":"ذكر دال قد","title":"البيت 264","page":"ج1 ص21","text":"وفي حرف زينا خلاف ومظهر ... هشام بصاد حرفه متحملا","a":"وفي حرف زينا خلاف ومظهر","b":"هشام بصاد حرفه متحملا","ref":["ibraz:287","siraj:22"]},{"id":"shatibiyya:265","bookId":"shatibiyya","type":"bayt","num":265,"seq":265,"chapter":"ذكر تاء التأنيث","title":"البيت 265","page":"ج1 ص21","text":"وأبدت سنا ثغر صفت زرق ظلمه ... جمعن ورودا باردا عطر الطلا","a":"وأبدت سنا ثغر صفت زرق ظلمه","b":"جمعن ورودا باردا عطر الطلا","ref":["ibraz:289","siraj:23"]},{"id":"shatibiyya:266","bookId":"shatibiyya","type":"bayt","num":266,"seq":266,"chapter":"ذكر تاء التأنيث","title":"البيت 266","page":"ج1 ص21","text":"فإظهاره در نمته بدوره ... وأدغم ورش ظافرا ومخولا","a":"فإظهاره در نمته بدوره","b":"وأدغم ورش ظافرا ومخولا","ref":["siraj:23"]},{"id":"shatibiyya:267","bookId":"shatibiyya","type":"bayt","num":267,"seq":267,"chapter":"ذكر تاء التأنيث","title":"البيت 267","page":"ج1 ص21","text":"وأظهر كهف وافر سيب جوده ... زكي وفي عصرة ومحللا","a":"وأظهر كهف وافر سيب جوده","b":"زكي وفي عصرة ومحللا","ref":["ibraz:291","siraj:23"]},{"id":"shatibiyya:268","bookId":"shatibiyya","type":"bayt","num":268,"seq":268,"chapter":"ذكر تاء التأنيث","title":"البيت 268","page":"ج1 ص21","text":"واظهر راويه هشام لهدمت ... وفي وجبت خلف ابن ذكوان يفتلا","a":"واظهر راويه هشام لهدمت","b":"وفي وجبت خلف ابن ذكوان يفتلا","ref":["ibraz:292","siraj:23"]},{"id":"shatibiyya:269","bookId":"shatibiyya","type":"bayt","num":269,"seq":269,"chapter":"ذكر لام هل وبل","title":"البيت 269","page":"ج1 ص21","text":"ألا بل وهل تروي ثنا ظعن زينب ... سمير نواها طلح ضر ومبتلا","a":"ألا بل وهل تروي ثنا ظعن زينب","b":"سمير نواها طلح ضر ومبتلا","ref":["ibraz:294","siraj:24"]},{"id":"shatibiyya:270","bookId":"shatibiyya","type":"bayt","num":270,"seq":270,"chapter":"ذكر لام هل وبل","title":"البيت 270","page":"ج1 ص21","text":"فأدغمها راو وأدغم فاضل ... وقور ثناه سر تيما وقد حلا","a":"فأدغمها راو وأدغم فاضل","b":"وقور ثناه سر تيما وقد حلا","ref":["ibraz:295","siraj:24"]},{"id":"shatibiyya:271","bookId":"shatibiyya","type":"bayt","num":271,"seq":271,"chapter":"ذكر لام هل وبل","title":"البيت 271","page":"ج1 ص21","text":"وبل في النسا خلادهم بخلافه ... وفي هل ترى الإدغام حب وحملا","a":"وبل في النسا خلادهم بخلافه","b":"وفي هل ترى الإدغام حب وحملا","ref":["ibraz:296","siraj:24"]},{"id":"shatibiyya:272","bookId":"shatibiyya","type":"bayt","num":272,"seq":272,"chapter":"ذكر لام هل وبل","title":"البيت 272","page":"ج1 ص21","text":"وأظهر لدى واع نبيل ضمانه ... وفي الرعد هل واستوف لا زاجرا هلا","a":"وأظهر لدى واع نبيل ضمانه","b":"وفي الرعد هل واستوف لا زاجرا هلا","ref":["siraj:24"]},{"id":"shatibiyya:273","bookId":"shatibiyya","type":"bayt","num":273,"seq":273,"chapter":"باب اتفاقهم في إدغام إذ وقد وتاء التأنيث وهل وبل","title":"البيت 273","page":"ج1 ص22","text":"ولا خلف في الإدغام إذ ذل ظالم ... وقد تيمت دعد وسيما تبتلا","a":"ولا خلف في الإدغام إذ ذل ظالم","b":"وقد تيمت دعد وسيما تبتلا","ref":["ibraz:299","siraj:25"]},{"id":"shatibiyya:274","bookId":"shatibiyya","type":"bayt","num":274,"seq":274,"chapter":"باب اتفاقهم في إدغام إذ وقد وتاء التأنيث وهل وبل","title":"البيت 274","page":"ج1 ص22","text":"وقامت تريه دمية طيب وصفها ... وقل بل وهل راها لبيب ويعقلا","a":"وقامت تريه دمية طيب وصفها","b":"وقل بل وهل راها لبيب ويعقلا","ref":["ibraz:300","siraj:25"]},{"id":"shatibiyya:275","bookId":"shatibiyya","type":"bayt","num":275,"seq":275,"chapter":"باب اتفاقهم في إدغام إذ وقد وتاء التأنيث وهل وبل","title":"البيت 275","page":"ج1 ص22","text":"وما أول المثلين فيه مسكن ... فلا بد من إدغامه متمثلا","a":"وما أول المثلين فيه مسكن","b":"فلا بد من إدغامه متمثلا","ref":["ibraz:141","siraj:25"]},{"id":"shatibiyya:276","bookId":"shatibiyya","type":"bayt","num":276,"seq":276,"chapter":"باب حروف قربت مخارجها","title":"البيت 276","page":"ج1 ص22","text":"وإدغام باء الجزم في الفاء قد رسا ... حميدا وخير في يتب قاصدا ولا","a":"وإدغام باء الجزم في الفاء قد رسا","b":"حميدا وخير في يتب قاصدا ولا","ref":["ibraz:303","siraj:26"]},{"id":"shatibiyya:277","bookId":"shatibiyya","type":"bayt","num":277,"seq":277,"chapter":"باب حروف قربت مخارجها","title":"البيت 277","page":"ج1 ص22","text":"ومع جزمه يفعل بذلك سلموا ... ونخسف بهم راعوا وشذا تثقلا","a":"ومع جزمه يفعل بذلك سلموا","b":"ونخسف بهم راعوا وشذا تثقلا","ref":["ibraz:304","siraj:26"]},{"id":"shatibiyya:278","bookId":"shatibiyya","type":"bayt","num":278,"seq":278,"chapter":"باب حروف قربت مخارجها","title":"البيت 278","page":"ج1 ص22","text":"وعذت على إدغامه ونبذتها ... شواهد حماد وأورثتموا حلا","a":"وعذت على إدغامه ونبذتها","b":"شواهد حماد وأورثتموا حلا","ref":["ibraz:305","siraj:26"]},{"id":"shatibiyya:279","bookId":"shatibiyya","type":"bayt","num":279,"seq":279,"chapter":"باب حروف قربت مخارجها","title":"البيت 279","page":"ج1 ص22","text":"له شرعه والراء جزما بلامها ... كواصبر لحكم طال بالخلف يذبلا","a":"له شرعه والراء جزما بلامها","b":"كواصبر لحكم طال بالخلف يذبلا","ref":["siraj:26"]},{"id":"shatibiyya:280","bookId":"shatibiyya","type":"bayt","num":280,"seq":280,"chapter":"باب حروف قربت مخارجها","title":"البيت 280","page":"ج1 ص22","text":"وياسين أظهر عن فتى حقه بدا ... ونون وفيه الخلف عن ورشهم خلا","a":"وياسين أظهر عن فتى حقه بدا","b":"ونون وفيه الخلف عن ورشهم خلا","ref":["siraj:26"]},{"id":"shatibiyya:281","bookId":"shatibiyya","type":"bayt","num":281,"seq":281,"chapter":"باب حروف قربت مخارجها","title":"البيت 281","page":"ج1 ص22","text":"وحرمي نصر صاد مريم من يرد ... ثواب لبثت الفرد والجمع وصلا","a":"وحرمي نصر صاد مريم من يرد","b":"ثواب لبثت الفرد والجمع وصلا","ref":["ibraz:308","siraj:26"]},{"id":"shatibiyya:282","bookId":"shatibiyya","type":"bayt","num":282,"seq":282,"chapter":"باب حروف قربت مخارجها","title":"البيت 282","page":"ج1 ص22","text":"وطاسين عند الميم فاز اتخذتم ... أخذتم وفي الإفراد عاشر دغفلا","a":"وطاسين عند الميم فاز اتخذتم","b":"أخذتم وفي الإفراد عاشر دغفلا","ref":["siraj:26"]},{"id":"shatibiyya:283","bookId":"shatibiyya","type":"bayt","num":283,"seq":283,"chapter":"باب حروف قربت مخارجها","title":"البيت 283","page":"ج1 ص22","text":"وفي اركب هدى بر قريب بخلفهم ... كما ضاع جا يلهث له دار جهلا","a":"وفي اركب هدى بر قريب بخلفهم","b":"كما ضاع جا يلهث له دار جهلا","ref":["ibraz:310","siraj:26"]},{"id":"shatibiyya:284","bookId":"shatibiyya","type":"bayt","num":284,"seq":284,"chapter":"باب حروف قربت مخارجها","title":"البيت 284","page":"ج1 ص22","text":"وقالون ذو خلف وفي البقره فقل ... يعذب دنا بالخلف جودا وموبلا","a":"وقالون ذو خلف وفي البقره فقل","b":"يعذب دنا بالخلف جودا وموبلا","ref":["ibraz:311","siraj:26"]},{"id":"shatibiyya:285","bookId":"shatibiyya","type":"bayt","num":285,"seq":285,"chapter":"باب أحكام النون الساكنة والتنوين","title":"البيت 285","page":"ج1 ص23","text":"وكلهم التنوين والنون أدغموا ... بلا غنة في اللام والرا ليجملا","a":"وكلهم التنوين والنون أدغموا","b":"بلا غنة في اللام والرا ليجملا","ref":["ibraz:313","siraj:27"]},{"id":"shatibiyya:286","bookId":"shatibiyya","type":"bayt","num":286,"seq":286,"chapter":"باب أحكام النون الساكنة والتنوين","title":"البيت 286","page":"ج1 ص23","text":"وكل بينمو أدغموا مع غنة ... وفي الواو واليا دونها خلف تلا","a":"وكل بينمو أدغموا مع غنة","b":"وفي الواو واليا دونها خلف تلا","ref":["ibraz:314","siraj:27"]},{"id":"shatibiyya:287","bookId":"shatibiyya","type":"bayt","num":287,"seq":287,"chapter":"باب أحكام النون الساكنة والتنوين","title":"البيت 287","page":"ج1 ص23","text":"وعندهما للكل أظهر بكلمة ... مخافة إشباه المضاعف أثقلا","a":"وعندهما للكل أظهر بكلمة","b":"مخافة إشباه المضاعف أثقلا","ref":["ibraz:315","siraj:27"]},{"id":"shatibiyya:288","bookId":"shatibiyya","type":"bayt","num":288,"seq":288,"chapter":"باب أحكام النون الساكنة والتنوين","title":"البيت 288","page":"ج1 ص23","text":"وعند حروف الحلق للكل أظهرا ... ألا هاج حكم عم خاليه غفلا","a":"وعند حروف الحلق للكل أظهرا","b":"ألا هاج حكم عم خاليه غفلا","ref":["ibraz:316","siraj:27"]},{"id":"shatibiyya:289","bookId":"shatibiyya","type":"bayt","num":289,"seq":289,"chapter":"باب أحكام النون الساكنة والتنوين","title":"البيت 289","page":"ج1 ص23","text":"وقلبهما ميما لدى البا وأخفيا ... على غنة عند البواقي ليكملا","a":"وقلبهما ميما لدى البا وأخفيا","b":"على غنة عند البواقي ليكملا","ref":["siraj:27"]},{"id":"shatibiyya:290","bookId":"shatibiyya","type":"bayt","num":290,"seq":290,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 290","page":"ج1 ص23","text":"وحمزة منهم والكسائي بعده ... أمالا ذوات الياء حيث تأصلا","a":"وحمزة منهم والكسائي بعده","b":"أمالا ذوات الياء حيث تأصلا","ref":["ibraz:319","siraj:28"]},{"id":"shatibiyya:291","bookId":"shatibiyya","type":"bayt","num":291,"seq":291,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 291","page":"ج1 ص23","text":"وتثنية الأسماء تكشفها وإن ... رددت إليك الفعل صادفت منهلا","a":"وتثنية الأسماء تكشفها وإن","b":"رددت إليك الفعل صادفت منهلا","ref":["ibraz:320","siraj:28"]},{"id":"shatibiyya:292","bookId":"shatibiyya","type":"bayt","num":292,"seq":292,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 292","page":"ج1 ص23","text":"هدى واشتراه والهوى وهداهم ... وفي ألف التأنيث في الكل ميلا","a":"هدى واشتراه والهوى وهداهم","b":"وفي ألف التأنيث في الكل ميلا","ref":["ibraz:321","siraj:28"]},{"id":"shatibiyya:293","bookId":"shatibiyya","type":"bayt","num":293,"seq":293,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 293","page":"ج1 ص23","text":"وكيف جرت فعلى ففيها وجودها ... وإن ضم أو يفتح فعالى فحصلا","a":"وكيف جرت فعلى ففيها وجودها","b":"وإن ضم أو يفتح فعالى فحصلا","ref":["ibraz:322","siraj:28"]},{"id":"shatibiyya:294","bookId":"shatibiyya","type":"bayt","num":294,"seq":294,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 294","page":"ج1 ص23","text":"وفي اسم في الاستفهام أنى وفي متى ... معا وعسى أيضا أمالا وقل بلى","a":"وفي اسم في الاستفهام أنى وفي متى","b":"معا وعسى أيضا أمالا وقل بلى","ref":["ibraz:323","siraj:28"]},{"id":"shatibiyya:295","bookId":"shatibiyya","type":"bayt","num":295,"seq":295,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 295","page":"ج1 ص23","text":"وما رسموا بالياء غير لدى وما ... زكى وإلى من بعد حتى وقل على","a":"وما رسموا بالياء غير لدى وما","b":"زكى وإلى من بعد حتى وقل على","ref":["ibraz:324","siraj:28"]},{"id":"shatibiyya:296","bookId":"shatibiyya","type":"bayt","num":296,"seq":296,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 296","page":"ج1 ص23","text":"وكل ثلاثي يزيد فإنه ... ممال كزكاها وأنجى مع ابتلى","a":"وكل ثلاثي يزيد فإنه","b":"ممال كزكاها وأنجى مع ابتلى","ref":["ibraz:319","siraj:28"]},{"id":"shatibiyya:297","bookId":"shatibiyya","type":"bayt","num":297,"seq":297,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 297","page":"ج1 ص24","text":"ولكن أحيا عنهما بعد واوه ... وفيما سواه للكسائي ميلا","a":"ولكن أحيا عنهما بعد واوه","b":"وفيما سواه للكسائي ميلا","ref":["ibraz:326","siraj:28"]},{"id":"shatibiyya:298","bookId":"shatibiyya","type":"bayt","num":298,"seq":298,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 298","page":"ج1 ص24","text":"ورءياي والرءيا ومرضات كيفما ... أتى وخطايا مثله متقبلا","a":"ورءياي والرءيا ومرضات كيفما","b":"أتى وخطايا مثله متقبلا","ref":["ibraz:327"]},{"id":"shatibiyya:299","bookId":"shatibiyya","type":"bayt","num":299,"seq":299,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 299","page":"ج1 ص24","text":"ومحياهمو أيضا وحق تقاته ... وفي قد هداني ليس أمرك مشكلا","a":"ومحياهمو أيضا وحق تقاته","b":"وفي قد هداني ليس أمرك مشكلا","ref":["siraj:28"]},{"id":"shatibiyya:300","bookId":"shatibiyya","type":"bayt","num":300,"seq":300,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 300","page":"ج1 ص24","text":"وفي الكهف أنساني ومن قبل جاء من ... عصاني وأوصاني بمريم يجتلا","a":"وفي الكهف أنساني ومن قبل جاء من","b":"عصاني وأوصاني بمريم يجتلا","ref":["ibraz:329","siraj:28"]},{"id":"shatibiyya:301","bookId":"shatibiyya","type":"bayt","num":301,"seq":301,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 301","page":"ج1 ص24","text":"وفيها وفي طاسين آتاني الذي ... أذعت به حتى تضوع مندلا","a":"وفيها وفي طاسين آتاني الذي","b":"أذعت به حتى تضوع مندلا"},{"id":"shatibiyya:302","bookId":"shatibiyya","type":"bayt","num":302,"seq":302,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 302","page":"ج1 ص24","text":"وحرف تلاها مع طحاها وفي سجى ... وحرف دحاها وهي بالواو تبتلا","a":"وحرف تلاها مع طحاها وفي سجى","b":"وحرف دحاها وهي بالواو تبتلا","ref":["ibraz:331","siraj:28"]},{"id":"shatibiyya:303","bookId":"shatibiyya","type":"bayt","num":303,"seq":303,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 303","page":"ج1 ص24","text":"وأما ضحاها والضحى والربا مع ال ... قوى فأمالاها وبالواو تختلا","a":"وأما ضحاها والضحى والربا مع ال","b":"قوى فأمالاها وبالواو تختلا","ref":["ibraz:332","siraj:28"]},{"id":"shatibiyya:304","bookId":"shatibiyya","type":"bayt","num":304,"seq":304,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 304","page":"ج1 ص24","text":"ورؤياك مع مثواي عنه لحفصهم ... ومحياي مشكاة هداي قد انجلا","a":"ورؤياك مع مثواي عنه لحفصهم","b":"ومحياي مشكاة هداي قد انجلا","ref":["ibraz:333","siraj:28"]},{"id":"shatibiyya:305","bookId":"shatibiyya","type":"bayt","num":305,"seq":305,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 305","page":"ج1 ص24","text":"ومما أمالاه أواخر آي ما ... بطه وآي النجم كي تتعدلا","a":"ومما أمالاه أواخر آي ما","b":"بطه وآي النجم كي تتعدلا","ref":["ibraz:332","siraj:28"]},{"id":"shatibiyya:306","bookId":"shatibiyya","type":"bayt","num":306,"seq":306,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 306","page":"ج1 ص24","text":"وفي الشمس والأعلى وفي الليل والضحى ... وفي اقرأ وفي والنازعات تميلا","a":"وفي الشمس والأعلى وفي الليل والضحى","b":"وفي اقرأ وفي والنازعات تميلا","ref":["ibraz:335","siraj:28"]},{"id":"shatibiyya:307","bookId":"shatibiyya","type":"bayt","num":307,"seq":307,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 307","page":"ج1 ص24","text":"ومن تحتها ثم القيامة في ال ... معارج يا منهال أفلحت منهلا","a":"ومن تحتها ثم القيامة في ال","b":"معارج يا منهال أفلحت منهلا"},{"id":"shatibiyya:308","bookId":"shatibiyya","type":"bayt","num":308,"seq":308,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 308","page":"ج1 ص24","text":"رمى صحبة أعمى في الاسراء ثانيا ... سوى وسدى في الوقف عنهم تسبلا","a":"رمى صحبة أعمى في الاسراء ثانيا","b":"سوى وسدى في الوقف عنهم تسبلا","ref":["ibraz:337","siraj:28"]},{"id":"shatibiyya:309","bookId":"shatibiyya","type":"bayt","num":309,"seq":309,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 309","page":"ج1 ص24","text":"وراء تراءى فاز في شعرائه ... وأعمى في الاسرا حكم صحبة اولا","a":"وراء تراءى فاز في شعرائه","b":"وأعمى في الاسرا حكم صحبة اولا","ref":["ibraz:338","siraj:28"]},{"id":"shatibiyya:310","bookId":"shatibiyya","type":"bayt","num":310,"seq":310,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 310","page":"ج1 ص24","text":"وما بعد راء شاع حكما وحفصهم ... يوالي بمجراها وفي هود أنزلا","a":"وما بعد راء شاع حكما وحفصهم","b":"يوالي بمجراها وفي هود أنزلا","ref":["ibraz:339","siraj:28"]},{"id":"shatibiyya:311","bookId":"shatibiyya","type":"bayt","num":311,"seq":311,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 311","page":"ج1 ص25","text":"نأى شرع يمن باختلاف وشعبة ... في الاسرا وهم والنون ضوء سنا تلا","a":"نأى شرع يمن باختلاف وشعبة","b":"في الاسرا وهم والنون ضوء سنا تلا","ref":["ibraz:340","siraj:29"]},{"id":"shatibiyya:312","bookId":"shatibiyya","type":"bayt","num":312,"seq":312,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 312","page":"ج1 ص25","text":"إناه له شاف وقل أو كلاهما ... شفا ولكسر أو لياء تميلا","a":"إناه له شاف وقل أو كلاهما","b":"شفا ولكسر أو لياء تميلا","ref":["ibraz:341","siraj:29"]},{"id":"shatibiyya:313","bookId":"shatibiyya","type":"bayt","num":313,"seq":313,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 313","page":"ج1 ص25","text":"وذو الراء ورش بين بين وفي أرا ... كهم وذوات اليا له الخلف جملا","a":"وذو الراء ورش بين بين وفي أرا","b":"كهم وذوات اليا له الخلف جملا","ref":["siraj:29"]},{"id":"shatibiyya:314","bookId":"shatibiyya","type":"bayt","num":314,"seq":314,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 314","page":"ج1 ص25","text":"ولكن رءوس الآي قد قل فتحها ... له غير ماها فيه فاحضر مكملا","a":"ولكن رءوس الآي قد قل فتحها","b":"له غير ماها فيه فاحضر مكملا","ref":["ibraz:63","siraj:4"]},{"id":"shatibiyya:315","bookId":"shatibiyya","type":"bayt","num":315,"seq":315,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 315","page":"ج1 ص25","text":"وكيف أتت فعلى وآخر آي ما ... تقدم للبصري سوى راهما اعتلا","a":"وكيف أتت فعلى وآخر آي ما","b":"تقدم للبصري سوى راهما اعتلا","ref":["ibraz:344","siraj:29"]},{"id":"shatibiyya:316","bookId":"shatibiyya","type":"bayt","num":316,"seq":316,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 316","page":"ج1 ص25","text":"ويا ويلتى أنى ويا حسرتى طووا ... وعن غيره قسها ويا أسفى العلا","a":"ويا ويلتى أنى ويا حسرتى طووا","b":"وعن غيره قسها ويا أسفى العلا","ref":["ibraz:345"]},{"id":"shatibiyya:317","bookId":"shatibiyya","type":"bayt","num":317,"seq":317,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 317","page":"ج1 ص25","text":"وكيف الثلاثي غير زاغت بماضي ... أمل خاب خافوا طاب ضاقت فتجملا","a":"وكيف الثلاثي غير زاغت بماضي","b":"أمل خاب خافوا طاب ضاقت فتجملا","ref":["ibraz:346","siraj:29"]},{"id":"shatibiyya:318","bookId":"shatibiyya","type":"bayt","num":318,"seq":318,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 318","page":"ج1 ص25","text":"وحاق وزاغوا جاء شاء وزاد فز ... وجاء ابن ذكوان وفي شاء ميلا","a":"وحاق وزاغوا جاء شاء وزاد فز","b":"وجاء ابن ذكوان وفي شاء ميلا"},{"id":"shatibiyya:319","bookId":"shatibiyya","type":"bayt","num":319,"seq":319,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 319","page":"ج1 ص25","text":"فزادهم الأولى وفي الغير خلفه ... وقل صحبة بل ران واصحب معدلا","a":"فزادهم الأولى وفي الغير خلفه","b":"وقل صحبة بل ران واصحب معدلا","ref":["ibraz:348","siraj:29"]},{"id":"shatibiyya:320","bookId":"shatibiyya","type":"bayt","num":320,"seq":320,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 320","page":"ج1 ص25","text":"وفي ألفات قبل را طرف أتت ... بكسر أمل تدعى حميدا وتقبلا","a":"وفي ألفات قبل را طرف أتت","b":"بكسر أمل تدعى حميدا وتقبلا","ref":["ibraz:349","siraj:29"]},{"id":"shatibiyya:321","bookId":"shatibiyya","type":"bayt","num":321,"seq":321,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 321","page":"ج1 ص25","text":"كأبصارهم والدار ثم الحمار مع ... حمارك والكفار واقتس لتنضلا","a":"كأبصارهم والدار ثم الحمار مع","b":"حمارك والكفار واقتس لتنضلا","ref":["ibraz:350","siraj:29"]},{"id":"shatibiyya:322","bookId":"shatibiyya","type":"bayt","num":322,"seq":322,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 322","page":"ج1 ص25","text":"ومع كافرين الكافرين بيائه ... وهار روى مرو بخلف صد حلا","a":"ومع كافرين الكافرين بيائه","b":"وهار روى مرو بخلف صد حلا","ref":["ibraz:351","siraj:29"]},{"id":"shatibiyya:323","bookId":"shatibiyya","type":"bayt","num":323,"seq":323,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 323","page":"ج1 ص25","text":"بدار وجبارين والجار تمموا ... وورش جميع الباب كان مقللا","a":"بدار وجبارين والجار تمموا","b":"وورش جميع الباب كان مقللا","ref":["ibraz:352","siraj:29"]},{"id":"shatibiyya:324","bookId":"shatibiyya","type":"bayt","num":324,"seq":324,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 324","page":"ج1 ص25","text":"وهذان عنه باختلاف ومعه في ال ... بوار وفي القهار حمزة قللا","a":"وهذان عنه باختلاف ومعه في ال","b":"بوار وفي القهار حمزة قللا","ref":["ibraz:353","siraj:29"]},{"id":"shatibiyya:325","bookId":"shatibiyya","type":"bayt","num":325,"seq":325,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 325","page":"ج1 ص26","text":"وإضجاع ذي راءين حج رواته ... كالأبرار والتقليل جادل فيصلا","a":"وإضجاع ذي راءين حج رواته","b":"كالأبرار والتقليل جادل فيصلا","ref":["ibraz:354","siraj:29"]},{"id":"shatibiyya:326","bookId":"shatibiyya","type":"bayt","num":326,"seq":326,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 326","page":"ج1 ص26","text":"وإضجاع أنصاري تميم وسارعوا ... نسارع والباري وبارئكم تلا","a":"وإضجاع أنصاري تميم وسارعوا","b":"نسارع والباري وبارئكم تلا","ref":["ibraz:355","siraj:29"]},{"id":"shatibiyya:327","bookId":"shatibiyya","type":"bayt","num":327,"seq":327,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 327","page":"ج1 ص26","text":"وآذانهم طغيانهم ويسارع ... ون آذاننا عنه الجواري تمثلا","a":"وآذانهم طغيانهم ويسارع","b":"ون آذاننا عنه الجواري تمثلا","ref":["ibraz:356","siraj:29"]},{"id":"shatibiyya:328","bookId":"shatibiyya","type":"bayt","num":328,"seq":328,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 328","page":"ج1 ص26","text":"يواري أواري في العقود بخلفه ... ضعافا وحرفا النمل آتيك قولا","a":"يواري أواري في العقود بخلفه","b":"ضعافا وحرفا النمل آتيك قولا","ref":["ibraz:357","siraj:29"]},{"id":"shatibiyya:329","bookId":"shatibiyya","type":"bayt","num":329,"seq":329,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 329","page":"ج1 ص26","text":"بخلف ضممناه مشارب لامع ... وآنية في هل أتاك لأعدلا","a":"بخلف ضممناه مشارب لامع","b":"وآنية في هل أتاك لأعدلا","ref":["ibraz:358","siraj:29"]},{"id":"shatibiyya:330","bookId":"shatibiyya","type":"bayt","num":330,"seq":330,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 330","page":"ج1 ص26","text":"وفي الكافرون عابدون وعابد ... وخلفهم في الناس في الجر حصلا","a":"وفي الكافرون عابدون وعابد","b":"وخلفهم في الناس في الجر حصلا","ref":["ibraz:359","siraj:29"]},{"id":"shatibiyya:331","bookId":"shatibiyya","type":"bayt","num":331,"seq":331,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 331","page":"ج1 ص26","text":"حمارك والمحراب إكراههن وال ... حمار وفي الإكرام عمران مثلا","a":"حمارك والمحراب إكراههن وال","b":"حمار وفي الإكرام عمران مثلا","ref":["ibraz:360","siraj:30"]},{"id":"shatibiyya:332","bookId":"shatibiyya","type":"bayt","num":332,"seq":332,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 332","page":"ج1 ص26","text":"وكل بخلف لابن ذكوان غير ما ... يجر من المحراب فاعلم لتعملا","a":"وكل بخلف لابن ذكوان غير ما","b":"يجر من المحراب فاعلم لتعملا","ref":["ibraz:361","siraj:30"]},{"id":"shatibiyya:333","bookId":"shatibiyya","type":"bayt","num":333,"seq":333,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 333","page":"ج1 ص26","text":"ولا يمنع الإسكان في الوقف عارضا ... إمالة ما للكسر في الوصل ميلا","a":"ولا يمنع الإسكان في الوقف عارضا","b":"إمالة ما للكسر في الوصل ميلا","ref":["ibraz:362","siraj:30"]},{"id":"shatibiyya:334","bookId":"shatibiyya","type":"bayt","num":334,"seq":334,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 334","page":"ج1 ص26","text":"وقبل سكون قف بما في أصولهم ... وذو الراء فيه الخلف في الوصل يجتلا","a":"وقبل سكون قف بما في أصولهم","b":"وذو الراء فيه الخلف في الوصل يجتلا","ref":["ibraz:363","siraj:30"]},{"id":"shatibiyya:335","bookId":"shatibiyya","type":"bayt","num":335,"seq":335,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 335","page":"ج1 ص26","text":"كموسى الهدى عيسى ابن مريم والقرى ال ... لتي مع ذكرى الدار فافهم محصلا","a":"كموسى الهدى عيسى ابن مريم والقرى ال","b":"لتي مع ذكرى الدار فافهم محصلا","ref":["ibraz:364","siraj:30"]},{"id":"shatibiyya:336","bookId":"shatibiyya","type":"bayt","num":336,"seq":336,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 336","page":"ج1 ص26","text":"وقد فخموا التنوين وقفا ورققوا ... وتفخيمهم في النصب أجمع أشملا","a":"وقد فخموا التنوين وقفا ورققوا","b":"وتفخيمهم في النصب أجمع أشملا","ref":["ibraz:365","siraj:30"]},{"id":"shatibiyya:337","bookId":"shatibiyya","type":"bayt","num":337,"seq":337,"chapter":"باب الفتح والإمالة وبين اللفظين","title":"البيت 337","page":"ج1 ص26","text":"مسمى ومولى رفعه مع جره ... ومنصوبه غزى وتترا تزيلا","a":"مسمى ومولى رفعه مع جره","b":"ومنصوبه غزى وتترا تزيلا","ref":["ibraz:367","siraj:30"]},{"id":"shatibiyya:338","bookId":"shatibiyya","type":"bayt","num":338,"seq":338,"chapter":"باب مذهب الكسائي في إمالة هاء التأنيث في الوقف","title":"البيت 338","page":"ج1 ص27","text":"وفي هاء تأنيث الوقوف وقبلها ... ممال الكسائي غير عشر ليعدلا","a":"وفي هاء تأنيث الوقوف وقبلها","b":"ممال الكسائي غير عشر ليعدلا","ref":["ibraz:369","siraj:4"]},{"id":"shatibiyya:339","bookId":"shatibiyya","type":"bayt","num":339,"seq":339,"chapter":"باب مذهب الكسائي في إمالة هاء التأنيث في الوقف","title":"البيت 339","page":"ج1 ص27","text":"ويجمعها حق ضغاط عص خظا ... وأكهر بعد الياء يسكن ميلا","a":"ويجمعها حق ضغاط عص خظا","b":"وأكهر بعد الياء يسكن ميلا","ref":["ibraz:370","siraj:31"]},{"id":"shatibiyya:340","bookId":"shatibiyya","type":"bayt","num":340,"seq":340,"chapter":"باب مذهب الكسائي في إمالة هاء التأنيث في الوقف","title":"البيت 340","page":"ج1 ص27","text":"أو الكسر والإسكان ليس بحاجز ... ويضعف بعد الفتح والضم أرجلا","a":"أو الكسر والإسكان ليس بحاجز","b":"ويضعف بعد الفتح والضم أرجلا","ref":["ibraz:371","siraj:31"]},{"id":"shatibiyya:341","bookId":"shatibiyya","type":"bayt","num":341,"seq":341,"chapter":"باب مذهب الكسائي في إمالة هاء التأنيث في الوقف","title":"البيت 341","page":"ج1 ص27","text":"لعبره مائه وجهه وليكه وبعضهم ... سوى ألف عند الكسائي ميلا","a":"لعبره مائه وجهه وليكه وبعضهم","b":"سوى ألف عند الكسائي ميلا","ref":["ibraz:372","siraj:31"]},{"id":"shatibiyya:342","bookId":"shatibiyya","type":"bayt","num":342,"seq":342,"chapter":"باب مذاهبهم في الراءات","title":"البيت 342","page":"ج1 ص27","text":"ورقق ورش كل راء وقبلها ... مسكنة ياء أو الكسر موصلا","a":"ورقق ورش كل راء وقبلها","b":"مسكنة ياء أو الكسر موصلا","ref":["ibraz:374","siraj:32"]},{"id":"shatibiyya:343","bookId":"shatibiyya","type":"bayt","num":343,"seq":343,"chapter":"باب مذاهبهم في الراءات","title":"البيت 343","page":"ج1 ص27","text":"ولم ير فصلا ساكنا بعد كسرة ... سوى حرف الاستعلا سوى الخا فكملا","a":"ولم ير فصلا ساكنا بعد كسرة","b":"سوى حرف الاستعلا سوى الخا فكملا","ref":["ibraz:375","siraj:32"]},{"id":"shatibiyya:344","bookId":"shatibiyya","type":"bayt","num":344,"seq":344,"chapter":"باب مذاهبهم في الراءات","title":"البيت 344","page":"ج1 ص27","text":"وفخمها في الأعجمي وفي إرم ... وتكريرها حتى يرى متعدلا","a":"وفخمها في الأعجمي وفي إرم","b":"وتكريرها حتى يرى متعدلا","ref":["ibraz:376","siraj:32"]},{"id":"shatibiyya:345","bookId":"shatibiyya","type":"bayt","num":345,"seq":345,"chapter":"باب مذاهبهم في الراءات","title":"البيت 345","page":"ج1 ص27","text":"وتفخيمه ذكرا وسترا وبابه ... لدى جلة الأصحاب أعمر أرحلا","a":"وتفخيمه ذكرا وسترا وبابه","b":"لدى جلة الأصحاب أعمر أرحلا","ref":["ibraz:377","siraj:32"]},{"id":"shatibiyya:346","bookId":"shatibiyya","type":"bayt","num":346,"seq":346,"chapter":"باب مذاهبهم في الراءات","title":"البيت 346","page":"ج1 ص27","text":"وفي شرر عنه يرقق كلهم ... وحيران بالتفخيم بعض تقبلا","a":"وفي شرر عنه يرقق كلهم","b":"وحيران بالتفخيم بعض تقبلا","ref":["ibraz:997","siraj:32"]},{"id":"shatibiyya:347","bookId":"shatibiyya","type":"bayt","num":347,"seq":347,"chapter":"باب مذاهبهم في الراءات","title":"البيت 347","page":"ج1 ص27","text":"وفي الراء عن ورش سوى ما ذكرته ... مذاهب شذت في الأداء توقلا","a":"وفي الراء عن ورش سوى ما ذكرته","b":"مذاهب شذت في الأداء توقلا","ref":["ibraz:998","siraj:32"]},{"id":"shatibiyya:348","bookId":"shatibiyya","type":"bayt","num":348,"seq":348,"chapter":"باب مذاهبهم في الراءات","title":"البيت 348","page":"ج1 ص27","text":"ولا بد من ترقيقها بعد كسرة ... إذا سكنت يا صاح للسبعة الملا","a":"ولا بد من ترقيقها بعد كسرة","b":"إذا سكنت يا صاح للسبعة الملا","ref":["ibraz:999","siraj:32"]},{"id":"shatibiyya:349","bookId":"shatibiyya","type":"bayt","num":349,"seq":349,"chapter":"باب مذاهبهم في الراءات","title":"البيت 349","page":"ج1 ص28","text":"وما حرف الاستعلاء بعد فراؤه ... لكلهم التفخيم فيها تذللا","a":"وما حرف الاستعلاء بعد فراؤه","b":"لكلهم التفخيم فيها تذللا","ref":["ibraz:1000","siraj:32"]},{"id":"shatibiyya:350","bookId":"shatibiyya","type":"bayt","num":350,"seq":350,"chapter":"باب مذاهبهم في الراءات","title":"البيت 350","page":"ج1 ص28","text":"ويجمعها قظ خص ضغط وخلفهم ... بفرق جرى بين المشايخ سلسلا","a":"ويجمعها قظ خص ضغط وخلفهم","b":"بفرق جرى بين المشايخ سلسلا","ref":["ibraz:1001","siraj:32"]},{"id":"shatibiyya:351","bookId":"shatibiyya","type":"bayt","num":351,"seq":351,"chapter":"باب مذاهبهم في الراءات","title":"البيت 351","page":"ج1 ص28","text":"وما بعد كسر عارض أو مفصل ... ففخم فهذا حكمه متبذلا","a":"وما بعد كسر عارض أو مفصل","b":"ففخم فهذا حكمه متبذلا","ref":["ibraz:1002","siraj:32"]},{"id":"shatibiyya:352","bookId":"shatibiyya","type":"bayt","num":352,"seq":352,"chapter":"باب مذاهبهم في الراءات","title":"البيت 352","page":"ج1 ص28","text":"وما بعده كسر أو اليا فما لهم ... بترقيقه نص وثيق فيمثلا","a":"وما بعده كسر أو اليا فما لهم","b":"بترقيقه نص وثيق فيمثلا","ref":["ibraz:1003","siraj:32"]},{"id":"shatibiyya:353","bookId":"shatibiyya","type":"bayt","num":353,"seq":353,"chapter":"باب مذاهبهم في الراءات","title":"البيت 353","page":"ج1 ص28","text":"وما لقياس في القراءة مدخل ... فدونك ما فيه الرضا متكفلا","a":"وما لقياس في القراءة مدخل","b":"فدونك ما فيه الرضا متكفلا","ref":["ibraz:1004","siraj:32"]},{"id":"shatibiyya:354","bookId":"shatibiyya","type":"bayt","num":354,"seq":354,"chapter":"باب مذاهبهم في الراءات","title":"البيت 354","page":"ج1 ص28","text":"وترقيقها مكسورة عند وصلهم ... وتفخيمها في الوقف أجمع أشملا","a":"وترقيقها مكسورة عند وصلهم","b":"وتفخيمها في الوقف أجمع أشملا","ref":["ibraz:1005","siraj:32"]},{"id":"shatibiyya:355","bookId":"shatibiyya","type":"bayt","num":355,"seq":355,"chapter":"باب مذاهبهم في الراءات","title":"البيت 355","page":"ج1 ص28","text":"ولكنها في وقفهم مع غيرها ... ترقق بعد الكسر أو ما تميلا","a":"ولكنها في وقفهم مع غيرها","b":"ترقق بعد الكسر أو ما تميلا","ref":["ibraz:1006","siraj:32"]},{"id":"shatibiyya:356","bookId":"shatibiyya","type":"bayt","num":356,"seq":356,"chapter":"باب مذاهبهم في الراءات","title":"البيت 356","page":"ج1 ص28","text":"أو الياء تأتي بالسكون ورومهم ... كما وصلهم فابل الذكاء مصقلا","a":"أو الياء تأتي بالسكون ورومهم","b":"كما وصلهم فابل الذكاء مصقلا","ref":["ibraz:1007","siraj:32"]},{"id":"shatibiyya:357","bookId":"shatibiyya","type":"bayt","num":357,"seq":357,"chapter":"باب مذاهبهم في الراءات","title":"البيت 357","page":"ج1 ص28","text":"وفيما عدا هذا الذي قد وصفته ... على الأصل بالتفخيم كن متعملا","a":"وفيما عدا هذا الذي قد وصفته","b":"على الأصل بالتفخيم كن متعملا","ref":["ibraz:1008","siraj:32"]},{"id":"shatibiyya:358","bookId":"shatibiyya","type":"bayt","num":358,"seq":358,"chapter":"باب اللامات","title":"البيت 358","page":"ج1 ص28","text":"وغلظ ورش فتح لام لصادها ... أو الطاء أو للظاء قبل تنزلا","a":"وغلظ ورش فتح لام لصادها","b":"أو الطاء أو للظاء قبل تنزلا","ref":["ibraz:379","siraj:4"]},{"id":"shatibiyya:359","bookId":"shatibiyya","type":"bayt","num":359,"seq":359,"chapter":"باب اللامات","title":"البيت 359","page":"ج1 ص28","text":"إذا فتحت أو سكنت كصلاتهم ... ومطلع أيضا ثم ظل ويوصلا","a":"إذا فتحت أو سكنت كصلاتهم","b":"ومطلع أيضا ثم ظل ويوصلا","ref":["ibraz:380","siraj:33"]},{"id":"shatibiyya:360","bookId":"shatibiyya","type":"bayt","num":360,"seq":360,"chapter":"باب اللامات","title":"البيت 360","page":"ج1 ص28","text":"وفي طال خلف مع فصالا وعندما ... يسكن وقفا والمفخم فضلا","a":"وفي طال خلف مع فصالا وعندما","b":"يسكن وقفا والمفخم فضلا","ref":["ibraz:381","siraj:33"]},{"id":"shatibiyya:361","bookId":"shatibiyya","type":"bayt","num":361,"seq":361,"chapter":"باب اللامات","title":"البيت 361","page":"ج1 ص28","text":"وحكم ذوات الياء منها كهذه ... وعند رءوس الآي ترقيقها اعتلا","a":"وحكم ذوات الياء منها كهذه","b":"وعند رءوس الآي ترقيقها اعتلا","ref":["ibraz:382","siraj:33"]},{"id":"shatibiyya:362","bookId":"shatibiyya","type":"bayt","num":362,"seq":362,"chapter":"باب اللامات","title":"البيت 362","page":"ج1 ص29","text":"وكل لدى اسم الله من بعد كسرة ... يرققها حتى يروق مرتلا","a":"وكل لدى اسم الله من بعد كسرة","b":"يرققها حتى يروق مرتلا","ref":["ibraz:383","siraj:33"]},{"id":"shatibiyya:363","bookId":"shatibiyya","type":"bayt","num":363,"seq":363,"chapter":"باب اللامات","title":"البيت 363","page":"ج1 ص29","text":"كما فخموه بعد فتح وضمة ... فتم نظام الشمل وصلا وفيصلا","a":"كما فخموه بعد فتح وضمة","b":"فتم نظام الشمل وصلا وفيصلا","ref":["ibraz:384","siraj:33"]},{"id":"shatibiyya:364","bookId":"shatibiyya","type":"bayt","num":364,"seq":364,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 364","page":"ج1 ص29","text":"والاسكان أصل الوقف وهو اشتقاقه ... من الوقف عن تحريك حرف تعزلا","a":"والاسكان أصل الوقف وهو اشتقاقه","b":"من الوقف عن تحريك حرف تعزلا","ref":["ibraz:386","siraj:34"]},{"id":"shatibiyya:365","bookId":"shatibiyya","type":"bayt","num":365,"seq":365,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 365","page":"ج1 ص29","text":"وعند أبي عمرو وكوفيهم به ... من الروم والإشمام سمت تجملا","a":"وعند أبي عمرو وكوفيهم به","b":"من الروم والإشمام سمت تجملا","ref":["ibraz:387","siraj:34"]},{"id":"shatibiyya:366","bookId":"shatibiyya","type":"bayt","num":366,"seq":366,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 366","page":"ج1 ص29","text":"وأكثر أعلام القران يراهما ... لسائرهم أولى العلائق مطولا","a":"وأكثر أعلام القران يراهما","b":"لسائرهم أولى العلائق مطولا","ref":["ibraz:388","siraj:34"]},{"id":"shatibiyya:367","bookId":"shatibiyya","type":"bayt","num":367,"seq":367,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 367","page":"ج1 ص29","text":"ورومك إسماع المحرك واقفا ... بصوت خفي كل دان تنولا","a":"ورومك إسماع المحرك واقفا","b":"بصوت خفي كل دان تنولا","ref":["ibraz:389","siraj:34"]},{"id":"shatibiyya:368","bookId":"shatibiyya","type":"bayt","num":368,"seq":368,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 368","page":"ج1 ص29","text":"والاشمام إطباق الشفاه بعيد ما ... يسكن لا صوت هناك فيصحلا","a":"والاشمام إطباق الشفاه بعيد ما","b":"يسكن لا صوت هناك فيصحلا","ref":["ibraz:390","siraj:34"]},{"id":"shatibiyya:369","bookId":"shatibiyya","type":"bayt","num":369,"seq":369,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 369","page":"ج1 ص29","text":"وفعلهما في الضم والرفع وارد ... ورومك عند الكسر والجر وصلا","a":"وفعلهما في الضم والرفع وارد","b":"ورومك عند الكسر والجر وصلا","ref":["ibraz:391","siraj:34"]},{"id":"shatibiyya:370","bookId":"shatibiyya","type":"bayt","num":370,"seq":370,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 370","page":"ج1 ص29","text":"ولم يره في الفتح والنصب قارئ ... وعند إمام النحو في الكل أعملا","a":"ولم يره في الفتح والنصب قارئ","b":"وعند إمام النحو في الكل أعملا","ref":["ibraz:392","siraj:34"]},{"id":"shatibiyya:371","bookId":"shatibiyya","type":"bayt","num":371,"seq":371,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 371","page":"ج1 ص29","text":"وما نوع التحريك إلا للازم ... بناء وإعرابا غدا متنقلا","a":"وما نوع التحريك إلا للازم","b":"بناء وإعرابا غدا متنقلا","ref":["ibraz:393","siraj:34"]},{"id":"shatibiyya:372","bookId":"shatibiyya","type":"bayt","num":372,"seq":372,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 372","page":"ج1 ص29","text":"وفي هاء تأنيث وميم الجميع قل ... وعارض شكل لم يكونا ليدخلا","a":"وفي هاء تأنيث وميم الجميع قل","b":"وعارض شكل لم يكونا ليدخلا","ref":["ibraz:394"]},{"id":"shatibiyya:373","bookId":"shatibiyya","type":"bayt","num":373,"seq":373,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 373","page":"ج1 ص29","text":"وفي الهاء للإضمار قوم أبوهما ... ومن قبله ضم أو الكسر مثلا","a":"وفي الهاء للإضمار قوم أبوهما","b":"ومن قبله ضم أو الكسر مثلا","ref":["ibraz:395"]},{"id":"shatibiyya:374","bookId":"shatibiyya","type":"bayt","num":374,"seq":374,"chapter":"باب الوقف على أواخر الكلم","title":"البيت 374","page":"ج1 ص30","text":"أو اماهما واو وياء وبعضهم ... يرى لهما في كل حال محللا","a":"أو اماهما واو وياء وبعضهم","b":"يرى لهما في كل حال محللا","ref":["ibraz:396","siraj:34"]},{"id":"shatibiyya:375","bookId":"shatibiyya","type":"bayt","num":375,"seq":375,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 375","page":"ج1 ص30","text":"وكوفيهم والمازني ونافع ... عنوا باتباع الخط في وقف الابتلا","a":"وكوفيهم والمازني ونافع","b":"عنوا باتباع الخط في وقف الابتلا","ref":["ibraz:398","siraj:35"]},{"id":"shatibiyya:376","bookId":"shatibiyya","type":"bayt","num":376,"seq":376,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 376","page":"ج1 ص30","text":"ولابن كثير يرتضى وابن عامر ... وما اختلفوا فيه حر أن يفصلا","a":"ولابن كثير يرتضى وابن عامر","b":"وما اختلفوا فيه حر أن يفصلا","ref":["ibraz:399","siraj:35"]},{"id":"shatibiyya:377","bookId":"shatibiyya","type":"bayt","num":377,"seq":377,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 377","page":"ج1 ص30","text":"إذا كتبت بالتاء هاء مؤنث ... فبالهاء قف حقا رضى ومعولا","a":"إذا كتبت بالتاء هاء مؤنث","b":"فبالهاء قف حقا رضى ومعولا","ref":["siraj:35"]},{"id":"shatibiyya:378","bookId":"shatibiyya","type":"bayt","num":378,"seq":378,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 378","page":"ج1 ص30","text":"وفي اللات مع مرضات مع ذات بهجة ... ولات رضى هيهات هاديه رفلا","a":"وفي اللات مع مرضات مع ذات بهجة","b":"ولات رضى هيهات هاديه رفلا","ref":["siraj:35"]},{"id":"shatibiyya:379","bookId":"shatibiyya","type":"bayt","num":379,"seq":379,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 379","page":"ج1 ص30","text":"وقف يا أبه كفؤا دنا وكأين ال ... وقوف بنون وهو بالياء حصلا","a":"وقف يا أبه كفؤا دنا وكأين ال","b":"وقوف بنون وهو بالياء حصلا","ref":["siraj:35"]},{"id":"shatibiyya:380","bookId":"shatibiyya","type":"bayt","num":380,"seq":380,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 380","page":"ج1 ص30","text":"ومال لدى الفرقان والكهف والنسا ... وسال على ما حج والخلف رتلا","a":"ومال لدى الفرقان والكهف والنسا","b":"وسال على ما حج والخلف رتلا","ref":["siraj:35"]},{"id":"shatibiyya:381","bookId":"shatibiyya","type":"bayt","num":381,"seq":381,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 381","page":"ج1 ص30","text":"ويا أيها فوق الدخان وأيها ... لدى النور والرحمن رافقن حملا","a":"ويا أيها فوق الدخان وأيها","b":"لدى النور والرحمن رافقن حملا","ref":["siraj:35"]},{"id":"shatibiyya:382","bookId":"shatibiyya","type":"bayt","num":382,"seq":382,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 382","page":"ج1 ص30","text":"وفي الها على الإتباع ضم ابن عامر ... لدى الوصل والمرسوم فيهن أخيلا","a":"وفي الها على الإتباع ضم ابن عامر","b":"لدى الوصل والمرسوم فيهن أخيلا","ref":["siraj:35"]},{"id":"shatibiyya:383","bookId":"shatibiyya","type":"bayt","num":383,"seq":383,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 383","page":"ج1 ص30","text":"وقف ويكأنه ويكأن برسمه ... وبالياء قف رفقا وبالكاف حللا","a":"وقف ويكأنه ويكأن برسمه","b":"وبالياء قف رفقا وبالكاف حللا","ref":["siraj:35"]},{"id":"shatibiyya:384","bookId":"shatibiyya","type":"bayt","num":384,"seq":384,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 384","page":"ج1 ص30","text":"وأيا بأيا ما شفا وسواهما ... بما وبوادي النمل باليا سنا تلا","a":"وأيا بأيا ما شفا وسواهما","b":"بما وبوادي النمل باليا سنا تلا","ref":["siraj:35"]},{"id":"shatibiyya:385","bookId":"shatibiyya","type":"bayt","num":385,"seq":385,"chapter":"باب الوقف على مرسوم الخط","title":"البيت 385","page":"ج1 ص31","text":"وفي مه وممه قف وعمه لمه بمه ... بخلف عن البزي وادفع مجهلا","a":"وفي مه وممه قف وعمه لمه بمه","b":"بخلف عن البزي وادفع مجهلا","ref":["siraj:35"]},{"id":"shatibiyya:386","bookId":"shatibiyya","type":"bayt","num":386,"seq":386,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 386","page":"ج1 ص31","text":"وليست بلام الفعل ياء إضافة ... وما هي من نفس الأصول فتشكلا","a":"وليست بلام الفعل ياء إضافة","b":"وما هي من نفس الأصول فتشكلا","ref":["ibraz:401","siraj:36"]},{"id":"shatibiyya:387","bookId":"shatibiyya","type":"bayt","num":387,"seq":387,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 387","page":"ج1 ص31","text":"ولكنها كالهاء والكاف كل ما ... تليه يرى للهاء والكاف مدخلا","a":"ولكنها كالهاء والكاف كل ما","b":"تليه يرى للهاء والكاف مدخلا","ref":["ibraz:402","siraj:36"]},{"id":"shatibiyya:388","bookId":"shatibiyya","type":"bayt","num":388,"seq":388,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 388","page":"ج1 ص31","text":"وفي مائتي ياء وعشر منيفة ... وثنتين خلف القوم أحكيه مجملا","a":"وفي مائتي ياء وعشر منيفة","b":"وثنتين خلف القوم أحكيه مجملا","ref":["ibraz:403","siraj:36"]},{"id":"shatibiyya:389","bookId":"shatibiyya","type":"bayt","num":389,"seq":389,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 389","page":"ج1 ص31","text":"فتسعون مع همز بفتح وتسعها ... سما فتحها إلا مواضع هملا","a":"فتسعون مع همز بفتح وتسعها","b":"سما فتحها إلا مواضع هملا","ref":["ibraz:404","siraj:36"]},{"id":"shatibiyya:390","bookId":"shatibiyya","type":"bayt","num":390,"seq":390,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 390","page":"ج1 ص31","text":"فأرني وتفتني اتبعني سكونها ... لكل وترحمني أكن ولقد جلا","a":"فأرني وتفتني اتبعني سكونها","b":"لكل وترحمني أكن ولقد جلا","ref":["ibraz:405","siraj:36"]},{"id":"shatibiyya:391","bookId":"shatibiyya","type":"bayt","num":391,"seq":391,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 391","page":"ج1 ص31","text":"ذروني وادعوني اذكروني فتحها ... دواء وأوزعني معا جاد هطلا","a":"ذروني وادعوني اذكروني فتحها","b":"دواء وأوزعني معا جاد هطلا","ref":["ibraz:406","siraj:36"]},{"id":"shatibiyya:392","bookId":"shatibiyya","type":"bayt","num":392,"seq":392,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 392","page":"ج1 ص31","text":"ليبلوني معه سبيلي لنافع ... وعنه وللبصري ثمان تنخلا","a":"ليبلوني معه سبيلي لنافع","b":"وعنه وللبصري ثمان تنخلا","ref":["ibraz:407","siraj:36"]},{"id":"shatibiyya:393","bookId":"shatibiyya","type":"bayt","num":393,"seq":393,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 393","page":"ج1 ص31","text":"بيوسف إني الأولان ولي بها ... وضيفي ويسر لي ودوني تمثلا","a":"بيوسف إني الأولان ولي بها","b":"وضيفي ويسر لي ودوني تمثلا","ref":["ibraz:408","siraj:36"]},{"id":"shatibiyya:394","bookId":"shatibiyya","type":"bayt","num":394,"seq":394,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 394","page":"ج1 ص31","text":"وياءان في اجعل لي وأربع إذ حمت ... هداها ولكني بها اثنان وكلا","a":"وياءان في اجعل لي وأربع إذ حمت","b":"هداها ولكني بها اثنان وكلا","ref":["ibraz:409","siraj:36"]},{"id":"shatibiyya:395","bookId":"shatibiyya","type":"bayt","num":395,"seq":395,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 395","page":"ج1 ص31","text":"وتحتي وقل في هود إني أراكمو ... وقل فطرن في هود هاديه أوصلا","a":"وتحتي وقل في هود إني أراكمو","b":"وقل فطرن في هود هاديه أوصلا","ref":["ibraz:410","siraj:36"]},{"id":"shatibiyya:396","bookId":"shatibiyya","type":"bayt","num":396,"seq":396,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 396","page":"ج1 ص31","text":"ويحزنني حرميهم تعدانني ... حشرتني أعمى تأمروني وصلا","a":"ويحزنني حرميهم تعدانني","b":"حشرتني أعمى تأمروني وصلا","ref":["ibraz:411","siraj:36"]},{"id":"shatibiyya:397","bookId":"shatibiyya","type":"bayt","num":397,"seq":397,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 397","page":"ج1 ص32","text":"أرهطي سما مولى ومالي سما لوى ... لعلي سما كفؤا معي نفر العلا","a":"أرهطي سما مولى ومالي سما لوى","b":"لعلي سما كفؤا معي نفر العلا","ref":["ibraz:412","siraj:36"]},{"id":"shatibiyya:398","bookId":"shatibiyya","type":"bayt","num":398,"seq":398,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 398","page":"ج1 ص32","text":"عماد وتحت النمل عندي حسنه ... إلى دره بالخلف وافق موهلا","a":"عماد وتحت النمل عندي حسنه","b":"إلى دره بالخلف وافق موهلا","ref":["ibraz:413","siraj:36"]},{"id":"shatibiyya:399","bookId":"shatibiyya","type":"bayt","num":399,"seq":399,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 399","page":"ج1 ص32","text":"وثنتان مع خمسين مع كسر همزة ... بفتح أولي حكم سوى ما تعزلا","a":"وثنتان مع خمسين مع كسر همزة","b":"بفتح أولي حكم سوى ما تعزلا","ref":["ibraz:414","siraj:36"]},{"id":"shatibiyya:400","bookId":"shatibiyya","type":"bayt","num":400,"seq":400,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 400","page":"ج1 ص32","text":"بناتي وأنصاري عبادي ولعنتي ... وما بعده إن شاء بالفتح أهملا","a":"بناتي وأنصاري عبادي ولعنتي","b":"وما بعده إن شاء بالفتح أهملا","ref":["ibraz:415","siraj:36"]},{"id":"shatibiyya:401","bookId":"shatibiyya","type":"bayt","num":401,"seq":401,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 401","page":"ج1 ص32","text":"وفي إخوتي ورش يدي عن أولي حمى ... وفي رسلي أصل كسا وافي الملا","a":"وفي إخوتي ورش يدي عن أولي حمى","b":"وفي رسلي أصل كسا وافي الملا","ref":["ibraz:416","siraj:36"]},{"id":"shatibiyya:402","bookId":"shatibiyya","type":"bayt","num":402,"seq":402,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 402","page":"ج1 ص32","text":"وأمي وأجري سكنا دين صحبة ... دعاءي وآباءي لكوف تجملا","a":"وأمي وأجري سكنا دين صحبة","b":"دعاءي وآباءي لكوف تجملا","ref":["ibraz:587","siraj:36"]},{"id":"shatibiyya:403","bookId":"shatibiyya","type":"bayt","num":403,"seq":403,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 403","page":"ج1 ص32","text":"وحزني وتوفيقي ظلال وكلهم ... يصدقني أنظرني وأخرتني إلى","a":"وحزني وتوفيقي ظلال وكلهم","b":"يصدقني أنظرني وأخرتني إلى","ref":["ibraz:588","siraj:37"]},{"id":"shatibiyya:404","bookId":"shatibiyya","type":"bayt","num":404,"seq":404,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 404","page":"ج1 ص32","text":"وذريتي يدعونني وخطابه ... وعشر يليها الهمز بالضم مشكلا","a":"وذريتي يدعونني وخطابه","b":"وعشر يليها الهمز بالضم مشكلا","ref":["ibraz:589","siraj:37"]},{"id":"shatibiyya:405","bookId":"shatibiyya","type":"bayt","num":405,"seq":405,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 405","page":"ج1 ص32","text":"فعن نافع فافتح وأسكن لكلهم ... بعهدي وآتوني لتفتح مقفلا","a":"فعن نافع فافتح وأسكن لكلهم","b":"بعهدي وآتوني لتفتح مقفلا","ref":["ibraz:590","siraj:37"]},{"id":"shatibiyya:406","bookId":"shatibiyya","type":"bayt","num":406,"seq":406,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 406","page":"ج1 ص32","text":"وفي اللام للتعريف أربع عشرة ... فإسكانها فاش وعهدي في علا","a":"وفي اللام للتعريف أربع عشرة","b":"فإسكانها فاش وعهدي في علا","ref":["ibraz:591","siraj:37"]},{"id":"shatibiyya:407","bookId":"shatibiyya","type":"bayt","num":407,"seq":407,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 407","page":"ج1 ص32","text":"وقل لعبادي كان شرعا وفي الندا ... حمى شاع آياتي كما فاح منزلا","a":"وقل لعبادي كان شرعا وفي الندا","b":"حمى شاع آياتي كما فاح منزلا","ref":["ibraz:592","siraj:37"]},{"id":"shatibiyya:408","bookId":"shatibiyya","type":"bayt","num":408,"seq":408,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 408","page":"ج1 ص32","text":"فخمس عبادي اعدد وعهدي أرادني ... وربي الذي آتان آياتي الحلا","a":"فخمس عبادي اعدد وعهدي أرادني","b":"وربي الذي آتان آياتي الحلا","ref":["ibraz:593","siraj:37"]},{"id":"shatibiyya:409","bookId":"shatibiyya","type":"bayt","num":409,"seq":409,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 409","page":"ج1 ص32","text":"وأهلكني منها وفي صاد مسني ... مع الأنبيا ربي في الاعراف كملا","a":"وأهلكني منها وفي صاد مسني","b":"مع الأنبيا ربي في الاعراف كملا","ref":["siraj:37"]},{"id":"shatibiyya:410","bookId":"shatibiyya","type":"bayt","num":410,"seq":410,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 410","page":"ج1 ص33","text":"وسبع بهمز الوصل فردا وفتحهم ... أخي مع إني حقه ليتني حلا","a":"وسبع بهمز الوصل فردا وفتحهم","b":"أخي مع إني حقه ليتني حلا","ref":["ibraz:595","siraj:37"]},{"id":"shatibiyya:411","bookId":"shatibiyya","type":"bayt","num":411,"seq":411,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 411","page":"ج1 ص33","text":"ونفسي سما ذكري سما قومي الرضا ... حميد هدى بعدي سما صفوه ولا","a":"ونفسي سما ذكري سما قومي الرضا","b":"حميد هدى بعدي سما صفوه ولا","ref":["ibraz:596","siraj:37"]},{"id":"shatibiyya:412","bookId":"shatibiyya","type":"bayt","num":412,"seq":412,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 412","page":"ج1 ص33","text":"ومع غير همز في ثلاثين خلفهم ... ومحياي جي بالخلف والفتح خولا","a":"ومع غير همز في ثلاثين خلفهم","b":"ومحياي جي بالخلف والفتح خولا","ref":["ibraz:597","siraj:37"]},{"id":"shatibiyya:413","bookId":"shatibiyya","type":"bayt","num":413,"seq":413,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 413","page":"ج1 ص33","text":"وعم علا وجهي وبيتي بنوح عن ... لوى وسواه عد أصلا ليحفلا","a":"وعم علا وجهي وبيتي بنوح عن","b":"لوى وسواه عد أصلا ليحفلا","ref":["ibraz:598","siraj:37"]},{"id":"shatibiyya:414","bookId":"shatibiyya","type":"bayt","num":414,"seq":414,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 414","page":"ج1 ص33","text":"ومع شركاءي من وراءي دونوا ... ولي دين عن هاد بخلف له الحلا","a":"ومع شركاءي من وراءي دونوا","b":"ولي دين عن هاد بخلف له الحلا","ref":["ibraz:599"]},{"id":"shatibiyya:415","bookId":"shatibiyya","type":"bayt","num":415,"seq":415,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 415","page":"ج1 ص33","text":"مماتي أتى أرضي صراطي ابن عامر ... وفي النمل مالي دم لمن راق نوفلا","a":"مماتي أتى أرضي صراطي ابن عامر","b":"وفي النمل مالي دم لمن راق نوفلا","ref":["ibraz:600","siraj:37"]},{"id":"shatibiyya:416","bookId":"shatibiyya","type":"bayt","num":416,"seq":416,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 416","page":"ج1 ص33","text":"ولي نعجة ما كان لي اثنين مع معي ... ثمان علا والظلة الثان عن جلا","a":"ولي نعجة ما كان لي اثنين مع معي","b":"ثمان علا والظلة الثان عن جلا","ref":["ibraz:601","siraj:37"]},{"id":"shatibiyya:417","bookId":"shatibiyya","type":"bayt","num":417,"seq":417,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 417","page":"ج1 ص33","text":"ومع تومنوا لي يؤمنوا بي جاويا ... عبادي صف والحذف عن شاكر دلا","a":"ومع تومنوا لي يؤمنوا بي جاويا","b":"عبادي صف والحذف عن شاكر دلا","ref":["ibraz:602","siraj:37"]},{"id":"shatibiyya:418","bookId":"shatibiyya","type":"bayt","num":418,"seq":418,"chapter":"باب مذاهبهم في ياءات الإضافة","title":"البيت 418","page":"ج1 ص33","text":"وفتح ولي فيها لورش وحفصهم ... ومالي في ياسين سكن فتكملا","a":"وفتح ولي فيها لورش وحفصهم","b":"ومالي في ياسين سكن فتكملا","ref":["ibraz:603","siraj:37"]},{"id":"shatibiyya:419","bookId":"shatibiyya","type":"bayt","num":419,"seq":419,"chapter":"باب ياءات الزوائد","title":"البيت 419","page":"ج1 ص33","text":"ودونك ياءات تسمى زوائدا ... لأن كن عن خط المصاحف معزلا","a":"ودونك ياءات تسمى زوائدا","b":"لأن كن عن خط المصاحف معزلا","ref":["ibraz:418","siraj:38"]},{"id":"shatibiyya:420","bookId":"shatibiyya","type":"bayt","num":420,"seq":420,"chapter":"باب ياءات الزوائد","title":"البيت 420","page":"ج1 ص33","text":"وتثبت في الحالين درا لوامعا ... بخلف وأولى النمل حمزة كملا","a":"وتثبت في الحالين درا لوامعا","b":"بخلف وأولى النمل حمزة كملا","ref":["ibraz:419","siraj:3"]},{"id":"shatibiyya:421","bookId":"shatibiyya","type":"bayt","num":421,"seq":421,"chapter":"باب ياءات الزوائد","title":"البيت 421","page":"ج1 ص33","text":"وفي الوصل حماد شكور إمامه ... وجملتها ستون واثنان فاعقلا","a":"وفي الوصل حماد شكور إمامه","b":"وجملتها ستون واثنان فاعقلا","ref":["ibraz:420","siraj:38"]},{"id":"shatibiyya:422","bookId":"shatibiyya","type":"bayt","num":422,"seq":422,"chapter":"باب ياءات الزوائد","title":"البيت 422","page":"ج1 ص33","text":"فيسري إلى الداع الجوار المناد يه ... دين يؤتين مع أن تعلمني ولا","a":"فيسري إلى الداع الجوار المناد يه","b":"دين يؤتين مع أن تعلمني ولا","ref":["ibraz:421","siraj:38"]},{"id":"shatibiyya:423","bookId":"shatibiyya","type":"bayt","num":423,"seq":423,"chapter":"باب ياءات الزوائد","title":"البيت 423","page":"ج1 ص34","text":"وأخرتني الإسرا وتتبعن سما ... وفي الكهف نبغي يأت في هود رفلا","a":"وأخرتني الإسرا وتتبعن سما","b":"وفي الكهف نبغي يأت في هود رفلا","ref":["ibraz:422","siraj:38"]},{"id":"shatibiyya:424","bookId":"shatibiyya","type":"bayt","num":424,"seq":424,"chapter":"باب ياءات الزوائد","title":"البيت 424","page":"ج1 ص34","text":"سما ودعاءي في جنا حلو هديه ... وفي اتبعوني أهدكم حقه بلا","a":"سما ودعاءي في جنا حلو هديه","b":"وفي اتبعوني أهدكم حقه بلا","ref":["ibraz:423"]},{"id":"shatibiyya:425","bookId":"shatibiyya","type":"bayt","num":425,"seq":425,"chapter":"باب ياءات الزوائد","title":"البيت 425","page":"ج1 ص34","text":"وإن ترني عنهم تمدونني سما ... فريقا ويدع الداع هاك جنا حلا","a":"وإن ترني عنهم تمدونني سما","b":"فريقا ويدع الداع هاك جنا حلا","ref":["ibraz:424","siraj:38"]},{"id":"shatibiyya:426","bookId":"shatibiyya","type":"bayt","num":426,"seq":426,"chapter":"باب ياءات الزوائد","title":"البيت 426","page":"ج1 ص34","text":"وفي الفجر بالوادي دنا جريانه ... وفي الوقف بالوجهين وافق قنبلا","a":"وفي الفجر بالوادي دنا جريانه","b":"وفي الوقف بالوجهين وافق قنبلا","ref":["ibraz:425","siraj:38"]},{"id":"shatibiyya:427","bookId":"shatibiyya","type":"bayt","num":427,"seq":427,"chapter":"باب ياءات الزوائد","title":"البيت 427","page":"ج1 ص34","text":"وأكرمني معه أهانن إذ هدى ... وحذفهما للمازني عد أعدلا","a":"وأكرمني معه أهانن إذ هدى","b":"وحذفهما للمازني عد أعدلا","ref":["ibraz:426","siraj:38"]},{"id":"shatibiyya:428","bookId":"shatibiyya","type":"bayt","num":428,"seq":428,"chapter":"باب ياءات الزوائد","title":"البيت 428","page":"ج1 ص34","text":"وفي النمل آتاني ويفتح عن أولي ... حمى وخلاف الوقف بين حلا علا","a":"وفي النمل آتاني ويفتح عن أولي","b":"حمى وخلاف الوقف بين حلا علا","ref":["ibraz:427","siraj:38"]},{"id":"shatibiyya:429","bookId":"shatibiyya","type":"bayt","num":429,"seq":429,"chapter":"باب ياءات الزوائد","title":"البيت 429","page":"ج1 ص34","text":"ومع كالجواب الباد حق جناهما ... وفي المهتد الإسرا وتحت أخو حلا","a":"ومع كالجواب الباد حق جناهما","b":"وفي المهتد الإسرا وتحت أخو حلا","ref":["ibraz:428"]},{"id":"shatibiyya:430","bookId":"shatibiyya","type":"bayt","num":430,"seq":430,"chapter":"باب ياءات الزوائد","title":"البيت 430","page":"ج1 ص34","text":"وفي اتبعن في آل عمران عنهما ... وكيدون في الأعراف حج ليحملا","a":"وفي اتبعن في آل عمران عنهما","b":"وكيدون في الأعراف حج ليحملا","ref":["ibraz:429","siraj:38"]},{"id":"shatibiyya:431","bookId":"shatibiyya","type":"bayt","num":431,"seq":431,"chapter":"باب ياءات الزوائد","title":"البيت 431","page":"ج1 ص34","text":"بخلف وتؤتوني بيوسف حقه ... وفي هود تسألني حواريه جملا","a":"بخلف وتؤتوني بيوسف حقه","b":"وفي هود تسألني حواريه جملا","ref":["ibraz:430","siraj:38"]},{"id":"shatibiyya:432","bookId":"shatibiyya","type":"bayt","num":432,"seq":432,"chapter":"باب ياءات الزوائد","title":"البيت 432","page":"ج1 ص34","text":"وتخزون فيها حج أشركتمون قد ... هدان اتقون يا أولي اخشون مع ولا","a":"وتخزون فيها حج أشركتمون قد","b":"هدان اتقون يا أولي اخشون مع ولا","ref":["ibraz:431","siraj:38"]},{"id":"shatibiyya:433","bookId":"shatibiyya","type":"bayt","num":433,"seq":433,"chapter":"باب ياءات الزوائد","title":"البيت 433","page":"ج1 ص34","text":"وعنه وخافون ومن يتقي زكا ... بيوسف وافى كالصحيح معللا","a":"وعنه وخافون ومن يتقي زكا","b":"بيوسف وافى كالصحيح معللا","ref":["ibraz:432"]},{"id":"shatibiyya:434","bookId":"shatibiyya","type":"bayt","num":434,"seq":434,"chapter":"باب ياءات الزوائد","title":"البيت 434","page":"ج1 ص34","text":"وفي المتعالي دره والتلاق والت ... تناد درا باغيه بالخلف جهلا","a":"وفي المتعالي دره والتلاق والت","b":"تناد درا باغيه بالخلف جهلا","ref":["ibraz:433","siraj:38"]},{"id":"shatibiyya:435","bookId":"shatibiyya","type":"bayt","num":435,"seq":435,"chapter":"باب ياءات الزوائد","title":"البيت 435","page":"ج1 ص34","text":"ومع دعوة الداع دعاني حلا جنا ... وليسا لقالون عن الغر سبلا","a":"ومع دعوة الداع دعاني حلا جنا","b":"وليسا لقالون عن الغر سبلا","ref":["ibraz:434"]},{"id":"shatibiyya:436","bookId":"shatibiyya","type":"bayt","num":436,"seq":436,"chapter":"باب ياءات الزوائد","title":"البيت 436","page":"ج1 ص34","text":"نذيري لورش ثم تردين ترجمو ... ن فاعتزلون ستة نذري جلا","a":"نذيري لورش ثم تردين ترجمو","b":"ن فاعتزلون ستة نذري جلا","ref":["ibraz:435","siraj:39"]},{"id":"shatibiyya:437","bookId":"shatibiyya","type":"bayt","num":437,"seq":437,"chapter":"باب ياءات الزوائد","title":"البيت 437","page":"ج1 ص35","text":"وعيدي ثلاث ينقذون يكذبو ... ن قال نكيري أربع عنه وصلا","a":"وعيدي ثلاث ينقذون يكذبو","b":"ن قال نكيري أربع عنه وصلا","ref":["ibraz:436","siraj:39"]},{"id":"shatibiyya:438","bookId":"shatibiyya","type":"bayt","num":438,"seq":438,"chapter":"باب ياءات الزوائد","title":"البيت 438","page":"ج1 ص35","text":"فبشر عبادي افتح وقف ساكنا يدا ... وواتبعوني حج في الزخرف العلا","a":"فبشر عبادي افتح وقف ساكنا يدا","b":"وواتبعوني حج في الزخرف العلا","ref":["ibraz:437"]},{"id":"shatibiyya:439","bookId":"shatibiyya","type":"bayt","num":439,"seq":439,"chapter":"باب ياءات الزوائد","title":"البيت 439","page":"ج1 ص35","text":"وفي الكهف تسألني عن الكل ياؤه ... على رسمه والحذف بالخلف مثلا","a":"وفي الكهف تسألني عن الكل ياؤه","b":"على رسمه والحذف بالخلف مثلا","ref":["ibraz:438","siraj:39"]},{"id":"shatibiyya:440","bookId":"shatibiyya","type":"bayt","num":440,"seq":440,"chapter":"باب ياءات الزوائد","title":"البيت 440","page":"ج1 ص35","text":"وفي نرتعي خلف زكا وجميعهم ... بالإثبات تحت النمل يهديني تلا","a":"وفي نرتعي خلف زكا وجميعهم","b":"بالإثبات تحت النمل يهديني تلا","ref":["ibraz:439","siraj:39"]},{"id":"shatibiyya:441","bookId":"shatibiyya","type":"bayt","num":441,"seq":441,"chapter":"باب ياءات الزوائد","title":"البيت 441","page":"ج1 ص35","text":"فهذي أصول القوم حال اطرادها ... أجابت بعون الله فانتظمت حلا","a":"فهذي أصول القوم حال اطرادها","b":"أجابت بعون الله فانتظمت حلا","ref":["ibraz:440","siraj:39"]},{"id":"shatibiyya:442","bookId":"shatibiyya","type":"bayt","num":442,"seq":442,"chapter":"باب ياءات الزوائد","title":"البيت 442","page":"ج1 ص35","text":"وإني لأرجوه لنظم حروفهم ... نفائس أعلاق تنفس عطلا","a":"وإني لأرجوه لنظم حروفهم","b":"نفائس أعلاق تنفس عطلا","ref":["ibraz:441","siraj:39"]},{"id":"shatibiyya:443","bookId":"shatibiyya","type":"bayt","num":443,"seq":443,"chapter":"سورة البقرة","title":"البيت 443","page":"ج1 ص35","text":"وما يخدعون الفتح من قبل ساكن ... وبعد ذكا والغير كالحرف أولا","a":"وما يخدعون الفتح من قبل ساكن","b":"وبعد ذكا والغير كالحرف أولا","ref":["ibraz:52","siraj:3"]},{"id":"shatibiyya:444","bookId":"shatibiyya","type":"bayt","num":444,"seq":444,"chapter":"سورة البقرة","title":"البيت 444","page":"ج1 ص35","text":"وخفف كوف يكذبون وياؤه ... بفتح وللباقين ضم وثقلا","a":"وخفف كوف يكذبون وياؤه","b":"بفتح وللباقين ضم وثقلا","ref":["ibraz:445","siraj:40"]},{"id":"shatibiyya:445","bookId":"shatibiyya","type":"bayt","num":445,"seq":445,"chapter":"سورة البقرة","title":"البيت 445","page":"ج1 ص35","text":"وقيل وغيض ثم جيء يشمها ... لدى كسرها ضما رجال لتكملا","a":"وقيل وغيض ثم جيء يشمها","b":"لدى كسرها ضما رجال لتكملا","ref":["ibraz:51","siraj:40"]},{"id":"shatibiyya:446","bookId":"shatibiyya","type":"bayt","num":446,"seq":446,"chapter":"سورة البقرة","title":"البيت 446","page":"ج1 ص35","text":"وحيل بإشمام وسيق كما رسا ... وسيء وسيئت كان راويه أنبلا","a":"وحيل بإشمام وسيق كما رسا","b":"وسيء وسيئت كان راويه أنبلا","ref":["ibraz:447","siraj:40"]},{"id":"shatibiyya:447","bookId":"shatibiyya","type":"bayt","num":447,"seq":447,"chapter":"سورة البقرة","title":"البيت 447","page":"ج1 ص35","text":"وها هو بعد الواو والفا ولامها ... وها هي أسكن راضيا باردا حلا","a":"وها هو بعد الواو والفا ولامها","b":"وها هي أسكن راضيا باردا حلا","ref":["ibraz:448","siraj:40"]},{"id":"shatibiyya:448","bookId":"shatibiyya","type":"bayt","num":448,"seq":448,"chapter":"سورة البقرة","title":"البيت 448","page":"ج1 ص36","text":"وثم هو رفقا بان والضم غيرهم ... وكسر وعن كل يمل هو انجلا","a":"وثم هو رفقا بان والضم غيرهم","b":"وكسر وعن كل يمل هو انجلا","ref":["ibraz:449","siraj:40"]},{"id":"shatibiyya:449","bookId":"shatibiyya","type":"bayt","num":449,"seq":449,"chapter":"سورة البقرة","title":"البيت 449","page":"ج1 ص36","text":"وفي فأزل اللام خفف لحمزة ... وزد ألفا من قبله فتكملا","a":"وفي فأزل اللام خفف لحمزة","b":"وزد ألفا من قبله فتكملا","ref":["ibraz:51","siraj:40"]},{"id":"shatibiyya:450","bookId":"shatibiyya","type":"bayt","num":450,"seq":450,"chapter":"سورة البقرة","title":"البيت 450","page":"ج1 ص36","text":"وآدم فارفع ناصبا كلماته ... بكسر وللمكي عكس تحولا","a":"وآدم فارفع ناصبا كلماته","b":"بكسر وللمكي عكس تحولا","ref":["ibraz:451","siraj:40"]},{"id":"shatibiyya:451","bookId":"shatibiyya","type":"bayt","num":451,"seq":451,"chapter":"سورة البقرة","title":"البيت 451","page":"ج1 ص36","text":"ويقبل الاولى أنثوا دون حاجز ... وعدنا جميعا دون ما ألف حلا","a":"ويقبل الاولى أنثوا دون حاجز","b":"وعدنا جميعا دون ما ألف حلا","ref":["ibraz:452","siraj:40"]},{"id":"shatibiyya:452","bookId":"shatibiyya","type":"bayt","num":452,"seq":452,"chapter":"سورة البقرة","title":"البيت 452","page":"ج1 ص36","text":"وإسكان بارئكم ويأمركم له ... ويأمرهم أيضا وتأمرهم تلا","a":"وإسكان بارئكم ويأمركم له","b":"ويأمرهم أيضا وتأمرهم تلا","ref":["ibraz:453","siraj:40"]},{"id":"shatibiyya:453","bookId":"shatibiyya","type":"bayt","num":453,"seq":453,"chapter":"سورة البقرة","title":"البيت 453","page":"ج1 ص36","text":"وينصركم أيضا ويشعركم وكم ... جليل عن الدوري مختلسا جلا","a":"وينصركم أيضا ويشعركم وكم","b":"جليل عن الدوري مختلسا جلا","ref":["ibraz:454","siraj:40"]},{"id":"shatibiyya:454","bookId":"shatibiyya","type":"bayt","num":454,"seq":454,"chapter":"سورة البقرة","title":"البيت 454","page":"ج1 ص36","text":"وفيها وفي الأعراف نغفر بنونه ... ولا ضم واكسر فاءه حين ظللا","a":"وفيها وفي الأعراف نغفر بنونه","b":"ولا ضم واكسر فاءه حين ظللا","ref":["ibraz:455","siraj:40"]},{"id":"shatibiyya:455","bookId":"shatibiyya","type":"bayt","num":455,"seq":455,"chapter":"سورة البقرة","title":"البيت 455","page":"ج1 ص36","text":"وذكر هنا أصلا وللشام أنثوا ... وعن نافع معه في الاعراف وصلا","a":"وذكر هنا أصلا وللشام أنثوا","b":"وعن نافع معه في الاعراف وصلا","ref":["ibraz:456","siraj:40"]},{"id":"shatibiyya:456","bookId":"shatibiyya","type":"bayt","num":456,"seq":456,"chapter":"سورة البقرة","title":"البيت 456","page":"ج1 ص36","text":"وجمعا وفردا في النبيء وفي النبو ... ءة الهمز كل غير نافع ابدلا","a":"وجمعا وفردا في النبيء وفي النبو","b":"ءة الهمز كل غير نافع ابدلا","ref":["ibraz:457","siraj:40"]},{"id":"shatibiyya:457","bookId":"shatibiyya","type":"bayt","num":457,"seq":457,"chapter":"سورة البقرة","title":"البيت 457","page":"ج1 ص36","text":"وقالون في الأحزاب في للنبي مع ... بيوت النبي الياء شدد مبدلا","a":"وقالون في الأحزاب في للنبي مع","b":"بيوت النبي الياء شدد مبدلا","ref":["ibraz:458","siraj:40"]},{"id":"shatibiyya:458","bookId":"shatibiyya","type":"bayt","num":458,"seq":458,"chapter":"سورة البقرة","title":"البيت 458","page":"ج1 ص36","text":"وفي الصابئين الهمز والصابئون خذ ... وهزؤا وكفؤا في السواكن فصلا","a":"وفي الصابئين الهمز والصابئون خذ","b":"وهزؤا وكفؤا في السواكن فصلا","ref":["ibraz:63","siraj:40"]},{"id":"shatibiyya:459","bookId":"shatibiyya","type":"bayt","num":459,"seq":459,"chapter":"سورة البقرة","title":"البيت 459","page":"ج1 ص36","text":"وضم لباقيهم وحمزة وقفه ... بواو وحفص واقفا ثم موصلا","a":"وضم لباقيهم وحمزة وقفه","b":"بواو وحفص واقفا ثم موصلا","ref":["ibraz:460","siraj:40"]},{"id":"shatibiyya:460","bookId":"shatibiyya","type":"bayt","num":460,"seq":460,"chapter":"سورة البقرة","title":"البيت 460","page":"ج1 ص36","text":"وبالغيب عما تعملون هنا دنا ... وغيبك في الثاني إلى صفوه دلا","a":"وبالغيب عما تعملون هنا دنا","b":"وغيبك في الثاني إلى صفوه دلا","ref":["ibraz:461","siraj:40"]},{"id":"shatibiyya:461","bookId":"shatibiyya","type":"bayt","num":461,"seq":461,"chapter":"سورة البقرة","title":"البيت 461","page":"ج1 ص36","text":"خطيئته التوحيد عن غير نافع ... ولا يعبدون الغيب شايع دخللا","a":"خطيئته التوحيد عن غير نافع","b":"ولا يعبدون الغيب شايع دخللا","ref":["ibraz:462","siraj:3"]},{"id":"shatibiyya:462","bookId":"shatibiyya","type":"bayt","num":462,"seq":462,"chapter":"سورة البقرة","title":"البيت 462","page":"ج1 ص37","text":"وقل حسنا شكرا وحسنا بضمه ... وساكنه الباقون واحسن مقولا","a":"وقل حسنا شكرا وحسنا بضمه","b":"وساكنه الباقون واحسن مقولا","ref":["ibraz:463","siraj:41"]},{"id":"shatibiyya:463","bookId":"shatibiyya","type":"bayt","num":463,"seq":463,"chapter":"سورة البقرة","title":"البيت 463","page":"ج1 ص37","text":"وتظاهرون الظاء خفف ثابتا ... وعنهم لدى التحريم أيضا تحللا","a":"وتظاهرون الظاء خفف ثابتا","b":"وعنهم لدى التحريم أيضا تحللا","ref":["ibraz:464","siraj:41"]},{"id":"shatibiyya:464","bookId":"shatibiyya","type":"bayt","num":464,"seq":464,"chapter":"سورة البقرة","title":"البيت 464","page":"ج1 ص37","text":"وحمزة أسرى في أسارى وضمهم ... تفادوهمو والمد إذ راق نفلا","a":"وحمزة أسرى في أسارى وضمهم","b":"تفادوهمو والمد إذ راق نفلا","ref":["ibraz:465","siraj:41"]},{"id":"shatibiyya:465","bookId":"shatibiyya","type":"bayt","num":465,"seq":465,"chapter":"سورة البقرة","title":"البيت 465","page":"ج1 ص37","text":"وحيث أتاك القدس إسكان داله ... دواء وللباقين بالضم أرسلا","a":"وحيث أتاك القدس إسكان داله","b":"دواء وللباقين بالضم أرسلا","ref":["ibraz:466","siraj:4"]},{"id":"shatibiyya:466","bookId":"shatibiyya","type":"bayt","num":466,"seq":466,"chapter":"سورة البقرة","title":"البيت 466","page":"ج1 ص37","text":"وينزل خففه وتنزل مثله ... وننزل حق وهو في الحجر ثقلا","a":"وينزل خففه وتنزل مثله","b":"وننزل حق وهو في الحجر ثقلا","ref":["ibraz:467","siraj:41"]},{"id":"shatibiyya:467","bookId":"shatibiyya","type":"bayt","num":467,"seq":467,"chapter":"سورة البقرة","title":"البيت 467","page":"ج1 ص37","text":"وخفف للبصري بسبحان والذي ... في الانعام للمكي على أن ينزلا","a":"وخفف للبصري بسبحان والذي","b":"في الانعام للمكي على أن ينزلا","ref":["ibraz:468","siraj:41"]},{"id":"shatibiyya:468","bookId":"shatibiyya","type":"bayt","num":468,"seq":468,"chapter":"سورة البقرة","title":"البيت 468","page":"ج1 ص37","text":"ومنزلها التخفيف حق شفاؤه ... وخفف عنهم ينزل الغيث مسجلا","a":"ومنزلها التخفيف حق شفاؤه","b":"وخفف عنهم ينزل الغيث مسجلا","ref":["ibraz:69","siraj:41"]},{"id":"shatibiyya:469","bookId":"shatibiyya","type":"bayt","num":469,"seq":469,"chapter":"سورة البقرة","title":"البيت 469","page":"ج1 ص37","text":"وجبريل فتح الجيم والرا وبعدها ... وعى همزة مكسورة صحبة ولا","a":"وجبريل فتح الجيم والرا وبعدها","b":"وعى همزة مكسورة صحبة ولا","ref":["ibraz:470","siraj:41"]},{"id":"shatibiyya:470","bookId":"shatibiyya","type":"bayt","num":470,"seq":470,"chapter":"سورة البقرة","title":"البيت 470","page":"ج1 ص37","text":"بحيث أتى والياء يحذف شعبة ... ومكيهم في الجيم بالفتح وكلا","a":"بحيث أتى والياء يحذف شعبة","b":"ومكيهم في الجيم بالفتح وكلا","ref":["ibraz:471","siraj:41"]},{"id":"shatibiyya:471","bookId":"shatibiyya","type":"bayt","num":471,"seq":471,"chapter":"سورة البقرة","title":"البيت 471","page":"ج1 ص37","text":"ودع ياء ميكائيل والهمز قبله ... على حجة والياء يحذف أجملا","a":"ودع ياء ميكائيل والهمز قبله","b":"على حجة والياء يحذف أجملا","ref":["ibraz:472","siraj:41"]},{"id":"shatibiyya:472","bookId":"shatibiyya","type":"bayt","num":472,"seq":472,"chapter":"سورة البقرة","title":"البيت 472","page":"ج1 ص37","text":"ولكن خفيف والشياطين رفعه ... كما شرطوا والعكس نحو سما العلا","a":"ولكن خفيف والشياطين رفعه","b":"كما شرطوا والعكس نحو سما العلا","ref":["ibraz:62","siraj:41"]},{"id":"shatibiyya:473","bookId":"shatibiyya","type":"bayt","num":473,"seq":473,"chapter":"سورة البقرة","title":"البيت 473","page":"ج1 ص37","text":"وننسخ به ضم وكسر كفى ونن ... سها مثله من غير همز ذكت إلى","a":"وننسخ به ضم وكسر كفى ونن","b":"سها مثله من غير همز ذكت إلى","ref":["ibraz:474","siraj:41"]},{"id":"shatibiyya:474","bookId":"shatibiyya","type":"bayt","num":474,"seq":474,"chapter":"سورة البقرة","title":"البيت 474","page":"ج1 ص37","text":"عليم وقالوا الواو الاولى سقوطها ... وكن فيكون النصب في الرفع كفلا","a":"عليم وقالوا الواو الاولى سقوطها","b":"وكن فيكون النصب في الرفع كفلا","ref":["ibraz:475","siraj:41"]},{"id":"shatibiyya:475","bookId":"shatibiyya","type":"bayt","num":475,"seq":475,"chapter":"سورة البقرة","title":"البيت 475","page":"ج1 ص37","text":"وفي آل عمران في الاولى ومريم ... وفي الطول عنه وهو باللفظ أعملا","a":"وفي آل عمران في الاولى ومريم","b":"وفي الطول عنه وهو باللفظ أعملا","ref":["ibraz:476","siraj:41"]},{"id":"shatibiyya:476","bookId":"shatibiyya","type":"bayt","num":476,"seq":476,"chapter":"سورة البقرة","title":"البيت 476","page":"ج1 ص38","text":"وفي النحل مع يس بالعطف نصبه ... كفى راويا وانقاد معناه يعملا","a":"وفي النحل مع يس بالعطف نصبه","b":"كفى راويا وانقاد معناه يعملا","ref":["ibraz:477","siraj:41"]},{"id":"shatibiyya:477","bookId":"shatibiyya","type":"bayt","num":477,"seq":477,"chapter":"سورة البقرة","title":"البيت 477","page":"ج1 ص38","text":"وتسأل ضموا التاء واللام حركوا ... برفع خلودا وهو من بعد نفي لا","a":"وتسأل ضموا التاء واللام حركوا","b":"برفع خلودا وهو من بعد نفي لا","ref":["ibraz:64","siraj:41"]},{"id":"shatibiyya:478","bookId":"shatibiyya","type":"bayt","num":478,"seq":478,"chapter":"سورة البقرة","title":"البيت 478","page":"ج1 ص38","text":"وفيها وفي نص النساء ثلاثة ... أواخر إبراهام لاح وجملا","a":"وفيها وفي نص النساء ثلاثة","b":"أواخر إبراهام لاح وجملا","ref":["ibraz:479","siraj:41"]},{"id":"shatibiyya:479","bookId":"shatibiyya","type":"bayt","num":479,"seq":479,"chapter":"سورة البقرة","title":"البيت 479","page":"ج1 ص38","text":"ومع آخر الأنعام حرفا براءة ... أخيرا وتحت الرعد حرف تنزلا","a":"ومع آخر الأنعام حرفا براءة","b":"أخيرا وتحت الرعد حرف تنزلا","ref":["ibraz:480","siraj:41"]},{"id":"shatibiyya:480","bookId":"shatibiyya","type":"bayt","num":480,"seq":480,"chapter":"سورة البقرة","title":"البيت 480","page":"ج1 ص38","text":"وفي مريم والنحل خمسة أحرف ... وآخر ما في العنكبوت منزلا","a":"وفي مريم والنحل خمسة أحرف","b":"وآخر ما في العنكبوت منزلا","ref":["ibraz:481","siraj:41"]},{"id":"shatibiyya:481","bookId":"shatibiyya","type":"bayt","num":481,"seq":481,"chapter":"سورة البقرة","title":"البيت 481","page":"ج1 ص38","text":"وفي النجم والشورى وفي الذاريات وال ... حديد ويروي في امتحانه الاولا","a":"وفي النجم والشورى وفي الذاريات وال","b":"حديد ويروي في امتحانه الاولا","ref":["ibraz:482","siraj:41"]},{"id":"shatibiyya:482","bookId":"shatibiyya","type":"bayt","num":482,"seq":482,"chapter":"سورة البقرة","title":"البيت 482","page":"ج1 ص38","text":"ووجهان فيه لابن ذكوان ههنا ... وواتخذوا بالفتح عم وأوغلا","a":"ووجهان فيه لابن ذكوان ههنا","b":"وواتخذوا بالفتح عم وأوغلا","ref":["ibraz:483"]},{"id":"shatibiyya:483","bookId":"shatibiyya","type":"bayt","num":483,"seq":483,"chapter":"سورة البقرة","title":"البيت 483","page":"ج1 ص38","text":"وأرنا وأرني ساكنا الكسر دم يدا ... وفي فصلت يروي صفا دره كلا","a":"وأرنا وأرني ساكنا الكسر دم يدا","b":"وفي فصلت يروي صفا دره كلا","ref":["ibraz:484"]},{"id":"shatibiyya:484","bookId":"shatibiyya","type":"bayt","num":484,"seq":484,"chapter":"سورة البقرة","title":"البيت 484","page":"ج1 ص38","text":"وأخفاهما طلق وخف ابن عامر ... فأمتعه أوصى بوصى كما اعتلا","a":"وأخفاهما طلق وخف ابن عامر","b":"فأمتعه أوصى بوصى كما اعتلا","ref":["ibraz:485","siraj:42"]},{"id":"shatibiyya:485","bookId":"shatibiyya","type":"bayt","num":485,"seq":485,"chapter":"سورة البقرة","title":"البيت 485","page":"ج1 ص38","text":"وفي أم يقولون الخطاب كما علا ... شفا ورءوف قصر صحبته حلا","a":"وفي أم يقولون الخطاب كما علا","b":"شفا ورءوف قصر صحبته حلا","ref":["ibraz:486","siraj:42"]},{"id":"shatibiyya:486","bookId":"shatibiyya","type":"bayt","num":486,"seq":486,"chapter":"سورة البقرة","title":"البيت 486","page":"ج1 ص38","text":"وخاطب عما يعملون كما شفا ... ولام موليها على الفتح كملا","a":"وخاطب عما يعملون كما شفا","b":"ولام موليها على الفتح كملا","ref":["ibraz:487","siraj:42"]},{"id":"shatibiyya:487","bookId":"shatibiyya","type":"bayt","num":487,"seq":487,"chapter":"سورة البقرة","title":"البيت 487","page":"ج1 ص38","text":"وفي يعملون الغيب حل وساكن ... بحرفيه يطوع وفي الطاء ثقلا","a":"وفي يعملون الغيب حل وساكن","b":"بحرفيه يطوع وفي الطاء ثقلا","ref":["ibraz:488","siraj:42"]},{"id":"shatibiyya:488","bookId":"shatibiyya","type":"bayt","num":488,"seq":488,"chapter":"سورة البقرة","title":"البيت 488","page":"ج1 ص38","text":"وفي التاء ياء شاع والريح وحدا ... وفي الكهف معها والشريعة وصلا","a":"وفي التاء ياء شاع والريح وحدا","b":"وفي الكهف معها والشريعة وصلا","ref":["ibraz:489","siraj:42"]},{"id":"shatibiyya:489","bookId":"shatibiyya","type":"bayt","num":489,"seq":489,"chapter":"سورة البقرة","title":"البيت 489","page":"ج1 ص39","text":"وفي النمل والأعراف والروم ثانيا ... وفاطر دم شكرا وفي الحجر فصلا","a":"وفي النمل والأعراف والروم ثانيا","b":"وفاطر دم شكرا وفي الحجر فصلا","ref":["ibraz:490","siraj:42"]},{"id":"shatibiyya:490","bookId":"shatibiyya","type":"bayt","num":490,"seq":490,"chapter":"سورة البقرة","title":"البيت 490","page":"ج1 ص39","text":"وفي سورة الشورى ومن تحت رعده ... خصوص وفي الفرقان زاكيه هللا","a":"وفي سورة الشورى ومن تحت رعده","b":"خصوص وفي الفرقان زاكيه هللا","ref":["ibraz:491"]},{"id":"shatibiyya:491","bookId":"shatibiyya","type":"bayt","num":491,"seq":491,"chapter":"سورة البقرة","title":"البيت 491","page":"ج1 ص39","text":"وأي خطاب بعد عم ولو ترى ... وفي إذ يرون الياء بالضم كللا","a":"وأي خطاب بعد عم ولو ترى","b":"وفي إذ يرون الياء بالضم كللا","ref":["ibraz:492","siraj:42"]},{"id":"shatibiyya:492","bookId":"shatibiyya","type":"bayt","num":492,"seq":492,"chapter":"سورة البقرة","title":"البيت 492","page":"ج1 ص39","text":"وحيث أتي خطوات الطاء ساكن ... وقل ضمه عن زاهد كيف رتلا","a":"وحيث أتي خطوات الطاء ساكن","b":"وقل ضمه عن زاهد كيف رتلا","ref":["ibraz:493","siraj:42"]},{"id":"shatibiyya:493","bookId":"shatibiyya","type":"bayt","num":493,"seq":493,"chapter":"سورة البقرة","title":"البيت 493","page":"ج1 ص39","text":"وضمك أولى الساكنين لثالث ... يضم لزوما كسره في ند حلا","a":"وضمك أولى الساكنين لثالث","b":"يضم لزوما كسره في ند حلا","ref":["ibraz:494","siraj:42"]},{"id":"shatibiyya:494","bookId":"shatibiyya","type":"bayt","num":494,"seq":494,"chapter":"سورة البقرة","title":"البيت 494","page":"ج1 ص39","text":"قل ادعوا أو انقص قالت اخرج أن اعبدوا ... ومحظورا انظر مع قد استهزئ اعتلا","a":"قل ادعوا أو انقص قالت اخرج أن اعبدوا","b":"ومحظورا انظر مع قد استهزئ اعتلا","ref":["ibraz:495","siraj:42"]},{"id":"shatibiyya:495","bookId":"shatibiyya","type":"bayt","num":495,"seq":495,"chapter":"سورة البقرة","title":"البيت 495","page":"ج1 ص39","text":"سوى أو وقل لابن العلا وبكسره ... لتنوينه قال ابن ذكوان مقولا","a":"سوى أو وقل لابن العلا وبكسره","b":"لتنوينه قال ابن ذكوان مقولا","ref":["ibraz:70","siraj:42"]},{"id":"shatibiyya:496","bookId":"shatibiyya","type":"bayt","num":496,"seq":496,"chapter":"سورة البقرة","title":"البيت 496","page":"ج1 ص39","text":"بخلف له في رحمة وخبيثة ... ورفعك ليس البر ينصب في علا","a":"بخلف له في رحمة وخبيثة","b":"ورفعك ليس البر ينصب في علا","ref":["ibraz:497","siraj:42"]},{"id":"shatibiyya:497","bookId":"shatibiyya","type":"bayt","num":497,"seq":497,"chapter":"سورة البقرة","title":"البيت 497","page":"ج1 ص39","text":"ولكن خفيف وارفع البر عم في ... هما وموص ثقله صح شلشلا","a":"ولكن خفيف وارفع البر عم في","b":"هما وموص ثقله صح شلشلا","ref":["ibraz:498","siraj:42"]},{"id":"shatibiyya:498","bookId":"shatibiyya","type":"bayt","num":498,"seq":498,"chapter":"سورة البقرة","title":"البيت 498","page":"ج1 ص39","text":"وفدية نون وارفع الخفض بعد في ... طعام لدى غصن دنا وتذللا","a":"وفدية نون وارفع الخفض بعد في","b":"طعام لدى غصن دنا وتذللا","ref":["ibraz:499","siraj:42"]},{"id":"shatibiyya:499","bookId":"shatibiyya","type":"bayt","num":499,"seq":499,"chapter":"سورة البقرة","title":"البيت 499","page":"ج1 ص39","text":"مساكين مجموعا وليس منونا ... ويفتح منه النون عم وأبجلا","a":"مساكين مجموعا وليس منونا","b":"ويفتح منه النون عم وأبجلا","ref":["ibraz:500","siraj:42"]},{"id":"shatibiyya:500","bookId":"shatibiyya","type":"bayt","num":500,"seq":500,"chapter":"سورة البقرة","title":"البيت 500","page":"ج1 ص39","text":"ونقل قران والقران دواؤنا ... وفي تكملوا قل شعبة الميم ثقلا","a":"ونقل قران والقران دواؤنا","b":"وفي تكملوا قل شعبة الميم ثقلا","ref":["ibraz:501"]},{"id":"shatibiyya:501","bookId":"shatibiyya","type":"bayt","num":501,"seq":501,"chapter":"سورة البقرة","title":"البيت 501","page":"ج1 ص39","text":"وكسر بيوت والبيوت يضم عن ... حمى جلة وجها على الأصل أقبلا","a":"وكسر بيوت والبيوت يضم عن","b":"حمى جلة وجها على الأصل أقبلا","ref":["ibraz:51","siraj:42"]},{"id":"shatibiyya:502","bookId":"shatibiyya","type":"bayt","num":502,"seq":502,"chapter":"سورة البقرة","title":"البيت 502","page":"ج1 ص40","text":"ولا تقتلوهم بعده يقتلوكمو ... فإن قتلوكم قصرها شاع وانجلا","a":"ولا تقتلوهم بعده يقتلوكمو","b":"فإن قتلوكم قصرها شاع وانجلا","ref":["ibraz:503","siraj:42"]},{"id":"shatibiyya:503","bookId":"shatibiyya","type":"bayt","num":503,"seq":503,"chapter":"سورة البقرة","title":"البيت 503","page":"ج1 ص40","text":"وبالرفع نونه فلا رفث ولا ... فسوق ولا حقا وزان محملا","a":"وبالرفع نونه فلا رفث ولا","b":"فسوق ولا حقا وزان محملا","ref":["ibraz:504","siraj:43"]},{"id":"shatibiyya:504","bookId":"shatibiyya","type":"bayt","num":504,"seq":504,"chapter":"سورة البقرة","title":"البيت 504","page":"ج1 ص40","text":"وفتحك سين السلم أصل رضى دنا ... وحتى يقول الرفع في اللام أولا","a":"وفتحك سين السلم أصل رضى دنا","b":"وحتى يقول الرفع في اللام أولا","ref":["ibraz:505","siraj:43"]},{"id":"shatibiyya:505","bookId":"shatibiyya","type":"bayt","num":505,"seq":505,"chapter":"سورة البقرة","title":"البيت 505","page":"ج1 ص40","text":"وفي التاء فاضمم وافتح الجيم ترجع ال ... أمور سما نصا وحيث تنزلا","a":"وفي التاء فاضمم وافتح الجيم ترجع ال","b":"أمور سما نصا وحيث تنزلا","ref":["ibraz:506","siraj:43"]},{"id":"shatibiyya:506","bookId":"shatibiyya","type":"bayt","num":506,"seq":506,"chapter":"سورة البقرة","title":"البيت 506","page":"ج1 ص40","text":"وإثم كبير شاع بالثا مثلثا ... وغيرهما بالباء نقطة اسفلا","a":"وإثم كبير شاع بالثا مثلثا","b":"وغيرهما بالباء نقطة اسفلا","ref":["ibraz:51","siraj:43"]},{"id":"shatibiyya:507","bookId":"shatibiyya","type":"bayt","num":507,"seq":507,"chapter":"سورة البقرة","title":"البيت 507","page":"ج1 ص40","text":"قل العفو للبصري رفع وبعده ... لأعنتكم بالخلف أحمد سهلا","a":"قل العفو للبصري رفع وبعده","b":"لأعنتكم بالخلف أحمد سهلا","ref":["ibraz:508","siraj:43"]},{"id":"shatibiyya:508","bookId":"shatibiyya","type":"bayt","num":508,"seq":508,"chapter":"سورة البقرة","title":"البيت 508","page":"ج1 ص40","text":"ويطهرن في الطاء السكون وهاؤه ... يضم وخفا إذ سما كيف عولا","a":"ويطهرن في الطاء السكون وهاؤه","b":"يضم وخفا إذ سما كيف عولا","ref":["ibraz:509","siraj:43"]},{"id":"shatibiyya:509","bookId":"shatibiyya","type":"bayt","num":509,"seq":509,"chapter":"سورة البقرة","title":"البيت 509","page":"ج1 ص40","text":"وضم يخافا فاز والكل أدغموا ... تضارر وضم الراء حق وذو جلا","a":"وضم يخافا فاز والكل أدغموا","b":"تضارر وضم الراء حق وذو جلا","ref":["ibraz:510","siraj:43"]},{"id":"shatibiyya:510","bookId":"shatibiyya","type":"bayt","num":510,"seq":510,"chapter":"سورة البقرة","title":"البيت 510","page":"ج1 ص40","text":"وقصر أتيتم من ربا وأتيتمو ... هنا دار وجها ليس إلا مبجلا","a":"وقصر أتيتم من ربا وأتيتمو","b":"هنا دار وجها ليس إلا مبجلا","ref":["ibraz:511","siraj:43"]},{"id":"shatibiyya:511","bookId":"shatibiyya","type":"bayt","num":511,"seq":511,"chapter":"سورة البقرة","title":"البيت 511","page":"ج1 ص40","text":"معا قدر حرك من صحاب وحيث جا ... يضم تمسوهن وامدده شلشلا","a":"معا قدر حرك من صحاب وحيث جا","b":"يضم تمسوهن وامدده شلشلا","ref":["ibraz:512"]},{"id":"shatibiyya:512","bookId":"shatibiyya","type":"bayt","num":512,"seq":512,"chapter":"سورة البقرة","title":"البيت 512","page":"ج1 ص40","text":"وصية ارفع صفو حرميه رضى ... ويبصط عنهم غير قنبل اعتلا","a":"وصية ارفع صفو حرميه رضى","b":"ويبصط عنهم غير قنبل اعتلا","ref":["ibraz:50","siraj:43"]},{"id":"shatibiyya:513","bookId":"shatibiyya","type":"bayt","num":513,"seq":513,"chapter":"سورة البقرة","title":"البيت 513","page":"ج1 ص40","text":"وبالسين باقيهم وفي الخلق بصطة ... وقل فيهما الوجهان قولا موصلا","a":"وبالسين باقيهم وفي الخلق بصطة","b":"وقل فيهما الوجهان قولا موصلا","ref":["ibraz:514","siraj:43"]},{"id":"shatibiyya:514","bookId":"shatibiyya","type":"bayt","num":514,"seq":514,"chapter":"سورة البقرة","title":"البيت 514","page":"ج1 ص40","text":"يضاعفه ارفع في الحديد وههنا ... سما شكره والعين في الكل ثقلا","a":"يضاعفه ارفع في الحديد وههنا","b":"سما شكره والعين في الكل ثقلا","ref":["ibraz:515"]},{"id":"shatibiyya:515","bookId":"shatibiyya","type":"bayt","num":515,"seq":515,"chapter":"سورة البقرة","title":"البيت 515","page":"ج1 ص41","text":"كما دار واقصر مع مضعفة وقل ... عسيتم بكسر السين حيث أتى انجلا","a":"كما دار واقصر مع مضعفة وقل","b":"عسيتم بكسر السين حيث أتى انجلا","ref":["ibraz:516","siraj:43"]},{"id":"shatibiyya:516","bookId":"shatibiyya","type":"bayt","num":516,"seq":516,"chapter":"سورة البقرة","title":"البيت 516","page":"ج1 ص41","text":"دفاع بها والحج فتح وساكن ... وقصر خصوصا غرفة ضم ذو ولا","a":"دفاع بها والحج فتح وساكن","b":"وقصر خصوصا غرفة ضم ذو ولا","ref":["ibraz:517","siraj:43"]},{"id":"shatibiyya:517","bookId":"shatibiyya","type":"bayt","num":517,"seq":517,"chapter":"سورة البقرة","title":"البيت 517","page":"ج1 ص41","text":"ولا بيع نونه ولا خلة ولا ... شفاعة وارفعهن ذا أسوة تلا","a":"ولا بيع نونه ولا خلة ولا","b":"شفاعة وارفعهن ذا أسوة تلا","ref":["ibraz:518","siraj:43"]},{"id":"shatibiyya:518","bookId":"shatibiyya","type":"bayt","num":518,"seq":518,"chapter":"سورة البقرة","title":"البيت 518","page":"ج1 ص41","text":"ولا لغو لا تأثيم لا بيع مع ولا ... خلال بإبراهيم والطور وصلا","a":"ولا لغو لا تأثيم لا بيع مع ولا","b":"خلال بإبراهيم والطور وصلا","ref":["ibraz:519","siraj:43"]},{"id":"shatibiyya:519","bookId":"shatibiyya","type":"bayt","num":519,"seq":519,"chapter":"سورة البقرة","title":"البيت 519","page":"ج1 ص41","text":"ومد أنا في الوصل مع ضم همزة ... وفتح أتى والخلف في الكسر بجلا","a":"ومد أنا في الوصل مع ضم همزة","b":"وفتح أتى والخلف في الكسر بجلا","ref":["ibraz:520","siraj:43"]},{"id":"shatibiyya:520","bookId":"shatibiyya","type":"bayt","num":520,"seq":520,"chapter":"سورة البقرة","title":"البيت 520","page":"ج1 ص41","text":"وننشزها ذاك وبالراء غيرهم ... وصل يتسنه دون هاء شمردلا","a":"وننشزها ذاك وبالراء غيرهم","b":"وصل يتسنه دون هاء شمردلا","ref":["ibraz:521","siraj:43"]},{"id":"shatibiyya:521","bookId":"shatibiyya","type":"bayt","num":521,"seq":521,"chapter":"سورة البقرة","title":"البيت 521","page":"ج1 ص41","text":"وبالوصل قال اعلم مع الجزم شافع ... فصرهن ضم الصاد بالكسر فصلا","a":"وبالوصل قال اعلم مع الجزم شافع","b":"فصرهن ضم الصاد بالكسر فصلا","ref":["ibraz:522","siraj:43"]},{"id":"shatibiyya:522","bookId":"shatibiyya","type":"bayt","num":522,"seq":522,"chapter":"سورة البقرة","title":"البيت 522","page":"ج1 ص41","text":"وجزءا وجزء ضم الاسكان صف وحي ... ثما أكلها ذكرا وفي الغير ذو حلا","a":"وجزءا وجزء ضم الاسكان صف وحي","b":"ثما أكلها ذكرا وفي الغير ذو حلا","ref":["ibraz:523","siraj:43"]},{"id":"shatibiyya:523","bookId":"shatibiyya","type":"bayt","num":523,"seq":523,"chapter":"سورة البقرة","title":"البيت 523","page":"ج1 ص41","text":"وفي ربوة في المؤمنين وههنا ... على فتح ضم الراء نبهث كفلا","a":"وفي ربوة في المؤمنين وههنا","b":"على فتح ضم الراء نبهث كفلا","ref":["ibraz:524"]},{"id":"shatibiyya:524","bookId":"shatibiyya","type":"bayt","num":524,"seq":524,"chapter":"سورة البقرة","title":"البيت 524","page":"ج1 ص41","text":"وفي الوصل للبزي شدد تيمموا ... وتاء توفى في النسا عنه مجملا","a":"وفي الوصل للبزي شدد تيمموا","b":"وتاء توفى في النسا عنه مجملا","ref":["ibraz:525","siraj:43"]},{"id":"shatibiyya:525","bookId":"shatibiyya","type":"bayt","num":525,"seq":525,"chapter":"سورة البقرة","title":"البيت 525","page":"ج1 ص41","text":"وفي آل عمران له لا تفرقوا ... والانعام فيها فتفرق مثلا","a":"وفي آل عمران له لا تفرقوا","b":"والانعام فيها فتفرق مثلا","ref":["ibraz:526","siraj:43"]},{"id":"shatibiyya:526","bookId":"shatibiyya","type":"bayt","num":526,"seq":526,"chapter":"سورة البقرة","title":"البيت 526","page":"ج1 ص41","text":"وعند العقود التاء في لا تعاونوا ... ويروى ثلاثا في تلقف مثلا","a":"وعند العقود التاء في لا تعاونوا","b":"ويروى ثلاثا في تلقف مثلا","ref":["ibraz:527","siraj:43"]},{"id":"shatibiyya:527","bookId":"shatibiyya","type":"bayt","num":527,"seq":527,"chapter":"سورة البقرة","title":"البيت 527","page":"ج1 ص41","text":"تنزل عنه أربع وتناصرو ... ن نارا تلظى إذ تلقون ثقلا","a":"تنزل عنه أربع وتناصرو","b":"ن نارا تلظى إذ تلقون ثقلا","ref":["ibraz:528","siraj:44"]},{"id":"shatibiyya:528","bookId":"shatibiyya","type":"bayt","num":528,"seq":528,"chapter":"سورة البقرة","title":"البيت 528","page":"ج1 ص42","text":"تكلم مع حرفي تولوا بهودها ... وفي نورها والإمتحان وبعدلا","a":"تكلم مع حرفي تولوا بهودها","b":"وفي نورها والإمتحان وبعدلا","ref":["ibraz:529","siraj:44"]},{"id":"shatibiyya:529","bookId":"shatibiyya","type":"bayt","num":529,"seq":529,"chapter":"سورة البقرة","title":"البيت 529","page":"ج1 ص42","text":"في الانفال أيضا ثم فيها تنازعوا ... تبرجن في الأحزاب مع أن تبدلا","a":"في الانفال أيضا ثم فيها تنازعوا","b":"تبرجن في الأحزاب مع أن تبدلا","ref":["ibraz:530","siraj:44"]},{"id":"shatibiyya:530","bookId":"shatibiyya","type":"bayt","num":530,"seq":530,"chapter":"سورة البقرة","title":"البيت 530","page":"ج1 ص42","text":"وفي التوبة الغراء قل هل تربصو ... ن عنه وجمع الساكنين هنا انجلى","a":"وفي التوبة الغراء قل هل تربصو","b":"ن عنه وجمع الساكنين هنا انجلى","ref":["siraj:44"]},{"id":"shatibiyya:531","bookId":"shatibiyya","type":"bayt","num":531,"seq":531,"chapter":"سورة البقرة","title":"البيت 531","page":"ج1 ص42","text":"تميز يروي ثم حرف تخيرو ... ن عنه تلهى قبله الهاء وصلا","a":"تميز يروي ثم حرف تخيرو","b":"ن عنه تلهى قبله الهاء وصلا","ref":["ibraz:532","siraj:44"]},{"id":"shatibiyya:532","bookId":"shatibiyya","type":"bayt","num":532,"seq":532,"chapter":"سورة البقرة","title":"البيت 532","page":"ج1 ص42","text":"وفي الحجرات التاء في لتعارفوا ... وبعد ولا حرفان من قبله جلا","a":"وفي الحجرات التاء في لتعارفوا","b":"وبعد ولا حرفان من قبله جلا","ref":["ibraz:533","siraj:44"]},{"id":"shatibiyya:533","bookId":"shatibiyya","type":"bayt","num":533,"seq":533,"chapter":"سورة البقرة","title":"البيت 533","page":"ج1 ص42","text":"وكنتم تمنون الذي مع تفكهو ... ن عنه على وجهين فافهم محصلا","a":"وكنتم تمنون الذي مع تفكهو","b":"ن عنه على وجهين فافهم محصلا","ref":["ibraz:534","siraj:44"]},{"id":"shatibiyya:534","bookId":"shatibiyya","type":"bayt","num":534,"seq":534,"chapter":"سورة البقرة","title":"البيت 534","page":"ج1 ص42","text":"نعما معا في النون فتح كما شفا ... وإخفاء كسر العين صيغ به حلا","a":"نعما معا في النون فتح كما شفا","b":"وإخفاء كسر العين صيغ به حلا","ref":["ibraz:535","siraj:44"]},{"id":"shatibiyya:535","bookId":"shatibiyya","type":"bayt","num":535,"seq":535,"chapter":"سورة البقرة","title":"البيت 535","page":"ج1 ص42","text":"ويا ونكفر عن كرام وجزمه ... أتى شافيا والغير بالرفع وكلا","a":"ويا ونكفر عن كرام وجزمه","b":"أتى شافيا والغير بالرفع وكلا","ref":["ibraz:536","siraj:44"]},{"id":"shatibiyya:536","bookId":"shatibiyya","type":"bayt","num":536,"seq":536,"chapter":"سورة البقرة","title":"البيت 536","page":"ج1 ص42","text":"ويحسب كسر السين مستقبلا سما ... رضاه ولم يلزم قياسا مؤصلا","a":"ويحسب كسر السين مستقبلا سما","b":"رضاه ولم يلزم قياسا مؤصلا","ref":["ibraz:537","siraj:44"]},{"id":"shatibiyya:537","bookId":"shatibiyya","type":"bayt","num":537,"seq":537,"chapter":"سورة البقرة","title":"البيت 537","page":"ج1 ص42","text":"وقل فأذنوا بالمد واكسر فتى صفا ... وميسرة بالضم في السين أصلا","a":"وقل فأذنوا بالمد واكسر فتى صفا","b":"وميسرة بالضم في السين أصلا","ref":["ibraz:538","siraj:44"]},{"id":"shatibiyya:538","bookId":"shatibiyya","type":"bayt","num":538,"seq":538,"chapter":"سورة البقرة","title":"البيت 538","page":"ج1 ص42","text":"وتصدقوا خف نما ترجعون قل ... بضم وفتح عن سوى ولد العلا","a":"وتصدقوا خف نما ترجعون قل","b":"بضم وفتح عن سوى ولد العلا","ref":["ibraz:539","siraj:44"]},{"id":"shatibiyya:539","bookId":"shatibiyya","type":"bayt","num":539,"seq":539,"chapter":"سورة البقرة","title":"البيت 539","page":"ج1 ص42","text":"وفي أن تضل الكسر فاز وخففوا ... فتذكر حقا وارفع الرا فتعدلا","a":"وفي أن تضل الكسر فاز وخففوا","b":"فتذكر حقا وارفع الرا فتعدلا","ref":["ibraz:540","siraj:44"]},{"id":"shatibiyya:540","bookId":"shatibiyya","type":"bayt","num":540,"seq":540,"chapter":"سورة البقرة","title":"البيت 540","page":"ج1 ص42","text":"تجارة انصب رفعه في النسا ثوى ... وحاضرة معها هنا عاصم تلا","a":"تجارة انصب رفعه في النسا ثوى","b":"وحاضرة معها هنا عاصم تلا","ref":["ibraz:541","siraj:44"]},{"id":"shatibiyya:541","bookId":"shatibiyya","type":"bayt","num":541,"seq":541,"chapter":"سورة البقرة","title":"البيت 541","page":"ج1 ص42","text":"وحق رهان ضم كسر وفتحة ... وقصر ويغفر مع يعذب سما العلا","a":"وحق رهان ضم كسر وفتحة","b":"وقصر ويغفر مع يعذب سما العلا","ref":["ibraz:542","siraj:44"]},{"id":"shatibiyya:542","bookId":"shatibiyya","type":"bayt","num":542,"seq":542,"chapter":"سورة البقرة","title":"البيت 542","page":"ج1 ص43","text":"شذا الجزم والتوحيد في وكتابه ... شريف وفي التحريم جمع حمى علا","a":"شذا الجزم والتوحيد في وكتابه","b":"شريف وفي التحريم جمع حمى علا","ref":["ibraz:543","siraj:44"]},{"id":"shatibiyya:543","bookId":"shatibiyya","type":"bayt","num":543,"seq":543,"chapter":"سورة البقرة","title":"البيت 543","page":"ج1 ص43","text":"وبيتي وعهدي فاذكروني مضافها ... وربي وبي مني وإني معا حلا","a":"وبيتي وعهدي فاذكروني مضافها","b":"وربي وبي مني وإني معا حلا","ref":["ibraz:544","siraj:44"]},{"id":"shatibiyya:544","bookId":"shatibiyya","type":"bayt","num":544,"seq":544,"chapter":"سورة آل عمران","title":"البيت 544","page":"ج1 ص43","text":"وإضجاعك التوراة ما رد حسنه ... وقلل في جود وبالخلف بللا","a":"وإضجاعك التوراة ما رد حسنه","b":"وقلل في جود وبالخلف بللا","ref":["ibraz:63","siraj:45"]},{"id":"shatibiyya:545","bookId":"shatibiyya","type":"bayt","num":545,"seq":545,"chapter":"سورة آل عمران","title":"البيت 545","page":"ج1 ص43","text":"وفي تغلبون الغيب مع تحشرون في ... رضا وترون الغيب خص وخللا","a":"وفي تغلبون الغيب مع تحشرون في","b":"رضا وترون الغيب خص وخللا","ref":["ibraz:546","siraj:45"]},{"id":"shatibiyya:546","bookId":"shatibiyya","type":"bayt","num":546,"seq":546,"chapter":"سورة آل عمران","title":"البيت 546","page":"ج1 ص43","text":"ورضوان اضمم غير ثاني العقود كس ... ره صح إن الدين بالفتح رفلا","a":"ورضوان اضمم غير ثاني العقود كس","b":"ره صح إن الدين بالفتح رفلا","ref":["ibraz:547","siraj:45"]},{"id":"shatibiyya:547","bookId":"shatibiyya","type":"bayt","num":547,"seq":547,"chapter":"سورة آل عمران","title":"البيت 547","page":"ج1 ص43","text":"وفي يقتلون الثان قال يقاتلو ... ن حمزة وهو الحبر ساد مقتلا","a":"وفي يقتلون الثان قال يقاتلو","b":"ن حمزة وهو الحبر ساد مقتلا","ref":["ibraz:548","siraj:45"]},{"id":"shatibiyya:548","bookId":"shatibiyya","type":"bayt","num":548,"seq":548,"chapter":"سورة آل عمران","title":"البيت 548","page":"ج1 ص43","text":"وفي بلد ميت مع الميت خففوا ... صفا نفرا والميتة الخف خولا","a":"وفي بلد ميت مع الميت خففوا","b":"صفا نفرا والميتة الخف خولا","ref":["ibraz:549","siraj:45"]},{"id":"shatibiyya:549","bookId":"shatibiyya","type":"bayt","num":549,"seq":549,"chapter":"سورة آل عمران","title":"البيت 549","page":"ج1 ص43","text":"وميتا لدى الأنعام والحجرات خذ ... وما لم يمت للكل جاء مثقلا","a":"وميتا لدى الأنعام والحجرات خذ","b":"وما لم يمت للكل جاء مثقلا","ref":["ibraz:550","siraj:45"]},{"id":"shatibiyya:550","bookId":"shatibiyya","type":"bayt","num":550,"seq":550,"chapter":"سورة آل عمران","title":"البيت 550","page":"ج1 ص43","text":"وكفلها الكوفي ثقيلا وسكنوا ... وضعت وضموا ساكنا صح كفلا","a":"وكفلها الكوفي ثقيلا وسكنوا","b":"وضعت وضموا ساكنا صح كفلا","ref":["ibraz:551","siraj:45"]},{"id":"shatibiyya:551","bookId":"shatibiyya","type":"bayt","num":551,"seq":551,"chapter":"سورة آل عمران","title":"البيت 551","page":"ج1 ص43","text":"وقل زكريا دون همز جميعه ... صحاب ورفع غير شعبة الاولا","a":"وقل زكريا دون همز جميعه","b":"صحاب ورفع غير شعبة الاولا","ref":["ibraz:552","siraj:3"]},{"id":"shatibiyya:552","bookId":"shatibiyya","type":"bayt","num":552,"seq":552,"chapter":"سورة آل عمران","title":"البيت 552","page":"ج1 ص43","text":"وذكر فناداه وأضجعه شاهدا ... ومن بعد أن الله يكسر في كلا","a":"وذكر فناداه وأضجعه شاهدا","b":"ومن بعد أن الله يكسر في كلا","ref":["ibraz:553","siraj:45"]},{"id":"shatibiyya:553","bookId":"shatibiyya","type":"bayt","num":553,"seq":553,"chapter":"سورة آل عمران","title":"البيت 553","page":"ج1 ص43","text":"مع الكهف والإسراء يبشر كم سما ... نعم ضم حرك واكسر الضم أثقلا","a":"مع الكهف والإسراء يبشر كم سما","b":"نعم ضم حرك واكسر الضم أثقلا","ref":["ibraz:554","siraj:45"]},{"id":"shatibiyya:554","bookId":"shatibiyya","type":"bayt","num":554,"seq":554,"chapter":"سورة آل عمران","title":"البيت 554","page":"ج1 ص44","text":"نعم عم في الشورى وفي التوبة اعكسوا ... لحمزة مع كاف مع الحجر أولا","a":"نعم عم في الشورى وفي التوبة اعكسوا","b":"لحمزة مع كاف مع الحجر أولا","ref":["ibraz:555","siraj:45"]},{"id":"shatibiyya:555","bookId":"shatibiyya","type":"bayt","num":555,"seq":555,"chapter":"سورة آل عمران","title":"البيت 555","page":"ج1 ص44","text":"نعلمه بالياء نص أئمة ... وبالكسر أني أخلق اعتاد أفصلا","a":"نعلمه بالياء نص أئمة","b":"وبالكسر أني أخلق اعتاد أفصلا","ref":["ibraz:556","siraj:45"]},{"id":"shatibiyya:556","bookId":"shatibiyya","type":"bayt","num":556,"seq":556,"chapter":"سورة آل عمران","title":"البيت 556","page":"ج1 ص44","text":"وفي طائرا طيرا بها وعقودها ... خصوصا وياء في نوفيهم علا","a":"وفي طائرا طيرا بها وعقودها","b":"خصوصا وياء في نوفيهم علا","ref":["ibraz:557","siraj:45"]},{"id":"shatibiyya:557","bookId":"shatibiyya","type":"bayt","num":557,"seq":557,"chapter":"سورة آل عمران","title":"البيت 557","page":"ج1 ص44","text":"ولا ألف في ها هأنتم زكا جنا ... وسهل أخا حمد وكم مبدل جلا","a":"ولا ألف في ها هأنتم زكا جنا","b":"وسهل أخا حمد وكم مبدل جلا","ref":["ibraz:558","siraj:45"]},{"id":"shatibiyya:558","bookId":"shatibiyya","type":"bayt","num":558,"seq":558,"chapter":"سورة آل عمران","title":"البيت 558","page":"ج1 ص44","text":"وفي هائه التنبيه من ثابت هدى ... وإبداله من همزة زان جملا","a":"وفي هائه التنبيه من ثابت هدى","b":"وإبداله من همزة زان جملا","ref":["ibraz:559","siraj:45"]},{"id":"shatibiyya:559","bookId":"shatibiyya","type":"bayt","num":559,"seq":559,"chapter":"سورة آل عمران","title":"البيت 559","page":"ج1 ص44","text":"ويحتمل الوجهين عن غيرهم وكم ... وجيه به الوجهين للكل حملا","a":"ويحتمل الوجهين عن غيرهم وكم","b":"وجيه به الوجهين للكل حملا","ref":["ibraz:560","siraj:45"]},{"id":"shatibiyya:560","bookId":"shatibiyya","type":"bayt","num":560,"seq":560,"chapter":"سورة آل عمران","title":"البيت 560","page":"ج1 ص44","text":"ويقصر في التنبيه ذو القصر مذهبا ... وذو البدل الوجهان عنه مسهلا","a":"ويقصر في التنبيه ذو القصر مذهبا","b":"وذو البدل الوجهان عنه مسهلا","ref":["ibraz:586","siraj:45"]},{"id":"shatibiyya:561","bookId":"shatibiyya","type":"bayt","num":561,"seq":561,"chapter":"سورة آل عمران","title":"البيت 561","page":"ج1 ص44","text":"وضم وحرك تعلمون الكتاب مع ... مشددة من بعد بالكسر ذللا","a":"وضم وحرك تعلمون الكتاب مع","b":"مشددة من بعد بالكسر ذللا","ref":["ibraz:561","siraj:45"]},{"id":"shatibiyya:562","bookId":"shatibiyya","type":"bayt","num":562,"seq":562,"chapter":"سورة آل عمران","title":"البيت 562","page":"ج1 ص44","text":"ورفع ولا يأمركمو روحه سما ... وبالتاء آتينا مع الضم خولا","a":"ورفع ولا يأمركمو روحه سما","b":"وبالتاء آتينا مع الضم خولا","ref":["siraj:45"]},{"id":"shatibiyya:563","bookId":"shatibiyya","type":"bayt","num":563,"seq":563,"chapter":"سورة آل عمران","title":"البيت 563","page":"ج1 ص44","text":"وكسر لما فيه وبالغيب ترجعو ... ن عاد وفي تبغون حاكيه عولا","a":"وكسر لما فيه وبالغيب ترجعو","b":"ن عاد وفي تبغون حاكيه عولا","ref":["ibraz:563","siraj:45"]},{"id":"shatibiyya:564","bookId":"shatibiyya","type":"bayt","num":564,"seq":564,"chapter":"سورة آل عمران","title":"البيت 564","page":"ج1 ص44","text":"وبالكسر حج البيت عن شاهد وغي ... ب ما تفعلوا لن تكفروه لهم تلا","a":"وبالكسر حج البيت عن شاهد وغي","b":"ب ما تفعلوا لن تكفروه لهم تلا","ref":["ibraz:564","siraj:46"]},{"id":"shatibiyya:565","bookId":"shatibiyya","type":"bayt","num":565,"seq":565,"chapter":"سورة آل عمران","title":"البيت 565","page":"ج1 ص45","text":"يضركم بكسر الضاد مع جزم رائه ... سما ويضم الغير والراء ثقلا","a":"يضركم بكسر الضاد مع جزم رائه","b":"سما ويضم الغير والراء ثقلا","ref":["ibraz:565","siraj:46"]},{"id":"shatibiyya:566","bookId":"shatibiyya","type":"bayt","num":566,"seq":566,"chapter":"سورة آل عمران","title":"البيت 566","page":"ج1 ص45","text":"وفيما هنا قل منزلين ومنزلو ... ن لليحصبي في العنكبوت مثقلا","a":"وفيما هنا قل منزلين ومنزلو","b":"ن لليحصبي في العنكبوت مثقلا","ref":["ibraz:566","siraj:46"]},{"id":"shatibiyya:567","bookId":"shatibiyya","type":"bayt","num":567,"seq":567,"chapter":"سورة آل عمران","title":"البيت 567","page":"ج1 ص45","text":"وحق نصير كسر واو مسومي ... ن قل سارعوا لا واو قبل كما انجلى","a":"وحق نصير كسر واو مسومي","b":"ن قل سارعوا لا واو قبل كما انجلى","ref":["ibraz:69","siraj:46"]},{"id":"shatibiyya:568","bookId":"shatibiyya","type":"bayt","num":568,"seq":568,"chapter":"سورة آل عمران","title":"البيت 568","page":"ج1 ص45","text":"وقرح بضم القاف والقرح صحبة ... ومع مد كائن كسر همزته دلا","a":"وقرح بضم القاف والقرح صحبة","b":"ومع مد كائن كسر همزته دلا","ref":["ibraz:568","siraj:46"]},{"id":"shatibiyya:569","bookId":"shatibiyya","type":"bayt","num":569,"seq":569,"chapter":"سورة آل عمران","title":"البيت 569","page":"ج1 ص45","text":"ولا ياء مكسورا وقاتل بعده ... يمد وفتح الضم والكسر ذو ولا","a":"ولا ياء مكسورا وقاتل بعده","b":"يمد وفتح الضم والكسر ذو ولا","ref":["ibraz:569","siraj:46"]},{"id":"shatibiyya:570","bookId":"shatibiyya","type":"bayt","num":570,"seq":570,"chapter":"سورة آل عمران","title":"البيت 570","page":"ج1 ص45","text":"وحرك عين الرعب ضما كما رسا ... ورعبا ويغشى أنثوا شائعا تلا","a":"وحرك عين الرعب ضما كما رسا","b":"ورعبا ويغشى أنثوا شائعا تلا","ref":["ibraz:570","siraj:46"]},{"id":"shatibiyya:571","bookId":"shatibiyya","type":"bayt","num":571,"seq":571,"chapter":"سورة آل عمران","title":"البيت 571","page":"ج1 ص45","text":"وقل كله لله بالرفع حامدا ... بما يعملون الغيب شايع دخللا","a":"وقل كله لله بالرفع حامدا","b":"بما يعملون الغيب شايع دخللا","ref":["ibraz:571","siraj:46"]},{"id":"shatibiyya:572","bookId":"shatibiyya","type":"bayt","num":572,"seq":572,"chapter":"سورة آل عمران","title":"البيت 572","page":"ج1 ص45","text":"ومتم ومتنا مت في ضم كسرها ... صفا نفر وردا وحفص هنا اجتلا","a":"ومتم ومتنا مت في ضم كسرها","b":"صفا نفر وردا وحفص هنا اجتلا","ref":["ibraz:572","siraj:46"]},{"id":"shatibiyya:573","bookId":"shatibiyya","type":"bayt","num":573,"seq":573,"chapter":"سورة آل عمران","title":"البيت 573","page":"ج1 ص45","text":"وبالغيب عنه تجمعون وضم في ... يغل وفتح الضم إذ شاع كفلا","a":"وبالغيب عنه تجمعون وضم في","b":"يغل وفتح الضم إذ شاع كفلا","ref":["ibraz:573","siraj:46"]},{"id":"shatibiyya:574","bookId":"shatibiyya","type":"bayt","num":574,"seq":574,"chapter":"سورة آل عمران","title":"البيت 574","page":"ج1 ص45","text":"بما قتلوا التشديد لبى وبعده ... وفي الحج للشامي والآخر كملا","a":"بما قتلوا التشديد لبى وبعده","b":"وفي الحج للشامي والآخر كملا","ref":["ibraz:574","siraj:46"]},{"id":"shatibiyya:575","bookId":"shatibiyya","type":"bayt","num":575,"seq":575,"chapter":"سورة آل عمران","title":"البيت 575","page":"ج1 ص45","text":"دراك وقد قالا في الانعام قتلوا ... وبالخلف غيبا يحسبن له ولا","a":"دراك وقد قالا في الانعام قتلوا","b":"وبالخلف غيبا يحسبن له ولا","ref":["ibraz:575","siraj:46"]},{"id":"shatibiyya:576","bookId":"shatibiyya","type":"bayt","num":576,"seq":576,"chapter":"سورة آل عمران","title":"البيت 576","page":"ج1 ص45","text":"وأن اكسروا رفقا ويحزن غير الان ... بياء بضم واكسر الضم أحفلا","a":"وأن اكسروا رفقا ويحزن غير الان","b":"بياء بضم واكسر الضم أحفلا","ref":["ibraz:576","siraj:46"]},{"id":"shatibiyya:577","bookId":"shatibiyya","type":"bayt","num":577,"seq":577,"chapter":"سورة آل عمران","title":"البيت 577","page":"ج1 ص45","text":"وخاطب حرفا يحسبن فخذ وقل ... بما يعملون الغيب حق وذو ملا","a":"وخاطب حرفا يحسبن فخذ وقل","b":"بما يعملون الغيب حق وذو ملا","ref":["ibraz:577","siraj:46"]},{"id":"shatibiyya:578","bookId":"shatibiyya","type":"bayt","num":578,"seq":578,"chapter":"سورة آل عمران","title":"البيت 578","page":"ج1 ص45","text":"يميز مع الأنفال فاكسر سكونه ... وشدده بعد الفتح والضم شلشلا","a":"يميز مع الأنفال فاكسر سكونه","b":"وشدده بعد الفتح والضم شلشلا","ref":["ibraz:578","siraj:46"]},{"id":"shatibiyya:579","bookId":"shatibiyya","type":"bayt","num":579,"seq":579,"chapter":"سورة آل عمران","title":"البيت 579","page":"ج1 ص46","text":"سنكتب ياء ضم مع فتح ضمه ... وقتل ارفعوا مع يا نقول فيكملا","a":"سنكتب ياء ضم مع فتح ضمه","b":"وقتل ارفعوا مع يا نقول فيكملا","ref":["ibraz:579","siraj:46"]},{"id":"shatibiyya:580","bookId":"shatibiyya","type":"bayt","num":580,"seq":580,"chapter":"سورة آل عمران","title":"البيت 580","page":"ج1 ص46","text":"وبالزبر الشامي كذا رسمهم وبال ... كتاب هشام واكشف الرسم مجملا","a":"وبالزبر الشامي كذا رسمهم وبال","b":"كتاب هشام واكشف الرسم مجملا","ref":["ibraz:580","siraj:46"]},{"id":"shatibiyya:581","bookId":"shatibiyya","type":"bayt","num":581,"seq":581,"chapter":"سورة آل عمران","title":"البيت 581","page":"ج1 ص46","text":"صفا حق غيب يكتمون يبيننن ... لا تحسبن الغيب كيف سما اعتلا","a":"صفا حق غيب يكتمون يبيننن","b":"لا تحسبن الغيب كيف سما اعتلا","ref":["ibraz:581"]},{"id":"shatibiyya:582","bookId":"shatibiyya","type":"bayt","num":582,"seq":582,"chapter":"سورة آل عمران","title":"البيت 582","page":"ج1 ص46","text":"وحقا بضم البا فلا يحسبنهم ... وغيب وفيه العطف أو جاء مبدلا","a":"وحقا بضم البا فلا يحسبنهم","b":"وغيب وفيه العطف أو جاء مبدلا","ref":["ibraz:582"]},{"id":"shatibiyya:583","bookId":"shatibiyya","type":"bayt","num":583,"seq":583,"chapter":"سورة آل عمران","title":"البيت 583","page":"ج1 ص46","text":"هنا قاتلوا أخر شفاء وبعد في ... براءة أخر يقتلون شمردلا","a":"هنا قاتلوا أخر شفاء وبعد في","b":"براءة أخر يقتلون شمردلا","ref":["ibraz:583","siraj:46"]},{"id":"shatibiyya:584","bookId":"shatibiyya","type":"bayt","num":584,"seq":584,"chapter":"سورة آل عمران","title":"البيت 584","page":"ج1 ص46","text":"وياآتها وجهي وإني كلاهما ... ومني واجعل لي وأنصاري الملا","a":"وياآتها وجهي وإني كلاهما","b":"ومني واجعل لي وأنصاري الملا","ref":["siraj:46"]},{"id":"shatibiyya:585","bookId":"shatibiyya","type":"bayt","num":585,"seq":585,"chapter":"سورة النساء","title":"البيت 585","page":"ج1 ص46","text":"وكوفيهم تساءلون مخففا ... وحمزة والأرحام بالخفض جملا","a":"وكوفيهم تساءلون مخففا","b":"وحمزة والأرحام بالخفض جملا","ref":["ibraz:604","siraj:4"]},{"id":"shatibiyya:586","bookId":"shatibiyya","type":"bayt","num":586,"seq":586,"chapter":"سورة النساء","title":"البيت 586","page":"ج1 ص46","text":"وقصر قياما عم يصلون ضم كم ... صفا نافع بالرفع واحدة جلا","a":"وقصر قياما عم يصلون ضم كم","b":"صفا نافع بالرفع واحدة جلا","ref":["ibraz:605","siraj:47"]},{"id":"shatibiyya:587","bookId":"shatibiyya","type":"bayt","num":587,"seq":587,"chapter":"سورة النساء","title":"البيت 587","page":"ج1 ص46","text":"ويوصى بفتح الصاد صح كما دنا ... ووافق حفص في الأخير مجملا","a":"ويوصى بفتح الصاد صح كما دنا","b":"ووافق حفص في الأخير مجملا","ref":["ibraz:606","siraj:47"]},{"id":"shatibiyya:588","bookId":"shatibiyya","type":"bayt","num":588,"seq":588,"chapter":"سورة النساء","title":"البيت 588","page":"ج1 ص46","text":"وفي أم مع في أمها فلأمه ... لدى الوصل ضم الهمز بالكسر شمللا","a":"وفي أم مع في أمها فلأمه","b":"لدى الوصل ضم الهمز بالكسر شمللا","ref":["ibraz:607","siraj:47"]},{"id":"shatibiyya:589","bookId":"shatibiyya","type":"bayt","num":589,"seq":589,"chapter":"سورة النساء","title":"البيت 589","page":"ج1 ص46","text":"وفي أمهات النحل والنور والزمر ... مع النجم شاف واكسر الميم فيصلا","a":"وفي أمهات النحل والنور والزمر","b":"مع النجم شاف واكسر الميم فيصلا","ref":["ibraz:608","siraj:47"]},{"id":"shatibiyya:590","bookId":"shatibiyya","type":"bayt","num":590,"seq":590,"chapter":"سورة النساء","title":"البيت 590","page":"ج1 ص46","text":"وندخله نون مع طلاق وفوق مع ... نكفر نعذب معه في الفتح إذ كلا","a":"وندخله نون مع طلاق وفوق مع","b":"نكفر نعذب معه في الفتح إذ كلا","ref":["ibraz:609","siraj:47"]},{"id":"shatibiyya:591","bookId":"shatibiyya","type":"bayt","num":591,"seq":591,"chapter":"سورة النساء","title":"البيت 591","page":"ج1 ص46","text":"وهذان هاتين اللذان اللذين قل ... يشدد للمكي فذانك دم حلا","a":"وهذان هاتين اللذان اللذين قل","b":"يشدد للمكي فذانك دم حلا","ref":["ibraz:610","siraj:47"]},{"id":"shatibiyya:592","bookId":"shatibiyya","type":"bayt","num":592,"seq":592,"chapter":"سورة النساء","title":"البيت 592","page":"ج1 ص47","text":"وضم هنا كرها وعند براءة ... شهاب وفي الأحقاف ثبت معقلا","a":"وضم هنا كرها وعند براءة","b":"شهاب وفي الأحقاف ثبت معقلا","ref":["ibraz:611","siraj:47"]},{"id":"shatibiyya:593","bookId":"shatibiyya","type":"bayt","num":593,"seq":593,"chapter":"سورة النساء","title":"البيت 593","page":"ج1 ص47","text":"وفي الكل فافتح يا مبينة دنا ... صحيحا وكسر الجمع كم شرفا علا","a":"وفي الكل فافتح يا مبينة دنا","b":"صحيحا وكسر الجمع كم شرفا علا","ref":["ibraz:612","siraj:47"]},{"id":"shatibiyya:594","bookId":"shatibiyya","type":"bayt","num":594,"seq":594,"chapter":"سورة النساء","title":"البيت 594","page":"ج1 ص47","text":"وفي محصنات فاكسر الصاد راويا ... وفي المحصنات اكسر له غير أولا","a":"وفي محصنات فاكسر الصاد راويا","b":"وفي المحصنات اكسر له غير أولا","ref":["ibraz:613","siraj:47"]},{"id":"shatibiyya:595","bookId":"shatibiyya","type":"bayt","num":595,"seq":595,"chapter":"سورة النساء","title":"البيت 595","page":"ج1 ص47","text":"وضم وكسر في أحل صحابه ... وجوه وفي أحصن عن نفر العلا","a":"وضم وكسر في أحل صحابه","b":"وجوه وفي أحصن عن نفر العلا","ref":["ibraz:614","siraj:47"]},{"id":"shatibiyya:596","bookId":"shatibiyya","type":"bayt","num":596,"seq":596,"chapter":"سورة النساء","title":"البيت 596","page":"ج1 ص47","text":"مع الحج ضموا مدخلا خصه وسل ... فسل حركوا بالنقل راشده دلا","a":"مع الحج ضموا مدخلا خصه وسل","b":"فسل حركوا بالنقل راشده دلا","ref":["ibraz:615","siraj:47"]},{"id":"shatibiyya:597","bookId":"shatibiyya","type":"bayt","num":597,"seq":597,"chapter":"سورة النساء","title":"البيت 597","page":"ج1 ص47","text":"وفي عاقدت قصر ثوى ومع الحدي ... د فتح سكون البخل والضم شمللا","a":"وفي عاقدت قصر ثوى ومع الحدي","b":"د فتح سكون البخل والضم شمللا","ref":["ibraz:616","siraj:47"]},{"id":"shatibiyya:598","bookId":"shatibiyya","type":"bayt","num":598,"seq":598,"chapter":"سورة النساء","title":"البيت 598","page":"ج1 ص47","text":"وفي حسنه حرمي رفع وضمهم ... تسوى نما حقا وعم مثقلا","a":"وفي حسنه حرمي رفع وضمهم","b":"تسوى نما حقا وعم مثقلا","ref":["ibraz:617","siraj:47"]},{"id":"shatibiyya:599","bookId":"shatibiyya","type":"bayt","num":599,"seq":599,"chapter":"سورة النساء","title":"البيت 599","page":"ج1 ص47","text":"ولامستم اقصر تحتها وبها شفا ... ورفع قليل منهم النصب كللا","a":"ولامستم اقصر تحتها وبها شفا","b":"ورفع قليل منهم النصب كللا","ref":["ibraz:618","siraj:47"]},{"id":"shatibiyya:600","bookId":"shatibiyya","type":"bayt","num":600,"seq":600,"chapter":"سورة النساء","title":"البيت 600","page":"ج1 ص47","text":"وأنث يكن عن دارم تظلمون غي ... ب شهد دنا إدغام بيت في حلا","a":"وأنث يكن عن دارم تظلمون غي","b":"ب شهد دنا إدغام بيت في حلا","ref":["ibraz:619","siraj:47"]},{"id":"shatibiyya:601","bookId":"shatibiyya","type":"bayt","num":601,"seq":601,"chapter":"سورة النساء","title":"البيت 601","page":"ج1 ص47","text":"وإشمام صاد ساكن قبل داله ... كأصدق زايا شاع وارتاح أشملا","a":"وإشمام صاد ساكن قبل داله","b":"كأصدق زايا شاع وارتاح أشملا","ref":["ibraz:620","siraj:47"]},{"id":"shatibiyya:602","bookId":"shatibiyya","type":"bayt","num":602,"seq":602,"chapter":"سورة النساء","title":"البيت 602","page":"ج1 ص47","text":"وفيها وتحت الفتح قل فتثبتوا ... من الثبت والغير البيان تبدلا","a":"وفيها وتحت الفتح قل فتثبتوا","b":"من الثبت والغير البيان تبدلا","ref":["ibraz:621","siraj:47"]},{"id":"shatibiyya:603","bookId":"shatibiyya","type":"bayt","num":603,"seq":603,"chapter":"سورة النساء","title":"البيت 603","page":"ج1 ص47","text":"وعم فتى قصر السلام مؤخرا ... وغير أولي بالرفع فى حق نهشلا","a":"وعم فتى قصر السلام مؤخرا","b":"وغير أولي بالرفع فى حق نهشلا","ref":["ibraz:622","siraj:47"]},{"id":"shatibiyya:604","bookId":"shatibiyya","type":"bayt","num":604,"seq":604,"chapter":"سورة النساء","title":"البيت 604","page":"ج1 ص47","text":"ونؤتيه باليا فى حماه وضم يد ... خلون وفتح الضم حق صرى حلا","a":"ونؤتيه باليا فى حماه وضم يد","b":"خلون وفتح الضم حق صرى حلا","ref":["ibraz:623","siraj:47"]},{"id":"shatibiyya:605","bookId":"shatibiyya","type":"bayt","num":605,"seq":605,"chapter":"سورة النساء","title":"البيت 605","page":"ج1 ص47","text":"وفي مريم والطول الاول عنهم ... وفي الثان دم صفوا وفي فاطر حلا","a":"وفي مريم والطول الاول عنهم","b":"وفي الثان دم صفوا وفي فاطر حلا","ref":["ibraz:624","siraj:47"]},{"id":"shatibiyya:606","bookId":"shatibiyya","type":"bayt","num":606,"seq":606,"chapter":"سورة النساء","title":"البيت 606","page":"ج1 ص48","text":"ويصالحا فاضمم وسكن مخففا ... مع القصر واكسر لامه ثابتا تلا","a":"ويصالحا فاضمم وسكن مخففا","b":"مع القصر واكسر لامه ثابتا تلا","ref":["ibraz:625","siraj:47"]},{"id":"shatibiyya:607","bookId":"shatibiyya","type":"bayt","num":607,"seq":607,"chapter":"سورة النساء","title":"البيت 607","page":"ج1 ص48","text":"وتلووا بحذف الواو الاولى ولامه ... فضم سكونا لست فيه مجهلا","a":"وتلووا بحذف الواو الاولى ولامه","b":"فضم سكونا لست فيه مجهلا","ref":["ibraz:626","siraj:47"]},{"id":"shatibiyya:608","bookId":"shatibiyya","type":"bayt","num":608,"seq":608,"chapter":"سورة النساء","title":"البيت 608","page":"ج1 ص48","text":"ونزل فتح الضم والكسر حصنه ... وأنزل عنهم عاصم بعد نزلا","a":"ونزل فتح الضم والكسر حصنه","b":"وأنزل عنهم عاصم بعد نزلا","ref":["ibraz:627","siraj:47"]},{"id":"shatibiyya:609","bookId":"shatibiyya","type":"bayt","num":609,"seq":609,"chapter":"سورة النساء","title":"البيت 609","page":"ج1 ص48","text":"ويا سوف تؤتيهم عزيز وحمزة ... سيؤتيهم في الدرك كوف تحملا","a":"ويا سوف تؤتيهم عزيز وحمزة","b":"سيؤتيهم في الدرك كوف تحملا","ref":["ibraz:628"]},{"id":"shatibiyya:610","bookId":"shatibiyya","type":"bayt","num":610,"seq":610,"chapter":"سورة النساء","title":"البيت 610","page":"ج1 ص48","text":"بالاسكان تعدوا سكنوه وخففوا ... خصوصا وأخفى العين قالون مسهلا","a":"بالاسكان تعدوا سكنوه وخففوا","b":"خصوصا وأخفى العين قالون مسهلا","ref":["ibraz:629","siraj:47"]},{"id":"shatibiyya:611","bookId":"shatibiyya","type":"bayt","num":611,"seq":611,"chapter":"سورة النساء","title":"البيت 611","page":"ج1 ص48","text":"وفي الانبيا ضم الزبور وههنا ... زبورا وفي الإسرا لحمزة أسجلا","a":"وفي الانبيا ضم الزبور وههنا","b":"زبورا وفي الإسرا لحمزة أسجلا","ref":["ibraz:630"]},{"id":"shatibiyya:612","bookId":"shatibiyya","type":"bayt","num":612,"seq":612,"chapter":"سورة المائدة","title":"البيت 612","page":"ج1 ص48","text":"وسكن معا شنآن صحا كلاهما ... وفي كسر أن صدوكم حامد دلا","a":"وسكن معا شنآن صحا كلاهما","b":"وفي كسر أن صدوكم حامد دلا","ref":["siraj:48"]},{"id":"shatibiyya:613","bookId":"shatibiyya","type":"bayt","num":613,"seq":613,"chapter":"سورة المائدة","title":"البيت 613","page":"ج1 ص48","text":"مع القصر شدد ياء قاسية شفا ... وأرجلكم بالنصب عم رضا علا","a":"مع القصر شدد ياء قاسية شفا","b":"وأرجلكم بالنصب عم رضا علا","ref":["ibraz:52","siraj:48"]},{"id":"shatibiyya:614","bookId":"shatibiyya","type":"bayt","num":614,"seq":614,"chapter":"سورة المائدة","title":"البيت 614","page":"ج1 ص48","text":"وفي رسلنا مع رسلكم ثم رسلهم ... وفي سبلنا في الضم الاسكان حصلا","a":"وفي رسلنا مع رسلكم ثم رسلهم","b":"وفي سبلنا في الضم الاسكان حصلا","ref":["ibraz:633","siraj:48"]},{"id":"shatibiyya:615","bookId":"shatibiyya","type":"bayt","num":615,"seq":615,"chapter":"سورة المائدة","title":"البيت 615","page":"ج1 ص48","text":"وفي كلمات السحت عم نهى فتى ... وكيف أتى أذن به نافع تلا","a":"وفي كلمات السحت عم نهى فتى","b":"وكيف أتى أذن به نافع تلا","ref":["ibraz:634","siraj:48"]},{"id":"shatibiyya:616","bookId":"shatibiyya","type":"bayt","num":616,"seq":616,"chapter":"سورة المائدة","title":"البيت 616","page":"ج1 ص48","text":"ورحما سوى الشامي ونذرا صحابهم ... حموه ونكرا شرع حق له علا","a":"ورحما سوى الشامي ونذرا صحابهم","b":"حموه ونكرا شرع حق له علا","ref":["ibraz:635","siraj:48"]},{"id":"shatibiyya:617","bookId":"shatibiyya","type":"bayt","num":617,"seq":617,"chapter":"سورة المائدة","title":"البيت 617","page":"ج1 ص48","text":"ونكر دنا والعين فارفع وعطفها ... رضى والجروح ارفع رضى نفر ملا","a":"ونكر دنا والعين فارفع وعطفها","b":"رضى والجروح ارفع رضى نفر ملا","ref":["ibraz:636","siraj:48"]},{"id":"shatibiyya:618","bookId":"shatibiyya","type":"bayt","num":618,"seq":618,"chapter":"سورة المائدة","title":"البيت 618","page":"ج1 ص48","text":"وحمزة وليحكم بكسر ونصبه ... يحركه يبغون خاطب كملا","a":"وحمزة وليحكم بكسر ونصبه","b":"يحركه يبغون خاطب كملا","ref":["ibraz:64","siraj:48"]},{"id":"shatibiyya:619","bookId":"shatibiyya","type":"bayt","num":619,"seq":619,"chapter":"سورة المائدة","title":"البيت 619","page":"ج1 ص49","text":"وقبل يقول الواو غصن ورافع ... سوى ابن العلا من يرتدد عم مرسلا","a":"وقبل يقول الواو غصن ورافع","b":"سوى ابن العلا من يرتدد عم مرسلا","ref":["ibraz:638","siraj:48"]},{"id":"shatibiyya:620","bookId":"shatibiyya","type":"bayt","num":620,"seq":620,"chapter":"سورة المائدة","title":"البيت 620","page":"ج1 ص49","text":"وحرك بالإدغام للغير داله ... وبالخفض والكفار راويه حصلا","a":"وحرك بالإدغام للغير داله","b":"وبالخفض والكفار راويه حصلا","ref":["ibraz:639","siraj:48"]},{"id":"shatibiyya:621","bookId":"shatibiyya","type":"bayt","num":621,"seq":621,"chapter":"سورة المائدة","title":"البيت 621","page":"ج1 ص49","text":"وبا عبد اضمم واخفض التا بعد فز ... رسالته اجمع واكسر التا كما اعتلا","a":"وبا عبد اضمم واخفض التا بعد فز","b":"رسالته اجمع واكسر التا كما اعتلا"},{"id":"shatibiyya:622","bookId":"shatibiyya","type":"bayt","num":622,"seq":622,"chapter":"سورة المائدة","title":"البيت 622","page":"ج1 ص49","text":"صفا وتكون الرفع حج شهوده ... وعقدتم التخفيف من صحبة ولا","a":"صفا وتكون الرفع حج شهوده","b":"وعقدتم التخفيف من صحبة ولا","ref":["ibraz:641","siraj:48"]},{"id":"shatibiyya:623","bookId":"shatibiyya","type":"bayt","num":623,"seq":623,"chapter":"سورة المائدة","title":"البيت 623","page":"ج1 ص49","text":"وفي العين فامدد مقسطا فجزاء نو ... ونوا مثل ما في خفضه الرفع ثملا","a":"وفي العين فامدد مقسطا فجزاء نو","b":"ونوا مثل ما في خفضه الرفع ثملا","ref":["ibraz:642","siraj:48"]},{"id":"shatibiyya:624","bookId":"shatibiyya","type":"bayt","num":624,"seq":624,"chapter":"سورة المائدة","title":"البيت 624","page":"ج1 ص49","text":"وكفارة نون طعام برفع خف ... ضه دم غنى واقصر قياما له ملا","a":"وكفارة نون طعام برفع خف","b":"ضه دم غنى واقصر قياما له ملا","ref":["ibraz:643","siraj:48"]},{"id":"shatibiyya:625","bookId":"shatibiyya","type":"bayt","num":625,"seq":625,"chapter":"سورة المائدة","title":"البيت 625","page":"ج1 ص49","text":"وضم استحق افتح لحفص وكسره ... وفي الأوليان الأولين فطب صلا","a":"وضم استحق افتح لحفص وكسره","b":"وفي الأوليان الأولين فطب صلا","ref":["ibraz:644","siraj:48"]},{"id":"shatibiyya:626","bookId":"shatibiyya","type":"bayt","num":626,"seq":626,"chapter":"سورة المائدة","title":"البيت 626","page":"ج1 ص49","text":"وضم الغيوب يكسران عيونا ال ... عيون شيوخا دانه صحبه ملا","a":"وضم الغيوب يكسران عيونا ال","b":"عيون شيوخا دانه صحبه ملا","ref":["ibraz:645","siraj:48"]},{"id":"shatibiyya:627","bookId":"shatibiyya","type":"bayt","num":627,"seq":627,"chapter":"سورة المائدة","title":"البيت 627","page":"ج1 ص49","text":"جيوب منير دون شك وساحر ... بسحر بها مع هود والصف شمللا","a":"جيوب منير دون شك وساحر","b":"بسحر بها مع هود والصف شمللا","ref":["ibraz:646","siraj:48"]},{"id":"shatibiyya:628","bookId":"shatibiyya","type":"bayt","num":628,"seq":628,"chapter":"سورة المائدة","title":"البيت 628","page":"ج1 ص49","text":"وخاطب في هل يستطيع رواته ... وربك رفع الباء بالنصب رتلا","a":"وخاطب في هل يستطيع رواته","b":"وربك رفع الباء بالنصب رتلا","ref":["ibraz:647","siraj:48"]},{"id":"shatibiyya:629","bookId":"shatibiyya","type":"bayt","num":629,"seq":629,"chapter":"سورة المائدة","title":"البيت 629","page":"ج1 ص49","text":"ويوم برفع خذ وإني ثلاثها ... ولي ويدي أمي مضافاتها العلا","a":"ويوم برفع خذ وإني ثلاثها","b":"ولي ويدي أمي مضافاتها العلا","ref":["ibraz:648","siraj:48"]},{"id":"shatibiyya:630","bookId":"shatibiyya","type":"bayt","num":630,"seq":630,"chapter":"سورة الأنعام","title":"البيت 630","page":"ج1 ص49","text":"وصحبة يصرف فتح ضم وراؤه ... بكسر وذكر لم يكن شاع وانجلا","a":"وصحبة يصرف فتح ضم وراؤه","b":"بكسر وذكر لم يكن شاع وانجلا","ref":["ibraz:649","siraj:49"]},{"id":"shatibiyya:631","bookId":"shatibiyya","type":"bayt","num":631,"seq":631,"chapter":"سورة الأنعام","title":"البيت 631","page":"ج1 ص49","text":"وفتنتهم بالرفع عن دين كامل ... وبا ربنا بالنصب شرف وصلا","a":"وفتنتهم بالرفع عن دين كامل","b":"وبا ربنا بالنصب شرف وصلا","ref":["ibraz:650","siraj:49"]},{"id":"shatibiyya:632","bookId":"shatibiyya","type":"bayt","num":632,"seq":632,"chapter":"سورة الأنعام","title":"البيت 632","page":"ج1 ص50","text":"نكذب نصب الرفع فاز عليمه ... وفي ونكون انصبه في كسبه علا","a":"نكذب نصب الرفع فاز عليمه","b":"وفي ونكون انصبه في كسبه علا","ref":["ibraz:651","siraj:49"]},{"id":"shatibiyya:633","bookId":"shatibiyya","type":"bayt","num":633,"seq":633,"chapter":"سورة الأنعام","title":"البيت 633","page":"ج1 ص50","text":"وللدار حذف اللام الاخرى ابن عامر ... والآخرة المرفوع بالخفض وكلا","a":"وللدار حذف اللام الاخرى ابن عامر","b":"والآخرة المرفوع بالخفض وكلا","ref":["ibraz:652","siraj:49"]},{"id":"shatibiyya:634","bookId":"shatibiyya","type":"bayt","num":634,"seq":634,"chapter":"سورة الأنعام","title":"البيت 634","page":"ج1 ص50","text":"وعم علا لا يعقلون وتحتها ... خطابا وقل في يوسف عم نيطلا","a":"وعم علا لا يعقلون وتحتها","b":"خطابا وقل في يوسف عم نيطلا","ref":["ibraz:653","siraj:49"]},{"id":"shatibiyya:635","bookId":"shatibiyya","type":"bayt","num":635,"seq":635,"chapter":"سورة الأنعام","title":"البيت 635","page":"ج1 ص50","text":"وياسين من أصل ولا يكذبونك ال ... خفيف أتى رحبا وطاب تأولا","a":"وياسين من أصل ولا يكذبونك ال","b":"خفيف أتى رحبا وطاب تأولا","ref":["ibraz:654","siraj:49"]},{"id":"shatibiyya:636","bookId":"shatibiyya","type":"bayt","num":636,"seq":636,"chapter":"سورة الأنعام","title":"البيت 636","page":"ج1 ص50","text":"أريت في الاستفهام لا عين راجع ... وعن نافع سهل وكم مبدل جلا","a":"أريت في الاستفهام لا عين راجع","b":"وعن نافع سهل وكم مبدل جلا","ref":["ibraz:655"]},{"id":"shatibiyya:637","bookId":"shatibiyya","type":"bayt","num":637,"seq":637,"chapter":"سورة الأنعام","title":"البيت 637","page":"ج1 ص50","text":"إذا فتحت شدد لشام وههنا ... فتحنا وفي الأعراف واقتربت كلا","a":"إذا فتحت شدد لشام وههنا","b":"فتحنا وفي الأعراف واقتربت كلا","ref":["ibraz:655"]},{"id":"shatibiyya:638","bookId":"shatibiyya","type":"bayt","num":638,"seq":638,"chapter":"سورة الأنعام","title":"البيت 638","page":"ج1 ص50","text":"وبالغدوة الشامي بالضم ههنا ... وعن ألف واو وفي الكهف وصلا","a":"وبالغدوة الشامي بالضم ههنا","b":"وعن ألف واو وفي الكهف وصلا","ref":["ibraz:657"]},{"id":"shatibiyya:639","bookId":"shatibiyya","type":"bayt","num":639,"seq":639,"chapter":"سورة الأنعام","title":"البيت 639","page":"ج1 ص50","text":"وإن بفتح عم نصرا وبعد كم ... نما يستبين صحبة ذكروا ولا","a":"وإن بفتح عم نصرا وبعد كم","b":"نما يستبين صحبة ذكروا ولا","ref":["ibraz:655","siraj:49"]},{"id":"shatibiyya:640","bookId":"shatibiyya","type":"bayt","num":640,"seq":640,"chapter":"سورة الأنعام","title":"البيت 640","page":"ج1 ص50","text":"سبيل برفع خذ ويقض بضم سا ... كن مع ضم الكسر شدد وأهملا","a":"سبيل برفع خذ ويقض بضم سا","b":"كن مع ضم الكسر شدد وأهملا","ref":["ibraz:659","siraj:49"]},{"id":"shatibiyya:641","bookId":"shatibiyya","type":"bayt","num":641,"seq":641,"chapter":"سورة الأنعام","title":"البيت 641","page":"ج1 ص50","text":"نعم دون إلباس وذكر مضجعا ... توفاه واستهواه حمزة منسلا","a":"نعم دون إلباس وذكر مضجعا","b":"توفاه واستهواه حمزة منسلا","ref":["ibraz:660","siraj:49"]},{"id":"shatibiyya:642","bookId":"shatibiyya","type":"bayt","num":642,"seq":642,"chapter":"سورة الأنعام","title":"البيت 642","page":"ج1 ص50","text":"معا خفية في ضمه كسر شعبة ... وأنجيت للكوفي أنجى تحولا","a":"معا خفية في ضمه كسر شعبة","b":"وأنجيت للكوفي أنجى تحولا","ref":["ibraz:661","siraj:49"]},{"id":"shatibiyya:643","bookId":"shatibiyya","type":"bayt","num":643,"seq":643,"chapter":"سورة الأنعام","title":"البيت 643","page":"ج1 ص50","text":"قل الله ينجيكم يثقل معهم ... هشام وشام ينسينك ثقلا","a":"قل الله ينجيكم يثقل معهم","b":"هشام وشام ينسينك ثقلا","ref":["ibraz:662","siraj:49"]},{"id":"shatibiyya:644","bookId":"shatibiyya","type":"bayt","num":644,"seq":644,"chapter":"سورة الأنعام","title":"البيت 644","page":"ج1 ص50","text":"وحرفي رأى كلا أمل مزن صحبة ... وفي همزه حسن وفي الراء يجتلا","a":"وحرفي رأى كلا أمل مزن صحبة","b":"وفي همزه حسن وفي الراء يجتلا","ref":["ibraz:663","siraj:49"]},{"id":"shatibiyya:645","bookId":"shatibiyya","type":"bayt","num":645,"seq":645,"chapter":"سورة الأنعام","title":"البيت 645","page":"ج1 ص50","text":"بخلف وخلف فيهما مع مضمر ... مصيب وعن عثمان في الكل قللا","a":"بخلف وخلف فيهما مع مضمر","b":"مصيب وعن عثمان في الكل قللا","ref":["ibraz:664","siraj:49"]},{"id":"shatibiyya:646","bookId":"shatibiyya","type":"bayt","num":646,"seq":646,"chapter":"سورة الأنعام","title":"البيت 646","page":"ج1 ص51","text":"وقبل السكون الرا أمل في صفا يد ... بخلف وقل في الهمز خلف يقي صلا","a":"وقبل السكون الرا أمل في صفا يد","b":"بخلف وقل في الهمز خلف يقي صلا","ref":["ibraz:665","siraj:49"]},{"id":"shatibiyya:647","bookId":"shatibiyya","type":"bayt","num":647,"seq":647,"chapter":"سورة الأنعام","title":"البيت 647","page":"ج1 ص51","text":"وقف فيه كالأولى ونحو رأت رأوا ... رأيت بفتح الكل وقفا وموصلا","a":"وقف فيه كالأولى ونحو رأت رأوا","b":"رأيت بفتح الكل وقفا وموصلا","ref":["ibraz:666","siraj:49"]},{"id":"shatibiyya:648","bookId":"shatibiyya","type":"bayt","num":648,"seq":648,"chapter":"سورة الأنعام","title":"البيت 648","page":"ج1 ص51","text":"وخفف نونا قبل في الله من له ... بخلف أتى والحذف لم يك أولا","a":"وخفف نونا قبل في الله من له","b":"بخلف أتى والحذف لم يك أولا","ref":["siraj:49"]},{"id":"shatibiyya:649","bookId":"shatibiyya","type":"bayt","num":649,"seq":649,"chapter":"سورة الأنعام","title":"البيت 649","page":"ج1 ص51","text":"وفي درجات النون مع يوسف ... ثوى ووالليسع الحرفان حرك مثقلا","a":"وفي درجات النون مع يوسف","b":"ثوى ووالليسع الحرفان حرك مثقلا","ref":["ibraz:668","siraj:3"]},{"id":"shatibiyya:650","bookId":"shatibiyya","type":"bayt","num":650,"seq":650,"chapter":"سورة الأنعام","title":"البيت 650","page":"ج1 ص51","text":"وسكن شفاء واقتده حذف هائه ... شفاء وبالتحريك بالكسر كفلا","a":"وسكن شفاء واقتده حذف هائه","b":"شفاء وبالتحريك بالكسر كفلا","ref":["ibraz:669","siraj:49"]},{"id":"shatibiyya:651","bookId":"shatibiyya","type":"bayt","num":651,"seq":651,"chapter":"سورة الأنعام","title":"البيت 651","page":"ج1 ص51","text":"ومد بخلف ماج والكل واقف ... بإسكانه يذكو عبيرا ومندلا","a":"ومد بخلف ماج والكل واقف","b":"بإسكانه يذكو عبيرا ومندلا","ref":["ibraz:670","siraj:49"]},{"id":"shatibiyya:652","bookId":"shatibiyya","type":"bayt","num":652,"seq":652,"chapter":"سورة الأنعام","title":"البيت 652","page":"ج1 ص51","text":"وتبدونها تخفون مع تجعلونه ... على غيبه حقا وينذر صندلا","a":"وتبدونها تخفون مع تجعلونه","b":"على غيبه حقا وينذر صندلا","ref":["ibraz:671","siraj:50"]},{"id":"shatibiyya:653","bookId":"shatibiyya","type":"bayt","num":653,"seq":653,"chapter":"سورة الأنعام","title":"البيت 653","page":"ج1 ص51","text":"وبينكم ارفع في صفا نفر وجا ... عل اقصر وفتح الكسر والرفع ثملا","a":"وبينكم ارفع في صفا نفر وجا","b":"عل اقصر وفتح الكسر والرفع ثملا","ref":["ibraz:672"]},{"id":"shatibiyya:654","bookId":"shatibiyya","type":"bayt","num":654,"seq":654,"chapter":"سورة الأنعام","title":"البيت 654","page":"ج1 ص51","text":"وعنهم بنصب الليل واكسر بمستقر ... ر القاف حقا خرقوا ثقله انجلا","a":"وعنهم بنصب الليل واكسر بمستقر","b":"ر القاف حقا خرقوا ثقله انجلا","ref":["ibraz:673","siraj:50"]},{"id":"shatibiyya:655","bookId":"shatibiyya","type":"bayt","num":655,"seq":655,"chapter":"سورة الأنعام","title":"البيت 655","page":"ج1 ص51","text":"وضمان مع ياسين في ثمر شفا ... ودارست حق مده ولقد حلا","a":"وضمان مع ياسين في ثمر شفا","b":"ودارست حق مده ولقد حلا","ref":["ibraz:674","siraj:50"]},{"id":"shatibiyya:656","bookId":"shatibiyya","type":"bayt","num":656,"seq":656,"chapter":"سورة الأنعام","title":"البيت 656","page":"ج1 ص51","text":"وحرك وسكن كافيا واكسر انها ... حمى صوبه بالخلف در وأوبلا","a":"وحرك وسكن كافيا واكسر انها","b":"حمى صوبه بالخلف در وأوبلا","ref":["ibraz:675"]},{"id":"shatibiyya:657","bookId":"shatibiyya","type":"bayt","num":657,"seq":657,"chapter":"سورة الأنعام","title":"البيت 657","page":"ج1 ص51","text":"وخاطب فيها يؤمنون كما فشا ... وصحبة كفؤ في الشريعة وصلا","a":"وخاطب فيها يؤمنون كما فشا","b":"وصحبة كفؤ في الشريعة وصلا","ref":["ibraz:676","siraj:50"]},{"id":"shatibiyya:658","bookId":"shatibiyya","type":"bayt","num":658,"seq":658,"chapter":"سورة الأنعام","title":"البيت 658","page":"ج1 ص51","text":"وكسر وفتح ضم في قبلا حمى ... ظهيرا وللكوفي في الكهف وصلا","a":"وكسر وفتح ضم في قبلا حمى","b":"ظهيرا وللكوفي في الكهف وصلا","ref":["ibraz:677","siraj:50"]},{"id":"shatibiyya:659","bookId":"shatibiyya","type":"bayt","num":659,"seq":659,"chapter":"سورة الأنعام","title":"البيت 659","page":"ج1 ص51","text":"وقل كلمات دون ما ألف ثوى ... وفي يونس والطول حاميه ظللا","a":"وقل كلمات دون ما ألف ثوى","b":"وفي يونس والطول حاميه ظللا","ref":["ibraz:678","siraj:50"]},{"id":"shatibiyya:660","bookId":"shatibiyya","type":"bayt","num":660,"seq":660,"chapter":"سورة الأنعام","title":"البيت 660","page":"ج1 ص52","text":"وشدد حفص منزل وابن عامر ... وحرم فتح الضم والكسر إذ علا","a":"وشدد حفص منزل وابن عامر","b":"وحرم فتح الضم والكسر إذ علا","ref":["ibraz:679","siraj:50"]},{"id":"shatibiyya:661","bookId":"shatibiyya","type":"bayt","num":661,"seq":661,"chapter":"سورة الأنعام","title":"البيت 661","page":"ج1 ص52","text":"وفصل إذ ثنى يضلون ضم مع ... يضلوا الذي في يونس ثابتا ولا","a":"وفصل إذ ثنى يضلون ضم مع","b":"يضلوا الذي في يونس ثابتا ولا","ref":["ibraz:680","siraj:50"]},{"id":"shatibiyya:662","bookId":"shatibiyya","type":"bayt","num":662,"seq":662,"chapter":"سورة الأنعام","title":"البيت 662","page":"ج1 ص52","text":"رسالات فرد وافتحوا دون علة ... وضيقا مع الفرقان حرك مثقلا","a":"رسالات فرد وافتحوا دون علة","b":"وضيقا مع الفرقان حرك مثقلا","ref":["ibraz:640","siraj:50"]},{"id":"shatibiyya:663","bookId":"shatibiyya","type":"bayt","num":663,"seq":663,"chapter":"سورة الأنعام","title":"البيت 663","page":"ج1 ص52","text":"بكسر سوى المكي ورا حرجا هنا ... على كسرها إلف صفا وتوسلا","a":"بكسر سوى المكي ورا حرجا هنا","b":"على كسرها إلف صفا وتوسلا","ref":["ibraz:682","siraj:50"]},{"id":"shatibiyya:664","bookId":"shatibiyya","type":"bayt","num":664,"seq":664,"chapter":"سورة الأنعام","title":"البيت 664","page":"ج1 ص52","text":"ويصعد خف ساكن دم ومده ... صحيح وخف العين داوم صندلا","a":"ويصعد خف ساكن دم ومده","b":"صحيح وخف العين داوم صندلا","ref":["ibraz:683","siraj:50"]},{"id":"shatibiyya:665","bookId":"shatibiyya","type":"bayt","num":665,"seq":665,"chapter":"سورة الأنعام","title":"البيت 665","page":"ج1 ص52","text":"ونحشر مع ثان بيونس وهو في ... سبأ مع نقول اليا في الأربع عملا","a":"ونحشر مع ثان بيونس وهو في","b":"سبأ مع نقول اليا في الأربع عملا","ref":["siraj:50"]},{"id":"shatibiyya:666","bookId":"shatibiyya","type":"bayt","num":666,"seq":666,"chapter":"سورة الأنعام","title":"البيت 666","page":"ج1 ص52","text":"وخاطب شام يعلمون ومن تكو ... ن فيها وتحت النمل ذكره شلشلا","a":"وخاطب شام يعلمون ومن تكو","b":"ن فيها وتحت النمل ذكره شلشلا"},{"id":"shatibiyya:667","bookId":"shatibiyya","type":"bayt","num":667,"seq":667,"chapter":"سورة الأنعام","title":"البيت 667","page":"ج1 ص52","text":"مكانات مد النون في الكل شعبة ... بزعمهم الحرفان بالضم رتلا","a":"مكانات مد النون في الكل شعبة","b":"بزعمهم الحرفان بالضم رتلا","ref":["ibraz:686","siraj:50"]},{"id":"shatibiyya:668","bookId":"shatibiyya","type":"bayt","num":668,"seq":668,"chapter":"سورة الأنعام","title":"البيت 668","page":"ج1 ص52","text":"وزين في ضم وكسر ورفع قت ... ل أولادهم بالنصب شاميهم تلا","a":"وزين في ضم وكسر ورفع قت","b":"ل أولادهم بالنصب شاميهم تلا","ref":["ibraz:687","siraj:50"]},{"id":"shatibiyya:669","bookId":"shatibiyya","type":"bayt","num":669,"seq":669,"chapter":"سورة الأنعام","title":"البيت 669","page":"ج1 ص52","text":"ويخفض عنه الرفع في شركاؤهم ... وفي مصحف الشامين بالياء مثلا","a":"ويخفض عنه الرفع في شركاؤهم","b":"وفي مصحف الشامين بالياء مثلا","ref":["ibraz:688","siraj:50"]},{"id":"shatibiyya:670","bookId":"shatibiyya","type":"bayt","num":670,"seq":670,"chapter":"سورة الأنعام","title":"البيت 670","page":"ج1 ص52","text":"ومفعوله بين المضافين فاصل ... ولم يلف غير الظرف في الشعر فيصلا","a":"ومفعوله بين المضافين فاصل","b":"ولم يلف غير الظرف في الشعر فيصلا","ref":["ibraz:689","siraj:50"]},{"id":"shatibiyya:671","bookId":"shatibiyya","type":"bayt","num":671,"seq":671,"chapter":"سورة الأنعام","title":"البيت 671","page":"ج1 ص52","text":"كلله در اليوم من لامها فلا ... تلم من مليمي النحو إلا مجهلا","a":"كلله در اليوم من لامها فلا","b":"تلم من مليمي النحو إلا مجهلا","ref":["ibraz:690"]},{"id":"shatibiyya:672","bookId":"shatibiyya","type":"bayt","num":672,"seq":672,"chapter":"سورة الأنعام","title":"البيت 672","page":"ج1 ص52","text":"ومع رسمه زج القلوص أبي مزا ... دة الأخفش النحوي أنشد مجملا","a":"ومع رسمه زج القلوص أبي مزا","b":"دة الأخفش النحوي أنشد مجملا","ref":["ibraz:692","siraj:50"]},{"id":"shatibiyya:673","bookId":"shatibiyya","type":"bayt","num":673,"seq":673,"chapter":"سورة الأنعام","title":"البيت 673","page":"ج1 ص52","text":"وإن يكن انث كفؤ صدق وميتة ... دنا كافيا وافتح حصاد كذي حلا","a":"وإن يكن انث كفؤ صدق وميتة","b":"دنا كافيا وافتح حصاد كذي حلا","ref":["ibraz:693"]},{"id":"shatibiyya:674","bookId":"shatibiyya","type":"bayt","num":674,"seq":674,"chapter":"سورة الأنعام","title":"البيت 674","page":"ج1 ص53","text":"نما وسكون المعز حصن وأنثوا ... يكون كما في دينهم ميتة كلا","a":"نما وسكون المعز حصن وأنثوا","b":"يكون كما في دينهم ميتة كلا","ref":["ibraz:694","siraj:50"]},{"id":"shatibiyya:675","bookId":"shatibiyya","type":"bayt","num":675,"seq":675,"chapter":"سورة الأنعام","title":"البيت 675","page":"ج1 ص53","text":"وتذكرون الكل خف على شذا ... وأن اكسروا شرعا وبالخف كملا","a":"وتذكرون الكل خف على شذا","b":"وأن اكسروا شرعا وبالخف كملا","ref":["ibraz:695","siraj:51"]},{"id":"shatibiyya:676","bookId":"shatibiyya","type":"bayt","num":676,"seq":676,"chapter":"سورة الأنعام","title":"البيت 676","page":"ج1 ص53","text":"ويأتيهم شاف مع النحل فارقوا ... مع الروم مداه خفيفا وعدلا","a":"ويأتيهم شاف مع النحل فارقوا","b":"مع الروم مداه خفيفا وعدلا","ref":["ibraz:696","siraj:51"]},{"id":"shatibiyya:677","bookId":"shatibiyya","type":"bayt","num":677,"seq":677,"chapter":"سورة الأنعام","title":"البيت 677","page":"ج1 ص53","text":"وكسر وفتح خف في قيما ذكا ... وياآتها وجهي مماتي مقبلا","a":"وكسر وفتح خف في قيما ذكا","b":"وياآتها وجهي مماتي مقبلا","ref":["ibraz:697","siraj:51"]},{"id":"shatibiyya:678","bookId":"shatibiyya","type":"bayt","num":678,"seq":678,"chapter":"سورة الأنعام","title":"البيت 678","page":"ج1 ص53","text":"وربي صراطي ثم إني ثلاثة ... ومحياي والإسكان صح تحملا","a":"وربي صراطي ثم إني ثلاثة","b":"ومحياي والإسكان صح تحملا","ref":["ibraz:698","siraj:51"]},{"id":"shatibiyya:679","bookId":"shatibiyya","type":"bayt","num":679,"seq":679,"chapter":"سورة الأعراف","title":"البيت 679","page":"ج1 ص53","text":"وتذكرون الغيب زد قبل تائه ... كريما وخف الذال كم شرفا علا","a":"وتذكرون الغيب زد قبل تائه","b":"كريما وخف الذال كم شرفا علا","ref":["ibraz:699","siraj:52"]},{"id":"shatibiyya:680","bookId":"shatibiyya","type":"bayt","num":680,"seq":680,"chapter":"سورة الأعراف","title":"البيت 680","page":"ج1 ص53","text":"مع الزخرف اعكس تخرجون بفتحة ... وضم وأولى الروم شافيه مثلا","a":"مع الزخرف اعكس تخرجون بفتحة","b":"وضم وأولى الروم شافيه مثلا","ref":["ibraz:700","siraj:52"]},{"id":"shatibiyya:681","bookId":"shatibiyya","type":"bayt","num":681,"seq":681,"chapter":"سورة الأعراف","title":"البيت 681","page":"ج1 ص53","text":"بخلف مضى في الروم لا يخرجون في ... رضا ولباس الرفع في حق نهشلا","a":"بخلف مضى في الروم لا يخرجون في","b":"رضا ولباس الرفع في حق نهشلا","ref":["ibraz:701","siraj:52"]},{"id":"shatibiyya:682","bookId":"shatibiyya","type":"bayt","num":682,"seq":682,"chapter":"سورة الأعراف","title":"البيت 682","page":"ج1 ص53","text":"وخالصة أصل ولا يعلمون قل ... لشعبة في الثاني ويفتح شمللا","a":"وخالصة أصل ولا يعلمون قل","b":"لشعبة في الثاني ويفتح شمللا","ref":["ibraz:702","siraj:52"]},{"id":"shatibiyya:683","bookId":"shatibiyya","type":"bayt","num":683,"seq":683,"chapter":"سورة الأعراف","title":"البيت 683","page":"ج1 ص53","text":"وخفف شفا حكما وما الواو دع كفى ... وحيث نعم بالكسر في العين رتلا","a":"وخفف شفا حكما وما الواو دع كفى","b":"وحيث نعم بالكسر في العين رتلا","ref":["ibraz:703","siraj:52"]},{"id":"shatibiyya:684","bookId":"shatibiyya","type":"bayt","num":684,"seq":684,"chapter":"سورة الأعراف","title":"البيت 684","page":"ج1 ص53","text":"وأن لعنة التخفيف والرفع نصه ... سما ما خلا البزي وفي النور أوصلا","a":"وأن لعنة التخفيف والرفع نصه","b":"سما ما خلا البزي وفي النور أوصلا","ref":["ibraz:70","siraj:52"]},{"id":"shatibiyya:685","bookId":"shatibiyya","type":"bayt","num":685,"seq":685,"chapter":"سورة الأعراف","title":"البيت 685","page":"ج1 ص53","text":"ويغشي بها والرعد ثقل صحبة ... ووالشمس مع عطف الثلاثة كملا","a":"ويغشي بها والرعد ثقل صحبة","b":"ووالشمس مع عطف الثلاثة كملا","ref":["ibraz:705","siraj:52"]},{"id":"shatibiyya:686","bookId":"shatibiyya","type":"bayt","num":686,"seq":686,"chapter":"سورة الأعراف","title":"البيت 686","page":"ج1 ص53","text":"وفي النحل معه في الأخيرين حفصهم ... ونشرا سكون الضم في الكل ذللا","a":"وفي النحل معه في الأخيرين حفصهم","b":"ونشرا سكون الضم في الكل ذللا","ref":["ibraz:706","siraj:52"]},{"id":"shatibiyya:687","bookId":"shatibiyya","type":"bayt","num":687,"seq":687,"chapter":"سورة الأعراف","title":"البيت 687","page":"ج1 ص54","text":"وفي النون فتح الضم شاف وعاصم ... روى نونه بالباء نقطة اسفلا","a":"وفي النون فتح الضم شاف وعاصم","b":"روى نونه بالباء نقطة اسفلا","ref":["ibraz:707","siraj:52"]},{"id":"shatibiyya:688","bookId":"shatibiyya","type":"bayt","num":688,"seq":688,"chapter":"سورة الأعراف","title":"البيت 688","page":"ج1 ص54","text":"ورا من إله غيره خفض رفعه ... بكل رسا والخف أبلغكم حلا","a":"ورا من إله غيره خفض رفعه","b":"بكل رسا والخف أبلغكم حلا","ref":["ibraz:708","siraj:52"]},{"id":"shatibiyya:689","bookId":"shatibiyya","type":"bayt","num":689,"seq":689,"chapter":"سورة الأعراف","title":"البيت 689","page":"ج1 ص54","text":"مع احقافها والواو زد بعد مفسد ... ين كفؤا وبالإخبار إنكمو علا","a":"مع احقافها والواو زد بعد مفسد","b":"ين كفؤا وبالإخبار إنكمو علا","ref":["ibraz:709","siraj:52"]},{"id":"shatibiyya:690","bookId":"shatibiyya","type":"bayt","num":690,"seq":690,"chapter":"سورة الأعراف","title":"البيت 690","page":"ج1 ص54","text":"ألا وعلى الحرمي إن لنا هنا ... وأو أمن الإسكان حرميه كلا","a":"ألا وعلى الحرمي إن لنا هنا","b":"وأو أمن الإسكان حرميه كلا","ref":["ibraz:710","siraj:52"]},{"id":"shatibiyya:691","bookId":"shatibiyya","type":"bayt","num":691,"seq":691,"chapter":"سورة الأعراف","title":"البيت 691","page":"ج1 ص54","text":"علي على خصوا وفي ساحر بها ... ويونس سحار شفا وتسلسلا","a":"علي على خصوا وفي ساحر بها","b":"ويونس سحار شفا وتسلسلا","ref":["ibraz:711","siraj:52"]},{"id":"shatibiyya:692","bookId":"shatibiyya","type":"bayt","num":692,"seq":692,"chapter":"سورة الأعراف","title":"البيت 692","page":"ج1 ص54","text":"وفي الكل تلقف خف حفص وضم في ... سنقتل واكسر ضمه متثقلا","a":"وفي الكل تلقف خف حفص وضم في","b":"سنقتل واكسر ضمه متثقلا","ref":["ibraz:712","siraj:52"]},{"id":"shatibiyya:693","bookId":"shatibiyya","type":"bayt","num":693,"seq":693,"chapter":"سورة الأعراف","title":"البيت 693","page":"ج1 ص54","text":"وحرك ذكا حسن وفي يقتلون خذ ... معا يعرشون الكسر ضم كذي صلا","a":"وحرك ذكا حسن وفي يقتلون خذ","b":"معا يعرشون الكسر ضم كذي صلا","ref":["ibraz:713","siraj:52"]},{"id":"shatibiyya:694","bookId":"shatibiyya","type":"bayt","num":694,"seq":694,"chapter":"سورة الأعراف","title":"البيت 694","page":"ج1 ص54","text":"وفي يعكفون الضم يكسر شافيا ... وأنجى بحذف الياء والنون كفلا","a":"وفي يعكفون الضم يكسر شافيا","b":"وأنجى بحذف الياء والنون كفلا","ref":["ibraz:714","siraj:52"]},{"id":"shatibiyya:695","bookId":"shatibiyya","type":"bayt","num":695,"seq":695,"chapter":"سورة الأعراف","title":"البيت 695","page":"ج1 ص54","text":"ودكاء لا تنوين وامدده هامزا ... شفا وعن الكوفي في الكهف وصلا","a":"ودكاء لا تنوين وامدده هامزا","b":"شفا وعن الكوفي في الكهف وصلا","ref":["ibraz:715","siraj:52"]},{"id":"shatibiyya:696","bookId":"shatibiyya","type":"bayt","num":696,"seq":696,"chapter":"سورة الأعراف","title":"البيت 696","page":"ج1 ص54","text":"وجمع رسالاتي حمته ذكوره ... وفي الرشد حرك وافتح الضم شلشلا","a":"وجمع رسالاتي حمته ذكوره","b":"وفي الرشد حرك وافتح الضم شلشلا","ref":["ibraz:716","siraj:4"]},{"id":"shatibiyya:697","bookId":"shatibiyya","type":"bayt","num":697,"seq":697,"chapter":"سورة الأعراف","title":"البيت 697","page":"ج1 ص54","text":"وفي الكهف حسناه وضم حليهم ... بكسر شفا واف والاتباع ذو حلا","a":"وفي الكهف حسناه وضم حليهم","b":"بكسر شفا واف والاتباع ذو حلا","ref":["ibraz:717","siraj:52"]},{"id":"shatibiyya:698","bookId":"shatibiyya","type":"bayt","num":698,"seq":698,"chapter":"سورة الأعراف","title":"البيت 698","page":"ج1 ص54","text":"وخاطب يرحمنا ويغفر لنا شذا ... وبا ربنا رفع لغيرهما انجلا","a":"وخاطب يرحمنا ويغفر لنا شذا","b":"وبا ربنا رفع لغيرهما انجلا","ref":["ibraz:718","siraj:52"]},{"id":"shatibiyya:699","bookId":"shatibiyya","type":"bayt","num":699,"seq":699,"chapter":"سورة الأعراف","title":"البيت 699","page":"ج1 ص54","text":"وميم ابن أم اكسر معا كفؤ صحبة ... وآصارهم بالجمع والمد كللا","a":"وميم ابن أم اكسر معا كفؤ صحبة","b":"وآصارهم بالجمع والمد كللا","ref":["ibraz:719"]},{"id":"shatibiyya:700","bookId":"shatibiyya","type":"bayt","num":700,"seq":700,"chapter":"سورة الأعراف","title":"البيت 700","page":"ج1 ص55","text":"خطيئاتكم وحده عنه ورفعه ... كما ألفوا والغير بالكسر عدلا","a":"خطيئاتكم وحده عنه ورفعه","b":"كما ألفوا والغير بالكسر عدلا","ref":["ibraz:720","siraj:53"]},{"id":"shatibiyya:701","bookId":"shatibiyya","type":"bayt","num":701,"seq":701,"chapter":"سورة الأعراف","title":"البيت 701","page":"ج1 ص55","text":"ولكن خطايا حج فيها ونوحها ... ومعذرة رفع سوى حفصهم تلا","a":"ولكن خطايا حج فيها ونوحها","b":"ومعذرة رفع سوى حفصهم تلا","ref":["ibraz:721","siraj:53"]},{"id":"shatibiyya:702","bookId":"shatibiyya","type":"bayt","num":702,"seq":702,"chapter":"سورة الأعراف","title":"البيت 702","page":"ج1 ص55","text":"وبيس بياء أم والهمز كهفه ... ومثل رئيس غير هذين عولا","a":"وبيس بياء أم والهمز كهفه","b":"ومثل رئيس غير هذين عولا","ref":["ibraz:722","siraj:53"]},{"id":"shatibiyya:703","bookId":"shatibiyya","type":"bayt","num":703,"seq":703,"chapter":"سورة الأعراف","title":"البيت 703","page":"ج1 ص55","text":"وبيئس اسكن بين فتحين صادقا ... بخلف وخفف يمسكون صفا ولا","a":"وبيئس اسكن بين فتحين صادقا","b":"بخلف وخفف يمسكون صفا ولا","ref":["ibraz:723","siraj:53"]},{"id":"shatibiyya:704","bookId":"shatibiyya","type":"bayt","num":704,"seq":704,"chapter":"سورة الأعراف","title":"البيت 704","page":"ج1 ص55","text":"ويقصر ذريات مع فتح تائه ... وفي الطور في الثاني ظهير تحملا","a":"ويقصر ذريات مع فتح تائه","b":"وفي الطور في الثاني ظهير تحملا","ref":["ibraz:66","siraj:53"]},{"id":"shatibiyya:705","bookId":"shatibiyya","type":"bayt","num":705,"seq":705,"chapter":"سورة الأعراف","title":"البيت 705","page":"ج1 ص55","text":"وياسين دم غصنا ويكسر رفع أو ... ول الطور للبصري وبالمد كم حلا","a":"وياسين دم غصنا ويكسر رفع أو","b":"ول الطور للبصري وبالمد كم حلا","ref":["ibraz:725","siraj:53"]},{"id":"shatibiyya:706","bookId":"shatibiyya","type":"bayt","num":706,"seq":706,"chapter":"سورة الأعراف","title":"البيت 706","page":"ج1 ص55","text":"يقولوا معا غيب حميد وحيث يل ... حدون بفتح الضم والكسر فصلا","a":"يقولوا معا غيب حميد وحيث يل","b":"حدون بفتح الضم والكسر فصلا","ref":["ibraz:726","siraj:53"]},{"id":"shatibiyya:707","bookId":"shatibiyya","type":"bayt","num":707,"seq":707,"chapter":"سورة الأعراف","title":"البيت 707","page":"ج1 ص55","text":"وفي النحل والاه الكسائي وجزمهم ... يذرهم شفا والياء غصن تهدلا","a":"وفي النحل والاه الكسائي وجزمهم","b":"يذرهم شفا والياء غصن تهدلا","ref":["ibraz:727","siraj:53"]},{"id":"shatibiyya:708","bookId":"shatibiyya","type":"bayt","num":708,"seq":708,"chapter":"سورة الأعراف","title":"البيت 708","page":"ج1 ص55","text":"وحرك وضم الكسر وامدده هامزا ... ولا نون شركا عن شذا نفر ملا","a":"وحرك وضم الكسر وامدده هامزا","b":"ولا نون شركا عن شذا نفر ملا","ref":["ibraz:728","siraj:53"]},{"id":"shatibiyya:709","bookId":"shatibiyya","type":"bayt","num":709,"seq":709,"chapter":"سورة الأعراف","title":"البيت 709","page":"ج1 ص55","text":"ولا يتبعوكم خف مع فتح بائه ... ويتبعهم في الظلة احتل واعتلا","a":"ولا يتبعوكم خف مع فتح بائه","b":"ويتبعهم في الظلة احتل واعتلا","ref":["ibraz:729","siraj:53"]},{"id":"shatibiyya:710","bookId":"shatibiyya","type":"bayt","num":710,"seq":710,"chapter":"سورة الأعراف","title":"البيت 710","page":"ج1 ص55","text":"وقل طائف طيف رضى حقه ويا ... يمدون فاضمم واكسر الضم أعدلا","a":"وقل طائف طيف رضى حقه ويا","b":"يمدون فاضمم واكسر الضم أعدلا","ref":["ibraz:730","siraj:53"]},{"id":"shatibiyya:711","bookId":"shatibiyya","type":"bayt","num":711,"seq":711,"chapter":"سورة الأعراف","title":"البيت 711","page":"ج1 ص55","text":"وربي معي بعدي وإني كلاهما ... عذابي آياتي مضافاتها العلا","a":"وربي معي بعدي وإني كلاهما","b":"عذابي آياتي مضافاتها العلا","ref":["ibraz:731","siraj:53"]},{"id":"shatibiyya:712","bookId":"shatibiyya","type":"bayt","num":712,"seq":712,"chapter":"سورة الأنفال","title":"البيت 712","page":"ج1 ص55","text":"وفي مردفين الدال يفتح نافع ... وعن قنبل يروى وليس معولا","a":"وفي مردفين الدال يفتح نافع","b":"وعن قنبل يروى وليس معولا","ref":["ibraz:732","siraj:54"]},{"id":"shatibiyya:713","bookId":"shatibiyya","type":"bayt","num":713,"seq":713,"chapter":"سورة الأنفال","title":"البيت 713","page":"ج1 ص56","text":"ويغشي سما خفا وفي ضمه افتحوا ... وفي الكسر حقا والنعاس ارفعوا ولا","a":"ويغشي سما خفا وفي ضمه افتحوا","b":"وفي الكسر حقا والنعاس ارفعوا ولا","ref":["ibraz:733","siraj:54"]},{"id":"shatibiyya:714","bookId":"shatibiyya","type":"bayt","num":714,"seq":714,"chapter":"سورة الأنفال","title":"البيت 714","page":"ج1 ص56","text":"وتخفيفهم في الأولين هنا ول ... كن الله وارفع هاءه شاع كفلا","a":"وتخفيفهم في الأولين هنا ول","b":"كن الله وارفع هاءه شاع كفلا","ref":["ibraz:734","siraj:54"]},{"id":"shatibiyya:715","bookId":"shatibiyya","type":"bayt","num":715,"seq":715,"chapter":"سورة الأنفال","title":"البيت 715","page":"ج1 ص56","text":"وموهن بالتخفيف ذاع وفيه لم ... ينون لحفص كيد بالخفض عولا","a":"وموهن بالتخفيف ذاع وفيه لم","b":"ينون لحفص كيد بالخفض عولا","ref":["ibraz:735","siraj:54"]},{"id":"shatibiyya:716","bookId":"shatibiyya","type":"bayt","num":716,"seq":716,"chapter":"سورة الأنفال","title":"البيت 716","page":"ج1 ص56","text":"وبعد وإن الفتح عم علا وفي ... هما العدوة اكسر حقا الضم واعدلا","a":"وبعد وإن الفتح عم علا وفي","b":"هما العدوة اكسر حقا الضم واعدلا","ref":["ibraz:736","siraj:54"]},{"id":"shatibiyya:717","bookId":"shatibiyya","type":"bayt","num":717,"seq":717,"chapter":"سورة الأنفال","title":"البيت 717","page":"ج1 ص56","text":"ومن حيي اكسر مظهرا إذ صفا هدى ... وإذ يتوفى أنثوه له ملا","a":"ومن حيي اكسر مظهرا إذ صفا هدى","b":"وإذ يتوفى أنثوه له ملا","ref":["ibraz:737","siraj:54"]},{"id":"shatibiyya:718","bookId":"shatibiyya","type":"bayt","num":718,"seq":718,"chapter":"سورة الأنفال","title":"البيت 718","page":"ج1 ص56","text":"وبالغيب فيها تحسبن كما فشا ... عميما وقل في النور فاشيه كحلا","a":"وبالغيب فيها تحسبن كما فشا","b":"عميما وقل في النور فاشيه كحلا","ref":["ibraz:738","siraj:54"]},{"id":"shatibiyya:719","bookId":"shatibiyya","type":"bayt","num":719,"seq":719,"chapter":"سورة الأنفال","title":"البيت 719","page":"ج1 ص56","text":"وإنهم افتح كافيا واكسروا لشع ... بة السلم واكسر في القتال فطب صلا","a":"وإنهم افتح كافيا واكسروا لشع","b":"بة السلم واكسر في القتال فطب صلا","ref":["ibraz:739","siraj:54"]},{"id":"shatibiyya:720","bookId":"shatibiyya","type":"bayt","num":720,"seq":720,"chapter":"سورة الأنفال","title":"البيت 720","page":"ج1 ص56","text":"وثاني يكن غصن وثالثها ثوى ... وضعفا بفتح الضم فاشيه نفلا","a":"وثاني يكن غصن وثالثها ثوى","b":"وضعفا بفتح الضم فاشيه نفلا","ref":["ibraz:740","siraj:54"]},{"id":"shatibiyya:721","bookId":"shatibiyya","type":"bayt","num":721,"seq":721,"chapter":"سورة الأنفال","title":"البيت 721","page":"ج1 ص56","text":"وفي الروم صف عن خلف فصل وأنث ان ... يكون مع الأسرى الأسارى حلا حلا","a":"وفي الروم صف عن خلف فصل وأنث ان","b":"يكون مع الأسرى الأسارى حلا حلا","ref":["ibraz:741","siraj:54"]},{"id":"shatibiyya:722","bookId":"shatibiyya","type":"bayt","num":722,"seq":722,"chapter":"سورة الأنفال","title":"البيت 722","page":"ج1 ص56","text":"ولايتهم بالكسر فز وبكهفه ... شفا ومعا إني بياءين أقبلا","a":"ولايتهم بالكسر فز وبكهفه","b":"شفا ومعا إني بياءين أقبلا","ref":["ibraz:742","siraj:54"]},{"id":"shatibiyya:723","bookId":"shatibiyya","type":"bayt","num":723,"seq":723,"chapter":"سورة التوبة","title":"البيت 723","page":"ج1 ص56","text":"ويكسر لا أيمان عند ابن عامر ... ووحد حق مسجد الله الاولا","a":"ويكسر لا أيمان عند ابن عامر","b":"ووحد حق مسجد الله الاولا","ref":["ibraz:743","siraj:55"]},{"id":"shatibiyya:724","bookId":"shatibiyya","type":"bayt","num":724,"seq":724,"chapter":"سورة التوبة","title":"البيت 724","page":"ج1 ص56","text":"عشيراتكم بالجمع صدق ونونوا ... عزير رضى نص وبالكسر وكلا","a":"عشيراتكم بالجمع صدق ونونوا","b":"عزير رضى نص وبالكسر وكلا","ref":["ibraz:744","siraj:55"]},{"id":"shatibiyya:725","bookId":"shatibiyya","type":"bayt","num":725,"seq":725,"chapter":"سورة التوبة","title":"البيت 725","page":"ج1 ص57","text":"يضاهون ضم الهاء يكسر عاصم ... وزد همزة مضمومة عنه واعقلا","a":"يضاهون ضم الهاء يكسر عاصم","b":"وزد همزة مضمومة عنه واعقلا","ref":["ibraz:745","siraj:55"]},{"id":"shatibiyya:726","bookId":"shatibiyya","type":"bayt","num":726,"seq":726,"chapter":"سورة التوبة","title":"البيت 726","page":"ج1 ص57","text":"يضل بضم الياء مع فتح ضاده ... صحاب ولم يخشوا هناك مضللا","a":"يضل بضم الياء مع فتح ضاده","b":"صحاب ولم يخشوا هناك مضللا","ref":["ibraz:746","siraj:55"]},{"id":"shatibiyya:727","bookId":"shatibiyya","type":"bayt","num":727,"seq":727,"chapter":"سورة التوبة","title":"البيت 727","page":"ج1 ص57","text":"وأن تقبل التذكير شاع وصاله ... ورحمة المرفوع بالخفض فاقبلا","a":"وأن تقبل التذكير شاع وصاله","b":"ورحمة المرفوع بالخفض فاقبلا","ref":["ibraz:747","siraj:55"]},{"id":"shatibiyya:728","bookId":"shatibiyya","type":"bayt","num":728,"seq":728,"chapter":"سورة التوبة","title":"البيت 728","page":"ج1 ص57","text":"ويعف بنون دون ضم وفاؤه ... يضم تعذب تاه بالنون وصلا","a":"ويعف بنون دون ضم وفاؤه","b":"يضم تعذب تاه بالنون وصلا","ref":["ibraz:748","siraj:55"]},{"id":"shatibiyya:729","bookId":"shatibiyya","type":"bayt","num":729,"seq":729,"chapter":"سورة التوبة","title":"البيت 729","page":"ج1 ص57","text":"وفي ذاله كسر وطائفة بنص ... ب مرفوعه عن عاصم كله اعتلا","a":"وفي ذاله كسر وطائفة بنص","b":"ب مرفوعه عن عاصم كله اعتلا","ref":["ibraz:749","siraj:55"]},{"id":"shatibiyya:730","bookId":"shatibiyya","type":"bayt","num":730,"seq":730,"chapter":"سورة التوبة","title":"البيت 730","page":"ج1 ص57","text":"وحق بضم السوء مع ثان فتحها ... وتحريك ورش قربة ضمه جلا","a":"وحق بضم السوء مع ثان فتحها","b":"وتحريك ورش قربة ضمه جلا","ref":["ibraz:750","siraj:55"]},{"id":"shatibiyya:731","bookId":"shatibiyya","type":"bayt","num":731,"seq":731,"chapter":"سورة التوبة","title":"البيت 731","page":"ج1 ص57","text":"ومن تحتها المكي ... يجر وزاد من صلاتك وحد وافتح التا شذا علا","a":"ومن تحتها المكي","b":"يجر وزاد من صلاتك وحد وافتح التا شذا علا","ref":["ibraz:60","siraj:55"]},{"id":"shatibiyya:732","bookId":"shatibiyya","type":"bayt","num":732,"seq":732,"chapter":"سورة التوبة","title":"البيت 732","page":"ج1 ص57","text":"ووحد لهم في هود ترجئ همزه ... صفا نفر مع مرجئون وقد حلا","a":"ووحد لهم في هود ترجئ همزه","b":"صفا نفر مع مرجئون وقد حلا","ref":["ibraz:752","siraj:55"]},{"id":"shatibiyya:733","bookId":"shatibiyya","type":"bayt","num":733,"seq":733,"chapter":"سورة التوبة","title":"البيت 733","page":"ج1 ص57","text":"وعم بلا واو الذين وضم في ... من اسس مع كسر وبنيانه ولا","a":"وعم بلا واو الذين وضم في","b":"من اسس مع كسر وبنيانه ولا","ref":["ibraz:753","siraj:55"]},{"id":"shatibiyya:734","bookId":"shatibiyya","type":"bayt","num":734,"seq":734,"chapter":"سورة التوبة","title":"البيت 734","page":"ج1 ص57","text":"وجرف سكون الضم في صفو كامل ... تقطع فتح الضم في كامل علا","a":"وجرف سكون الضم في صفو كامل","b":"تقطع فتح الضم في كامل علا","ref":["ibraz:754","siraj:55"]},{"id":"shatibiyya:735","bookId":"shatibiyya","type":"bayt","num":735,"seq":735,"chapter":"سورة التوبة","title":"البيت 735","page":"ج1 ص57","text":"يزيغ على فصل يرون مخاطب ... فشا ومعي فيها بياءين حملا","a":"يزيغ على فصل يرون مخاطب","b":"فشا ومعي فيها بياءين حملا","ref":["ibraz:755","siraj:55"]},{"id":"shatibiyya:736","bookId":"shatibiyya","type":"bayt","num":736,"seq":736,"chapter":"سورة يونس عليه السلام","title":"البيت 736","page":"ج1 ص57","text":"وإضجاع را كل الفواتح ذكره ... حمى غير حفص طا ويا صحبة ولا","a":"وإضجاع را كل الفواتح ذكره","b":"حمى غير حفص طا ويا صحبة ولا","ref":["ibraz:70","siraj:4"]},{"id":"shatibiyya:737","bookId":"shatibiyya","type":"bayt","num":737,"seq":737,"chapter":"سورة يونس عليه السلام","title":"البيت 737","page":"ج1 ص57","text":"وكم صحبة يا كاف والخلف ياسر ... وها صف رضى حلوا وتحت جنى حلا","a":"وكم صحبة يا كاف والخلف ياسر","b":"وها صف رضى حلوا وتحت جنى حلا","ref":["ibraz:757","siraj:56"]},{"id":"shatibiyya:738","bookId":"shatibiyya","type":"bayt","num":738,"seq":738,"chapter":"سورة يونس عليه السلام","title":"البيت 738","page":"ج1 ص58","text":"شفا صادقا حم مختار صحبة ... وبصر وهم أدرى وبالخلف مثلا","a":"شفا صادقا حم مختار صحبة","b":"وبصر وهم أدرى وبالخلف مثلا","ref":["ibraz:758","siraj:56"]},{"id":"shatibiyya:739","bookId":"shatibiyya","type":"bayt","num":739,"seq":739,"chapter":"سورة يونس عليه السلام","title":"البيت 739","page":"ج1 ص58","text":"وذو الرا لورش بين بين ونافع ... لدى مريم هايا وحا جيده حلا","a":"وذو الرا لورش بين بين ونافع","b":"لدى مريم هايا وحا جيده حلا","ref":["ibraz:759","siraj:56"]},{"id":"shatibiyya:740","bookId":"shatibiyya","type":"bayt","num":740,"seq":740,"chapter":"سورة يونس عليه السلام","title":"البيت 740","page":"ج1 ص58","text":"نفصل يا حق علا ساحر ظبى ... وحيث ضياء وافق الهمز قنبلا","a":"نفصل يا حق علا ساحر ظبى","b":"وحيث ضياء وافق الهمز قنبلا","ref":["ibraz:760","siraj:56"]},{"id":"shatibiyya:741","bookId":"shatibiyya","type":"bayt","num":741,"seq":741,"chapter":"سورة يونس عليه السلام","title":"البيت 741","page":"ج1 ص58","text":"وفي قضي الفتحان مع ألف هنا ... وقل أجل المرفوع بالنصب كملا","a":"وفي قضي الفتحان مع ألف هنا","b":"وقل أجل المرفوع بالنصب كملا","ref":["ibraz:761","siraj:56"]},{"id":"shatibiyya:742","bookId":"shatibiyya","type":"bayt","num":742,"seq":742,"chapter":"سورة يونس عليه السلام","title":"البيت 742","page":"ج1 ص58","text":"وقصر ولا هاد بخلف زكا وفي ال ... قيامة لا الأولى وبالحال أولا","a":"وقصر ولا هاد بخلف زكا وفي ال","b":"قيامة لا الأولى وبالحال أولا","ref":["ibraz:762","siraj:56"]},{"id":"shatibiyya:743","bookId":"shatibiyya","type":"bayt","num":743,"seq":743,"chapter":"سورة يونس عليه السلام","title":"البيت 743","page":"ج1 ص58","text":"وخاطب عما يشركون هنا شذا ... وفي الروم والحرفين في النحل أولا","a":"وخاطب عما يشركون هنا شذا","b":"وفي الروم والحرفين في النحل أولا","ref":["ibraz:763","siraj:56"]},{"id":"shatibiyya:744","bookId":"shatibiyya","type":"bayt","num":744,"seq":744,"chapter":"سورة يونس عليه السلام","title":"البيت 744","page":"ج1 ص58","text":"يسيركم قل فيه ينشركم كفى ... متاع سوى حفص برفع تحملا","a":"يسيركم قل فيه ينشركم كفى","b":"متاع سوى حفص برفع تحملا","ref":["ibraz:764","siraj:56"]},{"id":"shatibiyya:745","bookId":"shatibiyya","type":"bayt","num":745,"seq":745,"chapter":"سورة يونس عليه السلام","title":"البيت 745","page":"ج1 ص58","text":"وإسكان قطعا دون ريب وروده ... وفي باء تبلو التاء شاع تنزلا","a":"وإسكان قطعا دون ريب وروده","b":"وفي باء تبلو التاء شاع تنزلا","ref":["ibraz:765","siraj:56"]},{"id":"shatibiyya:746","bookId":"shatibiyya","type":"bayt","num":746,"seq":746,"chapter":"سورة يونس عليه السلام","title":"البيت 746","page":"ج1 ص58","text":"ويا لا يهدي اكسر صفيا وهاه نل ... وأخفى بنو حمد وخفف شلشلا","a":"ويا لا يهدي اكسر صفيا وهاه نل","b":"وأخفى بنو حمد وخفف شلشلا","ref":["ibraz:766","siraj:56"]},{"id":"shatibiyya:747","bookId":"shatibiyya","type":"bayt","num":747,"seq":747,"chapter":"سورة يونس عليه السلام","title":"البيت 747","page":"ج1 ص58","text":"ولكن خفيف وارفع الناس عنهما ... وخاطب فيها يجمعون له ملا","a":"ولكن خفيف وارفع الناس عنهما","b":"وخاطب فيها يجمعون له ملا","ref":["ibraz:767","siraj:56"]},{"id":"shatibiyya:748","bookId":"shatibiyya","type":"bayt","num":748,"seq":748,"chapter":"سورة يونس عليه السلام","title":"البيت 748","page":"ج1 ص58","text":"ويعزب كسر الضم مع سبأ رسا ... وأصغر فارفعه وأكبر فيصلا","a":"ويعزب كسر الضم مع سبأ رسا","b":"وأصغر فارفعه وأكبر فيصلا","ref":["ibraz:768","siraj:56"]},{"id":"shatibiyya:749","bookId":"shatibiyya","type":"bayt","num":749,"seq":749,"chapter":"سورة يونس عليه السلام","title":"البيت 749","page":"ج1 ص58","text":"مع المد قطع السحر حكم تبوءا ... بيا وقف حفص لم يصح فيحملا","a":"مع المد قطع السحر حكم تبوءا","b":"بيا وقف حفص لم يصح فيحملا","ref":["ibraz:769","siraj:56"]},{"id":"shatibiyya:750","bookId":"shatibiyya","type":"bayt","num":750,"seq":750,"chapter":"سورة يونس عليه السلام","title":"البيت 750","page":"ج1 ص59","text":"وتتبعان النون خف مدا وم ... اج بالفتح والإسكان قبل مثقلا","a":"وتتبعان النون خف مدا وم","b":"اج بالفتح والإسكان قبل مثقلا","ref":["ibraz:770","siraj:56"]},{"id":"shatibiyya:751","bookId":"shatibiyya","type":"bayt","num":751,"seq":751,"chapter":"سورة يونس عليه السلام","title":"البيت 751","page":"ج1 ص59","text":"وفي أنه اكسر شافيا وبنونه ... ونجعل صفو الخف ننج رضى علا","a":"وفي أنه اكسر شافيا وبنونه","b":"ونجعل صفو الخف ننج رضى علا","ref":["ibraz:771","siraj:56"]},{"id":"shatibiyya:752","bookId":"shatibiyya","type":"bayt","num":752,"seq":752,"chapter":"سورة يونس عليه السلام","title":"البيت 752","page":"ج1 ص59","text":"وذاك هو الثاني ونفسي ياؤها ... وربي مع أجري وإني ولي حلا","a":"وذاك هو الثاني ونفسي ياؤها","b":"وربي مع أجري وإني ولي حلا","ref":["ibraz:772","siraj:56"]},{"id":"shatibiyya:753","bookId":"shatibiyya","type":"bayt","num":753,"seq":753,"chapter":"سورة هود عليه السلام","title":"البيت 753","page":"ج1 ص59","text":"وإني لكم بالفتح حق رواته ... وباديء بعد الدال بالهمز حللا","a":"وإني لكم بالفتح حق رواته","b":"وباديء بعد الدال بالهمز حللا","ref":["ibraz:773","siraj:57"]},{"id":"shatibiyya:754","bookId":"shatibiyya","type":"bayt","num":754,"seq":754,"chapter":"سورة هود عليه السلام","title":"البيت 754","page":"ج1 ص59","text":"ومن كل نون مع قد افلح عالما ... فعميت اضممه وثقل شذا علا","a":"ومن كل نون مع قد افلح عالما","b":"فعميت اضممه وثقل شذا علا","ref":["ibraz:774","siraj:57"]},{"id":"shatibiyya:755","bookId":"shatibiyya","type":"bayt","num":755,"seq":755,"chapter":"سورة هود عليه السلام","title":"البيت 755","page":"ج1 ص59","text":"وفي ضم مجراها سواهم وفتح يا ... بني هنا نص وفي الكل عولا","a":"وفي ضم مجراها سواهم وفتح يا","b":"بني هنا نص وفي الكل عولا","ref":["ibraz:775","siraj:57"]},{"id":"shatibiyya:756","bookId":"shatibiyya","type":"bayt","num":756,"seq":756,"chapter":"سورة هود عليه السلام","title":"البيت 756","page":"ج1 ص59","text":"وآخر لقمان يواليه أحمد ... وسكنه زاك وشيخه الاولا","a":"وآخر لقمان يواليه أحمد","b":"وسكنه زاك وشيخه الاولا","ref":["ibraz:776","siraj:57"]},{"id":"shatibiyya:757","bookId":"shatibiyya","type":"bayt","num":757,"seq":757,"chapter":"سورة هود عليه السلام","title":"البيت 757","page":"ج1 ص59","text":"وفي عمل فتح ورفع ونونوا ... وغير ارفعوا إلا الكسائي ذا الملا","a":"وفي عمل فتح ورفع ونونوا","b":"وغير ارفعوا إلا الكسائي ذا الملا","ref":["ibraz:777","siraj:57"]},{"id":"shatibiyya:758","bookId":"shatibiyya","type":"bayt","num":758,"seq":758,"chapter":"سورة هود عليه السلام","title":"البيت 758","page":"ج1 ص59","text":"وتسئلن خف الكهف ظل حمي وها ... هنا غصنه وافتح هنا نونه دلا","a":"وتسئلن خف الكهف ظل حمي وها","b":"هنا غصنه وافتح هنا نونه دلا","ref":["ibraz:778"]},{"id":"shatibiyya:759","bookId":"shatibiyya","type":"bayt","num":759,"seq":759,"chapter":"سورة هود عليه السلام","title":"البيت 759","page":"ج1 ص59","text":"ويومئذ مع سال فافتح أتى رضا ... وفي النمل حصن قبله النون ثملا","a":"ويومئذ مع سال فافتح أتى رضا","b":"وفي النمل حصن قبله النون ثملا","ref":["ibraz:779","siraj:57"]},{"id":"shatibiyya:760","bookId":"shatibiyya","type":"bayt","num":760,"seq":760,"chapter":"سورة هود عليه السلام","title":"البيت 760","page":"ج1 ص59","text":"ثمود مع الفرقان والعنكبوت لم ... ينون على فصل وفي النجم فصلا","a":"ثمود مع الفرقان والعنكبوت لم","b":"ينون على فصل وفي النجم فصلا","ref":["ibraz:64","siraj:4"]},{"id":"shatibiyya:761","bookId":"shatibiyya","type":"bayt","num":761,"seq":761,"chapter":"سورة هود عليه السلام","title":"البيت 761","page":"ج1 ص59","text":"نما لثمود نونوا واخفضوا رضا ... ويعقوب نصب الرفع عن فاضل كلا","a":"نما لثمود نونوا واخفضوا رضا","b":"ويعقوب نصب الرفع عن فاضل كلا","ref":["ibraz:781"]},{"id":"shatibiyya:762","bookId":"shatibiyya","type":"bayt","num":762,"seq":762,"chapter":"سورة هود عليه السلام","title":"البيت 762","page":"ج1 ص59","text":"هنا قال سلم كسره وسكونه ... وقصر وفوق الطور شاع تنزلاش","a":"هنا قال سلم كسره وسكونه","b":"وقصر وفوق الطور شاع تنزلاش","ref":["ibraz:782","siraj:57"]},{"id":"shatibiyya:763","bookId":"shatibiyya","type":"bayt","num":763,"seq":763,"chapter":"سورة هود عليه السلام","title":"البيت 763","page":"ج1 ص60","text":"وفاسر أن اسر الوصل أصل دنا وها ... هنا حق إلا امراتك ارفع وأبدلا","a":"وفاسر أن اسر الوصل أصل دنا وها","b":"هنا حق إلا امراتك ارفع وأبدلا","ref":["ibraz:783","siraj:57"]},{"id":"shatibiyya:764","bookId":"shatibiyya","type":"bayt","num":764,"seq":764,"chapter":"سورة هود عليه السلام","title":"البيت 764","page":"ج1 ص60","text":"وفي سعدوا فاضمم صحابا وسل به ... وخف وإن كلا إلى صفوه دلا","a":"وفي سعدوا فاضمم صحابا وسل به","b":"وخف وإن كلا إلى صفوه دلا","ref":["ibraz:784","siraj:57"]},{"id":"shatibiyya:765","bookId":"shatibiyya","type":"bayt","num":765,"seq":765,"chapter":"سورة هود عليه السلام","title":"البيت 765","page":"ج1 ص60","text":"وفيها وفي يس والطارق العلا ... يشدد لما كامل نص فاعتلا","a":"وفيها وفي يس والطارق العلا","b":"يشدد لما كامل نص فاعتلا","ref":["ibraz:785"]},{"id":"shatibiyya:766","bookId":"shatibiyya","type":"bayt","num":766,"seq":766,"chapter":"سورة هود عليه السلام","title":"البيت 766","page":"ج1 ص60","text":"وفي زخرف في نص لسن بخلفه ... ويرجع فيه الضم والفتح إذ علا","a":"وفي زخرف في نص لسن بخلفه","b":"ويرجع فيه الضم والفتح إذ علا","ref":["ibraz:786","siraj:57"]},{"id":"shatibiyya:767","bookId":"shatibiyya","type":"bayt","num":767,"seq":767,"chapter":"سورة هود عليه السلام","title":"البيت 767","page":"ج1 ص60","text":"وخاطب عما يعملون هنا وآ ... خر النمل علما عم وارتاد منزلا","a":"وخاطب عما يعملون هنا وآ","b":"خر النمل علما عم وارتاد منزلا","ref":["siraj:57"]},{"id":"shatibiyya:768","bookId":"shatibiyya","type":"bayt","num":768,"seq":768,"chapter":"سورة هود عليه السلام","title":"البيت 768","page":"ج1 ص60","text":"وياآتها عني وإني ثمانيا ... وضيفي ولكني ونصحي فاقبلا","a":"وياآتها عني وإني ثمانيا","b":"وضيفي ولكني ونصحي فاقبلا","ref":["siraj:57"]},{"id":"shatibiyya:769","bookId":"shatibiyya","type":"bayt","num":769,"seq":769,"chapter":"سورة هود عليه السلام","title":"البيت 769","page":"ج1 ص60","text":"شقاقي وتوفيقي ورهطي عدها ... ومع فطرن أجري معا تحص مكملا","a":"شقاقي وتوفيقي ورهطي عدها","b":"ومع فطرن أجري معا تحص مكملا","ref":["ibraz:789","siraj:57"]},{"id":"shatibiyya:770","bookId":"shatibiyya","type":"bayt","num":770,"seq":770,"chapter":"سورة يوسف عليه السلام","title":"البيت 770","page":"ج1 ص60","text":"ويا أبت افتح حيث جا لابن عامر ... ووحد للمكي آيات الولا","a":"ويا أبت افتح حيث جا لابن عامر","b":"ووحد للمكي آيات الولا","ref":["ibraz:791","siraj:58"]},{"id":"shatibiyya:771","bookId":"shatibiyya","type":"bayt","num":771,"seq":771,"chapter":"سورة يوسف عليه السلام","title":"البيت 771","page":"ج1 ص60","text":"غيابات في الحرفين بالجمع نافع ... وتأمننا للكل يخفى مفصلا","a":"غيابات في الحرفين بالجمع نافع","b":"وتأمننا للكل يخفى مفصلا","ref":["ibraz:792","siraj:58"]},{"id":"shatibiyya:772","bookId":"shatibiyya","type":"bayt","num":772,"seq":772,"chapter":"سورة يوسف عليه السلام","title":"البيت 772","page":"ج1 ص60","text":"وأدغم مع إشمامه البعض عنهم ... ونرتع ونلعب ياء حصن تطولا","a":"وأدغم مع إشمامه البعض عنهم","b":"ونرتع ونلعب ياء حصن تطولا","ref":["ibraz:793","siraj:58"]},{"id":"shatibiyya:773","bookId":"shatibiyya","type":"bayt","num":773,"seq":773,"chapter":"سورة يوسف عليه السلام","title":"البيت 773","page":"ج1 ص60","text":"ويرتع سكون الكسر في العين ذو حما ... وبشراي حذف الياء ثبت وميلا","a":"ويرتع سكون الكسر في العين ذو حما","b":"وبشراي حذف الياء ثبت وميلا","ref":["ibraz:794"]},{"id":"shatibiyya:774","bookId":"shatibiyya","type":"bayt","num":774,"seq":774,"chapter":"سورة يوسف عليه السلام","title":"البيت 774","page":"ج1 ص60","text":"شفاء وقلل جهبذا وكلاهما ... عن ابن العلا والفتح عنه تفضلا","a":"شفاء وقلل جهبذا وكلاهما","b":"عن ابن العلا والفتح عنه تفضلا","ref":["ibraz:795","siraj:58"]},{"id":"shatibiyya:775","bookId":"shatibiyya","type":"bayt","num":775,"seq":775,"chapter":"سورة يوسف عليه السلام","title":"البيت 775","page":"ج1 ص60","text":"وهيت بكسر أصل كفؤ وهمزه ... لسان وضم التا لوى خلفه دلا","a":"وهيت بكسر أصل كفؤ وهمزه","b":"لسان وضم التا لوى خلفه دلا","ref":["ibraz:796","siraj:58"]},{"id":"shatibiyya:776","bookId":"shatibiyya","type":"bayt","num":776,"seq":776,"chapter":"سورة يوسف عليه السلام","title":"البيت 776","page":"ج1 ص61","text":"وفي كاف فتح اللام في مخلصا ثوى ... وفي المخلصين الكل حصن تجملا","a":"وفي كاف فتح اللام في مخلصا ثوى","b":"وفي المخلصين الكل حصن تجملا","ref":["ibraz:757","siraj:58"]},{"id":"shatibiyya:777","bookId":"shatibiyya","type":"bayt","num":777,"seq":777,"chapter":"سورة يوسف عليه السلام","title":"البيت 777","page":"ج1 ص61","text":"معا وصل حاشا حج دأبا لحفصهم ... فحرك وخاطب يعصرون شمردلا","a":"معا وصل حاشا حج دأبا لحفصهم","b":"فحرك وخاطب يعصرون شمردلا","ref":["ibraz:798","siraj:58"]},{"id":"shatibiyya:778","bookId":"shatibiyya","type":"bayt","num":778,"seq":778,"chapter":"سورة يوسف عليه السلام","title":"البيت 778","page":"ج1 ص61","text":"ونكتل بيا شاف وحيث يشاء نو ... ن دار وحفظا حافظا شاع عقلا","a":"ونكتل بيا شاف وحيث يشاء نو","b":"ن دار وحفظا حافظا شاع عقلا","ref":["ibraz:799","siraj:58"]},{"id":"shatibiyya:779","bookId":"shatibiyya","type":"bayt","num":779,"seq":779,"chapter":"سورة يوسف عليه السلام","title":"البيت 779","page":"ج1 ص61","text":"وفتيته فتيانه عن شذا ورد ... بالاخبار في قالوا أئنك دغفلا","a":"وفتيته فتيانه عن شذا ورد","b":"بالاخبار في قالوا أئنك دغفلا","ref":["ibraz:800","siraj:58"]},{"id":"shatibiyya:780","bookId":"shatibiyya","type":"bayt","num":780,"seq":780,"chapter":"سورة يوسف عليه السلام","title":"البيت 780","page":"ج1 ص61","text":"وييأس معا واستيأس استيأسوا وتي ... أسوا اقلب عن البزي بخلف وأبدلا","a":"وييأس معا واستيأس استيأسوا وتي","b":"أسوا اقلب عن البزي بخلف وأبدلا","ref":["ibraz:801","siraj:58"]},{"id":"shatibiyya:781","bookId":"shatibiyya","type":"bayt","num":781,"seq":781,"chapter":"سورة يوسف عليه السلام","title":"البيت 781","page":"ج1 ص61","text":"ويوحى إليهم كسر حاء جميعها ... ونون علا يوحى إليه شذا علا","a":"ويوحى إليهم كسر حاء جميعها","b":"ونون علا يوحى إليه شذا علا","ref":["ibraz:802","siraj:58"]},{"id":"shatibiyya:782","bookId":"shatibiyya","type":"bayt","num":782,"seq":782,"chapter":"سورة يوسف عليه السلام","title":"البيت 782","page":"ج1 ص61","text":"وثاني ننج احذف وشدد وحركن ... كذا نل وخفف كذبوا ثابتا تلا","a":"وثاني ننج احذف وشدد وحركن","b":"كذا نل وخفف كذبوا ثابتا تلا","ref":["ibraz:803"]},{"id":"shatibiyya:783","bookId":"shatibiyya","type":"bayt","num":783,"seq":783,"chapter":"سورة يوسف عليه السلام","title":"البيت 783","page":"ج1 ص61","text":"وأني وإنى الخمس ربي بأربع ... أراني معا نفسي ليحزنني حلا","a":"وأني وإنى الخمس ربي بأربع","b":"أراني معا نفسي ليحزنني حلا","ref":["ibraz:804","siraj:58"]},{"id":"shatibiyya:784","bookId":"shatibiyya","type":"bayt","num":784,"seq":784,"chapter":"سورة يوسف عليه السلام","title":"البيت 784","page":"ج1 ص61","text":"وفي إخوتي حزني سبيلي بي ولي ... لعلي آباءي أبي فاخش موحلا","a":"وفي إخوتي حزني سبيلي بي ولي","b":"لعلي آباءي أبي فاخش موحلا","ref":["ibraz:805","siraj:58"]},{"id":"shatibiyya:785","bookId":"shatibiyya","type":"bayt","num":785,"seq":785,"chapter":"سورة الرعد","title":"البيت 785","page":"ج1 ص61","text":"وزرع نخيل غير صنوان اولا ... لدى خفضها رفع على حقه طلا","a":"وزرع نخيل غير صنوان اولا","b":"لدى خفضها رفع على حقه طلا","ref":["ibraz:806","siraj:59"]},{"id":"shatibiyya:786","bookId":"shatibiyya","type":"bayt","num":786,"seq":786,"chapter":"سورة الرعد","title":"البيت 786","page":"ج1 ص61","text":"وذكر تسقى عاصم وابن عامر ... وقل بعده باليا يفضل شلشلا","a":"وذكر تسقى عاصم وابن عامر","b":"وقل بعده باليا يفضل شلشلا","ref":["ibraz:807","siraj:59"]},{"id":"shatibiyya:787","bookId":"shatibiyya","type":"bayt","num":787,"seq":787,"chapter":"سورة الرعد","title":"البيت 787","page":"ج1 ص61","text":"وما كرر استفهامه نحو آئذا ... أئنا فذو استفهام الكل أولا","a":"وما كرر استفهامه نحو آئذا","b":"أئنا فذو استفهام الكل أولا","ref":["ibraz:808","siraj:59"]},{"id":"shatibiyya:788","bookId":"shatibiyya","type":"bayt","num":788,"seq":788,"chapter":"سورة الرعد","title":"البيت 788","page":"ج1 ص61","text":"سوى نافع في النمل والشام مخبر ... سوى النازعات مع إذا وقعت ولا","a":"سوى نافع في النمل والشام مخبر","b":"سوى النازعات مع إذا وقعت ولا","ref":["ibraz:809","siraj:59"]},{"id":"shatibiyya:789","bookId":"shatibiyya","type":"bayt","num":789,"seq":789,"chapter":"سورة الرعد","title":"البيت 789","page":"ج1 ص62","text":"ودون عناد عم في العنكبوت مخ ... برا وهو في الثاني أتى راشدا ولا","a":"ودون عناد عم في العنكبوت مخ","b":"برا وهو في الثاني أتى راشدا ولا","ref":["ibraz:810","siraj:59"]},{"id":"shatibiyya:790","bookId":"shatibiyya","type":"bayt","num":790,"seq":790,"chapter":"سورة الرعد","title":"البيت 790","page":"ج1 ص62","text":"سوى العنكبوت وهو في النمل كن رضا ... وزاداه نونا إننا عنهما اعتلا","a":"سوى العنكبوت وهو في النمل كن رضا","b":"وزاداه نونا إننا عنهما اعتلا","ref":["ibraz:811","siraj:59"]},{"id":"shatibiyya:791","bookId":"shatibiyya","type":"bayt","num":791,"seq":791,"chapter":"سورة الرعد","title":"البيت 791","page":"ج1 ص62","text":"وعم رضا في النازعات وهم على ... أصولهم وامدد لوى حافظ بلا","a":"وعم رضا في النازعات وهم على","b":"أصولهم وامدد لوى حافظ بلا","ref":["ibraz:812","siraj:59"]},{"id":"shatibiyya:792","bookId":"shatibiyya","type":"bayt","num":792,"seq":792,"chapter":"سورة الرعد","title":"البيت 792","page":"ج1 ص62","text":"وهاد ووال قف وواق بيائه ... وباق دنا هل يستوي صحبة تلا","a":"وهاد ووال قف وواق بيائه","b":"وباق دنا هل يستوي صحبة تلا","ref":["ibraz:813","siraj:59"]},{"id":"shatibiyya:793","bookId":"shatibiyya","type":"bayt","num":793,"seq":793,"chapter":"سورة الرعد","title":"البيت 793","page":"ج1 ص62","text":"وبعد صحاب يوقدون وضمهم ... وصدوا ثوى مع صد في الطول وانجلا","a":"وبعد صحاب يوقدون وضمهم","b":"وصدوا ثوى مع صد في الطول وانجلا","ref":["ibraz:814","siraj:59"]},{"id":"shatibiyya:794","bookId":"shatibiyya","type":"bayt","num":794,"seq":794,"chapter":"سورة الرعد","title":"البيت 794","page":"ج1 ص62","text":"ويثبت في تخفيفه حق ناصر ... وفي الكافر الكفار بالجمع ذللا","a":"ويثبت في تخفيفه حق ناصر","b":"وفي الكافر الكفار بالجمع ذللا","ref":["ibraz:815","siraj:59"]},{"id":"shatibiyya:795","bookId":"shatibiyya","type":"bayt","num":795,"seq":795,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 795","page":"ج1 ص62","text":"وفي الخفض في الله الذي الرفع عم خا ... لق امدده واكسر وارفع القاف شلشلا","a":"وفي الخفض في الله الذي الرفع عم خا","b":"لق امدده واكسر وارفع القاف شلشلا","ref":["ibraz:816","siraj:60"]},{"id":"shatibiyya:796","bookId":"shatibiyya","type":"bayt","num":796,"seq":796,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 796","page":"ج1 ص62","text":"وفي النور واخفض كل فيها والأرض ها ... هنا مصرخي اكسر لحمزة مجملا","a":"وفي النور واخفض كل فيها والأرض ها","b":"هنا مصرخي اكسر لحمزة مجملا","ref":["ibraz:817","siraj:60"]},{"id":"shatibiyya:797","bookId":"shatibiyya","type":"bayt","num":797,"seq":797,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 797","page":"ج1 ص62","text":"كها وصل أو للساكنين وقطرب ... حكاها مع الفراء مع ولد العلا","a":"كها وصل أو للساكنين وقطرب","b":"حكاها مع الفراء مع ولد العلا","ref":["ibraz:818","siraj:60"]},{"id":"shatibiyya:798","bookId":"shatibiyya","type":"bayt","num":798,"seq":798,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 798","page":"ج1 ص62","text":"وضم كفا حصن يضلوا يضل عن ... وأفئدة باليا بخلف له ولا","a":"وضم كفا حصن يضلوا يضل عن","b":"وأفئدة باليا بخلف له ولا","ref":["ibraz:819","siraj:60"]},{"id":"shatibiyya:799","bookId":"shatibiyya","type":"bayt","num":799,"seq":799,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 799","page":"ج1 ص62","text":"وفي لتزول الفتح وارفعه راشدا ... وما كان لي إني عبادي خذ ملا","a":"وفي لتزول الفتح وارفعه راشدا","b":"وما كان لي إني عبادي خذ ملا","ref":["ibraz:820","siraj:60"]},{"id":"shatibiyya:800","bookId":"shatibiyya","type":"bayt","num":800,"seq":800,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 800","page":"ج1 ص62","text":"ورب خفيف إذ نما سكرت دنا ... تنزل ضم التا لشعبة مثلا","a":"ورب خفيف إذ نما سكرت دنا","b":"تنزل ضم التا لشعبة مثلا","ref":["ibraz:68","siraj:61"]},{"id":"shatibiyya:801","bookId":"shatibiyya","type":"bayt","num":801,"seq":801,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 801","page":"ج1 ص63","text":"وبالنون فيها واكسر الزاي وانصب ال ... ملائكة المرفوع عن شائد علا","a":"وبالنون فيها واكسر الزاي وانصب ال","b":"ملائكة المرفوع عن شائد علا","ref":["ibraz:822","siraj:61"]},{"id":"shatibiyya:802","bookId":"shatibiyya","type":"bayt","num":802,"seq":802,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 802","page":"ج1 ص63","text":"وثقل للمكي نون تبشرو ... ن واكسره حرميا وما الحذف أولا","a":"وثقل للمكي نون تبشرو","b":"ن واكسره حرميا وما الحذف أولا","ref":["ibraz:823","siraj:61"]},{"id":"shatibiyya:803","bookId":"shatibiyya","type":"bayt","num":803,"seq":803,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 803","page":"ج1 ص63","text":"ويقنط معه يقنطون وتقنطوا ... وهن بكسر النون رافقن حملا","a":"ويقنط معه يقنطون وتقنطوا","b":"وهن بكسر النون رافقن حملا","ref":["ibraz:824","siraj:61"]},{"id":"shatibiyya:804","bookId":"shatibiyya","type":"bayt","num":804,"seq":804,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 804","page":"ج1 ص63","text":"ومنجوهم خف وفي العنكبوت نن ... جين شفا منجوك صحبته دلا","a":"ومنجوهم خف وفي العنكبوت نن","b":"جين شفا منجوك صحبته دلا","ref":["siraj:61"]},{"id":"shatibiyya:805","bookId":"shatibiyya","type":"bayt","num":805,"seq":805,"chapter":"سورة إبراهيم عليه الصلاة والسلام","title":"البيت 805","page":"ج1 ص63","text":"قدرنا بها والنمل صف وعباد مع ... بناتي وأني ثم إني فاعقلا","a":"قدرنا بها والنمل صف وعباد مع","b":"بناتي وأني ثم إني فاعقلا","ref":["ibraz:826","siraj:61"]},{"id":"shatibiyya:806","bookId":"shatibiyya","type":"bayt","num":806,"seq":806,"chapter":"سورة النحل","title":"البيت 806","page":"ج1 ص63","text":"وينبت نون صح يدعون عاصم ... وفي شركاي الخلف في الهمز هلهلا","a":"وينبت نون صح يدعون عاصم","b":"وفي شركاي الخلف في الهمز هلهلا","ref":["ibraz:52","siraj:62"]},{"id":"shatibiyya:807","bookId":"shatibiyya","type":"bayt","num":807,"seq":807,"chapter":"سورة النحل","title":"البيت 807","page":"ج1 ص63","text":"ومن قبل فيهم يكسر النون نافع ... معا يتوفاهم لحمزة وصلا","a":"ومن قبل فيهم يكسر النون نافع","b":"معا يتوفاهم لحمزة وصلا","ref":["ibraz:667","siraj:62"]},{"id":"shatibiyya:808","bookId":"shatibiyya","type":"bayt","num":808,"seq":808,"chapter":"سورة النحل","title":"البيت 808","page":"ج1 ص63","text":"سما كاملا يهدي بضم وفتحة ... وخاطب تروا شرعا والآخر في كلا","a":"سما كاملا يهدي بضم وفتحة","b":"وخاطب تروا شرعا والآخر في كلا","ref":["ibraz:829","siraj:62"]},{"id":"shatibiyya:809","bookId":"shatibiyya","type":"bayt","num":809,"seq":809,"chapter":"سورة النحل","title":"البيت 809","page":"ج1 ص63","text":"ورا مفرطون اكسر أضا يتفيؤا ال ... مؤنث للبصري قبل تقبلا","a":"ورا مفرطون اكسر أضا يتفيؤا ال","b":"مؤنث للبصري قبل تقبلا","ref":["ibraz:830","siraj:62"]},{"id":"shatibiyya:810","bookId":"shatibiyya","type":"bayt","num":810,"seq":810,"chapter":"سورة النحل","title":"البيت 810","page":"ج1 ص63","text":"وحق صحاب ضم نسقيكمو معا ... لشعبة خاطب يجحدون معللا","a":"وحق صحاب ضم نسقيكمو معا","b":"لشعبة خاطب يجحدون معللا","ref":["siraj:62"]},{"id":"shatibiyya:811","bookId":"shatibiyya","type":"bayt","num":811,"seq":811,"chapter":"سورة النحل","title":"البيت 811","page":"ج1 ص63","text":"وظعنكم إسكانه ذائع ونج ... زين الذين النون داعيه نولا","a":"وظعنكم إسكانه ذائع ونج","b":"زين الذين النون داعيه نولا","ref":["ibraz:832"]},{"id":"shatibiyya:812","bookId":"shatibiyya","type":"bayt","num":812,"seq":812,"chapter":"سورة النحل","title":"البيت 812","page":"ج1 ص63","text":"ملكت وعنه نص الاخفش ياءه ... وعنه روى النقاش نونا موهلا","a":"ملكت وعنه نص الاخفش ياءه","b":"وعنه روى النقاش نونا موهلا","ref":["ibraz:833"]},{"id":"shatibiyya:813","bookId":"shatibiyya","type":"bayt","num":813,"seq":813,"chapter":"سورة النحل","title":"البيت 813","page":"ج1 ص63","text":"سوى الشام ضموا واكسروا فتنوا لهم ... ويكسر في ضيق مع النمل دخللا","a":"سوى الشام ضموا واكسروا فتنوا لهم","b":"ويكسر في ضيق مع النمل دخللا","ref":["ibraz:834","siraj:62"]},{"id":"shatibiyya:814","bookId":"shatibiyya","type":"bayt","num":814,"seq":814,"chapter":"سورة الإسراء","title":"البيت 814","page":"ج1 ص64","text":"ويتخذوا غيب حلا ليسوء نو ... ن راو وضم الهمز والمد عدلا","a":"ويتخذوا غيب حلا ليسوء نو","b":"ن راو وضم الهمز والمد عدلا","ref":["ibraz:835","siraj:63"]},{"id":"shatibiyya:815","bookId":"shatibiyya","type":"bayt","num":815,"seq":815,"chapter":"سورة الإسراء","title":"البيت 815","page":"ج1 ص64","text":"سما ويلقاه يضم مشددا ... كفى يبلغن امدده واكسر شمردلا","a":"سما ويلقاه يضم مشددا","b":"كفى يبلغن امدده واكسر شمردلا","ref":["ibraz:836","siraj:63"]},{"id":"shatibiyya:816","bookId":"shatibiyya","type":"bayt","num":816,"seq":816,"chapter":"سورة الإسراء","title":"البيت 816","page":"ج1 ص64","text":"وعن كلهم شدد وفا أف كلها ... بفتح دنا كفؤا ونون على اعتلا","a":"وعن كلهم شدد وفا أف كلها","b":"بفتح دنا كفؤا ونون على اعتلا","ref":["ibraz:837","siraj:63"]},{"id":"shatibiyya:817","bookId":"shatibiyya","type":"bayt","num":817,"seq":817,"chapter":"سورة الإسراء","title":"البيت 817","page":"ج1 ص64","text":"وبالفتح والتحريك خطأ مصوب ... وحركه المكي ومد وجملا","a":"وبالفتح والتحريك خطأ مصوب","b":"وحركه المكي ومد وجملا","ref":["siraj:63"]},{"id":"shatibiyya:818","bookId":"shatibiyya","type":"bayt","num":818,"seq":818,"chapter":"سورة الإسراء","title":"البيت 818","page":"ج1 ص64","text":"وخاطب في يسرف شهود وضمنا ... بحرفيه بالقسطاس كسر شذ علا","a":"وخاطب في يسرف شهود وضمنا","b":"بحرفيه بالقسطاس كسر شذ علا","ref":["ibraz:839","siraj:63"]},{"id":"shatibiyya:819","bookId":"shatibiyya","type":"bayt","num":819,"seq":819,"chapter":"سورة الإسراء","title":"البيت 819","page":"ج1 ص64","text":"وسيئة في همزه اضمم وهائه ... وذكر ولا تنوين ذكرا مكملا","a":"وسيئة في همزه اضمم وهائه","b":"وذكر ولا تنوين ذكرا مكملا","ref":["ibraz:840","siraj:63"]},{"id":"shatibiyya:820","bookId":"shatibiyya","type":"bayt","num":820,"seq":820,"chapter":"سورة الإسراء","title":"البيت 820","page":"ج1 ص64","text":"وخفف مع الفرقان واضمم ليذكروا ... شفاء وفي الفرقان يذكر فصلا","a":"وخفف مع الفرقان واضمم ليذكروا","b":"شفاء وفي الفرقان يذكر فصلا","ref":["ibraz:841","siraj:63"]},{"id":"shatibiyya:821","bookId":"shatibiyya","type":"bayt","num":821,"seq":821,"chapter":"سورة الإسراء","title":"البيت 821","page":"ج1 ص64","text":"وفي مريم بالعكس حق شفاؤه ... يقولون عن دار وفي الثان نزلا","a":"وفي مريم بالعكس حق شفاؤه","b":"يقولون عن دار وفي الثان نزلا","ref":["ibraz:473","siraj:63"]},{"id":"shatibiyya:822","bookId":"shatibiyya","type":"bayt","num":822,"seq":822,"chapter":"سورة الإسراء","title":"البيت 822","page":"ج1 ص64","text":"سما كفله أنث يسبح عن حمي ... شفا واكسروا إسكان رجلك عملا","a":"سما كفله أنث يسبح عن حمي","b":"شفا واكسروا إسكان رجلك عملا","ref":["ibraz:843","siraj:63"]},{"id":"shatibiyya:823","bookId":"shatibiyya","type":"bayt","num":823,"seq":823,"chapter":"سورة الإسراء","title":"البيت 823","page":"ج1 ص64","text":"ويخسف حق نونه ويعيدكم ... فيغرقكم واثنان يرسل يرسلا","a":"ويخسف حق نونه ويعيدكم","b":"فيغرقكم واثنان يرسل يرسلا","ref":["ibraz:844","siraj:63"]},{"id":"shatibiyya:824","bookId":"shatibiyya","type":"bayt","num":824,"seq":824,"chapter":"سورة الإسراء","title":"البيت 824","page":"ج1 ص64","text":"خلافك فافتح مع سكون وقصره ... سما صف نآى أخر معا همزه ملا","a":"خلافك فافتح مع سكون وقصره","b":"سما صف نآى أخر معا همزه ملا","ref":["ibraz:845","siraj:63"]},{"id":"shatibiyya:825","bookId":"shatibiyya","type":"bayt","num":825,"seq":825,"chapter":"سورة الإسراء","title":"البيت 825","page":"ج1 ص64","text":"تفجر في الأولى كتقتل ثابت ... وعم ندى كسفا بتحريكه ولا","a":"تفجر في الأولى كتقتل ثابت","b":"وعم ندى كسفا بتحريكه ولا","ref":["ibraz:846","siraj:63"]},{"id":"shatibiyya:826","bookId":"shatibiyya","type":"bayt","num":826,"seq":826,"chapter":"سورة الإسراء","title":"البيت 826","page":"ج1 ص64","text":"وفي سبأ حفص مع الشعراء قل ... وفي الروم سكن ليس بالخلف مشكلا","a":"وفي سبأ حفص مع الشعراء قل","b":"وفي الروم سكن ليس بالخلف مشكلا","ref":["ibraz:847","siraj:63"]},{"id":"shatibiyya:827","bookId":"shatibiyya","type":"bayt","num":827,"seq":827,"chapter":"سورة الإسراء","title":"البيت 827","page":"ج1 ص65","text":"وقل قال الاولى كيف دار وضم تا ... علمت رضى والياء في ربي انجلا","a":"وقل قال الاولى كيف دار وضم تا","b":"علمت رضى والياء في ربي انجلا","ref":["ibraz:848","siraj:63"]},{"id":"shatibiyya:828","bookId":"shatibiyya","type":"bayt","num":828,"seq":828,"chapter":"سورة الكهف","title":"البيت 828","page":"ج1 ص65","text":"وسكتة حفص دون قطع لطيفة ... على ألف التنوين في عوجا بلا","a":"وسكتة حفص دون قطع لطيفة","b":"على ألف التنوين في عوجا بلا","ref":["ibraz:849","siraj:64"]},{"id":"shatibiyya:829","bookId":"shatibiyya","type":"bayt","num":829,"seq":829,"chapter":"سورة الكهف","title":"البيت 829","page":"ج1 ص65","text":"وفي نون من راق ومرقدنا ولا ... م بل ران والباقون لا سكت موصلا","a":"وفي نون من راق ومرقدنا ولا","b":"م بل ران والباقون لا سكت موصلا","ref":["ibraz:850","siraj:64"]},{"id":"shatibiyya:830","bookId":"shatibiyya","type":"bayt","num":830,"seq":830,"chapter":"سورة الكهف","title":"البيت 830","page":"ج1 ص65","text":"ومن لدنه في الضم أسكن مشمه ... ومن بعده كسران عن شعبة اعتلا","a":"ومن لدنه في الضم أسكن مشمه","b":"ومن بعده كسران عن شعبة اعتلا","ref":["ibraz:851","siraj:64"]},{"id":"shatibiyya:831","bookId":"shatibiyya","type":"bayt","num":831,"seq":831,"chapter":"سورة الكهف","title":"البيت 831","page":"ج1 ص65","text":"وضم وسكن ثم ضم لغيره ... وكلهم في الها على أصله تلا","a":"وضم وسكن ثم ضم لغيره","b":"وكلهم في الها على أصله تلا","ref":["ibraz:852","siraj:64"]},{"id":"shatibiyya:832","bookId":"shatibiyya","type":"bayt","num":832,"seq":832,"chapter":"سورة الكهف","title":"البيت 832","page":"ج1 ص65","text":"وقل مرفقا فتح مع الكسر عمه ... وتزور للشامي كتحمر وصلا","a":"وقل مرفقا فتح مع الكسر عمه","b":"وتزور للشامي كتحمر وصلا","ref":["ibraz:60","siraj:64"]},{"id":"shatibiyya:833","bookId":"shatibiyya","type":"bayt","num":833,"seq":833,"chapter":"سورة الكهف","title":"البيت 833","page":"ج1 ص65","text":"وتزاور التخفيف في الزاي ثابت ... وحرميهم ملئت في اللام ثقلا","a":"وتزاور التخفيف في الزاي ثابت","b":"وحرميهم ملئت في اللام ثقلا","ref":["ibraz:854","siraj:64"]},{"id":"shatibiyya:834","bookId":"shatibiyya","type":"bayt","num":834,"seq":834,"chapter":"سورة الكهف","title":"البيت 834","page":"ج1 ص65","text":"بورقكم الإسكان في صفو حلوه ... وفيه عن الباقين كسر تأصلا","a":"بورقكم الإسكان في صفو حلوه","b":"وفيه عن الباقين كسر تأصلا","ref":["ibraz:855","siraj:64"]},{"id":"shatibiyya:835","bookId":"shatibiyya","type":"bayt","num":835,"seq":835,"chapter":"سورة الكهف","title":"البيت 835","page":"ج1 ص65","text":"وحذفك للتنوين من مائة شفا ... وتشرك خطاب وهو بالجزم كملا","a":"وحذفك للتنوين من مائة شفا","b":"وتشرك خطاب وهو بالجزم كملا","ref":["ibraz:856","siraj:64"]},{"id":"shatibiyya:836","bookId":"shatibiyya","type":"bayt","num":836,"seq":836,"chapter":"سورة الكهف","title":"البيت 836","page":"ج1 ص65","text":"وفي ثمر ضميه يفتح عاصم ... بحرفيه والإسكان في الميم حصلا","a":"وفي ثمر ضميه يفتح عاصم","b":"بحرفيه والإسكان في الميم حصلا","ref":["ibraz:858","siraj:64"]},{"id":"shatibiyya:837","bookId":"shatibiyya","type":"bayt","num":837,"seq":837,"chapter":"سورة الكهف","title":"البيت 837","page":"ج1 ص65","text":"ودع ميم خيرا منهما حكم ثابت ... وفي الوصل لكنا فمد له ملا","a":"ودع ميم خيرا منهما حكم ثابت","b":"وفي الوصل لكنا فمد له ملا","ref":["ibraz:859","siraj:64"]},{"id":"shatibiyya:838","bookId":"shatibiyya","type":"bayt","num":838,"seq":838,"chapter":"سورة الكهف","title":"البيت 838","page":"ج1 ص65","text":"وذكر تكن شاف وفي الحق جره ... على رفعه حبر سعيد تأولا","a":"وذكر تكن شاف وفي الحق جره","b":"على رفعه حبر سعيد تأولا","ref":["ibraz:860"]},{"id":"shatibiyya:839","bookId":"shatibiyya","type":"bayt","num":839,"seq":839,"chapter":"سورة الكهف","title":"البيت 839","page":"ج1 ص65","text":"وعقبا سكون الضم نص فتى ويا ... نسير والى فتحها نفر ملا","a":"وعقبا سكون الضم نص فتى ويا","b":"نسير والى فتحها نفر ملا","ref":["ibraz:861","siraj:64"]},{"id":"shatibiyya:840","bookId":"shatibiyya","type":"bayt","num":840,"seq":840,"chapter":"سورة الكهف","title":"البيت 840","page":"ج1 ص66","text":"وفي النون أنث والجبال برفعهم ... ويوم يقول النون حمزة فضلا","a":"وفي النون أنث والجبال برفعهم","b":"ويوم يقول النون حمزة فضلا","ref":["ibraz:862","siraj:64"]},{"id":"shatibiyya:841","bookId":"shatibiyya","type":"bayt","num":841,"seq":841,"chapter":"سورة الكهف","title":"البيت 841","page":"ج1 ص66","text":"لمهلكهم ضموا ومهلك أهله ... سوى عاصم والكسر في اللام عولا","a":"لمهلكهم ضموا ومهلك أهله","b":"سوى عاصم والكسر في اللام عولا","ref":["ibraz:863","siraj:64"]},{"id":"shatibiyya:842","bookId":"shatibiyya","type":"bayt","num":842,"seq":842,"chapter":"سورة الكهف","title":"البيت 842","page":"ج1 ص66","text":"وها كسر أنسانيه ضم لحفصهم ... ومعه عليه الله في الفتح وصلا","a":"وها كسر أنسانيه ضم لحفصهم","b":"ومعه عليه الله في الفتح وصلا","ref":["ibraz:864","siraj:64"]},{"id":"shatibiyya:843","bookId":"shatibiyya","type":"bayt","num":843,"seq":843,"chapter":"سورة الكهف","title":"البيت 843","page":"ج1 ص66","text":"لتغرق فتح الضم والكسر غيبة ... وقل أهلها بالرفع راويه فصلا","a":"لتغرق فتح الضم والكسر غيبة","b":"وقل أهلها بالرفع راويه فصلا","ref":["siraj:64"]},{"id":"shatibiyya:844","bookId":"shatibiyya","type":"bayt","num":844,"seq":844,"chapter":"سورة الكهف","title":"البيت 844","page":"ج1 ص66","text":"ومد وخفف ياء زاكية سما ... ونون لدني خف صاحبه إلى","a":"ومد وخفف ياء زاكية سما","b":"ونون لدني خف صاحبه إلى","ref":["ibraz:866","siraj:64"]},{"id":"shatibiyya:845","bookId":"shatibiyya","type":"bayt","num":845,"seq":845,"chapter":"سورة الكهف","title":"البيت 845","page":"ج1 ص66","text":"وسكن وأشمم ضمة الدال صادقا ... تخذت فخفف واكسر الخاء دم حلا","a":"وسكن وأشمم ضمة الدال صادقا","b":"تخذت فخفف واكسر الخاء دم حلا","ref":["ibraz:867","siraj:64"]},{"id":"shatibiyya:846","bookId":"shatibiyya","type":"bayt","num":846,"seq":846,"chapter":"سورة الكهف","title":"البيت 846","page":"ج1 ص66","text":"ومن بعد بالتخفيف يبدل هاهنا ... وفوق وتحت الملك كافيه ظللا","a":"ومن بعد بالتخفيف يبدل هاهنا","b":"وفوق وتحت الملك كافيه ظللا","ref":["siraj:64"]},{"id":"shatibiyya:847","bookId":"shatibiyya","type":"bayt","num":847,"seq":847,"chapter":"سورة الكهف","title":"البيت 847","page":"ج1 ص66","text":"فأتبع خفف في الثلاثة ذاكرا ... وحامية بالمد صحبته كلا","a":"فأتبع خفف في الثلاثة ذاكرا","b":"وحامية بالمد صحبته كلا","ref":["ibraz:869","siraj:64"]},{"id":"shatibiyya:848","bookId":"shatibiyya","type":"bayt","num":848,"seq":848,"chapter":"سورة الكهف","title":"البيت 848","page":"ج1 ص66","text":"وفي الهمز ياء عنهم وصحابهم ... جزاء فنون وانصب الرفع وأقبلا","a":"وفي الهمز ياء عنهم وصحابهم","b":"جزاء فنون وانصب الرفع وأقبلا","ref":["ibraz:870"]},{"id":"shatibiyya:849","bookId":"shatibiyya","type":"bayt","num":849,"seq":849,"chapter":"سورة الكهف","title":"البيت 849","page":"ج1 ص66","text":"على حق السدين سدا صحاب حق ... ق الضم مفتوح وياسين شد علا","a":"على حق السدين سدا صحاب حق","b":"ق الضم مفتوح وياسين شد علا","ref":["ibraz:871","siraj:64"]},{"id":"shatibiyya:850","bookId":"shatibiyya","type":"bayt","num":850,"seq":850,"chapter":"سورة الكهف","title":"البيت 850","page":"ج1 ص66","text":"ويأجوج مأجوج اهمز الكل ناصرا ... وفي يفقهون الضم والكسر شكلا","a":"ويأجوج مأجوج اهمز الكل ناصرا","b":"وفي يفقهون الضم والكسر شكلا","ref":["ibraz:63","siraj:64"]},{"id":"shatibiyya:851","bookId":"shatibiyya","type":"bayt","num":851,"seq":851,"chapter":"سورة الكهف","title":"البيت 851","page":"ج1 ص66","text":"وحرك بها والمؤمنين ومده ... خراجا شفا واعكس فخرج له ملا","a":"وحرك بها والمؤمنين ومده","b":"خراجا شفا واعكس فخرج له ملا","ref":["ibraz:873","siraj:64"]},{"id":"shatibiyya:852","bookId":"shatibiyya","type":"bayt","num":852,"seq":852,"chapter":"سورة الكهف","title":"البيت 852","page":"ج1 ص66","text":"ومكنني أظهر دليلا وسكنوا ... مع الضم في الصدفين عن شعبة الملا","a":"ومكنني أظهر دليلا وسكنوا","b":"مع الضم في الصدفين عن شعبة الملا","ref":["ibraz:874","siraj:64"]},{"id":"shatibiyya:853","bookId":"shatibiyya","type":"bayt","num":853,"seq":853,"chapter":"سورة الكهف","title":"البيت 853","page":"ج1 ص66","text":"كما حقه ضماه واهمز مسكنا ... لدى ردما ائتوني وقبل اكسر الولا","a":"كما حقه ضماه واهمز مسكنا","b":"لدى ردما ائتوني وقبل اكسر الولا","ref":["ibraz:875","siraj:64"]},{"id":"shatibiyya:854","bookId":"shatibiyya","type":"bayt","num":854,"seq":854,"chapter":"سورة الكهف","title":"البيت 854","page":"ج1 ص67","text":"لشعبة والثاني فشا صف بخلفه ... ولا كسر وابدأ فيهما الياء مبدلا","a":"لشعبة والثاني فشا صف بخلفه","b":"ولا كسر وابدأ فيهما الياء مبدلا","ref":["ibraz:876","siraj:64"]},{"id":"shatibiyya:855","bookId":"shatibiyya","type":"bayt","num":855,"seq":855,"chapter":"سورة الكهف","title":"البيت 855","page":"ج1 ص67","text":"وزد قبل همز الوصل والغير فيهما ... بقطعهما والمد بدءا وموصلا","a":"وزد قبل همز الوصل والغير فيهما","b":"بقطعهما والمد بدءا وموصلا","ref":["ibraz:877"]},{"id":"shatibiyya:856","bookId":"shatibiyya","type":"bayt","num":856,"seq":856,"chapter":"سورة الكهف","title":"البيت 856","page":"ج1 ص67","text":"وطاء فما اسطاعوا لحمزة شددوا ... وأن تنفد التذكير شاف تأولا","a":"وطاء فما اسطاعوا لحمزة شددوا","b":"وأن تنفد التذكير شاف تأولا","ref":["ibraz:878","siraj:64"]},{"id":"shatibiyya:857","bookId":"shatibiyya","type":"bayt","num":857,"seq":857,"chapter":"سورة الكهف","title":"البيت 857","page":"ج1 ص67","text":"ثلاث معي دوني وربي بأربع ... وما قبل إن شاء المضافات تجتلا","a":"ثلاث معي دوني وربي بأربع","b":"وما قبل إن شاء المضافات تجتلا","ref":["ibraz:879","siraj:64"]},{"id":"shatibiyya:858","bookId":"shatibiyya","type":"bayt","num":858,"seq":858,"chapter":"سورة مريم عليها السلام","title":"البيت 858","page":"ج1 ص67","text":"وحرفا يرث بالجزم حلو رضى وقل ... خلقت خلقنا شاع وجها مجملا","a":"وحرفا يرث بالجزم حلو رضى وقل","b":"خلقت خلقنا شاع وجها مجملا","ref":["ibraz:880","siraj:65"]},{"id":"shatibiyya:859","bookId":"shatibiyya","type":"bayt","num":859,"seq":859,"chapter":"سورة مريم عليها السلام","title":"البيت 859","page":"ج1 ص67","text":"وضم بكيا كسره عنهما وقل ... عتيا صليا مع جثيا شذا علا","a":"وضم بكيا كسره عنهما وقل","b":"عتيا صليا مع جثيا شذا علا","ref":["ibraz:881","siraj:65"]},{"id":"shatibiyya:860","bookId":"shatibiyya","type":"bayt","num":860,"seq":860,"chapter":"سورة مريم عليها السلام","title":"البيت 860","page":"ج1 ص67","text":"وهمز أهب باليا جرى حلو بحره ... بخلف ونسيا فتحه فائز علا","a":"وهمز أهب باليا جرى حلو بحره","b":"بخلف ونسيا فتحه فائز علا","ref":["ibraz:882","siraj:65"]},{"id":"shatibiyya:861","bookId":"shatibiyya","type":"bayt","num":861,"seq":861,"chapter":"سورة مريم عليها السلام","title":"البيت 861","page":"ج1 ص67","text":"ومن تحتها اكسر واخفض الدهر عن شذا ... وخف تساقط فاصلا فتحملا","a":"ومن تحتها اكسر واخفض الدهر عن شذا","b":"وخف تساقط فاصلا فتحملا","ref":["ibraz:883","siraj:65"]},{"id":"shatibiyya:862","bookId":"shatibiyya","type":"bayt","num":862,"seq":862,"chapter":"سورة مريم عليها السلام","title":"البيت 862","page":"ج1 ص67","text":"وبالضم والتخفيف والكسر حفصهم ... وفي رفع قول الحق نصب ند كلا","a":"وبالضم والتخفيف والكسر حفصهم","b":"وفي رفع قول الحق نصب ند كلا","ref":["ibraz:884","siraj:65"]},{"id":"shatibiyya:863","bookId":"shatibiyya","type":"bayt","num":863,"seq":863,"chapter":"سورة مريم عليها السلام","title":"البيت 863","page":"ج1 ص67","text":"وكسر وأن الله ذاك وأخبروا ... بخلف إذا ما مت موفين وصلا","a":"وكسر وأن الله ذاك وأخبروا","b":"بخلف إذا ما مت موفين وصلا","ref":["ibraz:885","siraj:65"]},{"id":"shatibiyya:864","bookId":"shatibiyya","type":"bayt","num":864,"seq":864,"chapter":"سورة مريم عليها السلام","title":"البيت 864","page":"ج1 ص67","text":"وننجي خفيفا رض مقاما بضمه ... دنا رءيا ابدل مدغما باسطا ملا","a":"وننجي خفيفا رض مقاما بضمه","b":"دنا رءيا ابدل مدغما باسطا ملا","ref":["ibraz:886","siraj:65"]},{"id":"shatibiyya:865","bookId":"shatibiyya","type":"bayt","num":865,"seq":865,"chapter":"سورة مريم عليها السلام","title":"البيت 865","page":"ج1 ص67","text":"وولدا بها والزخرف اضمم وسكنن ... شفاء وفي نوح شفا حقه ولا","a":"وولدا بها والزخرف اضمم وسكنن","b":"شفاء وفي نوح شفا حقه ولا","ref":["ibraz:887","siraj:65"]},{"id":"shatibiyya:866","bookId":"shatibiyya","type":"bayt","num":866,"seq":866,"chapter":"سورة مريم عليها السلام","title":"البيت 866","page":"ج1 ص68","text":"وفيها وفي الشورى يكاد أتى رضا ... وطا يتفطرن اكسروا غير أثقلا","a":"وفيها وفي الشورى يكاد أتى رضا","b":"وطا يتفطرن اكسروا غير أثقلا","ref":["ibraz:888","siraj:65"]},{"id":"shatibiyya:867","bookId":"shatibiyya","type":"bayt","num":867,"seq":867,"chapter":"سورة مريم عليها السلام","title":"البيت 867","page":"ج1 ص68","text":"وفي التاء نون ساكن حج في صفا ... كمال وفي الشورى حلا صفوه ولا","a":"وفي التاء نون ساكن حج في صفا","b":"كمال وفي الشورى حلا صفوه ولا","ref":["ibraz:889","siraj:65"]},{"id":"shatibiyya:868","bookId":"shatibiyya","type":"bayt","num":868,"seq":868,"chapter":"سورة مريم عليها السلام","title":"البيت 868","page":"ج1 ص68","text":"وراءي واجعل لي وإني كلاهما ... وربي وآتاني مضافاتها العلا","a":"وراءي واجعل لي وإني كلاهما","b":"وربي وآتاني مضافاتها العلا","ref":["ibraz:890"]},{"id":"shatibiyya:869","bookId":"shatibiyya","type":"bayt","num":869,"seq":869,"chapter":"سورة طه","title":"البيت 869","page":"ج1 ص68","text":"لحمزة فاضمم كسرها أهله امكثوا ... معا وافتحوا إني أنا دائما حلا","a":"لحمزة فاضمم كسرها أهله امكثوا","b":"معا وافتحوا إني أنا دائما حلا","ref":["ibraz:891","siraj:4"]},{"id":"shatibiyya:870","bookId":"shatibiyya","type":"bayt","num":870,"seq":870,"chapter":"سورة طه","title":"البيت 870","page":"ج1 ص68","text":"ونون بها والنازعات طوى ذكا ... وفي اخترتك اخترناك فاز وثقلا","a":"ونون بها والنازعات طوى ذكا","b":"وفي اخترتك اخترناك فاز وثقلا","ref":["ibraz:892","siraj:66"]},{"id":"shatibiyya:871","bookId":"shatibiyya","type":"bayt","num":871,"seq":871,"chapter":"سورة طه","title":"البيت 871","page":"ج1 ص68","text":"وأنا وشام قطع أشدد وضم في اب ... تدا غيره واضمم وأشركه كلكلا","a":"وأنا وشام قطع أشدد وضم في اب","b":"تدا غيره واضمم وأشركه كلكلا","ref":["ibraz:893","siraj:66"]},{"id":"shatibiyya:872","bookId":"shatibiyya","type":"bayt","num":872,"seq":872,"chapter":"سورة طه","title":"البيت 872","page":"ج1 ص68","text":"مع الزخرف اقصر بعد فتح وساكن ... مهادا ثوى واضمم سوى في ند كلا","a":"مع الزخرف اقصر بعد فتح وساكن","b":"مهادا ثوى واضمم سوى في ند كلا","ref":["ibraz:894","siraj:66"]},{"id":"shatibiyya:873","bookId":"shatibiyya","type":"bayt","num":873,"seq":873,"chapter":"سورة طه","title":"البيت 873","page":"ج1 ص68","text":"ويكسر باقيهم وفيه وفي سدى ... ممال وقوف في الأصول تأصلا","a":"ويكسر باقيهم وفيه وفي سدى","b":"ممال وقوف في الأصول تأصلا","ref":["ibraz:895","siraj:66"]},{"id":"shatibiyya:874","bookId":"shatibiyya","type":"bayt","num":874,"seq":874,"chapter":"سورة طه","title":"البيت 874","page":"ج1 ص68","text":"فيسحتكم ضم وكسر صحابهم ... وتخفيف قالوا إن عالمه دلا","a":"فيسحتكم ضم وكسر صحابهم","b":"وتخفيف قالوا إن عالمه دلا","ref":["ibraz:896","siraj:66"]},{"id":"shatibiyya:875","bookId":"shatibiyya","type":"bayt","num":875,"seq":875,"chapter":"سورة طه","title":"البيت 875","page":"ج1 ص68","text":"وهذين في هذان حج وثقله ... دنا فاجمعوا صل وافتح الميم حولا","a":"وهذين في هذان حج وثقله","b":"دنا فاجمعوا صل وافتح الميم حولا","ref":["ibraz:897","siraj:66"]},{"id":"shatibiyya:876","bookId":"shatibiyya","type":"bayt","num":876,"seq":876,"chapter":"سورة طه","title":"البيت 876","page":"ج1 ص68","text":"وقل ساحر سحر شفا وتلقف ار ... فع الجزم مع أنثى يخيل مقبلا","a":"وقل ساحر سحر شفا وتلقف ار","b":"فع الجزم مع أنثى يخيل مقبلا","ref":["ibraz:898","siraj:66"]},{"id":"shatibiyya:877","bookId":"shatibiyya","type":"bayt","num":877,"seq":877,"chapter":"سورة طه","title":"البيت 877","page":"ج1 ص69","text":"وأنجيتكم واعدتكم ما رزقتكم ... شفا لا تخف بالقصر والجزم فصلا","a":"وأنجيتكم واعدتكم ما رزقتكم","b":"شفا لا تخف بالقصر والجزم فصلا","ref":["ibraz:52","siraj:66"]},{"id":"shatibiyya:878","bookId":"shatibiyya","type":"bayt","num":878,"seq":878,"chapter":"سورة طه","title":"البيت 878","page":"ج1 ص69","text":"وحا فيحل الضم في كسره رضا ... وفي لام يحلل عنه وافى محللا","a":"وحا فيحل الضم في كسره رضا","b":"وفي لام يحلل عنه وافى محللا","ref":["ibraz:900","siraj:66"]},{"id":"shatibiyya:879","bookId":"shatibiyya","type":"bayt","num":879,"seq":879,"chapter":"سورة طه","title":"البيت 879","page":"ج1 ص69","text":"وفي ملكنا ضم شفا وافتحوا أولي ... نهى وحملنا ضم واكسر مثقلا","a":"وفي ملكنا ضم شفا وافتحوا أولي","b":"نهى وحملنا ضم واكسر مثقلا","ref":["ibraz:901","siraj:66"]},{"id":"shatibiyya:880","bookId":"shatibiyya","type":"bayt","num":880,"seq":880,"chapter":"سورة طه","title":"البيت 880","page":"ج1 ص69","text":"كما عند حرمي وخاطب يبصروا ... شذا وبكسر اللام تخلفه حلا","a":"كما عند حرمي وخاطب يبصروا","b":"شذا وبكسر اللام تخلفه حلا","ref":["siraj:66"]},{"id":"shatibiyya:881","bookId":"shatibiyya","type":"bayt","num":881,"seq":881,"chapter":"سورة طه","title":"البيت 881","page":"ج1 ص69","text":"دراك ومع ياء بننفخ ضمه ... وفي ضمه افتح عن سوى ولد العلا","a":"دراك ومع ياء بننفخ ضمه","b":"وفي ضمه افتح عن سوى ولد العلا","ref":["ibraz:903","siraj:66"]},{"id":"shatibiyya:882","bookId":"shatibiyya","type":"bayt","num":882,"seq":882,"chapter":"سورة طه","title":"البيت 882","page":"ج1 ص69","text":"وبالقصر للمكي واجزم فلا يخف ... وأنك لا في كسره صفوة العلا","a":"وبالقصر للمكي واجزم فلا يخف","b":"وأنك لا في كسره صفوة العلا","ref":["ibraz:904","siraj:4"]},{"id":"shatibiyya:883","bookId":"shatibiyya","type":"bayt","num":883,"seq":883,"chapter":"سورة طه","title":"البيت 883","page":"ج1 ص69","text":"وبالضم ترضى صف رضا يأتهم مؤن ... نث عن أولي حفظ لعلي أخي حلا","a":"وبالضم ترضى صف رضا يأتهم مؤن","b":"نث عن أولي حفظ لعلي أخي حلا","ref":["ibraz:905","siraj:66"]},{"id":"shatibiyya:884","bookId":"shatibiyya","type":"bayt","num":884,"seq":884,"chapter":"سورة طه","title":"البيت 884","page":"ج1 ص69","text":"وذكري معا إني معا لي معا حشر ... تني عين نفسي إنني رأسي انجلا","a":"وذكري معا إني معا لي معا حشر","b":"تني عين نفسي إنني رأسي انجلا","ref":["ibraz:906","siraj:66"]},{"id":"shatibiyya:885","bookId":"shatibiyya","type":"bayt","num":885,"seq":885,"chapter":"سورة الأنبياء عليهم السلام","title":"البيت 885","page":"ج1 ص69","text":"وقل قال عن شهد وآخرها علا ... وقل أولم لا واو داريه وصلا","a":"وقل قال عن شهد وآخرها علا","b":"وقل أولم لا واو داريه وصلا","ref":["ibraz:806","siraj:67"]},{"id":"shatibiyya:886","bookId":"shatibiyya","type":"bayt","num":886,"seq":886,"chapter":"سورة الأنبياء عليهم السلام","title":"البيت 886","page":"ج1 ص69","text":"وتسمع فتح الضم والكسر غيبة ... سوى اليحصبي والصم بالرفع وكلا","a":"وتسمع فتح الضم والكسر غيبة","b":"سوى اليحصبي والصم بالرفع وكلا","ref":["ibraz:908","siraj:67"]},{"id":"shatibiyya:887","bookId":"shatibiyya","type":"bayt","num":887,"seq":887,"chapter":"سورة الأنبياء عليهم السلام","title":"البيت 887","page":"ج1 ص69","text":"وقال به في النمل والروم دارم ... ومثقال مع لقمان بالرفع أكملا","a":"وقال به في النمل والروم دارم","b":"ومثقال مع لقمان بالرفع أكملا","ref":["ibraz:909","siraj:67"]},{"id":"shatibiyya:888","bookId":"shatibiyya","type":"bayt","num":888,"seq":888,"chapter":"سورة الأنبياء عليهم السلام","title":"البيت 888","page":"ج1 ص69","text":"جذاذا بكسر الضم راو ونونه ... ليحصنكم صافى وأنث عن كلا","a":"جذاذا بكسر الضم راو ونونه","b":"ليحصنكم صافى وأنث عن كلا","ref":["ibraz:910","siraj:67"]},{"id":"shatibiyya:889","bookId":"shatibiyya","type":"bayt","num":889,"seq":889,"chapter":"سورة الأنبياء عليهم السلام","title":"البيت 889","page":"ج1 ص70","text":"وسكن بين الكسر والقصر صحبة ... وحرم وننجي احذف وثقل كذي صلا","a":"وسكن بين الكسر والقصر صحبة","b":"وحرم وننجي احذف وثقل كذي صلا","ref":["ibraz:911","siraj:67"]},{"id":"shatibiyya:890","bookId":"shatibiyya","type":"bayt","num":890,"seq":890,"chapter":"سورة الأنبياء عليهم السلام","title":"البيت 890","page":"ج1 ص70","text":"وللكتب اجمع عن شذا ومضافها ... معي مسني إني عبادي مجتلا","a":"وللكتب اجمع عن شذا ومضافها","b":"معي مسني إني عبادي مجتلا","ref":["ibraz:912","siraj:67"]},{"id":"shatibiyya:891","bookId":"shatibiyya","type":"bayt","num":891,"seq":891,"chapter":"سورة الحج","title":"البيت 891","page":"ج1 ص70","text":"سكارى معا سكرى شفا ومحرك ... ليقطع بكسر اللام كم جيده حلا","a":"سكارى معا سكرى شفا ومحرك","b":"ليقطع بكسر اللام كم جيده حلا","ref":["ibraz:913","siraj:68"]},{"id":"shatibiyya:892","bookId":"shatibiyya","type":"bayt","num":892,"seq":892,"chapter":"سورة الحج","title":"البيت 892","page":"ج1 ص70","text":"ليوفوا ابن ذكوان ليطوفوا له ... ليقضوا سوى بزيهم نفر جلا","a":"ليوفوا ابن ذكوان ليطوفوا له","b":"ليقضوا سوى بزيهم نفر جلا","ref":["ibraz:914"]},{"id":"shatibiyya:893","bookId":"shatibiyya","type":"bayt","num":893,"seq":893,"chapter":"سورة الحج","title":"البيت 893","page":"ج1 ص70","text":"ومع فاطر انصب لؤلؤا نظم ألفة ... ورفع سواء غير حفص تنخلا","a":"ومع فاطر انصب لؤلؤا نظم ألفة","b":"ورفع سواء غير حفص تنخلا","ref":["ibraz:915","siraj:68"]},{"id":"shatibiyya:894","bookId":"shatibiyya","type":"bayt","num":894,"seq":894,"chapter":"سورة الحج","title":"البيت 894","page":"ج1 ص70","text":"وغير صحاب في الشريعة ثم ول ... يوفوا فحركه لشعبة أثقلا","a":"وغير صحاب في الشريعة ثم ول","b":"يوفوا فحركه لشعبة أثقلا","ref":["ibraz:916","siraj:68"]},{"id":"shatibiyya:895","bookId":"shatibiyya","type":"bayt","num":895,"seq":895,"chapter":"سورة الحج","title":"البيت 895","page":"ج1 ص70","text":"فتخطفه عن نافع مثله وقل ... معا منسكا بالكسر في السين شلشلا","a":"فتخطفه عن نافع مثله وقل","b":"معا منسكا بالكسر في السين شلشلا","ref":["ibraz:917","siraj:68"]},{"id":"shatibiyya:896","bookId":"shatibiyya","type":"bayt","num":896,"seq":896,"chapter":"سورة الحج","title":"البيت 896","page":"ج1 ص70","text":"ويدفع حق بين فتحيه ساكن ... يدافع والمضموم في أذن اعتلا","a":"ويدفع حق بين فتحيه ساكن","b":"يدافع والمضموم في أذن اعتلا","ref":["ibraz:444","siraj:68"]},{"id":"shatibiyya:897","bookId":"shatibiyya","type":"bayt","num":897,"seq":897,"chapter":"سورة الحج","title":"البيت 897","page":"ج1 ص70","text":"نعم حفظوا والفتح في تا يقاتلو ... ن عم علاه هدمت خف إذ دلا","a":"نعم حفظوا والفتح في تا يقاتلو","b":"ن عم علاه هدمت خف إذ دلا","ref":["ibraz:919","siraj:68"]},{"id":"shatibiyya:898","bookId":"shatibiyya","type":"bayt","num":898,"seq":898,"chapter":"سورة الحج","title":"البيت 898","page":"ج1 ص70","text":"وبصري أهلكنا بتاء وضمها ... يعدون فيه الغيب شايع دخللا","a":"وبصري أهلكنا بتاء وضمها","b":"يعدون فيه الغيب شايع دخللا","ref":["ibraz:920","siraj:68"]},{"id":"shatibiyya:899","bookId":"shatibiyya","type":"bayt","num":899,"seq":899,"chapter":"سورة الحج","title":"البيت 899","page":"ج1 ص70","text":"وفي سبإ حرفان معها معاجزي ... ن حق بلا مد وفي الجيم ثقلا","a":"وفي سبإ حرفان معها معاجزي","b":"ن حق بلا مد وفي الجيم ثقلا","ref":["ibraz:921","siraj:68"]},{"id":"shatibiyya:900","bookId":"shatibiyya","type":"bayt","num":900,"seq":900,"chapter":"سورة الحج","title":"البيت 900","page":"ج1 ص71","text":"والاول مع لقمان يدعون غلبوا ... سوى شعبة والياء بيتي جملا","a":"والاول مع لقمان يدعون غلبوا","b":"سوى شعبة والياء بيتي جملا","ref":["ibraz:922","siraj:68"]},{"id":"shatibiyya:901","bookId":"shatibiyya","type":"bayt","num":901,"seq":901,"chapter":"سورة المؤمنون","title":"البيت 901","page":"ج1 ص71","text":"أماناتهم وحد وفي سال داريا ... صلاتهم شاف وعظما كذي صلا","a":"أماناتهم وحد وفي سال داريا","b":"صلاتهم شاف وعظما كذي صلا","ref":["ibraz:545","siraj:69"]},{"id":"shatibiyya:902","bookId":"shatibiyya","type":"bayt","num":902,"seq":902,"chapter":"سورة المؤمنون","title":"البيت 902","page":"ج1 ص71","text":"مع العظم واضمم واكسر الضم حقه ... بتنبت والمفتوح سيناء ذللا","a":"مع العظم واضمم واكسر الضم حقه","b":"بتنبت والمفتوح سيناء ذللا","ref":["ibraz:924","siraj:69"]},{"id":"shatibiyya:903","bookId":"shatibiyya","type":"bayt","num":903,"seq":903,"chapter":"سورة المؤمنون","title":"البيت 903","page":"ج1 ص71","text":"وضم وفتح منزلا غير شعبة ... ونون تترا حقه واكسر الولا","a":"وضم وفتح منزلا غير شعبة","b":"ونون تترا حقه واكسر الولا","ref":["ibraz:925","siraj:69"]},{"id":"shatibiyya:904","bookId":"shatibiyya","type":"bayt","num":904,"seq":904,"chapter":"سورة المؤمنون","title":"البيت 904","page":"ج1 ص71","text":"وأن ثوى والنون خفف كفى وته ... جرون بضم واكسر الضم أجملا","a":"وأن ثوى والنون خفف كفى وته","b":"جرون بضم واكسر الضم أجملا","ref":["ibraz:926","siraj:69"]},{"id":"shatibiyya:905","bookId":"shatibiyya","type":"bayt","num":905,"seq":905,"chapter":"سورة المؤمنون","title":"البيت 905","page":"ج1 ص71","text":"وفي لام لله الأخيرين حذفها ... وفي الهاء رفع الجر عن ولد العلا","a":"وفي لام لله الأخيرين حذفها","b":"وفي الهاء رفع الجر عن ولد العلا","ref":["ibraz:535","siraj:69"]},{"id":"shatibiyya:906","bookId":"shatibiyya","type":"bayt","num":906,"seq":906,"chapter":"سورة المؤمنون","title":"البيت 906","page":"ج1 ص71","text":"وعالم خفض الرفع عن نفر وفت ... ح شقوتنا وامدد وحركه شلشلا","a":"وعالم خفض الرفع عن نفر وفت","b":"ح شقوتنا وامدد وحركه شلشلا","ref":["ibraz:928","siraj:69"]},{"id":"shatibiyya:907","bookId":"shatibiyya","type":"bayt","num":907,"seq":907,"chapter":"سورة المؤمنون","title":"البيت 907","page":"ج1 ص71","text":"وكسرك سخريا بها وبصادها ... على ضمه أعطى شفاء وأكملا","a":"وكسرك سخريا بها وبصادها","b":"على ضمه أعطى شفاء وأكملا","ref":["ibraz:535","siraj:69"]},{"id":"shatibiyya:908","bookId":"shatibiyya","type":"bayt","num":908,"seq":908,"chapter":"سورة المؤمنون","title":"البيت 908","page":"ج1 ص71","text":"وفي أنهم كسر شريف وترجع ... ون في الضم فتح واكسر الجيم واكملا","a":"وفي أنهم كسر شريف وترجع","b":"ون في الضم فتح واكسر الجيم واكملا","ref":["ibraz:930","siraj:69"]},{"id":"shatibiyya:909","bookId":"shatibiyya","type":"bayt","num":909,"seq":909,"chapter":"سورة المؤمنون","title":"البيت 909","page":"ج1 ص71","text":"وفي قال كم قل دون شك وبعده ... شفا وبها ياء لعلي عللا","a":"وفي قال كم قل دون شك وبعده","b":"شفا وبها ياء لعلي عللا","ref":["ibraz:931","siraj:69"]},{"id":"shatibiyya:910","bookId":"shatibiyya","type":"bayt","num":910,"seq":910,"chapter":"سورة النور","title":"البيت 910","page":"ج1 ص71","text":"وحق وفرضنا ثقيلا ورأفة ... يحركه المكي وأربع أولا","a":"وحق وفرضنا ثقيلا ورأفة","b":"يحركه المكي وأربع أولا","ref":["ibraz:932","siraj:70"]},{"id":"shatibiyya:911","bookId":"shatibiyya","type":"bayt","num":911,"seq":911,"chapter":"سورة النور","title":"البيت 911","page":"ج1 ص71","text":"صحاب وغير الحفص خامسة الأخي ... ر أن غضب التخفيف والكسر أدخلا","a":"صحاب وغير الحفص خامسة الأخي","b":"ر أن غضب التخفيف والكسر أدخلا","ref":["ibraz:933"]},{"id":"shatibiyya:912","bookId":"shatibiyya","type":"bayt","num":912,"seq":912,"chapter":"سورة النور","title":"البيت 912","page":"ج1 ص72","text":"ويرفع بعد الجر يشهد شائع ... وغير أولي بالنصب صاحبه كلا","a":"ويرفع بعد الجر يشهد شائع","b":"وغير أولي بالنصب صاحبه كلا","ref":["ibraz:934","siraj:70"]},{"id":"shatibiyya:913","bookId":"shatibiyya","type":"bayt","num":913,"seq":913,"chapter":"سورة النور","title":"البيت 913","page":"ج1 ص72","text":"ودري اكسر ضمه حجة رضى ... وفي مده والهمز صحبته حلا","a":"ودري اكسر ضمه حجة رضى","b":"وفي مده والهمز صحبته حلا","ref":["ibraz:935"]},{"id":"shatibiyya:914","bookId":"shatibiyya","type":"bayt","num":914,"seq":914,"chapter":"سورة النور","title":"البيت 914","page":"ج1 ص72","text":"يسبح فتح البا كذا صف ويوقد ال ... مؤنث صف شرعا وحق تفعلا","a":"يسبح فتح البا كذا صف ويوقد ال","b":"مؤنث صف شرعا وحق تفعلا","ref":["ibraz:936","siraj:70"]},{"id":"shatibiyya:915","bookId":"shatibiyya","type":"bayt","num":915,"seq":915,"chapter":"سورة النور","title":"البيت 915","page":"ج1 ص72","text":"وما نون البزي سحاب ورفعهم ... لدى ظلمات جر دار وأوصلا","a":"وما نون البزي سحاب ورفعهم","b":"لدى ظلمات جر دار وأوصلا","ref":["ibraz:937","siraj:70"]},{"id":"shatibiyya:916","bookId":"shatibiyya","type":"bayt","num":916,"seq":916,"chapter":"سورة النور","title":"البيت 916","page":"ج1 ص72","text":"كما استخلف اضممه مع الكسر صادقا ... وفي يبدلن الخف صاحبه دلا","a":"كما استخلف اضممه مع الكسر صادقا","b":"وفي يبدلن الخف صاحبه دلا","ref":["ibraz:938","siraj:70"]},{"id":"shatibiyya:917","bookId":"shatibiyya","type":"bayt","num":917,"seq":917,"chapter":"سورة النور","title":"البيت 917","page":"ج1 ص72","text":"وثاني ثلاث ارفع سوى صحبة ... وقف ولا وقف قبل النصب إن قلت أبدلا","a":"وثاني ثلاث ارفع سوى صحبة","b":"وقف ولا وقف قبل النصب إن قلت أبدلا","ref":["ibraz:939","siraj:70"]},{"id":"shatibiyya:918","bookId":"shatibiyya","type":"bayt","num":918,"seq":918,"chapter":"سورة الفرقان","title":"البيت 918","page":"ج1 ص72","text":"ويأكل منها النون شاع وجزمنا ... ويجعل برفع دل صافيه كملا","a":"ويأكل منها النون شاع وجزمنا","b":"ويجعل برفع دل صافيه كملا","ref":["ibraz:940"]},{"id":"shatibiyya:919","bookId":"shatibiyya","type":"bayt","num":919,"seq":919,"chapter":"سورة الفرقان","title":"البيت 919","page":"ج1 ص72","text":"ونحشر يا دار علا فيقول ن ... ون شام وخاطب تستطيعون عملا","a":"ونحشر يا دار علا فيقول ن","b":"ون شام وخاطب تستطيعون عملا","ref":["ibraz:941","siraj:71"]},{"id":"shatibiyya:920","bookId":"shatibiyya","type":"bayt","num":920,"seq":920,"chapter":"سورة الفرقان","title":"البيت 920","page":"ج1 ص72","text":"ونزل زده النون وارفع وخف وال ... ... ملائكة المرفوع ينصب دخللا","a":"ونزل زده النون وارفع وخف وال","b":"... ملائكة المرفوع ينصب دخللا","ref":["ibraz:942","siraj:71"]},{"id":"shatibiyya:921","bookId":"shatibiyya","type":"bayt","num":921,"seq":921,"chapter":"سورة الفرقان","title":"البيت 921","page":"ج1 ص72","text":"تشقق خف الشين مع قاف غالب ... ويأمر شاف واجمعوا سرجا ولا","a":"تشقق خف الشين مع قاف غالب","b":"ويأمر شاف واجمعوا سرجا ولا","ref":["ibraz:943","siraj:71"]},{"id":"shatibiyya:922","bookId":"shatibiyya","type":"bayt","num":922,"seq":922,"chapter":"سورة الفرقان","title":"البيت 922","page":"ج1 ص72","text":"ولم يقتروا اضمم عم والكسر ضم ثق ... يضاعف ويخلد رفع جزم كذي صلا","a":"ولم يقتروا اضمم عم والكسر ضم ثق","b":"يضاعف ويخلد رفع جزم كذي صلا","ref":["ibraz:944","siraj:71"]},{"id":"shatibiyya:923","bookId":"shatibiyya","type":"bayt","num":923,"seq":923,"chapter":"سورة الفرقان","title":"البيت 923","page":"ج1 ص73","text":"ووحد ذرياتنا حفظ صحبة ... ويلقون فاضممه وحرك مثقلا","a":"ووحد ذرياتنا حفظ صحبة","b":"ويلقون فاضممه وحرك مثقلا","ref":["ibraz:945","siraj:71"]},{"id":"shatibiyya:924","bookId":"shatibiyya","type":"bayt","num":924,"seq":924,"chapter":"سورة الفرقان","title":"البيت 924","page":"ج1 ص73","text":"سوى صحبة والياء قومي وليتني ... وكم لو وليت تورث القلب أنصلا","a":"سوى صحبة والياء قومي وليتني","b":"وكم لو وليت تورث القلب أنصلا","ref":["ibraz:946","siraj:71"]},{"id":"shatibiyya:925","bookId":"shatibiyya","type":"bayt","num":925,"seq":925,"chapter":"سورة الشعراء","title":"البيت 925","page":"ج1 ص73","text":"وفي حاذرون المد ما ثل فارهي ... ن ذاع وخلق اضمم وحرك به العلا","a":"وفي حاذرون المد ما ثل فارهي","b":"ن ذاع وخلق اضمم وحرك به العلا","ref":["ibraz:947","siraj:72"]},{"id":"shatibiyya:926","bookId":"shatibiyya","type":"bayt","num":926,"seq":926,"chapter":"سورة الشعراء","title":"البيت 926","page":"ج1 ص73","text":"كما في ند والأيكة اللام ساكن ... مع الهمز واخفضه وفي صاد غيطلا","a":"كما في ند والأيكة اللام ساكن","b":"مع الهمز واخفضه وفي صاد غيطلا","ref":["ibraz:948","siraj:72"]},{"id":"shatibiyya:927","bookId":"shatibiyya","type":"bayt","num":927,"seq":927,"chapter":"سورة الشعراء","title":"البيت 927","page":"ج1 ص73","text":"وفي نزل التخفيف والروح والأمي ... ن رفعهما علو سما وتبجلا","a":"وفي نزل التخفيف والروح والأمي","b":"ن رفعهما علو سما وتبجلا","ref":["ibraz:949","siraj:72"]},{"id":"shatibiyya:928","bookId":"shatibiyya","type":"bayt","num":928,"seq":928,"chapter":"سورة الشعراء","title":"البيت 928","page":"ج1 ص73","text":"وأنث يكن لليحصبي وارفع آية ... وفا فتوكل واو ظمآنه حلا","a":"وأنث يكن لليحصبي وارفع آية","b":"وفا فتوكل واو ظمآنه حلا","ref":["ibraz:950","siraj:72"]},{"id":"shatibiyya:929","bookId":"shatibiyya","type":"bayt","num":929,"seq":929,"chapter":"سورة الشعراء","title":"البيت 929","page":"ج1 ص73","text":"ويا خمس أجري مع عبادي ولي معي ... معا مع أبي إني معا ربي انجلا","a":"ويا خمس أجري مع عبادي ولي معي","b":"معا مع أبي إني معا ربي انجلا","ref":["ibraz:951","siraj:72"]},{"id":"shatibiyya:930","bookId":"shatibiyya","type":"bayt","num":930,"seq":930,"chapter":"سورة النمل","title":"البيت 930","page":"ج1 ص73","text":"شهاب بنون ثق وقل يأتينني ... دنا مكث افتح ضمة الكاف نوفلا","a":"شهاب بنون ثق وقل يأتينني","b":"دنا مكث افتح ضمة الكاف نوفلا","ref":["ibraz:952","siraj:73"]},{"id":"shatibiyya:931","bookId":"shatibiyya","type":"bayt","num":931,"seq":931,"chapter":"سورة النمل","title":"البيت 931","page":"ج1 ص73","text":"معا سبأ افتح دون نون حمى هدى ... وسكنه وانو الوقف زهرا ومندلا","a":"معا سبأ افتح دون نون حمى هدى","b":"وسكنه وانو الوقف زهرا ومندلا","ref":["ibraz:953","siraj:73"]},{"id":"shatibiyya:932","bookId":"shatibiyya","type":"bayt","num":932,"seq":932,"chapter":"سورة النمل","title":"البيت 932","page":"ج1 ص73","text":"ألا يسجدوا راو وقف مبتلى ألا ... ويا واسجدوا وأبدأه بالضم موصلا","a":"ألا يسجدوا راو وقف مبتلى ألا","b":"ويا واسجدوا وأبدأه بالضم موصلا","ref":["ibraz:954"]},{"id":"shatibiyya:933","bookId":"shatibiyya","type":"bayt","num":933,"seq":933,"chapter":"سورة النمل","title":"البيت 933","page":"ج1 ص73","text":"أراد ألا يا هؤلاء اسجدوا وقف ... له قبله والغير أدرج مبدلا","a":"أراد ألا يا هؤلاء اسجدوا وقف","b":"له قبله والغير أدرج مبدلا","ref":["ibraz:955","siraj:73"]},{"id":"shatibiyya:934","bookId":"shatibiyya","type":"bayt","num":934,"seq":934,"chapter":"سورة النمل","title":"البيت 934","page":"ج1 ص73","text":"وقد قيل مفعولا وأن أدغموا بلا ... وليس بمقطوع فقف يسجدوا ولا","a":"وقد قيل مفعولا وأن أدغموا بلا","b":"وليس بمقطوع فقف يسجدوا ولا","ref":["ibraz:956","siraj:73"]},{"id":"shatibiyya:935","bookId":"shatibiyya","type":"bayt","num":935,"seq":935,"chapter":"سورة النمل","title":"البيت 935","page":"ج1 ص74","text":"ويخفون خاطب يعلنون على رضا ... تمدونني الإدغام فاز فثقلا","a":"ويخفون خاطب يعلنون على رضا","b":"تمدونني الإدغام فاز فثقلا","ref":["ibraz:957","siraj:73"]},{"id":"shatibiyya:936","bookId":"shatibiyya","type":"bayt","num":936,"seq":936,"chapter":"سورة النمل","title":"البيت 936","page":"ج1 ص74","text":"مع السوق ساقيها وسوق اهمزوا زكا ... ووجه بهمز بعده الواو وكلا","a":"مع السوق ساقيها وسوق اهمزوا زكا","b":"ووجه بهمز بعده الواو وكلا","ref":["ibraz:958","siraj:73"]},{"id":"shatibiyya:937","bookId":"shatibiyya","type":"bayt","num":937,"seq":937,"chapter":"سورة النمل","title":"البيت 937","page":"ج1 ص74","text":"نقولن فاضمم رابعا ونبيتن ... نه ومعا في النون خاطب شمردلا","a":"نقولن فاضمم رابعا ونبيتن","b":"نه ومعا في النون خاطب شمردلا","ref":["ibraz:959","siraj:73"]},{"id":"shatibiyya:938","bookId":"shatibiyya","type":"bayt","num":938,"seq":938,"chapter":"سورة النمل","title":"البيت 938","page":"ج1 ص74","text":"ومع فتح أن الناس ما بعد مكرهم ... لكوف وأما يشركون ند حلا","a":"ومع فتح أن الناس ما بعد مكرهم","b":"لكوف وأما يشركون ند حلا","ref":["ibraz:960","siraj:73"]},{"id":"shatibiyya:939","bookId":"shatibiyya","type":"bayt","num":939,"seq":939,"chapter":"سورة النمل","title":"البيت 939","page":"ج1 ص74","text":"وشدد وصل وامدد بل أدارك الذي ... ذكا قبله يذكرون له حلا","a":"وشدد وصل وامدد بل أدارك الذي","b":"ذكا قبله يذكرون له حلا","ref":["ibraz:961","siraj:73"]},{"id":"shatibiyya:940","bookId":"shatibiyya","type":"bayt","num":940,"seq":940,"chapter":"سورة النمل","title":"البيت 940","page":"ج1 ص74","text":"بهادي معا تهدي فشا العمي ناصبا ... وباليا لكل قف وفي الروم شمللا","a":"بهادي معا تهدي فشا العمي ناصبا","b":"وباليا لكل قف وفي الروم شمللا","ref":["ibraz:962","siraj:73"]},{"id":"shatibiyya:941","bookId":"shatibiyya","type":"bayt","num":941,"seq":941,"chapter":"سورة النمل","title":"البيت 941","page":"ج1 ص74","text":"وآتوه فاقصر وافتح الضم علمه ... فشا تفعلون الغيب حق له ولا","a":"وآتوه فاقصر وافتح الضم علمه","b":"فشا تفعلون الغيب حق له ولا","ref":["ibraz:963","siraj:73"]},{"id":"shatibiyya:942","bookId":"shatibiyya","type":"bayt","num":942,"seq":942,"chapter":"سورة النمل","title":"البيت 942","page":"ج1 ص74","text":"ومالي وأوزعني وإني كلاهما ... ليبلوني الياءات في قول من بلا","a":"ومالي وأوزعني وإني كلاهما","b":"ليبلوني الياءات في قول من بلا","ref":["ibraz:964","siraj:73"]},{"id":"shatibiyya:943","bookId":"shatibiyya","type":"bayt","num":943,"seq":943,"chapter":"سورة القصص","title":"البيت 943","page":"ج1 ص74","text":"وفي نري الفتحان مع ألف ويا ... ئه وثلاث رفعها بعد شكلا","a":"وفي نري الفتحان مع ألف ويا","b":"ئه وثلاث رفعها بعد شكلا","ref":["ibraz:965","siraj:74"]},{"id":"shatibiyya:944","bookId":"shatibiyya","type":"bayt","num":944,"seq":944,"chapter":"سورة القصص","title":"البيت 944","page":"ج1 ص74","text":"وحزنا بضم مع سكون شفا ويص ... در اضمم وكسر الضم ظاميه أنهلا","a":"وحزنا بضم مع سكون شفا ويص","b":"در اضمم وكسر الضم ظاميه أنهلا","ref":["ibraz:966","siraj:74"]},{"id":"shatibiyya:945","bookId":"shatibiyya","type":"bayt","num":945,"seq":945,"chapter":"سورة القصص","title":"البيت 945","page":"ج1 ص75","text":"وجذوة اضمم فزت والفتح نل وصح ... بة كهف ضم الرهب واسكنه ذبلا","a":"وجذوة اضمم فزت والفتح نل وصح","b":"بة كهف ضم الرهب واسكنه ذبلا","ref":["ibraz:967","siraj:74"]},{"id":"shatibiyya:946","bookId":"shatibiyya","type":"bayt","num":946,"seq":946,"chapter":"سورة القصص","title":"البيت 946","page":"ج1 ص75","text":"يصدقني ارفع جزمه في نصوصه ... وقل قال موسى واحذف الواو دخللا","a":"يصدقني ارفع جزمه في نصوصه","b":"وقل قال موسى واحذف الواو دخللا","ref":["ibraz:968","siraj:74"]},{"id":"shatibiyya:947","bookId":"shatibiyya","type":"bayt","num":947,"seq":947,"chapter":"سورة القصص","title":"البيت 947","page":"ج1 ص75","text":"نما نفر بالضم والفتح يرجعو ... ن سحران ثق في ساحران فتقبلا","a":"نما نفر بالضم والفتح يرجعو","b":"ن سحران ثق في ساحران فتقبلا","ref":["ibraz:969","siraj:74"]},{"id":"shatibiyya:948","bookId":"shatibiyya","type":"bayt","num":948,"seq":948,"chapter":"سورة القصص","title":"البيت 948","page":"ج1 ص75","text":"ويجبى خليط يعقلون حفظته ... وفي خسف الفتحتين حفص تنخلا","a":"ويجبى خليط يعقلون حفظته","b":"وفي خسف الفتحتين حفص تنخلا","ref":["ibraz:970","siraj:74"]},{"id":"shatibiyya:949","bookId":"shatibiyya","type":"bayt","num":949,"seq":949,"chapter":"سورة القصص","title":"البيت 949","page":"ج1 ص75","text":"وعندي وذو الثنيا وإني أربع ... لعلي معا ربي ثلاث معي اعتلا","a":"وعندي وذو الثنيا وإني أربع","b":"لعلي معا ربي ثلاث معي اعتلا","ref":["ibraz:971","siraj:74"]},{"id":"shatibiyya:950","bookId":"shatibiyya","type":"bayt","num":950,"seq":950,"chapter":"سورة العنكبوت","title":"البيت 950","page":"ج1 ص75","text":"يروا صحبة خاطب وحرك ومد في الن ... نشاءة حقا وهو حيث تنزلا","a":"يروا صحبة خاطب وحرك ومد في الن","b":"نشاءة حقا وهو حيث تنزلا","ref":["ibraz:972","siraj:75"]},{"id":"shatibiyya:951","bookId":"shatibiyya","type":"bayt","num":951,"seq":951,"chapter":"سورة العنكبوت","title":"البيت 951","page":"ج1 ص75","text":"مودة المرفوع حق رواته ... ونونه وانصب بينكم عم صندلا","a":"مودة المرفوع حق رواته","b":"ونونه وانصب بينكم عم صندلا","ref":["ibraz:973","siraj:75"]},{"id":"shatibiyya:952","bookId":"shatibiyya","type":"bayt","num":952,"seq":952,"chapter":"سورة العنكبوت","title":"البيت 952","page":"ج1 ص75","text":"ويدعون نجم حافظ وموحد ... هنا آية من ربه صحبة دلا","a":"ويدعون نجم حافظ وموحد","b":"هنا آية من ربه صحبة دلا","ref":["ibraz:974","siraj:75"]},{"id":"shatibiyya:953","bookId":"shatibiyya","type":"bayt","num":953,"seq":953,"chapter":"سورة العنكبوت","title":"البيت 953","page":"ج1 ص75","text":"وفي ونقول الياء حصن ويرجعو ... ن صفو وحرف الروم صافيه حللا","a":"وفي ونقول الياء حصن ويرجعو","b":"ن صفو وحرف الروم صافيه حللا","ref":["siraj:75"]},{"id":"shatibiyya:954","bookId":"shatibiyya","type":"bayt","num":954,"seq":954,"chapter":"سورة العنكبوت","title":"البيت 954","page":"ج1 ص75","text":"وذات ثلاث سكنت با نبوئن ... ن مع خفه والهمز بالياء شمللا","a":"وذات ثلاث سكنت با نبوئن","b":"ن مع خفه والهمز بالياء شمللا","ref":["ibraz:976"]},{"id":"shatibiyya:955","bookId":"shatibiyya","type":"bayt","num":955,"seq":955,"chapter":"سورة العنكبوت","title":"البيت 955","page":"ج1 ص75","text":"وإسكان ول فاكسر كما حج جا ندى ... وربي عبادي أرضي اليا بها انجلا","a":"وإسكان ول فاكسر كما حج جا ندى","b":"وربي عبادي أرضي اليا بها انجلا","ref":["ibraz:977","siraj:75"]},{"id":"shatibiyya:956","bookId":"shatibiyya","type":"bayt","num":956,"seq":956,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 956","page":"ج1 ص76","text":"وعاقبة الثاني سما وبنونه ... نذيق زكا للعالمين اكسروا علا","a":"وعاقبة الثاني سما وبنونه","b":"نذيق زكا للعالمين اكسروا علا","ref":["ibraz:978","siraj:76"]},{"id":"shatibiyya:957","bookId":"shatibiyya","type":"bayt","num":957,"seq":957,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 957","page":"ج1 ص76","text":"ليربوا خطاب ضم والواو ساكن ... أتى واجمعوا آثار كم شرفا علا","a":"ليربوا خطاب ضم والواو ساكن","b":"أتى واجمعوا آثار كم شرفا علا","ref":["ibraz:979","siraj:76"]},{"id":"shatibiyya:958","bookId":"shatibiyya","type":"bayt","num":958,"seq":958,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 958","page":"ج1 ص76","text":"وينفع كوفي وفي الطول حصنه ... ورحمة ارفع فائزا ومحصلا","a":"وينفع كوفي وفي الطول حصنه","b":"ورحمة ارفع فائزا ومحصلا","ref":["ibraz:980","siraj:76"]},{"id":"shatibiyya:959","bookId":"shatibiyya","type":"bayt","num":959,"seq":959,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 959","page":"ج1 ص76","text":"ويتخذ المرفوع غير صحابهم ... تصعر بمد خف إذ شرعه حلا","a":"ويتخذ المرفوع غير صحابهم","b":"تصعر بمد خف إذ شرعه حلا","ref":["ibraz:981","siraj:76"]},{"id":"shatibiyya:960","bookId":"shatibiyya","type":"bayt","num":960,"seq":960,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 960","page":"ج1 ص76","text":"وفي نعمة حرك وذكر هاؤها ... وضم ولا تنوين عن حسن اعتلا","a":"وفي نعمة حرك وذكر هاؤها","b":"وضم ولا تنوين عن حسن اعتلا","ref":["ibraz:982","siraj:76"]},{"id":"shatibiyya:961","bookId":"shatibiyya","type":"bayt","num":961,"seq":961,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 961","page":"ج1 ص76","text":"سوى ابن العلا والبحر أخفي سكونه ... فشا خلقه التحريك حصن تطولا","a":"سوى ابن العلا والبحر أخفي سكونه","b":"فشا خلقه التحريك حصن تطولا","ref":["ibraz:983","siraj:76"]},{"id":"shatibiyya:962","bookId":"shatibiyya","type":"bayt","num":962,"seq":962,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 962","page":"ج1 ص76","text":"لما صبروا فاكسر وخفف شذا وقل ... بما يعملون اثنان عن ولد العلا","a":"لما صبروا فاكسر وخفف شذا وقل","b":"بما يعملون اثنان عن ولد العلا","ref":["ibraz:984","siraj:76"]},{"id":"shatibiyya:963","bookId":"shatibiyya","type":"bayt","num":963,"seq":963,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 963","page":"ج1 ص76","text":"وبالهمز كل اللاء والياء بعده ... ذكا وبياء ساكن حج هملا","a":"وبالهمز كل اللاء والياء بعده","b":"ذكا وبياء ساكن حج هملا","ref":["ibraz:985","siraj:76"]},{"id":"shatibiyya:964","bookId":"shatibiyya","type":"bayt","num":964,"seq":964,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 964","page":"ج1 ص76","text":"وكالياء مكسورا لورش وعنهما ... وقف مسكنا والهمز زاكيه بجلا","a":"وكالياء مكسورا لورش وعنهما","b":"وقف مسكنا والهمز زاكيه بجلا","ref":["ibraz:986","siraj:76"]},{"id":"shatibiyya:965","bookId":"shatibiyya","type":"bayt","num":965,"seq":965,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 965","page":"ج1 ص76","text":"وتظاهرون اضممه واكسر لعاصم ... وفي الهاء خفف وامدد الظاء ذبلا","a":"وتظاهرون اضممه واكسر لعاصم","b":"وفي الهاء خفف وامدد الظاء ذبلا","ref":["ibraz:988","siraj:76"]},{"id":"shatibiyya:966","bookId":"shatibiyya","type":"bayt","num":966,"seq":966,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 966","page":"ج1 ص76","text":"وخففه ثبت وفي قد سمع كما ... هنا وهناك الظاء خفف نوفلا","a":"وخففه ثبت وفي قد سمع كما","b":"هنا وهناك الظاء خفف نوفلا","ref":["ibraz:989","siraj:76"]},{"id":"shatibiyya:967","bookId":"shatibiyya","type":"bayt","num":967,"seq":967,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 967","page":"ج1 ص76","text":"وحق صحاب قصر وصل الظنون والر ... سول السبيلا وهو في الوقف في حلا","a":"وحق صحاب قصر وصل الظنون والر","b":"سول السبيلا وهو في الوقف في حلا","ref":["ibraz:990","siraj:76"]},{"id":"shatibiyya:968","bookId":"shatibiyya","type":"bayt","num":968,"seq":968,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 968","page":"ج1 ص77","text":"مقام لحفص ضم والثان عم في الد ... دخان وآتوها على المد ذو حلا","a":"مقام لحفص ضم والثان عم في الد","b":"دخان وآتوها على المد ذو حلا","ref":["ibraz:991","siraj:76"]},{"id":"shatibiyya:969","bookId":"shatibiyya","type":"bayt","num":969,"seq":969,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 969","page":"ج1 ص77","text":"وفي الكل ضم الكسر في إسوة ندى ... وقصر كفا حق يضاعف مثقلا","a":"وفي الكل ضم الكسر في إسوة ندى","b":"وقصر كفا حق يضاعف مثقلا","ref":["ibraz:992","siraj:76"]},{"id":"shatibiyya:970","bookId":"shatibiyya","type":"bayt","num":970,"seq":970,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 970","page":"ج1 ص77","text":"وباليا وفتح العين رفع العذاب حص ... ن حسن وتعمل نؤت بالياء شمللا","a":"وباليا وفتح العين رفع العذاب حص","b":"ن حسن وتعمل نؤت بالياء شمللا","ref":["ibraz:993","siraj:76"]},{"id":"shatibiyya:971","bookId":"shatibiyya","type":"bayt","num":971,"seq":971,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 971","page":"ج1 ص77","text":"وقرن افتح اذ نصوا يكون له ثوى ... يحل سوى البصري وخاتم وكلا","a":"وقرن افتح اذ نصوا يكون له ثوى","b":"يحل سوى البصري وخاتم وكلا","ref":["ibraz:994","siraj:76"]},{"id":"shatibiyya:972","bookId":"shatibiyya","type":"bayt","num":972,"seq":972,"chapter":"من سورة الروم إلى سورة سبأ","title":"البيت 972","page":"ج1 ص77","text":"بفتح نما ساداتنا اجمع بكسرة ... كفى وكثيرا نقطة تحت نفلا","a":"بفتح نما ساداتنا اجمع بكسرة","b":"كفى وكثيرا نقطة تحت نفلا","ref":["ibraz:996","siraj:76"]},{"id":"shatibiyya:973","bookId":"shatibiyya","type":"bayt","num":973,"seq":973,"chapter":"سورة سبأ وفاطر","title":"البيت 973","page":"ج1 ص77","text":"وعالم قل علام شاع ورفع خف ... ... ضه عم من رجز أليم معا ولا","a":"وعالم قل علام شاع ورفع خف","b":"... ضه عم من رجز أليم معا ولا","ref":["ibraz:1009","siraj:77"]},{"id":"shatibiyya:974","bookId":"shatibiyya","type":"bayt","num":974,"seq":974,"chapter":"سورة سبأ وفاطر","title":"البيت 974","page":"ج1 ص77","text":"على رفع خفض الميم دل عليمه ... ونخسف نشأ نسقط بها الياء شمللا","a":"على رفع خفض الميم دل عليمه","b":"ونخسف نشأ نسقط بها الياء شمللا","ref":["ibraz:1010","siraj:77"]},{"id":"shatibiyya:975","bookId":"shatibiyya","type":"bayt","num":975,"seq":975,"chapter":"سورة سبأ وفاطر","title":"البيت 975","page":"ج1 ص77","text":"وفي الريح رفع صح منسأته سكو ... ن همزته ماض وأبدله إذ حلا","a":"وفي الريح رفع صح منسأته سكو","b":"ن همزته ماض وأبدله إذ حلا","ref":["ibraz:1011","siraj:77"]},{"id":"shatibiyya:976","bookId":"shatibiyya","type":"bayt","num":976,"seq":976,"chapter":"سورة سبأ وفاطر","title":"البيت 976","page":"ج1 ص77","text":"مساكنهم سكنه واقصر على شذا ... وفي الكاف فافتح عالما فتبجلا","a":"مساكنهم سكنه واقصر على شذا","b":"وفي الكاف فافتح عالما فتبجلا","ref":["ibraz:1012","siraj:77"]},{"id":"shatibiyya:977","bookId":"shatibiyya","type":"bayt","num":977,"seq":977,"chapter":"سورة سبأ وفاطر","title":"البيت 977","page":"ج1 ص77","text":"نجازي بياء وافتح الزاي والكفو ... ر رفع سما كم صاب أكل أضف حلا","a":"نجازي بياء وافتح الزاي والكفو","b":"ر رفع سما كم صاب أكل أضف حلا","ref":["ibraz:1013","siraj:77"]},{"id":"shatibiyya:978","bookId":"shatibiyya","type":"bayt","num":978,"seq":978,"chapter":"سورة سبأ وفاطر","title":"البيت 978","page":"ج1 ص77","text":"وحق لوا باعد بقصر مشددا ... وصدق للكوفي جاء مثقلا","a":"وحق لوا باعد بقصر مشددا","b":"وصدق للكوفي جاء مثقلا","ref":["ibraz:1014","siraj:77"]},{"id":"shatibiyya:979","bookId":"shatibiyya","type":"bayt","num":979,"seq":979,"chapter":"سورة سبأ وفاطر","title":"البيت 979","page":"ج1 ص77","text":"وفزع فتح الضم والكسر كامل ... ومن أذن اضمم حلو شرع تسلسلا","a":"وفزع فتح الضم والكسر كامل","b":"ومن أذن اضمم حلو شرع تسلسلا","ref":["ibraz:1015","siraj:77"]},{"id":"shatibiyya:980","bookId":"shatibiyya","type":"bayt","num":980,"seq":980,"chapter":"سورة سبأ وفاطر","title":"البيت 980","page":"ج1 ص77","text":"وفي الغرفة التوحيد فاز ويهمز الت ... تناوش حلوا صحبة وتوصلا","a":"وفي الغرفة التوحيد فاز ويهمز الت","b":"تناوش حلوا صحبة وتوصلا","ref":["ibraz:1016","siraj:77"]},{"id":"shatibiyya:981","bookId":"shatibiyya","type":"bayt","num":981,"seq":981,"chapter":"سورة سبأ وفاطر","title":"البيت 981","page":"ج1 ص78","text":"وأجرى عبادي ربي اليا مضافها ... وقل رفع غير الله بالخفض شكلا","a":"وأجرى عبادي ربي اليا مضافها","b":"وقل رفع غير الله بالخفض شكلا","ref":["ibraz:1017"]},{"id":"shatibiyya:982","bookId":"shatibiyya","type":"bayt","num":982,"seq":982,"chapter":"سورة سبأ وفاطر","title":"البيت 982","page":"ج1 ص78","text":"ونجزي بياء ضم مع فتح زايه ... وكل به ارفع وهو عن ولد العلا","a":"ونجزي بياء ضم مع فتح زايه","b":"وكل به ارفع وهو عن ولد العلا","ref":["ibraz:1018","siraj:77"]},{"id":"shatibiyya:983","bookId":"shatibiyya","type":"bayt","num":983,"seq":983,"chapter":"سورة سبأ وفاطر","title":"البيت 983","page":"ج1 ص78","text":"وفي السيئ المخفوض همزا سكونه ... فشا بينات قصر حق فتى علا","a":"وفي السيئ المخفوض همزا سكونه","b":"فشا بينات قصر حق فتى علا","ref":["ibraz:1019","siraj:77"]},{"id":"shatibiyya:984","bookId":"shatibiyya","type":"bayt","num":984,"seq":984,"chapter":"سورة يس","title":"البيت 984","page":"ج1 ص78","text":"وتنزيل نصب الرفع كهف صحابه ... وخفف فعززنا لشعبة محملا","a":"وتنزيل نصب الرفع كهف صحابه","b":"وخفف فعززنا لشعبة محملا","ref":["ibraz:1020","siraj:78"]},{"id":"shatibiyya:985","bookId":"shatibiyya","type":"bayt","num":985,"seq":985,"chapter":"سورة يس","title":"البيت 985","page":"ج1 ص78","text":"وما عملته يحذف الهاء صحبة ... ووالقمر ارفعه سما ولقد حلا","a":"وما عملته يحذف الهاء صحبة","b":"ووالقمر ارفعه سما ولقد حلا","ref":["ibraz:1021","siraj:78"]},{"id":"shatibiyya:986","bookId":"shatibiyya","type":"bayt","num":986,"seq":986,"chapter":"سورة يس","title":"البيت 986","page":"ج1 ص78","text":"وخا يخصمون افتح سما لذ وأخف حل ... و بر وسكنه وخفف فتكملا","a":"وخا يخصمون افتح سما لذ وأخف حل","b":"و بر وسكنه وخفف فتكملا","ref":["ibraz:1022","siraj:78"]},{"id":"shatibiyya:987","bookId":"shatibiyya","type":"bayt","num":987,"seq":987,"chapter":"سورة يس","title":"البيت 987","page":"ج1 ص78","text":"وساكن شغل ضم ذكرا وكسر في ... ظلال بضم واقصر اللام شلشلا","a":"وساكن شغل ضم ذكرا وكسر في","b":"ظلال بضم واقصر اللام شلشلا","ref":["ibraz:1023"]},{"id":"shatibiyya:988","bookId":"shatibiyya","type":"bayt","num":988,"seq":988,"chapter":"سورة يس","title":"البيت 988","page":"ج1 ص78","text":"وقل جبلا مع كسر ضميه ثقله ... أخو نصرة واضمم وسكن كذي حلا","a":"وقل جبلا مع كسر ضميه ثقله","b":"أخو نصرة واضمم وسكن كذي حلا","ref":["ibraz:1024","siraj:78"]},{"id":"shatibiyya:989","bookId":"shatibiyya","type":"bayt","num":989,"seq":989,"chapter":"سورة يس","title":"البيت 989","page":"ج1 ص78","text":"وتنكسه فاضممه وحرك لعاصم ... وحمزة واكسر عنهما الضم أثقلا","a":"وتنكسه فاضممه وحرك لعاصم","b":"وحمزة واكسر عنهما الضم أثقلا","ref":["ibraz:1025"]},{"id":"shatibiyya:990","bookId":"shatibiyya","type":"bayt","num":990,"seq":990,"chapter":"سورة يس","title":"البيت 990","page":"ج1 ص78","text":"لينذر دم غصنا والاحقاف هم بها ... بخلف هدى مالي وإني معا حلا","a":"لينذر دم غصنا والاحقاف هم بها","b":"بخلف هدى مالي وإني معا حلا","ref":["ibraz:1026","siraj:78"]},{"id":"shatibiyya:991","bookId":"shatibiyya","type":"bayt","num":991,"seq":991,"chapter":"سورة الصافات","title":"البيت 991","page":"ج1 ص78","text":"وصفا وزجرا ذكرا ادغم حمزة ... وذروا بلا روم بها التا فثقلا","a":"وصفا وزجرا ذكرا ادغم حمزة","b":"وذروا بلا روم بها التا فثقلا","ref":["ibraz:1028","siraj:79"]},{"id":"shatibiyya:992","bookId":"shatibiyya","type":"bayt","num":992,"seq":992,"chapter":"سورة الصافات","title":"البيت 992","page":"ج1 ص78","text":"وخلادهم بالخلف فالملقيات فال ... مغيرات في ذكرا وصبحا فحصلا","a":"وخلادهم بالخلف فالملقيات فال","b":"مغيرات في ذكرا وصبحا فحصلا","ref":["ibraz:1029","siraj:79"]},{"id":"shatibiyya:993","bookId":"shatibiyya","type":"bayt","num":993,"seq":993,"chapter":"سورة الصافات","title":"البيت 993","page":"ج1 ص79","text":"بزينة نون في ند والكواكب ان ... صبوا صفوة يسمعون شذا علا","a":"بزينة نون في ند والكواكب ان","b":"صبوا صفوة يسمعون شذا علا","ref":["ibraz:1030","siraj:79"]},{"id":"shatibiyya:994","bookId":"shatibiyya","type":"bayt","num":994,"seq":994,"chapter":"سورة الصافات","title":"البيت 994","page":"ج1 ص79","text":"بثقليه واضمم تا عجبت شذا وسا ... كن معا او آباؤنا كيف بللا","a":"بثقليه واضمم تا عجبت شذا وسا","b":"كن معا او آباؤنا كيف بللا","ref":["ibraz:1031","siraj:79"]},{"id":"shatibiyya:995","bookId":"shatibiyya","type":"bayt","num":995,"seq":995,"chapter":"سورة الصافات","title":"البيت 995","page":"ج1 ص79","text":"وفي ينزفون الزاي فاكسر شذا وقل ... في الاخرى ثوى واضمم يزفون فاكملا","a":"وفي ينزفون الزاي فاكسر شذا وقل","b":"في الاخرى ثوى واضمم يزفون فاكملا","ref":["ibraz:1032","siraj:79"]},{"id":"shatibiyya:996","bookId":"shatibiyya","type":"bayt","num":996,"seq":996,"chapter":"سورة الصافات","title":"البيت 996","page":"ج1 ص79","text":"وماذا تري بالضم والكسر شائع ... وإلياس حذف الهمز بالخلف مثلا","a":"وماذا تري بالضم والكسر شائع","b":"وإلياس حذف الهمز بالخلف مثلا","ref":["ibraz:1033","siraj:79"]},{"id":"shatibiyya:997","bookId":"shatibiyya","type":"bayt","num":997,"seq":997,"chapter":"سورة الصافات","title":"البيت 997","page":"ج1 ص79","text":"وغير صحاب رفعه الله ربكم ... ورب وإلياسين بالكسر وصلا","a":"وغير صحاب رفعه الله ربكم","b":"ورب وإلياسين بالكسر وصلا","ref":["ibraz:1034","siraj:79"]},{"id":"shatibiyya:998","bookId":"shatibiyya","type":"bayt","num":998,"seq":998,"chapter":"سورة الصافات","title":"البيت 998","page":"ج1 ص79","text":"مع القصر مع إسكان كسر دنا غنى ... وإني وذو الثنيا وأني اجملا","a":"مع القصر مع إسكان كسر دنا غنى","b":"وإني وذو الثنيا وأني اجملا","ref":["ibraz:51","siraj:79"]},{"id":"shatibiyya:999","bookId":"shatibiyya","type":"bayt","num":999,"seq":999,"chapter":"سورة ص","title":"البيت 999","page":"ج1 ص79","text":"وضم فواق شاع خالصة أضف ... له الرحب وحد عبدنا قبل دخللا","a":"وضم فواق شاع خالصة أضف","b":"له الرحب وحد عبدنا قبل دخللا","ref":["ibraz:1036","siraj:80"]},{"id":"shatibiyya:1000","bookId":"shatibiyya","type":"bayt","num":1000,"seq":1000,"chapter":"سورة ص","title":"البيت 1000","page":"ج1 ص79","text":"وفي يوعدون دم حلا وبقاف دم ... وثقل غساقا معا شائد علا","a":"وفي يوعدون دم حلا وبقاف دم","b":"وثقل غساقا معا شائد علا","ref":["ibraz:1037","siraj:80"]},{"id":"shatibiyya:1001","bookId":"shatibiyya","type":"bayt","num":1001,"seq":1001,"chapter":"سورة ص","title":"البيت 1001","page":"ج1 ص79","text":"وآخر للبصري بضم وقصره ... ووصل اتخذناهم حلا شرعه ولا","a":"وآخر للبصري بضم وقصره","b":"ووصل اتخذناهم حلا شرعه ولا","ref":["ibraz:1038","siraj:80"]},{"id":"shatibiyya:1002","bookId":"shatibiyya","type":"bayt","num":1002,"seq":1002,"chapter":"سورة ص","title":"البيت 1002","page":"ج1 ص79","text":"وفالحق فى نصر وخذ ياء لي معا ... وإني وبعدي مسني لعنتي إلى","a":"وفالحق فى نصر وخذ ياء لي معا","b":"وإني وبعدي مسني لعنتي إلى","ref":["ibraz:1039","siraj:80"]},{"id":"shatibiyya:1003","bookId":"shatibiyya","type":"bayt","num":1003,"seq":1003,"chapter":"سورة الزمر","title":"البيت 1003","page":"ج1 ص79","text":"أمن خف حرمي فشا مد سالما ... مع الكسر حق عبده اجمع شمردلا","a":"أمن خف حرمي فشا مد سالما","b":"مع الكسر حق عبده اجمع شمردلا","ref":["ibraz:1040","siraj:81"]},{"id":"shatibiyya:1004","bookId":"shatibiyya","type":"bayt","num":1004,"seq":1004,"chapter":"سورة الزمر","title":"البيت 1004","page":"ج1 ص79","text":"وقل كاشفات ممسكات منونا ... ورحمته مع ضره النصب حملا","a":"وقل كاشفات ممسكات منونا","b":"ورحمته مع ضره النصب حملا","ref":["ibraz:1041","siraj:81"]},{"id":"shatibiyya:1005","bookId":"shatibiyya","type":"bayt","num":1005,"seq":1005,"chapter":"سورة الزمر","title":"البيت 1005","page":"ج1 ص80","text":"وضم قضى واكسر وحرك وبعد رف ... ع شاف مفازات اجمعوا شاع صندلا","a":"وضم قضى واكسر وحرك وبعد رف","b":"ع شاف مفازات اجمعوا شاع صندلا","ref":["ibraz:1042","siraj:81"]},{"id":"shatibiyya:1006","bookId":"shatibiyya","type":"bayt","num":1006,"seq":1006,"chapter":"سورة الزمر","title":"البيت 1006","page":"ج1 ص80","text":"وزد تأمروني النون كهفا وعم خف ... فه فتحت خفف وفي النبإ العلا","a":"وزد تأمروني النون كهفا وعم خف","b":"فه فتحت خفف وفي النبإ العلا","ref":["ibraz:1043","siraj:81"]},{"id":"shatibiyya:1007","bookId":"shatibiyya","type":"bayt","num":1007,"seq":1007,"chapter":"سورة الزمر","title":"البيت 1007","page":"ج1 ص80","text":"لكوف وخذ يا تأمروني أرادني ... وإني معا مع يا عبادي فحصلا","a":"لكوف وخذ يا تأمروني أرادني","b":"وإني معا مع يا عبادي فحصلا","ref":["ibraz:1044","siraj:81"]},{"id":"shatibiyya:1008","bookId":"shatibiyya","type":"bayt","num":1008,"seq":1008,"chapter":"سورة المؤمن","title":"البيت 1008","page":"ج1 ص80","text":"ويدعون خاطب إذ لوى هاء منهم ... بكاف كفى أو أن زد الهمز ثملا","a":"ويدعون خاطب إذ لوى هاء منهم","b":"بكاف كفى أو أن زد الهمز ثملا","ref":["ibraz:1045","siraj:82"]},{"id":"shatibiyya:1009","bookId":"shatibiyya","type":"bayt","num":1009,"seq":1009,"chapter":"سورة المؤمن","title":"البيت 1009","page":"ج1 ص80","text":"وسكن لهم واضمم بيظهر واكسرن ... ورفع الفساد انصب إلى عاقل حلا","a":"وسكن لهم واضمم بيظهر واكسرن","b":"ورفع الفساد انصب إلى عاقل حلا","ref":["ibraz:1046","siraj:82"]},{"id":"shatibiyya:1010","bookId":"shatibiyya","type":"bayt","num":1010,"seq":1010,"chapter":"سورة المؤمن","title":"البيت 1010","page":"ج1 ص80","text":"فأطلع ارفع غير حفص وقلب نو ... ونوا من حميد أدخلوا نفر صلا","a":"فأطلع ارفع غير حفص وقلب نو","b":"ونوا من حميد أدخلوا نفر صلا","ref":["ibraz:1047","siraj:82"]},{"id":"shatibiyya:1011","bookId":"shatibiyya","type":"bayt","num":1011,"seq":1011,"chapter":"سورة المؤمن","title":"البيت 1011","page":"ج1 ص80","text":"على الوصل واضمم كسره يتذكرو ... ن كهف سما واحفظ مضافاتها العلا","a":"على الوصل واضمم كسره يتذكرو","b":"ن كهف سما واحفظ مضافاتها العلا","ref":["ibraz:1048","siraj:82"]},{"id":"shatibiyya:1012","bookId":"shatibiyya","type":"bayt","num":1012,"seq":1012,"chapter":"سورة المؤمن","title":"البيت 1012","page":"ج1 ص80","text":"ذروني وادعوني وإني ثلاثة ... لعلي وفي مالي وأمري مع إلى","a":"ذروني وادعوني وإني ثلاثة","b":"لعلي وفي مالي وأمري مع إلى","ref":["ibraz:1049","siraj:82"]},{"id":"shatibiyya:1013","bookId":"shatibiyya","type":"bayt","num":1013,"seq":1013,"chapter":"سورة فصلت","title":"البيت 1013","page":"ج1 ص80","text":"وإسكان نحسات به كسره ذكا ... وقول مميل السين لليث أخملا","a":"وإسكان نحسات به كسره ذكا","b":"وقول مميل السين لليث أخملا","ref":["ibraz:1050","siraj:83"]},{"id":"shatibiyya:1014","bookId":"shatibiyya","type":"bayt","num":1014,"seq":1014,"chapter":"سورة فصلت","title":"البيت 1014","page":"ج1 ص80","text":"ونحشر ياء ضم مع فتح ضمه ... وأعداء خذ والجمع عم عقنقلا","a":"ونحشر ياء ضم مع فتح ضمه","b":"وأعداء خذ والجمع عم عقنقلا","ref":["ibraz:1051","siraj:83"]},{"id":"shatibiyya:1015","bookId":"shatibiyya","type":"bayt","num":1015,"seq":1015,"chapter":"سورة فصلت","title":"البيت 1015","page":"ج1 ص80","text":"لدى ثمرات ثم يا شركائى ال ... مضاف ويا ربي به الخلف بجلا","a":"لدى ثمرات ثم يا شركائى ال","b":"مضاف ويا ربي به الخلف بجلا","ref":["ibraz:1052","siraj:83"]},{"id":"shatibiyya:1016","bookId":"shatibiyya","type":"bayt","num":1016,"seq":1016,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1016","page":"ج1 ص81","text":"ويوحى بفتح الحاء دان ويفعلو ... ن غير صحاب يعلم ارفع كما اعتلا","a":"ويوحى بفتح الحاء دان ويفعلو","b":"ن غير صحاب يعلم ارفع كما اعتلا","ref":["ibraz:1053","siraj:84"]},{"id":"shatibiyya:1017","bookId":"shatibiyya","type":"bayt","num":1017,"seq":1017,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1017","page":"ج1 ص81","text":"بما كسبت لا فاء عم كبير في ... كبائر فيها ثم في النجم شمللا","a":"بما كسبت لا فاء عم كبير في","b":"كبائر فيها ثم في النجم شمللا","ref":["ibraz:1054","siraj:84"]},{"id":"shatibiyya:1018","bookId":"shatibiyya","type":"bayt","num":1018,"seq":1018,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1018","page":"ج1 ص81","text":"ويرسل فارفع مع فيوحي مسكنا ... أتانا وأن كنتم بكسر شذا العلا","a":"ويرسل فارفع مع فيوحي مسكنا","b":"أتانا وأن كنتم بكسر شذا العلا","ref":["ibraz:1055","siraj:84"]},{"id":"shatibiyya:1019","bookId":"shatibiyya","type":"bayt","num":1019,"seq":1019,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1019","page":"ج1 ص81","text":"وينشأ في ضم وثقل صحابه ... عباد برفع الدال في عند غلغلا","a":"وينشأ في ضم وثقل صحابه","b":"عباد برفع الدال في عند غلغلا","ref":["ibraz:1056","siraj:84"]},{"id":"shatibiyya:1020","bookId":"shatibiyya","type":"bayt","num":1020,"seq":1020,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1020","page":"ج1 ص81","text":"وسكن وزد همزا كواو أؤشهدوا ... أمينا وفيه المد بالخلف بللا","a":"وسكن وزد همزا كواو أؤشهدوا","b":"أمينا وفيه المد بالخلف بللا","ref":["ibraz:1057","siraj:84"]},{"id":"shatibiyya:1021","bookId":"shatibiyya","type":"bayt","num":1021,"seq":1021,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1021","page":"ج1 ص81","text":"وقل قال عن كفؤ وسقفا بضمه ... وتحريكه بالضم ذكر أنبلا","a":"وقل قال عن كفؤ وسقفا بضمه","b":"وتحريكه بالضم ذكر أنبلا","ref":["ibraz:1058","siraj:84"]},{"id":"shatibiyya:1022","bookId":"shatibiyya","type":"bayt","num":1022,"seq":1022,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1022","page":"ج1 ص81","text":"وحكم صحاب قصر همزة جاءنا ... وأسورة سكن وبالقصر عدلا","a":"وحكم صحاب قصر همزة جاءنا","b":"وأسورة سكن وبالقصر عدلا","ref":["ibraz:50","siraj:84"]},{"id":"shatibiyya:1023","bookId":"shatibiyya","type":"bayt","num":1023,"seq":1023,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1023","page":"ج1 ص81","text":"وفي سلفا ضما شريف وصاده ... يصدون كسر الضم فى حق نهشلا","a":"وفي سلفا ضما شريف وصاده","b":"يصدون كسر الضم فى حق نهشلا","ref":["ibraz:1060","siraj:84"]},{"id":"shatibiyya:1024","bookId":"shatibiyya","type":"bayt","num":1024,"seq":1024,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1024","page":"ج1 ص81","text":"ءآلهة كوف يحقق ثانيا ... وقل ألفا للكل ثالثا ابدلا","a":"ءآلهة كوف يحقق ثانيا","b":"وقل ألفا للكل ثالثا ابدلا","ref":["ibraz:1061","siraj:84"]},{"id":"shatibiyya:1025","bookId":"shatibiyya","type":"bayt","num":1025,"seq":1025,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1025","page":"ج1 ص81","text":"وفي تشتهيه تشتهي حق صحبة ... وفي ترجعون الغيب شايع دخللا","a":"وفي تشتهيه تشتهي حق صحبة","b":"وفي ترجعون الغيب شايع دخللا","ref":["ibraz:1062","siraj:84"]},{"id":"shatibiyya:1026","bookId":"shatibiyya","type":"bayt","num":1026,"seq":1026,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1026","page":"ج1 ص81","text":"وفي قيله اكسر واكسر الضم بعد في ... نصير وخاطب يعلمون كما انجلا","a":"وفي قيله اكسر واكسر الضم بعد في","b":"نصير وخاطب يعلمون كما انجلا","ref":["ibraz:1063","siraj:84"]},{"id":"shatibiyya:1027","bookId":"shatibiyya","type":"bayt","num":1027,"seq":1027,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1027","page":"ج1 ص81","text":"بتحتي عبادي اليا ويغلي دنا علا ... ورب السموات اخفضوا الرفع ثملا","a":"بتحتي عبادي اليا ويغلي دنا علا","b":"ورب السموات اخفضوا الرفع ثملا","ref":["ibraz:1064","siraj:84"]},{"id":"shatibiyya:1028","bookId":"shatibiyya","type":"bayt","num":1028,"seq":1028,"chapter":"سورة الشورى والزخرف والدخان","title":"البيت 1028","page":"ج1 ص81","text":"وضم اعتلوه اكسر غنى إنك افتحوا ... ربيعا وقل إني ولي الياء حملا","a":"وضم اعتلوه اكسر غنى إنك افتحوا","b":"ربيعا وقل إني ولي الياء حملا","ref":["ibraz:1065","siraj:84"]},{"id":"shatibiyya:1029","bookId":"shatibiyya","type":"bayt","num":1029,"seq":1029,"chapter":"سورة الشريعة والأحقاف","title":"البيت 1029","page":"ج1 ص82","text":"معا رفع آيات على كسره شفا ... وإن وفي أضمر بتوكيد اولا","a":"معا رفع آيات على كسره شفا","b":"وإن وفي أضمر بتوكيد اولا","ref":["ibraz:1067","siraj:85"]},{"id":"shatibiyya:1030","bookId":"shatibiyya","type":"bayt","num":1030,"seq":1030,"chapter":"سورة الشريعة والأحقاف","title":"البيت 1030","page":"ج1 ص82","text":"لنجزي يا نص سما وغشاوة ... به الفتح والإسكان والقصر شملا","a":"لنجزي يا نص سما وغشاوة","b":"به الفتح والإسكان والقصر شملا","ref":["ibraz:1068","siraj:85"]},{"id":"shatibiyya:1031","bookId":"shatibiyya","type":"bayt","num":1031,"seq":1031,"chapter":"سورة الشريعة والأحقاف","title":"البيت 1031","page":"ج1 ص82","text":"ووالساعة ارفع غير حمزة حسنا ال ... محسن إحسانا لكوف تحولا","a":"ووالساعة ارفع غير حمزة حسنا ال","b":"محسن إحسانا لكوف تحولا","ref":["ibraz:1069","siraj:85"]},{"id":"shatibiyya:1032","bookId":"shatibiyya","type":"bayt","num":1032,"seq":1032,"chapter":"سورة الشريعة والأحقاف","title":"البيت 1032","page":"ج1 ص82","text":"وغير صحاب أحسن ارفع وقبله ... وبعد بياء ضم فعلان وصلا","a":"وغير صحاب أحسن ارفع وقبله","b":"وبعد بياء ضم فعلان وصلا","ref":["ibraz:1070","siraj:85"]},{"id":"shatibiyya:1033","bookId":"shatibiyya","type":"bayt","num":1033,"seq":1033,"chapter":"سورة الشريعة والأحقاف","title":"البيت 1033","page":"ج1 ص82","text":"وقل عن هشام أدغموا تعدانني ... نوفيهم باليا له حق نهشلا","a":"وقل عن هشام أدغموا تعدانني","b":"نوفيهم باليا له حق نهشلا","ref":["ibraz:1071","siraj:85"]},{"id":"shatibiyya:1034","bookId":"shatibiyya","type":"bayt","num":1034,"seq":1034,"chapter":"سورة الشريعة والأحقاف","title":"البيت 1034","page":"ج1 ص82","text":"وقل لا ترى بالغيب واضمم وبعده ... مساكنهم بالرفع فاشيه نولا","a":"وقل لا ترى بالغيب واضمم وبعده","b":"مساكنهم بالرفع فاشيه نولا","ref":["ibraz:1072","siraj:85"]},{"id":"shatibiyya:1035","bookId":"shatibiyya","type":"bayt","num":1035,"seq":1035,"chapter":"سورة الشريعة والأحقاف","title":"البيت 1035","page":"ج1 ص82","text":"وياء ولكني ويا تعدانني ... وإني وأوزعني بها خلف من بلا","a":"وياء ولكني ويا تعدانني","b":"وإني وأوزعني بها خلف من بلا","ref":["ibraz:1073","siraj:85"]},{"id":"shatibiyya:1036","bookId":"shatibiyya","type":"bayt","num":1036,"seq":1036,"chapter":"سورة الرحمن عز وجل","title":"البيت 1036","page":"ج1 ص82","text":"وبالضم واقصر واكسر التاء قاتلوا ... على حجة والقصر في آسن دلا","a":"وبالضم واقصر واكسر التاء قاتلوا","b":"على حجة والقصر في آسن دلا","ref":["ibraz:52","siraj:86"]},{"id":"shatibiyya:1037","bookId":"shatibiyya","type":"bayt","num":1037,"seq":1037,"chapter":"سورة الرحمن عز وجل","title":"البيت 1037","page":"ج1 ص82","text":"وفي آنفا خلف هدى وبضمهم ... وكسر وتحريك وأملي حصلا","a":"وفي آنفا خلف هدى وبضمهم","b":"وكسر وتحريك وأملي حصلا","ref":["ibraz:1076","siraj:86"]},{"id":"shatibiyya:1038","bookId":"shatibiyya","type":"bayt","num":1038,"seq":1038,"chapter":"سورة الرحمن عز وجل","title":"البيت 1038","page":"ج1 ص82","text":"وأسرارهم فاكسر صحابا ونبلون ... نكم نعلم اليا صف ونبلو واقبلا","a":"وأسرارهم فاكسر صحابا ونبلون","b":"نكم نعلم اليا صف ونبلو واقبلا","ref":["ibraz:1077","siraj:86"]},{"id":"shatibiyya:1039","bookId":"shatibiyya","type":"bayt","num":1039,"seq":1039,"chapter":"سورة الرحمن عز وجل","title":"البيت 1039","page":"ج1 ص82","text":"وفي يؤمنوا حق وبعد ثلاثة ... وفي ياء يؤتيه غدير تسلسلا","a":"وفي يؤمنوا حق وبعد ثلاثة","b":"وفي ياء يؤتيه غدير تسلسلا","ref":["ibraz:1078","siraj:86"]},{"id":"shatibiyya:1040","bookId":"shatibiyya","type":"bayt","num":1040,"seq":1040,"chapter":"سورة الرحمن عز وجل","title":"البيت 1040","page":"ج1 ص82","text":"وبالضم ضرا شاع والكسر عنهما ... بلام كلام الله والقصر وكلا","a":"وبالضم ضرا شاع والكسر عنهما","b":"بلام كلام الله والقصر وكلا","ref":["ibraz:1079","siraj:86"]},{"id":"shatibiyya:1041","bookId":"shatibiyya","type":"bayt","num":1041,"seq":1041,"chapter":"سورة الرحمن عز وجل","title":"البيت 1041","page":"ج1 ص83","text":"بما يعملون حج حرك شطأه ... دعا ماجد واقصر فآزره ملا","a":"بما يعملون حج حرك شطأه","b":"دعا ماجد واقصر فآزره ملا","ref":["ibraz:1080","siraj:86"]},{"id":"shatibiyya:1042","bookId":"shatibiyya","type":"bayt","num":1042,"seq":1042,"chapter":"سورة الرحمن عز وجل","title":"البيت 1042","page":"ج1 ص83","text":"وفي يعملون دم يقول بياء إذ ... صفا واكسروا أدبار إذ فاز دخللا","a":"وفي يعملون دم يقول بياء إذ","b":"صفا واكسروا أدبار إذ فاز دخللا","ref":["ibraz:1081","siraj:86"]},{"id":"shatibiyya:1043","bookId":"shatibiyya","type":"bayt","num":1043,"seq":1043,"chapter":"سورة الرحمن عز وجل","title":"البيت 1043","page":"ج1 ص83","text":"وباليا ينادي قف دليلا بخلفه ... وقل مثل ما بالرفع شمم صندلا","a":"وباليا ينادي قف دليلا بخلفه","b":"وقل مثل ما بالرفع شمم صندلا","ref":["ibraz:1082","siraj:86"]},{"id":"shatibiyya:1044","bookId":"shatibiyya","type":"bayt","num":1044,"seq":1044,"chapter":"سورة الرحمن عز وجل","title":"البيت 1044","page":"ج1 ص83","text":"وفي الصعقة اقصر مسكن العين راويا ... وقوم بخفض الميم شرف حملا","a":"وفي الصعقة اقصر مسكن العين راويا","b":"وقوم بخفض الميم شرف حملا","ref":["ibraz:1083","siraj:86"]},{"id":"shatibiyya:1045","bookId":"shatibiyya","type":"bayt","num":1045,"seq":1045,"chapter":"سورة الرحمن عز وجل","title":"البيت 1045","page":"ج1 ص83","text":"وبصر وأتبعنا بواتبعت وما ... ألتنا اكسروا دنيا وإن افتحوا الجلا","a":"وبصر وأتبعنا بواتبعت وما","b":"ألتنا اكسروا دنيا وإن افتحوا الجلا","ref":["siraj:86"]},{"id":"shatibiyya:1046","bookId":"shatibiyya","type":"bayt","num":1046,"seq":1046,"chapter":"سورة الرحمن عز وجل","title":"البيت 1046","page":"ج1 ص83","text":"رضا يصعقون اضممه كم نص والمسي ... طرون لسان عاب بالخلف زملا","a":"رضا يصعقون اضممه كم نص والمسي","b":"طرون لسان عاب بالخلف زملا","ref":["ibraz:1085","siraj:86"]},{"id":"shatibiyya:1047","bookId":"shatibiyya","type":"bayt","num":1047,"seq":1047,"chapter":"سورة الرحمن عز وجل","title":"البيت 1047","page":"ج1 ص83","text":"وصاد كزاي قام بالخلف ضبعه ... وكذب يرويه هشام مثقلا","a":"وصاد كزاي قام بالخلف ضبعه","b":"وكذب يرويه هشام مثقلا","ref":["ibraz:1086","siraj:86"]},{"id":"shatibiyya:1048","bookId":"shatibiyya","type":"bayt","num":1048,"seq":1048,"chapter":"سورة الرحمن عز وجل","title":"البيت 1048","page":"ج1 ص83","text":"تمارونه تمرونه وافتحوا شذا ... مناءة للمكي زد الهمز وأحفلا","a":"تمارونه تمرونه وافتحوا شذا","b":"مناءة للمكي زد الهمز وأحفلا","ref":["ibraz:52"]},{"id":"shatibiyya:1049","bookId":"shatibiyya","type":"bayt","num":1049,"seq":1049,"chapter":"سورة الرحمن عز وجل","title":"البيت 1049","page":"ج1 ص83","text":"ويهمز ضيزى خشعا خاشعا شفا ... حميدا وخاطب يعلمون فطب كلا","a":"ويهمز ضيزى خشعا خاشعا شفا","b":"حميدا وخاطب يعلمون فطب كلا","ref":["ibraz:1088","siraj:86"]},{"id":"shatibiyya:1050","bookId":"shatibiyya","type":"bayt","num":1050,"seq":1050,"chapter":"سورة الرحمن عز وجل","title":"البيت 1050","page":"ج1 ص83","text":"ووالحب ذو الريحان رفع ثلاثها ... بنصب كفى والنون بالخفض شكلا","a":"ووالحب ذو الريحان رفع ثلاثها","b":"بنصب كفى والنون بالخفض شكلا","ref":["ibraz:1089","siraj:87"]},{"id":"shatibiyya:1051","bookId":"shatibiyya","type":"bayt","num":1051,"seq":1051,"chapter":"سورة الرحمن عز وجل","title":"البيت 1051","page":"ج1 ص83","text":"ويخرج فاضمم وافتح الضم إذ حمى ... وفى المنشآت الشين بالكسر فاحملا","a":"ويخرج فاضمم وافتح الضم إذ حمى","b":"وفى المنشآت الشين بالكسر فاحملا","ref":["ibraz:1090","siraj:87"]},{"id":"shatibiyya:1052","bookId":"shatibiyya","type":"bayt","num":1052,"seq":1052,"chapter":"سورة الرحمن عز وجل","title":"البيت 1052","page":"ج1 ص83","text":"صحيحا بخلف نفرغ الياء شائع ... شواظ بكسر الضم مكيهم جلا","a":"صحيحا بخلف نفرغ الياء شائع","b":"شواظ بكسر الضم مكيهم جلا","ref":["ibraz:1091","siraj:87"]},{"id":"shatibiyya:1053","bookId":"shatibiyya","type":"bayt","num":1053,"seq":1053,"chapter":"سورة الرحمن عز وجل","title":"البيت 1053","page":"ج1 ص84","text":"ورفع نحاس جر حق وكسر مي ... م يطمث في الاولى ضم تهدى وتقبلا","a":"ورفع نحاس جر حق وكسر مي","b":"م يطمث في الاولى ضم تهدى وتقبلا","ref":["ibraz:1092","siraj:87"]},{"id":"shatibiyya:1054","bookId":"shatibiyya","type":"bayt","num":1054,"seq":1054,"chapter":"سورة الرحمن عز وجل","title":"البيت 1054","page":"ج1 ص84","text":"وقال به الليث في الثان وحده ... شيوخ ونص الليث بالضم الاولا","a":"وقال به الليث في الثان وحده","b":"شيوخ ونص الليث بالضم الاولا"},{"id":"shatibiyya:1055","bookId":"shatibiyya","type":"bayt","num":1055,"seq":1055,"chapter":"سورة الرحمن عز وجل","title":"البيت 1055","page":"ج1 ص84","text":"وقول الكسائي ضم أيهما تشا ... وجيه وبعض المقرئين به تلا","a":"وقول الكسائي ضم أيهما تشا","b":"وجيه وبعض المقرئين به تلا","ref":["ibraz:1094","siraj:87"]},{"id":"shatibiyya:1056","bookId":"shatibiyya","type":"bayt","num":1056,"seq":1056,"chapter":"سورة الرحمن عز وجل","title":"البيت 1056","page":"ج1 ص84","text":"وآخرها يا ذي الجلال ابن عامر ... بواو ورسم الشام فيه تمثلا","a":"وآخرها يا ذي الجلال ابن عامر","b":"بواو ورسم الشام فيه تمثلا","ref":["ibraz:1095","siraj:87"]},{"id":"shatibiyya:1057","bookId":"shatibiyya","type":"bayt","num":1057,"seq":1057,"chapter":"سورة الواقعة والحديد","title":"البيت 1057","page":"ج1 ص84","text":"وحور وعين خفض رفعهما شفا ... وعربا سكون الضم صحح فاعتلى","a":"وحور وعين خفض رفعهما شفا","b":"وعربا سكون الضم صحح فاعتلى","ref":["ibraz:1096","siraj:88"]},{"id":"shatibiyya:1058","bookId":"shatibiyya","type":"bayt","num":1058,"seq":1058,"chapter":"سورة الواقعة والحديد","title":"البيت 1058","page":"ج1 ص84","text":"وخف قدرنا دار وانضم شرب في ... ندى الصفو واستفهام إنا صفا ولا","a":"وخف قدرنا دار وانضم شرب في","b":"ندى الصفو واستفهام إنا صفا ولا","ref":["ibraz:1097","siraj:88"]},{"id":"shatibiyya:1059","bookId":"shatibiyya","type":"bayt","num":1059,"seq":1059,"chapter":"سورة الواقعة والحديد","title":"البيت 1059","page":"ج1 ص84","text":"بموقع بالإسكان والقصر شائع ... وقد أخذ اضمم واكسر الخاء حولا","a":"بموقع بالإسكان والقصر شائع","b":"وقد أخذ اضمم واكسر الخاء حولا","ref":["ibraz:1098","siraj:88"]},{"id":"shatibiyya:1060","bookId":"shatibiyya","type":"bayt","num":1060,"seq":1060,"chapter":"سورة الواقعة والحديد","title":"البيت 1060","page":"ج1 ص84","text":"وميثاقكم عنه وكل كفى وأن ... ظرونا بقطع واكسر الضم فيصلا","a":"وميثاقكم عنه وكل كفى وأن","b":"ظرونا بقطع واكسر الضم فيصلا","ref":["ibraz:1099","siraj:88"]},{"id":"shatibiyya:1061","bookId":"shatibiyya","type":"bayt","num":1061,"seq":1061,"chapter":"سورة الواقعة والحديد","title":"البيت 1061","page":"ج1 ص84","text":"ويؤخذ غير الشام ما نزل الخفي ... ف إذ عز والصادان من بعد دم صلا","a":"ويؤخذ غير الشام ما نزل الخفي","b":"ف إذ عز والصادان من بعد دم صلا","ref":["ibraz:1100","siraj:88"]},{"id":"shatibiyya:1062","bookId":"shatibiyya","type":"bayt","num":1062,"seq":1062,"chapter":"سورة الواقعة والحديد","title":"البيت 1062","page":"ج1 ص84","text":"وآتاكم فاقصر حفيظا وقل هو ال ... غني هو احذف عم وصلا موصلا","a":"وآتاكم فاقصر حفيظا وقل هو ال","b":"غني هو احذف عم وصلا موصلا","ref":["ibraz:1101","siraj:88"]},{"id":"shatibiyya:1063","bookId":"shatibiyya","type":"bayt","num":1063,"seq":1063,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1063","page":"ج1 ص84","text":"وفي يتناجون اقصر النون ساكنا ... وقدمه واضمم جيمه فتكملا","a":"وفي يتناجون اقصر النون ساكنا","b":"وقدمه واضمم جيمه فتكملا","ref":["ibraz:1103","siraj:89"]},{"id":"shatibiyya:1064","bookId":"shatibiyya","type":"bayt","num":1064,"seq":1064,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1064","page":"ج1 ص84","text":"وكسر انشزوا فاضمم معا صفو خلفه ... علا عم وامدد في المجالس نوفلا","a":"وكسر انشزوا فاضمم معا صفو خلفه","b":"علا عم وامدد في المجالس نوفلا","ref":["ibraz:1104","siraj:89"]},{"id":"shatibiyya:1065","bookId":"shatibiyya","type":"bayt","num":1065,"seq":1065,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1065","page":"ج1 ص85","text":"وفي رسلي اليا يخربون الثقيل حز ... ومع دولة أنث يكون بخلف لا","a":"وفي رسلي اليا يخربون الثقيل حز","b":"ومع دولة أنث يكون بخلف لا","ref":["ibraz:1105","siraj:89"]},{"id":"shatibiyya:1066","bookId":"shatibiyya","type":"bayt","num":1066,"seq":1066,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1066","page":"ج1 ص85","text":"وكسر جدار ضم والفتح واقصروا ... ذوي أسوة إني بياء توصلا","a":"وكسر جدار ضم والفتح واقصروا","b":"ذوي أسوة إني بياء توصلا","ref":["ibraz:1106","siraj:89"]},{"id":"shatibiyya:1067","bookId":"shatibiyya","type":"bayt","num":1067,"seq":1067,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1067","page":"ج1 ص85","text":"ويفصل فتح الضم نص وصاده ... بكسر ثوى والثقل شافيه كملا","a":"ويفصل فتح الضم نص وصاده","b":"بكسر ثوى والثقل شافيه كملا","ref":["ibraz:1107","siraj:89"]},{"id":"shatibiyya:1068","bookId":"shatibiyya","type":"bayt","num":1068,"seq":1068,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1068","page":"ج1 ص85","text":"وفى تمسكوا ثقل حلا ومتم لا ... تنونه واخفض نوره عن شذا دلا","a":"وفى تمسكوا ثقل حلا ومتم لا","b":"تنونه واخفض نوره عن شذا دلا","ref":["ibraz:1108","siraj:89"]},{"id":"shatibiyya:1069","bookId":"shatibiyya","type":"bayt","num":1069,"seq":1069,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1069","page":"ج1 ص85","text":"ولله زد لاما وأنصار نونا ... سما وتنجيكم عن الشام ثقلا","a":"ولله زد لاما وأنصار نونا","b":"سما وتنجيكم عن الشام ثقلا","ref":["ibraz:1109","siraj:89"]},{"id":"shatibiyya:1070","bookId":"shatibiyya","type":"bayt","num":1070,"seq":1070,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1070","page":"ج1 ص85","text":"وبعدي وأنصاري بياء إضافة ... وخشب سكون الضم زاد رضا حلا","a":"وبعدي وأنصاري بياء إضافة","b":"وخشب سكون الضم زاد رضا حلا","ref":["ibraz:1110","siraj:89"]},{"id":"shatibiyya:1071","bookId":"shatibiyya","type":"bayt","num":1071,"seq":1071,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1071","page":"ج1 ص85","text":"وخف لووا إلفا بما يعملون صف ... أكون بواو وانصبوا الجزم حفلا","a":"وخف لووا إلفا بما يعملون صف","b":"أكون بواو وانصبوا الجزم حفلا","ref":["ibraz:1111"]},{"id":"shatibiyya:1072","bookId":"shatibiyya","type":"bayt","num":1072,"seq":1072,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1072","page":"ج1 ص85","text":"وبالغ لا تنوين مع خفض أمره ... لحفص وبالتخفيف عرف رفلا","a":"وبالغ لا تنوين مع خفض أمره","b":"لحفص وبالتخفيف عرف رفلا","ref":["ibraz:1112","siraj:89"]},{"id":"shatibiyya:1073","bookId":"shatibiyya","type":"bayt","num":1073,"seq":1073,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1073","page":"ج1 ص85","text":"وضم نصوحا شعبة من تفوت ... على القصر والتشديد شق تهللا","a":"وضم نصوحا شعبة من تفوت","b":"على القصر والتشديد شق تهللا","ref":["ibraz:1113","siraj:89"]},{"id":"shatibiyya:1074","bookId":"shatibiyya","type":"bayt","num":1074,"seq":1074,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1074","page":"ج1 ص85","text":"وآمنتمو في الهمزتين أصوله ... وفي الوصل الاولى قنبل واوا ابدلا","a":"وآمنتمو في الهمزتين أصوله","b":"وفي الوصل الاولى قنبل واوا ابدلا"},{"id":"shatibiyya:1075","bookId":"shatibiyya","type":"bayt","num":1075,"seq":1075,"chapter":"ومن سورة المجادلة إلى سورة (ن","title":"البيت 1075","page":"ج1 ص85","text":"فسحقا سكونا ضم مع غيب يعلمو ... ن من رض معي باليا وأهلكني انجلا","a":"فسحقا سكونا ضم مع غيب يعلمو","b":"ن من رض معي باليا وأهلكني انجلا","ref":["ibraz:1115","siraj:89"]},{"id":"shatibiyya:1076","bookId":"shatibiyya","type":"bayt","num":1076,"seq":1076,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1076","page":"ج1 ص85","text":"وضمهم في يزلقونك خالد ... ومن قبله فاكسر وحرك روى حلا","a":"وضمهم في يزلقونك خالد","b":"ومن قبله فاكسر وحرك روى حلا","ref":["ibraz:67","siraj:90"]},{"id":"shatibiyya:1077","bookId":"shatibiyya","type":"bayt","num":1077,"seq":1077,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1077","page":"ج1 ص85","text":"ويخفى شفاء ماليه ماهيه فصل ... وسلطانيه من دون هاء فتوصلا","a":"ويخفى شفاء ماليه ماهيه فصل","b":"وسلطانيه من دون هاء فتوصلا","ref":["ibraz:1117","siraj:90"]},{"id":"shatibiyya:1078","bookId":"shatibiyya","type":"bayt","num":1078,"seq":1078,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1078","page":"ج1 ص86","text":"ويذكرون يؤمنون مقاله ... بخلف له داع ويعرج رتلا","a":"ويذكرون يؤمنون مقاله","b":"بخلف له داع ويعرج رتلا","ref":["ibraz:1118","siraj:90"]},{"id":"shatibiyya:1079","bookId":"shatibiyya","type":"bayt","num":1079,"seq":1079,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1079","page":"ج1 ص86","text":"وسال بهمز غصن دان وغيرهم ... من الهمز أو من واو او ياء ابدلا","a":"وسال بهمز غصن دان وغيرهم","b":"من الهمز أو من واو او ياء ابدلا","ref":["ibraz:1119","siraj:90"]},{"id":"shatibiyya:1080","bookId":"shatibiyya","type":"bayt","num":1080,"seq":1080,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1080","page":"ج1 ص86","text":"ونزاعة فارفع سوى حفصهم وقل ... شهاداتهم بالجمع حفص تقبلا","a":"ونزاعة فارفع سوى حفصهم وقل","b":"شهاداتهم بالجمع حفص تقبلا","ref":["ibraz:1120","siraj:90"]},{"id":"shatibiyya:1081","bookId":"shatibiyya","type":"bayt","num":1081,"seq":1081,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1081","page":"ج1 ص86","text":"إلى نصب فاضمم وحرك به علا ... كرام وقل ودا به الضم أعملا","a":"إلى نصب فاضمم وحرك به علا","b":"كرام وقل ودا به الضم أعملا","ref":["ibraz:806","siraj:90"]},{"id":"shatibiyya:1082","bookId":"shatibiyya","type":"bayt","num":1082,"seq":1082,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1082","page":"ج1 ص86","text":"دعائي وإني ثم بيتي مضافها ... مع الواو فافتح إن كم شرفا علا","a":"دعائي وإني ثم بيتي مضافها","b":"مع الواو فافتح إن كم شرفا علا","ref":["ibraz:1122","siraj:90"]},{"id":"shatibiyya:1083","bookId":"shatibiyya","type":"bayt","num":1083,"seq":1083,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1083","page":"ج1 ص86","text":"وعن كلهم أن المساجد فتحه ... وفي أنه لما بكسر صوى العلا","a":"وعن كلهم أن المساجد فتحه","b":"وفي أنه لما بكسر صوى العلا","ref":["ibraz:1123","siraj:90"]},{"id":"shatibiyya:1084","bookId":"shatibiyya","type":"bayt","num":1084,"seq":1084,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1084","page":"ج1 ص86","text":"ونسلكه يا كوف وفي قال إنما ... هنا قل فشا نصا وطاب تقبلا","a":"ونسلكه يا كوف وفي قال إنما","b":"هنا قل فشا نصا وطاب تقبلا","ref":["ibraz:1124","siraj:90"]},{"id":"shatibiyya:1085","bookId":"shatibiyya","type":"bayt","num":1085,"seq":1085,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1085","page":"ج1 ص86","text":"وقل لبدا في كسره الضم لازم ... بخلف ويا ربي مضاف تجملا","a":"وقل لبدا في كسره الضم لازم","b":"بخلف ويا ربي مضاف تجملا","ref":["ibraz:1125","siraj:90"]},{"id":"shatibiyya:1086","bookId":"shatibiyya","type":"bayt","num":1086,"seq":1086,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1086","page":"ج1 ص86","text":"ووطئا وطاء فاكسروه كما حكوا ... ورب بخفض الرفع صحبته كلا","a":"ووطئا وطاء فاكسروه كما حكوا","b":"ورب بخفض الرفع صحبته كلا","ref":["ibraz:1126"]},{"id":"shatibiyya:1087","bookId":"shatibiyya","type":"bayt","num":1087,"seq":1087,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1087","page":"ج1 ص86","text":"وثا ثلثه فانصب وفا نصفه ظبى ... وثلثي سكون الضم لاح وجملا","a":"وثا ثلثه فانصب وفا نصفه ظبى","b":"وثلثي سكون الضم لاح وجملا","ref":["ibraz:1127","siraj:90"]},{"id":"shatibiyya:1088","bookId":"shatibiyya","type":"bayt","num":1088,"seq":1088,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1088","page":"ج1 ص86","text":"ووالرجز ضم الكسر حفص إذا قل إذ ... وأدبر فاهمزه وسكن عن اجتلا","a":"ووالرجز ضم الكسر حفص إذا قل إذ","b":"وأدبر فاهمزه وسكن عن اجتلا","ref":["ibraz:1128","siraj:90"]},{"id":"shatibiyya:1089","bookId":"shatibiyya","type":"bayt","num":1089,"seq":1089,"chapter":"ومن سورة (ن) إلى سورة القيامة","title":"البيت 1089","page":"ج1 ص86","text":"فبادر وفا مستنفره عم فتحه ... وما يذكرون الغيب خص وخللا","a":"فبادر وفا مستنفره عم فتحه","b":"وما يذكرون الغيب خص وخللا","ref":["ibraz:1129","siraj:90"]},{"id":"shatibiyya:1090","bookId":"shatibiyya","type":"bayt","num":1090,"seq":1090,"chapter":"ومن سورة القيامة إلى سورة النبأ","title":"البيت 1090","page":"ج1 ص86","text":"ورا برق افتح آمنا يذرون مع ... يحبون حق كف يمنى علا علا","a":"ورا برق افتح آمنا يذرون مع","b":"يحبون حق كف يمنى علا علا","ref":["ibraz:1131","siraj:91"]},{"id":"shatibiyya:1091","bookId":"shatibiyya","type":"bayt","num":1091,"seq":1091,"chapter":"ومن سورة القيامة إلى سورة النبأ","title":"البيت 1091","page":"ج1 ص87","text":"سلاسل نون إذ رووا صرفه لنا ... وبالقصر قف من عن هدى خلفهم فلا","a":"سلاسل نون إذ رووا صرفه لنا","b":"وبالقصر قف من عن هدى خلفهم فلا","ref":["ibraz:50","siraj:91"]},{"id":"shatibiyya:1092","bookId":"shatibiyya","type":"bayt","num":1092,"seq":1092,"chapter":"ومن سورة القيامة إلى سورة النبأ","title":"البيت 1092","page":"ج1 ص87","text":"زكا وقواريرا فنونه إذ دنا ... رضا صرفه واقصره في الوقف فيصلا","a":"زكا وقواريرا فنونه إذ دنا","b":"رضا صرفه واقصره في الوقف فيصلا","ref":["ibraz:1133","siraj:91"]},{"id":"shatibiyya:1093","bookId":"shatibiyya","type":"bayt","num":1093,"seq":1093,"chapter":"ومن سورة القيامة إلى سورة النبأ","title":"البيت 1093","page":"ج1 ص87","text":"وفي الثان نون إذ رووا صرفه وقل ... يمد هشام واقفا معهم ولا","a":"وفي الثان نون إذ رووا صرفه وقل","b":"يمد هشام واقفا معهم ولا","ref":["ibraz:1134","siraj:91"]},{"id":"shatibiyya:1094","bookId":"shatibiyya","type":"bayt","num":1094,"seq":1094,"chapter":"ومن سورة القيامة إلى سورة النبأ","title":"البيت 1094","page":"ج1 ص87","text":"وعاليهم اسكن واكسر الضم إذ فشا ... وخضر برفع الخفض عم حلا علا","a":"وعاليهم اسكن واكسر الضم إذ فشا","b":"وخضر برفع الخفض عم حلا علا","ref":["ibraz:1135","siraj:91"]},{"id":"shatibiyya:1095","bookId":"shatibiyya","type":"bayt","num":1095,"seq":1095,"chapter":"ومن سورة القيامة إلى سورة النبأ","title":"البيت 1095","page":"ج1 ص87","text":"وإستبرق حرمي نصر وخاطبوا ... تشاءون حصن وقتت واوه حلا","a":"وإستبرق حرمي نصر وخاطبوا","b":"تشاءون حصن وقتت واوه حلا","ref":["ibraz:1136","siraj:91"]},{"id":"shatibiyya:1096","bookId":"shatibiyya","type":"bayt","num":1096,"seq":1096,"chapter":"ومن سورة القيامة إلى سورة النبأ","title":"البيت 1096","page":"ج1 ص87","text":"وبالهمز باقيهم قدرنا ثقيلا اذ ... رسا وجمالات فوحد شذا علا","a":"وبالهمز باقيهم قدرنا ثقيلا اذ","b":"رسا وجمالات فوحد شذا علا","ref":["ibraz:1137","siraj:91"]},{"id":"shatibiyya:1097","bookId":"shatibiyya","type":"bayt","num":1097,"seq":1097,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1097","page":"ج1 ص87","text":"وقل لابثين القصر فاش وقل ولا ... كذابا بتخفيف الكسائي أقبلا","a":"وقل لابثين القصر فاش وقل ولا","b":"كذابا بتخفيف الكسائي أقبلا","ref":["ibraz:1139","siraj:92"]},{"id":"shatibiyya:1098","bookId":"shatibiyya","type":"bayt","num":1098,"seq":1098,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1098","page":"ج1 ص87","text":"وفي رفع با رب السموات خفضه ... ذلول وفي الرحمن ناميه كملا","a":"وفي رفع با رب السموات خفضه","b":"ذلول وفي الرحمن ناميه كملا"},{"id":"shatibiyya:1099","bookId":"shatibiyya","type":"bayt","num":1099,"seq":1099,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1099","page":"ج1 ص87","text":"وناخرة بالمد صحبتهم وفي ... تزكى تصدى الثان حرمي اثقلا","a":"وناخرة بالمد صحبتهم وفي","b":"تزكى تصدى الثان حرمي اثقلا","ref":["ibraz:1141","siraj:92"]},{"id":"shatibiyya:1100","bookId":"shatibiyya","type":"bayt","num":1100,"seq":1100,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1100","page":"ج1 ص87","text":"فتنفعه في رفعه نصب عاصم ... وإنا صببنا فتحه ثبته تلا","a":"فتنفعه في رفعه نصب عاصم","b":"وإنا صببنا فتحه ثبته تلا","ref":["ibraz:1142","siraj:92"]},{"id":"shatibiyya:1101","bookId":"shatibiyya","type":"bayt","num":1101,"seq":1101,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1101","page":"ج1 ص87","text":"وخفف حق سجرت ثقل نشرت ... شريعة حق سعرت عن أولي ملا","a":"وخفف حق سجرت ثقل نشرت","b":"شريعة حق سعرت عن أولي ملا","ref":["ibraz:1143","siraj:92"]},{"id":"shatibiyya:1102","bookId":"shatibiyya","type":"bayt","num":1102,"seq":1102,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1102","page":"ج1 ص87","text":"وظا بضنين حق راو وخف في ... فعدلك الكوفي وحقك يوم لا","a":"وظا بضنين حق راو وخف في","b":"فعدلك الكوفي وحقك يوم لا","ref":["ibraz:1144","siraj:92"]},{"id":"shatibiyya:1103","bookId":"shatibiyya","type":"bayt","num":1103,"seq":1103,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1103","page":"ج1 ص87","text":"وفي فاكهين اقصر علا وختامه ... بفتح وقدم مده راشدا ولا","a":"وفي فاكهين اقصر علا وختامه","b":"بفتح وقدم مده راشدا ولا","ref":["ibraz:1145","siraj:92"]},{"id":"shatibiyya:1104","bookId":"shatibiyya","type":"bayt","num":1104,"seq":1104,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1104","page":"ج1 ص88","text":"يصلى ثقيلا ضم عم رضا دنا ... وبا تركبن اضمم حيا عم نهلا","a":"يصلى ثقيلا ضم عم رضا دنا","b":"وبا تركبن اضمم حيا عم نهلا","ref":["ibraz:1146","siraj:92"]},{"id":"shatibiyya:1105","bookId":"shatibiyya","type":"bayt","num":1105,"seq":1105,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1105","page":"ج1 ص88","text":"ومحفوظ اخفض رفعه خص وهو في ال ... مجيد شفا والخف قدر رتلا","a":"ومحفوظ اخفض رفعه خص وهو في ال","b":"مجيد شفا والخف قدر رتلا","ref":["ibraz:1147","siraj:92"]},{"id":"shatibiyya:1106","bookId":"shatibiyya","type":"bayt","num":1106,"seq":1106,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1106","page":"ج1 ص88","text":"وبل يوثرون حز وتصلى يضم حز ... صفا تسمع التذكير حق وذو جلا","a":"وبل يوثرون حز وتصلى يضم حز","b":"صفا تسمع التذكير حق وذو جلا","ref":["ibraz:1148","siraj:92"]},{"id":"shatibiyya:1107","bookId":"shatibiyya","type":"bayt","num":1107,"seq":1107,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1107","page":"ج1 ص88","text":"وضم أولوا حق ولاغية لهم ... مصيطر اشمم ضاع والخلف قللا","a":"وضم أولوا حق ولاغية لهم","b":"مصيطر اشمم ضاع والخلف قللا","ref":["ibraz:1149","siraj:92"]},{"id":"shatibiyya:1108","bookId":"shatibiyya","type":"bayt","num":1108,"seq":1108,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1108","page":"ج1 ص88","text":"وبالسين لذ والوتر بالكسر شائع ... فقدر يروي اليحصبي مثقلا","a":"وبالسين لذ والوتر بالكسر شائع","b":"فقدر يروي اليحصبي مثقلا","ref":["ibraz:1150","siraj:92"]},{"id":"shatibiyya:1109","bookId":"shatibiyya","type":"bayt","num":1109,"seq":1109,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1109","page":"ج1 ص88","text":"وأربع غيب بعد بل لا حصولها ... يحضون فتح الضم بالمد ثملا","a":"وأربع غيب بعد بل لا حصولها","b":"يحضون فتح الضم بالمد ثملا","ref":["ibraz:1151","siraj:92"]},{"id":"shatibiyya:1110","bookId":"shatibiyya","type":"bayt","num":1110,"seq":1110,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1110","page":"ج1 ص88","text":"يعذب فافتحه ويوثق راويا ... وياءان في ربي وفك ارفعن ولا","a":"يعذب فافتحه ويوثق راويا","b":"وياءان في ربي وفك ارفعن ولا","ref":["ibraz:1152","siraj:92"]},{"id":"shatibiyya:1111","bookId":"shatibiyya","type":"bayt","num":1111,"seq":1111,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1111","page":"ج1 ص88","text":"وبعد اخفضن واكسر ومد منونا ... مع الرفع إطعام ندى عم فانهلا","a":"وبعد اخفضن واكسر ومد منونا","b":"مع الرفع إطعام ندى عم فانهلا","ref":["ibraz:1153","siraj:92"]},{"id":"shatibiyya:1112","bookId":"shatibiyya","type":"bayt","num":1112,"seq":1112,"chapter":"ومن سورة النبأ إلى سورة العلق","title":"البيت 1112","page":"ج1 ص88","text":"ومؤصدة فاهمز معا عن فتى حمى ... ولا عم في والشمس بالفاء وانجلا","a":"ومؤصدة فاهمز معا عن فتى حمى","b":"ولا عم في والشمس بالفاء وانجلا","ref":["ibraz:1154","siraj:92"]},{"id":"shatibiyya:1113","bookId":"shatibiyya","type":"bayt","num":1113,"seq":1113,"chapter":"من سورة العلق إلى آخر القرآن","title":"البيت 1113","page":"ج1 ص88","text":"وعن قنبل قصرا روى ابن مجاهد ... رآه ولم يأخذ به متعملا","a":"وعن قنبل قصرا روى ابن مجاهد","b":"رآه ولم يأخذ به متعملا","ref":["ibraz:1156","siraj:93"]},{"id":"shatibiyya:1114","bookId":"shatibiyya","type":"bayt","num":1114,"seq":1114,"chapter":"من سورة العلق إلى آخر القرآن","title":"البيت 1114","page":"ج1 ص88","text":"ومطلع كسر اللام رحب وحرفي ال ... برية فاهمز آهلا متأهلا","a":"ومطلع كسر اللام رحب وحرفي ال","b":"برية فاهمز آهلا متأهلا","ref":["ibraz:1157","siraj:93"]},{"id":"shatibiyya:1115","bookId":"shatibiyya","type":"bayt","num":1115,"seq":1115,"chapter":"من سورة العلق إلى آخر القرآن","title":"البيت 1115","page":"ج1 ص88","text":"وتا ترون اضمم في الاولى كما رسا ... وجمع بالتشديد شافيه كملا","a":"وتا ترون اضمم في الاولى كما رسا","b":"وجمع بالتشديد شافيه كملا","ref":["ibraz:1158","siraj:93"]},{"id":"shatibiyya:1116","bookId":"shatibiyya","type":"bayt","num":1116,"seq":1116,"chapter":"من سورة العلق إلى آخر القرآن","title":"البيت 1116","page":"ج1 ص89","text":"وصحبة الضمين في عمد وعوا ... لإيلاف باليا غير شاميهم تلا","a":"وصحبة الضمين في عمد وعوا","b":"لإيلاف باليا غير شاميهم تلا","ref":["ibraz:1159","siraj:93"]},{"id":"shatibiyya:1117","bookId":"shatibiyya","type":"bayt","num":1117,"seq":1117,"chapter":"من سورة العلق إلى آخر القرآن","title":"البيت 1117","page":"ج1 ص89","text":"وإيلاف كل وهو في الخط ساقط ... ولى دين قل في الكافرين تحصلا","a":"وإيلاف كل وهو في الخط ساقط","b":"ولى دين قل في الكافرين تحصلا","ref":["ibraz:1160","siraj:93"]},{"id":"shatibiyya:1118","bookId":"shatibiyya","type":"bayt","num":1118,"seq":1118,"chapter":"من سورة العلق إلى آخر القرآن","title":"البيت 1118","page":"ج1 ص89","text":"وها أبي لهب بالاسكان دونوا ... وحمالة المرفوع بالنصب نزلا","a":"وها أبي لهب بالاسكان دونوا","b":"وحمالة المرفوع بالنصب نزلا","ref":["siraj:93"]},{"id":"shatibiyya:1119","bookId":"shatibiyya","type":"bayt","num":1119,"seq":1119,"chapter":"باب التكبير","title":"البيت 1119","page":"ج1 ص89","text":"روى القلب ذكر الله فاستسق مقبلا ... ولا تعد روض الذاكرين فتمحلا","a":"روى القلب ذكر الله فاستسق مقبلا","b":"ولا تعد روض الذاكرين فتمحلا","ref":["ibraz:806","siraj:94"]},{"id":"shatibiyya:1120","bookId":"shatibiyya","type":"bayt","num":1120,"seq":1120,"chapter":"باب التكبير","title":"البيت 1120","page":"ج1 ص89","text":"وآثر عن الآثار مثراة عذبه ... وما مثله للعبد حصنا وموئلا","a":"وآثر عن الآثار مثراة عذبه","b":"وما مثله للعبد حصنا وموئلا","ref":["ibraz:1164","siraj:94"]},{"id":"shatibiyya:1121","bookId":"shatibiyya","type":"bayt","num":1121,"seq":1121,"chapter":"باب التكبير","title":"البيت 1121","page":"ج1 ص89","text":"ولا عمل أنجى له من عذابه ... غداة الجزا من ذكره متقبلا","a":"ولا عمل أنجى له من عذابه","b":"غداة الجزا من ذكره متقبلا","ref":["ibraz:1165","siraj:94"]},{"id":"shatibiyya:1122","bookId":"shatibiyya","type":"bayt","num":1122,"seq":1122,"chapter":"باب التكبير","title":"البيت 1122","page":"ج1 ص89","text":"ومن شغل القرآن عنه لسانه ... ينل خير أجر الذاكرين مكملا","a":"ومن شغل القرآن عنه لسانه","b":"ينل خير أجر الذاكرين مكملا","ref":["ibraz:1166","siraj:94"]},{"id":"shatibiyya:1123","bookId":"shatibiyya","type":"bayt","num":1123,"seq":1123,"chapter":"باب التكبير","title":"البيت 1123","page":"ج1 ص89","text":"وما أفضل الأعمال إلا افتتاحه ... مع الختم حلا وارتحالا موصلا","a":"وما أفضل الأعمال إلا افتتاحه","b":"مع الختم حلا وارتحالا موصلا","ref":["ibraz:1167","siraj:94"]},{"id":"shatibiyya:1124","bookId":"shatibiyya","type":"bayt","num":1124,"seq":1124,"chapter":"باب التكبير","title":"البيت 1124","page":"ج1 ص89","text":"وفيه عن المكين تكبيرهم مع ال ... خواتم قرب الختم يروى مسلسلا","a":"وفيه عن المكين تكبيرهم مع ال","b":"خواتم قرب الختم يروى مسلسلا","ref":["ibraz:1168","siraj:94"]},{"id":"shatibiyya:1125","bookId":"shatibiyya","type":"bayt","num":1125,"seq":1125,"chapter":"باب التكبير","title":"البيت 1125","page":"ج1 ص89","text":"إذا كبروا في آخر الناس أردفوا ... مع الحمد حتى المفلحون توسلا","a":"إذا كبروا في آخر الناس أردفوا","b":"مع الحمد حتى المفلحون توسلا","ref":["ibraz:1169","siraj:94"]},{"id":"shatibiyya:1126","bookId":"shatibiyya","type":"bayt","num":1126,"seq":1126,"chapter":"باب التكبير","title":"البيت 1126","page":"ج1 ص89","text":"وقال به البزي من آخر الضحى ... وبعض له من آخر الليل وصلا","a":"وقال به البزي من آخر الضحى","b":"وبعض له من آخر الليل وصلا","ref":["ibraz:1170","siraj:94"]},{"id":"shatibiyya:1127","bookId":"shatibiyya","type":"bayt","num":1127,"seq":1127,"chapter":"باب التكبير","title":"البيت 1127","page":"ج1 ص89","text":"فإن شئت فاقطع دونه أو عليه أو ... صل الكل دون القطع معه مبسملا","a":"فإن شئت فاقطع دونه أو عليه أو","b":"صل الكل دون القطع معه مبسملا","ref":["ibraz:1171","siraj:94"]},{"id":"shatibiyya:1128","bookId":"shatibiyya","type":"bayt","num":1128,"seq":1128,"chapter":"باب التكبير","title":"البيت 1128","page":"ج1 ص90","text":"وما قبله من ساكن أو منون ... فللساكنين اكسره في الوصل مرسلا","a":"وما قبله من ساكن أو منون","b":"فللساكنين اكسره في الوصل مرسلا","ref":["ibraz:1172","siraj:94"]},{"id":"shatibiyya:1129","bookId":"shatibiyya","type":"bayt","num":1129,"seq":1129,"chapter":"باب التكبير","title":"البيت 1129","page":"ج1 ص90","text":"وأدرج على إعرابه ما سواهما ... ولا تصلن هاء الضمير لتوصلا","a":"وأدرج على إعرابه ما سواهما","b":"ولا تصلن هاء الضمير لتوصلا","ref":["ibraz:1173","siraj:94"]},{"id":"shatibiyya:1130","bookId":"shatibiyya","type":"bayt","num":1130,"seq":1130,"chapter":"باب التكبير","title":"البيت 1130","page":"ج1 ص90","text":"وقل لفظه الله أكبر وقبله ... لأحمد زاد ابن الحباب فهللا","a":"وقل لفظه الله أكبر وقبله","b":"لأحمد زاد ابن الحباب فهللا","ref":["ibraz:1174","siraj:94"]},{"id":"shatibiyya:1131","bookId":"shatibiyya","type":"bayt","num":1131,"seq":1131,"chapter":"باب التكبير","title":"البيت 1131","page":"ج1 ص90","text":"وقيل بهذا عن أبي الفتح فارس ... وعن قنبل بعض بتكبيره تلا","a":"وقيل بهذا عن أبي الفتح فارس","b":"وعن قنبل بعض بتكبيره تلا","ref":["ibraz:1175","siraj:94"]},{"id":"shatibiyya:1132","bookId":"shatibiyya","type":"bayt","num":1132,"seq":1132,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1132","page":"ج1 ص90","text":"وهاك موازين الحروف وما حكى ... جهابذة النقاد فيها محصلا","a":"وهاك موازين الحروف وما حكى","b":"جهابذة النقاد فيها محصلا","ref":["ibraz:1177","siraj:95"]},{"id":"shatibiyya:1133","bookId":"shatibiyya","type":"bayt","num":1133,"seq":1133,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1133","page":"ج1 ص90","text":"ولا ريبة في عينهن ولا ربا ... وعند صليل الزيف يصدق الابتلا","a":"ولا ريبة في عينهن ولا ربا","b":"وعند صليل الزيف يصدق الابتلا","ref":["ibraz:1178","siraj:95"]},{"id":"shatibiyya:1134","bookId":"shatibiyya","type":"bayt","num":1134,"seq":1134,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1134","page":"ج1 ص90","text":"ولا بد في تعيينهن من الأولى ... عنوا بالمعاني عاملين وقولا","a":"ولا بد في تعيينهن من الأولى","b":"عنوا بالمعاني عاملين وقولا","ref":["siraj:95"]},{"id":"shatibiyya:1135","bookId":"shatibiyya","type":"bayt","num":1135,"seq":1135,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1135","page":"ج1 ص90","text":"فابدأ منها بالمخارج مردفا ... لهن بمشهور الصفات مفصلا","a":"فابدأ منها بالمخارج مردفا","b":"لهن بمشهور الصفات مفصلا","ref":["ibraz:1180","siraj:95"]},{"id":"shatibiyya:1136","bookId":"shatibiyya","type":"bayt","num":1136,"seq":1136,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1136","page":"ج1 ص90","text":"ثلاث بأقصى الحلق واثنان وسطه ... وحرفان منها أول الحلق جملا","a":"ثلاث بأقصى الحلق واثنان وسطه","b":"وحرفان منها أول الحلق جملا","ref":["ibraz:1181","siraj:95"]},{"id":"shatibiyya:1137","bookId":"shatibiyya","type":"bayt","num":1137,"seq":1137,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1137","page":"ج1 ص90","text":"وحرف له أقصى اللسان وفوقه ... من الحنك احفظه وحرف بأسفلا","a":"وحرف له أقصى اللسان وفوقه","b":"من الحنك احفظه وحرف بأسفلا","ref":["ibraz:1182","siraj:95"]},{"id":"shatibiyya:1138","bookId":"shatibiyya","type":"bayt","num":1138,"seq":1138,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1138","page":"ج1 ص90","text":"ووسطهما منه ثلاث وحافة ال ... لسان فأقصاها لحرف تطولا","a":"ووسطهما منه ثلاث وحافة ال","b":"لسان فأقصاها لحرف تطولا","ref":["ibraz:1183","siraj:95"]},{"id":"shatibiyya:1139","bookId":"shatibiyya","type":"bayt","num":1139,"seq":1139,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1139","page":"ج1 ص90","text":"إلى ما يلي الأضراس وهو لديهما ... يعز وباليمنى يكون مقللا","a":"إلى ما يلي الأضراس وهو لديهما","b":"يعز وباليمنى يكون مقللا","ref":["ibraz:1184","siraj:95"]},{"id":"shatibiyya:1140","bookId":"shatibiyya","type":"bayt","num":1140,"seq":1140,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1140","page":"ج1 ص91","text":"وحرف بأدناها إلى منتهاه قد ... يلي الحنك الأعلى ودونه ذو ولا","a":"وحرف بأدناها إلى منتهاه قد","b":"يلي الحنك الأعلى ودونه ذو ولا","ref":["ibraz:1185","siraj:95"]},{"id":"shatibiyya:1141","bookId":"shatibiyya","type":"bayt","num":1141,"seq":1141,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1141","page":"ج1 ص91","text":"وحرف يدانيه إلى الظهر مدخل ... وكم حاذق مع سيبويه به اجتلا","a":"وحرف يدانيه إلى الظهر مدخل","b":"وكم حاذق مع سيبويه به اجتلا","ref":["ibraz:1186","siraj:95"]},{"id":"shatibiyya:1142","bookId":"shatibiyya","type":"bayt","num":1142,"seq":1142,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1142","page":"ج1 ص91","text":"ومن طرف هن الثلاث لقطرب ... ويحيى مع الجرمي معناه قولا","a":"ومن طرف هن الثلاث لقطرب","b":"ويحيى مع الجرمي معناه قولا","ref":["ibraz:1187","siraj:95"]},{"id":"shatibiyya:1143","bookId":"shatibiyya","type":"bayt","num":1143,"seq":1143,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1143","page":"ج1 ص91","text":"ومنه ومن عليا الثنايا ثلاثة ... ومنه ومن أطرافها مثلها انجلى","a":"ومنه ومن عليا الثنايا ثلاثة","b":"ومنه ومن أطرافها مثلها انجلى","ref":["ibraz:1188","siraj:95"]},{"id":"shatibiyya:1144","bookId":"shatibiyya","type":"bayt","num":1144,"seq":1144,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1144","page":"ج1 ص91","text":"ومنه ومن بين الثنايا ثلاثة ... وحرف من اطراف الثنايا هي العلا","a":"ومنه ومن بين الثنايا ثلاثة","b":"وحرف من اطراف الثنايا هي العلا","ref":["ibraz:1189","siraj:95"]},{"id":"shatibiyya:1145","bookId":"shatibiyya","type":"bayt","num":1145,"seq":1145,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1145","page":"ج1 ص91","text":"ومن باطن السفلى من الشفتين قل ... وللشفتين اجعل ثلاثا لتعدلا","a":"ومن باطن السفلى من الشفتين قل","b":"وللشفتين اجعل ثلاثا لتعدلا","ref":["ibraz:1190","siraj:95"]},{"id":"shatibiyya:1146","bookId":"shatibiyya","type":"bayt","num":1146,"seq":1146,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1146","page":"ج1 ص91","text":"وفي أول من كلم بيتين جمعها ... سوى أربع فيهن كلمة اولا","a":"وفي أول من كلم بيتين جمعها","b":"سوى أربع فيهن كلمة اولا","ref":["ibraz:1191","siraj:95"]},{"id":"shatibiyya:1147","bookId":"shatibiyya","type":"bayt","num":1147,"seq":1147,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1147","page":"ج1 ص91","text":"أهاع حشا غاو خلا قارئ كما ... جرى شرط يسرى ضارع لاح نوفلا","a":"أهاع حشا غاو خلا قارئ كما","b":"جرى شرط يسرى ضارع لاح نوفلا","ref":["ibraz:1192","siraj:95"]},{"id":"shatibiyya:1148","bookId":"shatibiyya","type":"bayt","num":1148,"seq":1148,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1148","page":"ج1 ص91","text":"رعى طهر دين تمه ظل ذي ثنا ... صفا سجل زهد في وجوه بني ملا","a":"رعى طهر دين تمه ظل ذي ثنا","b":"صفا سجل زهد في وجوه بني ملا","ref":["ibraz:1193","siraj:95"]},{"id":"shatibiyya:1149","bookId":"shatibiyya","type":"bayt","num":1149,"seq":1149,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1149","page":"ج1 ص91","text":"وغنة تنوين ونون وميم ان ... سكن ولا إظهار في الأنف يجتلى","a":"وغنة تنوين ونون وميم ان","b":"سكن ولا إظهار في الأنف يجتلى","ref":["ibraz:1194","siraj:95"]},{"id":"shatibiyya:1150","bookId":"shatibiyya","type":"bayt","num":1150,"seq":1150,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1150","page":"ج1 ص91","text":"وجهر ورخو وانفتاح صفاتها ... ومستفل فاجمع بالاضداد أشملا","a":"وجهر ورخو وانفتاح صفاتها","b":"ومستفل فاجمع بالاضداد أشملا","ref":["ibraz:1195","siraj:95"]},{"id":"shatibiyya:1151","bookId":"shatibiyya","type":"bayt","num":1151,"seq":1151,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1151","page":"ج1 ص91","text":"فمهموسها عشر (حثت كسف شخصه) ... (أجدت كقطب) للشديدة مثلا","a":"فمهموسها عشر (حثت كسف شخصه)","b":"(أجدت كقطب) للشديدة مثلا","ref":["ibraz:1196","siraj:95"]},{"id":"shatibiyya:1152","bookId":"shatibiyya","type":"bayt","num":1152,"seq":1152,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1152","page":"ج1 ص91","text":"وما بين رخو والشديدة (عمرنل) ... و (واي) حروف المد والرخو كملا","a":"وما بين رخو والشديدة (عمرنل)","b":"و (واي) حروف المد والرخو كملا","ref":["ibraz:1197","siraj:95"]},{"id":"shatibiyya:1153","bookId":"shatibiyya","type":"bayt","num":1153,"seq":1153,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1153","page":"ج1 ص92","text":"و (قظ خص ضغط) سبع علو ومطبق ... هو الضاد والظا أعجما وإن اهملا","a":"و (قظ خص ضغط) سبع علو ومطبق","b":"هو الضاد والظا أعجما وإن اهملا","ref":["ibraz:1198","siraj:95"]},{"id":"shatibiyya:1154","bookId":"shatibiyya","type":"bayt","num":1154,"seq":1154,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1154","page":"ج1 ص92","text":"وصاد وسين مهملان وزايها ... صفير وشين بالتفشي تعملا","a":"وصاد وسين مهملان وزايها","b":"صفير وشين بالتفشي تعملا","ref":["ibraz:1199"]},{"id":"shatibiyya:1155","bookId":"shatibiyya","type":"bayt","num":1155,"seq":1155,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1155","page":"ج1 ص92","text":"ومنحرف لام وراء وكررت ... كما المستطيل الضاد ليس بأغفلا","a":"ومنحرف لام وراء وكررت","b":"كما المستطيل الضاد ليس بأغفلا","ref":["ibraz:1200","siraj:95"]},{"id":"shatibiyya:1156","bookId":"shatibiyya","type":"bayt","num":1156,"seq":1156,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1156","page":"ج1 ص92","text":"كما الألف الهاوي و (آوي) لعلة ... وفي (قطب جد) خمس قلقلة علا","a":"كما الألف الهاوي و (آوي) لعلة","b":"وفي (قطب جد) خمس قلقلة علا","ref":["ibraz:1201","siraj:95"]},{"id":"shatibiyya:1157","bookId":"shatibiyya","type":"bayt","num":1157,"seq":1157,"chapter":"باب مخارج الحروف وصفاتها التي يحتاج القارئ إليها","title":"البيت 1157","page":"ج1 ص92","text":"وأعرفهن القاف كل يعدها ... فهذا مع التوفيق كاف محصلا","a":"وأعرفهن القاف كل يعدها","b":"فهذا مع التوفيق كاف محصلا","ref":["ibraz:1202","siraj:95"]},{"id":"shatibiyya:1158","bookId":"shatibiyya","type":"bayt","num":1158,"seq":1158,"chapter":"الخاتمة","title":"البيت 1158","page":"ج1 ص92","text":"وقد وفق الله الكريم بمنه ... لإكمالها حسناء ميمونة الجلا","a":"وقد وفق الله الكريم بمنه","b":"لإكمالها حسناء ميمونة الجلا","ref":["ibraz:1203","siraj:95"]},{"id":"shatibiyya:1159","bookId":"shatibiyya","type":"bayt","num":1159,"seq":1159,"chapter":"الخاتمة","title":"البيت 1159","page":"ج1 ص92","text":"وأبياتها ألف تزيد ثلاثة ... ومع مائة سبعين زهرا وكملا","a":"وأبياتها ألف تزيد ثلاثة","b":"ومع مائة سبعين زهرا وكملا","ref":["ibraz:1204","siraj:95"]},{"id":"shatibiyya:1160","bookId":"shatibiyya","type":"bayt","num":1160,"seq":1160,"chapter":"الخاتمة","title":"البيت 1160","page":"ج1 ص92","text":"وقد كسيت منها المعاني عناية ... كما عريت عن كل عوراء مفصلا","a":"وقد كسيت منها المعاني عناية","b":"كما عريت عن كل عوراء مفصلا","ref":["ibraz:1205"]},{"id":"shatibiyya:1161","bookId":"shatibiyya","type":"bayt","num":1161,"seq":1161,"chapter":"الخاتمة","title":"البيت 1161","page":"ج1 ص92","text":"وتمت بحمد الله في الخلق سهلة ... منزهة عن منطق الهجر مقولا","a":"وتمت بحمد الله في الخلق سهلة","b":"منزهة عن منطق الهجر مقولا","ref":["ibraz:1206","siraj:96"]},{"id":"shatibiyya:1162","bookId":"shatibiyya","type":"bayt","num":1162,"seq":1162,"chapter":"الخاتمة","title":"البيت 1162","page":"ج1 ص92","text":"ولكنها تبغي من الناس كفؤها ... أخا ثقة يعفو ويغضي تجملا","a":"ولكنها تبغي من الناس كفؤها","b":"أخا ثقة يعفو ويغضي تجملا","ref":["ibraz:1207","siraj:96"]},{"id":"shatibiyya:1163","bookId":"shatibiyya","type":"bayt","num":1163,"seq":1163,"chapter":"الخاتمة","title":"البيت 1163","page":"ج1 ص92","text":"وليس لها إلا ذنوب وليها ... فيا طيب الأنفاس أحسن تأولا","a":"وليس لها إلا ذنوب وليها","b":"فيا طيب الأنفاس أحسن تأولا","ref":["ibraz:1208","siraj:96"]},{"id":"shatibiyya:1164","bookId":"shatibiyya","type":"bayt","num":1164,"seq":1164,"chapter":"الخاتمة","title":"البيت 1164","page":"ج1 ص92","text":"وقل رحم الرحمن حيا وميتا ... فتى كان للإنصاف والحلم معقلا","a":"وقل رحم الرحمن حيا وميتا","b":"فتى كان للإنصاف والحلم معقلا","ref":["ibraz:1209"]},{"id":"shatibiyya:1165","bookId":"shatibiyya","type":"bayt","num":1165,"seq":1165,"chapter":"الخاتمة","title":"البيت 1165","page":"ج1 ص93","text":"عسى الله يدني سعيه بجوازه ... وإن كان زيفا غير خاف مزللا","a":"عسى الله يدني سعيه بجوازه","b":"وإن كان زيفا غير خاف مزللا","ref":["siraj:96"]},{"id":"shatibiyya:1166","bookId":"shatibiyya","type":"bayt","num":1166,"seq":1166,"chapter":"الخاتمة","title":"البيت 1166","page":"ج1 ص93","text":"فيا خير غفار ويا خير راحم ... ويا خير مأمول جدا وتفضلا","a":"فيا خير غفار ويا خير راحم","b":"ويا خير مأمول جدا وتفضلا","ref":["ibraz:1211","siraj:96"]},{"id":"shatibiyya:1167","bookId":"shatibiyya","type":"bayt","num":1167,"seq":1167,"chapter":"الخاتمة","title":"البيت 1167","page":"ج1 ص93","text":"أقل عثرتي وانفع بها وبقصدها ... حنانيك يا الله يا رافع العلا","a":"أقل عثرتي وانفع بها وبقصدها","b":"حنانيك يا الله يا رافع العلا","ref":["ibraz:1212","siraj:96"]},{"id":"shatibiyya:1168","bookId":"shatibiyya","type":"bayt","num":1168,"seq":1168,"chapter":"الخاتمة","title":"البيت 1168","page":"ج1 ص93","text":"وآخر دعوانا بتوفيق ربنا ... أن الحمد لله الذي وحده علا","a":"وآخر دعوانا بتوفيق ربنا","b":"أن الحمد لله الذي وحده علا","ref":["ibraz:1213","siraj:96"]},{"id":"shatibiyya:1169","bookId":"shatibiyya","type":"bayt","num":1169,"seq":1169,"chapter":"الخاتمة","title":"البيت 1169","page":"ج1 ص93","text":"وبعد صلاة الله ثم سلامه ... على سيد الخلق الرضا متنخلا","a":"وبعد صلاة الله ثم سلامه","b":"على سيد الخلق الرضا متنخلا","ref":["ibraz:1214","siraj:96"]},{"id":"shatibiyya:1170","bookId":"shatibiyya","type":"bayt","num":1170,"seq":1170,"chapter":"الخاتمة","title":"البيت 1170","page":"ج1 ص93","text":"محمد المختار للمجد كعبة ... صلاة تباري الريح مسكا ومندلا","a":"محمد المختار للمجد كعبة","b":"صلاة تباري الريح مسكا ومندلا","ref":["ibraz:1215","siraj:96"]},{"id":"shatibiyya:1171","bookId":"shatibiyya","type":"bayt","num":1171,"seq":1171,"chapter":"الخاتمة","title":"البيت 1171","page":"ج1 ص93","text":"وتبدي على أصحابه نفحاتها ... بغير تناه زرنبا وقرنفلا","a":"وتبدي على أصحابه نفحاتها","b":"بغير تناه زرنبا وقرنفلا","ref":["ibraz:1216","siraj:96"]}]};